-- 0083 — SEO etiket optimizasyonu öneri tohumu (Jade Gold, tek seferlik veri)
--
-- 115 aktif Jade Gold listing için değer-öncelikli optimize 13-tag önerileri.
-- Bunlar bir kerelik AI analizinin ÇIKTISIDIR (fixture değil), o yüzden yalnız
-- ilgili org VARSA yüklenir (guard) ve mevcut satırlar KORUNUR (do nothing) —
-- push edilmiş/insan-düzenlenmiş durumu ezmez. Org yoksa (fresh/staging) no-op.

insert into public.seo_tag_optimizations
  (org_id, etsy_listing_id, title, ptype, archetype, old_tags, proposed_tags, dropped, added, key_issue, rationale, confidence)
select v.* from (values
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1219136707,'10K Solid Gold Square Nugget Ring | Men''s Statement Band','ring','leak',ARRAY['Nugget Ring','Nugget mens','Gold Nugget Ring','Nugget Rings','Gold Statement Rings','10K Gold Rings','10K Solid Gold Ring','Solid Gold Ring','Gold Square Ring','10K Ring','Gold Ring','Real Gold Ring','10K Gold Ring Men']::text[],ARRAY['Mens Nugget Ring','10K Gold Nugget Ring','Gold Statement Ring','Solid Gold Mens Ring','Real Gold Ring Men','Square Signet Ring','Chunky Gold Ring Men','Gift for Him','Hip Hop Ring Men','Iced Out Nugget Ring','Yellow Gold Band','Everyday Gold Ring','Boyfriend Gift Ring']::text[],'[{"tag": "Nugget Ring", "reason": "Tek kelime kokunu Mens Nugget Ring long-tail''i zaten kapsiyor; birebir tekrar slot israfi."}, {"tag": "Nugget Rings", "reason": "''Nugget Ring'' ile cogul/tekil ikizi; Etsy zaten esler, ayri slot gereksiz."}, {"tag": "Gold Nugget Ring", "reason": "10K Gold Nugget Ring varyantiyla ayni kok; niteligi eklenmis versiyon korundu."}, {"tag": "Nugget mens", "reason": "Bozuk/eksik ifade; ''Mens Nugget Ring'' dogru ve tam long-tail olarak yer aldi."}, {"tag": "10K Gold Rings", "reason": "''gold ring'' kokunun 9 tekrarindan biri; jenerik cogul, dusuk niyet."}, {"tag": "Solid Gold Ring", "reason": "Alici-eksik jenerik; ''Solid Gold Mens Ring'' hedefli versiyonuyla degistirildi."}, {"tag": "Gold Square Ring", "reason": "''Square Signet Ring'' daha satin-alma-niyetli stil terimiyle degistirildi."}, {"tag": "10K Ring", "reason": "Tek-nitelik jenerik, tekrar koku; dar niyet, slot israfi."}, {"tag": "Gold Ring", "reason": "En jenerik tek-kok; leak''in ana kaynagi, genis gezgin cekiyor."}, {"tag": "10K Solid Gold Ring", "reason": "10K+solid+gold+ring kombinasyonunu Etsy zaten diger tag kelimelerinden uretir; birebir fazlalik."}]'::jsonb,'[{"tag": "Gift for Him", "reason": "Hediye niyet-alanini aciyor; erkek takisinda en yuksek donusum getiren alici arama."}, {"tag": "Hip Hop Ring Men", "reason": "Stil slotu; nugget/chunky altin erkek takisinin gercek alt-kulturu, niyetli kitle."}, {"tag": "Chunky Gold Ring Men", "reason": "Urun gercegini (statement band) tanimlayan alici dili; dar redundancy yerine yeni kitle."}, {"tag": "Square Signet Ring", "reason": "Kare nugget formunun stil karsiligi; ''signet'' yuksek-niyet erkek yuzuk aramasi."}, {"tag": "Everyday Gold Ring", "reason": "Kullanim slotu; gunluk tasima niyetini yakalar, statement disi alici da doner."}, {"tag": "Boyfriend Gift Ring", "reason": "Hediye+alici birlesik long-tail; erkek takisinda guclu donusum sinyali."}, {"tag": "Iced Out Nugget Ring", "reason": "Stil/estetik nis; nugget alicisinin hip-hop ekseninde ararken kullandigi terim."}, {"tag": "Yellow Gold Band", "reason": "Malzeme (Yellow Gold) + form ''band'' basliktan turer; renk-spesifik arayan alici slotu."}]'::jsonb,'13 slotun ~9''u tek bir "gold ring" kokunu ve 4''u "nugget"i tekrarliyor; hediye/stil/kullanim/alici niyet-alanlari bos, o yuzden genis "altin yuzuk" gezginini cekip erkek 10K nugget alicisini kaciriyor (leak).','Baslik/urun gercegi: 10K som altin, KARE nugget, ERKEK statement BAND. Strateji leak oldugu icin donusumu kurtaracak sekilde redundancy''i kestim (9 ''gold ring'' tekrari -> tek guclu anchor grubu; 4 ''nugget'' -> 2 nitelikli long-tail) ve bosalan slotlari alici(mens), hediye(gift for him/boyfriend), stil(hip hop, signet, iced out), kullanim(everyday) ile doldurdum. Tum tag''ler urun-tipiyle (ring) uyumlu; celisen tip yok. 13 tag''in tamami <=20 karakter dogrulandi (en uzun ''Chunky Gold Ring Men''=20, ''Iced Out Nugget Ring''=20, ''10K Gold Nugget Ring''=20). Cogunluk cok-kelimeli long-tail; tek-kelime tag yok. Baslikta zaten baskin olan ''Nugget/Gold/10K'' korlemesine tekrarlanmadi, niyet-genisletildi.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1430538853,'14k Gold Miami Cuban Link Chain | Italian Curb Necklace','necklace','leak',ARRAY['Miami Cuban Link','Cuban Chain Necklace','14K Gold Necklace','Layering Necklace','Italian Link Chain','Curb Link Chain','Everyday Necklace','Micro Cuban Necklace','Groomsman Gift','Solid Gold Necklace','Anniversary Gift','Boys Chain Necklace','Thick Gold Chain']::text[],ARRAY['Miami Cuban Link','Cuban Link Necklace','Curb Chain Necklace','Italian Curb Chain','14K Gold Necklace','Solid Gold Necklace','Real Gold Chain','Gold Chain For Men','Layering Necklace','Gift For Him','Anniversary Gift','Hip Hop Jewelry','Statement Necklace']::text[],'[{"tag": "Boys Chain Necklace", "reason": "TIP/KITLE CELISKISI ve baslica donusum katili: som 14K gercek altin yuksek-fiyatli urun; ''boys'' ucuz cocuk takisi arayan ebeveyni ceker — leak''in kok nedeni."}, {"tag": "Micro Cuban Necklace", "reason": "''Thick Gold Chain'' ile celisiyor (ince vs kalin) ve basligta olmayan dar bir genislik nisine daraltiyor; premium gercek-altin alicisi icin dusuk niyet."}, {"tag": "Thick Gold Chain", "reason": "Tek-kelimeye yakin/muglak ve ''Micro Cuban'' ile celisik; yerine daha keskin alici dili ''Real Gold Chain'' geldi."}, {"tag": "Cuban Chain Necklace", "reason": "Cuban kokunun 3. tekrari (Miami Cuban Link + Cuban Link Necklace zaten kapsiyor) — slot israfi."}, {"tag": "Curb Link Chain", "reason": "Curb ''Curb Chain Necklace'' + ''Italian Curb Chain'' ile korundu; ucuncu link-chain tekrari kaldirildi."}, {"tag": "Italian Link Chain", "reason": "''Italian Curb Chain'' ile degistirildi — basligin iki terimini (Italian+Curb) tek slotta birlestirir, link-chain redundancy''sini keser."}, {"tag": "Everyday Necklace", "reason": "''Layering Necklace'' ile kullanim-slotu ortusuyor; agir statement zincirde everyday zayif — slot alici-niyetli tag''e (Gold Chain For Men) devredildi."}, {"tag": "Groomsman Gift", "reason": "Cok dar/mevsimsel nis; daha genis erkek-hediye slotu ''Gift For Him'' ile degistirildi (Anniversary Gift korundu)."}]'::jsonb,'[{"tag": "Cuban Link Necklace", "reason": "Urunun EN yuksek hacimli arama ifadesi; necklace tipini ekler ve satin-alma niyetini yakalar."}, {"tag": "Italian Curb Chain", "reason": "Basligin iki farkli terimini (Italian + Curb) tek slotta birlestirir; gereksiz ''gold chain'' tekrarini onler."}, {"tag": "Real Gold Chain", "reason": "Alici dili (''real gold'') — yuksek satin-alma niyeti, kalp-kirici ucuz kaplama arayanini eler, dogru kitleyi filtreler."}, {"tag": "Gold Chain For Men", "reason": "Cuban link agirlikla erkek-aramali; acik erkek hedeflemesi + yuksek niyet — leak''te eksik olan kritik alici slotu."}, {"tag": "Gift For Him", "reason": "Genis erkek-hediye slotu (dar Groomsman yerine); Anniversary ile hediye kapsamini cesitlendirir."}, {"tag": "Hip Hop Jewelry", "reason": "Cuban zincirin cekirdek stil/kitle sinyali; estetik-odakli satin-alma niyetini ceker."}, {"tag": "Statement Necklace", "reason": "Kalin Miami Cuban icin stil/kullanim slotu; ''micro'' celiskisini kaldirdiktan sonra tutarli (belirgin/iddiali) pozisyon."}]'::jsonb,'Tag seti premium 14K gerçek altın ürünü düşük-niyetli/yanlış kitleye açıyor: "Boys Chain Necklace" ucuz çocuk takısı arayanı çekiyor, cuban/link kökleri tekrar ederek slot israf ediyor ve erkek alıcı diline (gold chain for men, real gold, gift for him) hiç kaymıyor — bu yüzden 101K görüntü dönüşmüyor.','Strateji leak: trafik zaten var (101K views), sorun donusum, o yuzden relevance''i sikilastirip alici-niyetli dile kaydirdim. (1) Tip celiskisini attim: ''Boys Chain Necklace'' premium gercek-altin urunde yanlis/dusuk-niyetli kitle cektigi icin oncelikli cikarma. (2) Redundancy''yi kestim: 3x cuban -> 2 (Miami Cuban Link + Cuban Link Necklace), cift link-chain -> tek; kok butcesi cuban 2 / curb-italian 2 / gold necklace 2 / gold chain 2 ile sinirli. (3) Celiskiyi cozdum: Micro (ince) ve Thick (kalin) beraber bulaniklik yariyordu — ikisini de kaldirip ''Statement Necklace'' ile tek, tutarli ''iddiali'' pozisyon aldim. (4) Eksik slotlari doldurdum: erkek hedefleme (Gold Chain For Men, Gift For Him, Hip Hop Jewelry) ve alici dili (Real Gold Chain, Solid Gold Necklace) — cuban zincirin ana satin-alan kitlesi. Korunanlar: Miami Cuban Link (birincil stil, baslik), 14K Gold Necklace + Solid Gold Necklace (malzeme+deger), Layering Necklace (kullanim), Anniversary Gift (hediye). Tum tag''ler cok-kelimeli long-tail, birebir tekrar yok, hepsi <=20 karakter (en uzun ''Cuban Link Necklace''/''Solid Gold Necklace'' = 19). Necklace 6 kez geciyor ama her biri farkli modifierli ve urun tipi zaten necklace — mesru. Not: yuksek trafik/dusuk donusumun fiyat/fotograf bileseni de olabilir; tag''ler tek degisken degil, o yuzden orta guven.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1195581074,'10K Real Yellow Gold Miami Cuban Link Bracelet - Unisex','bracelet','leak',ARRAY['Gold Link Bracelet','Miami Link Chain','Miami Cuban Bracelet','10K Gold Bracelet','Miami Cuban Link','Link Chain Bracelet','Cuban Link Bracelet','10K Chain Bracelet','Real Gold Bracelet','Gold Chain Bracelet','Gold Bracelet','Miami Cuban','10K Cuban Bracelet']::text[],ARRAY['Miami Cuban Bracelet','Cuban Link Bracelet','10K Gold Bracelet','Real Gold Bracelet','Yellow Gold Bracelet','Mens Gold Bracelet','Womens Bracelet','Unisex Bracelet','Gift for Him','Gold Jewelry Gift','Statement Bracelet','Everyday Bracelet','Hip Hop Bracelet']::text[],'[{"tag": "Miami Link Chain", "reason": "Tip celiskisi: urun bracelet, ''chain'' zincir/kolye arayani cekiyor — leak kaynagi"}, {"tag": "Link Chain Bracelet", "reason": "''chain'' celiskisi + Cuban Link Bracelet ile ortusuyor, slot israfi"}, {"tag": "10K Chain Bracelet", "reason": "''chain'' celiskisi; 10K Gold Bracelet zaten karsiliyor"}, {"tag": "Gold Chain Bracelet", "reason": "''chain'' celiskisi — yanlis niyetli trafik, leak"}, {"tag": "Miami Cuban", "reason": "Tek konsept kok spam; Miami Cuban Bracelet ile birebir ortusen artiklik"}, {"tag": "Miami Cuban Link", "reason": "Miami Cuban + Cuban Link ile cift ortusme, redundancy"}, {"tag": "10K Cuban Bracelet", "reason": "Miami Cuban Bracelet + 10K Gold Bracelet ikilisini tekrarliyor"}, {"tag": "Gold Link Bracelet", "reason": "Cuban Link Bracelet ile ayni kok, ayirt edici deger yok"}, {"tag": "Gold Bracelet", "reason": "Cok genis/generik, satin alma niyeti dusuk; long-tail''e kaydirildi"}]'::jsonb,'[{"tag": "Yellow Gold Bracelet", "reason": "Malzeme gercegi (Yellow Gold) + baslikla uyumlu, renk niyetli aramayi yakalar"}, {"tag": "Mens Gold Bracelet", "reason": "Alici slotu (erkek) — Miami Cuban''in dominant erkek alicisini hedefler, donusum niyeti yuksek"}, {"tag": "Womens Bracelet", "reason": "Alici slotu (kadin) — unisex urunu kadin aramasina da acar, kitle genisletme"}, {"tag": "Unisex Bracelet", "reason": "Baslikla birebir (Unisex) — kimliksiz genis kitle sinyali"}, {"tag": "Gift for Him", "reason": "Hediye slotu — satin alma niyetli, erkek takı hediyesi aramasini yakalar"}, {"tag": "Gold Jewelry Gift", "reason": "Hediye slotu — genel altin taki hediyesi niyetli trafik"}, {"tag": "Statement Bracelet", "reason": "Stil/kullanim slotu — kalin Cuban link''in gorsel karakterine uygun"}, {"tag": "Everyday Bracelet", "reason": "Kullanim slotu — som altin dayanikliligi/gunluk giyim niyeti"}, {"tag": "Hip Hop Bracelet", "reason": "Tarz slotu — Miami Cuban kulturuyle dogal ortusen niyetli kitle"}]'::jsonb,'13 tag''in 4''u ("chain" iceren) urunu bilezik degil zincir/kolye arayan yanlis kitleye gosteriyor; bu leak''in (yuksek trafik/dusuk donusum) ana kaynagi. Ayrica "Miami Cuban" koku ~6 tag''de tekrarlanip slot israf ederken hediye/alici/kullanim slotlari hic yok.','Leak stratejisi geregi trafigi kesmeden relevance''i sikilastirdim. En kritik hamle: urun tipiyle CELISEN 4 ''chain'' tag''ini attim — bunlar bilezik degil zincir arayanlari cekip favori/goruntu uretip satin almadan cikartiyordu (conv %0.165''in yapisal nedeni). Ikinci hamle: ''Miami Cuban'' kokunun ~6 varyantli tekrarini 2 mesru long-tail''e indirdim (Miami Cuban Bracelet + Cuban Link Bracelet); Etsy zaten kelimeleri kendi kombinler, kok tekrari slot israfiydi. Bosalan 7+ slotu satin-alma niyetli eksenlere dagittim: alici (mens/womens/unisex), hediye (gift for him, gold jewelry gift), stil/kullanim (statement, everyday, hip hop), malzeme (yellow gold). Tum tag''ler cok-kelimeli long-tail, hepsi <=20 karakter, birebir tekrar yok; ''bracelet'' tekrari urun gercegi oldugu icin mesru (necklace/pendant kurali degil).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1283581532,'10K Gold Miami Cuban Link Chain Necklace','necklace','leak',ARRAY['Miami Chain','Miami Cuban Chain','Gold Chain','10K Chain','10K Gold Chain','Miami Link Chain','Cuban Link Chain','Gold Cuban Chain','Real Gold Chain','Gold Chain Men','Gold Cuban Necklace','Miami Necklace','10K Cuban Chain']::text[],ARRAY['Miami Cuban Link','Cuban Link Necklace','10K Solid Gold Chain','Real Gold Necklace','Gold Chain For Men','Mens Cuban Necklace','Hip Hop Jewelry','Gift For Him','Gift For Boyfriend','Everyday Gold Chain','Luxury Gold Chain','Mens Gift Idea','Thick Cuban Chain']::text[],'[{"tag": "Gold Chain", "reason": "Cok genel, tek-niyet ust-huni tag; en buyuk leak kaynagi — bol trafik ceker, alici degil bosgezer getirir."}, {"tag": "10K Chain", "reason": "Neredeyse tek-kelime, dusuk niyet; 10K zaten baslikta. ''10K Solid Gold Chain'' ile satin-alma-niyetli hale getirildi."}, {"tag": "Miami Chain", "reason": "''Miami Cuban Link'' ile ortulen zayif/genel varyant; kok tekrari (Miami+chain) slot israfi."}, {"tag": "Miami Cuban Chain", "reason": "Birebir''e yakin tekrar; Miami+Cuban+Link zaten ayri tag''lerde mevcut."}, {"tag": "Miami Link Chain", "reason": "Miami/link/chain uclusunun ucuncu tekrari — Etsy kelimeleri kendi kombinler, ekstra varyant slot yakar."}, {"tag": "Gold Cuban Chain", "reason": "Gold+Cuban+chain baska tag''lerde kapsandi; redundant."}, {"tag": "Gold Cuban Necklace", "reason": "Alici-hedefli ''Mens Cuban Necklace'' ile degistirildi — ayni urun tipi, daha dar/nitelikli kitle."}, {"tag": "Miami Necklace", "reason": "Ince/genel, dusuk niyet; Miami+necklace zaten ortuluyor."}, {"tag": "10K Cuban Chain", "reason": "10K+Cuban baska tag''lerde var; redundant, yeni slot getirmiyor."}, {"tag": "Gold Chain Men", "reason": "Gramersiz; alicinin aradigi tam ifade ''Gold Chain For Men'' ile duzeltildi."}]'::jsonb,'[{"tag": "10K Solid Gold Chain", "reason": "''Real/solid gold'' satin-alma dili — jenerik gold browser''i degil, som altin arayan nitelikli aliciyi ceker (leak karsiti)."}, {"tag": "Gift For Him", "reason": "Tamamen eksik hediye slotu; yuksek niyetli ''him'' hediye aramasi — leak''te browser''i alici niyetine kaydirir."}, {"tag": "Gift For Boyfriend", "reason": "Erkek takisinda devasa hediye-alici aramasi; net satin-alma niyeti, donusum kurtarici."}, {"tag": "Mens Gift Idea", "reason": "Ikinci hediye/alici slotu; erkek-agirlikli urun icin hediye-arayan kitleyi hedefler."}, {"tag": "Hip Hop Jewelry", "reason": "Stil slotu (Miami Cuban''in dogal kitlesi); niyet-tanimli, dar ve alakali."}, {"tag": "Luxury Gold Chain", "reason": "Stil/segment slotu; premium alici sinyali, dusuk-butce browser''i eler."}, {"tag": "Everyday Gold Chain", "reason": "Kullanim slotu; gunluk-tasima niyeti gercek alici davranisini yakalar."}, {"tag": "Gold Chain For Men", "reason": "Alicinin birebir aradigi tam long-tail; gramersiz ''Gold Chain Men''in yerine."}, {"tag": "Cuban Link Necklace", "reason": "Urun tipi (necklace) + cekirdek stil; baslikta ''necklace'' mesru — urun tipiyle uyumlu."}, {"tag": "Thick Cuban Chain", "reason": "Nitelik/urun-ozelligi long-tail''i; Cuban link dogasi geregi kalin — ''thick cuban'' guclu alici aramasi."}]'::jsonb,'Asiri redundancy (13 tag''in 11''inde ''chain'', Miami/Cuban/Gold ayni kokun varyantlariyla slot israfi) + sifir hediye/stil/kullanim slotu; genel ''Gold Chain''/''10K Chain'' tag''leri leak''i besliyor.','Arketip ''leak'' (views=64232 ama conv=0.118%): trafik bol, sorun donusum. Kok neden iki katmanli. (1) Asiri redundancy: eski sette ''chain'' 11/13, Miami 5, Cuban 6, Gold 7 tag''te — Etsy kelimeleri kendi kombinledigi icin bu varyantlar slot israfi ve hepsi TEK niyet (Miami Cuban gold chain) etrafinda donuyor. (2) Slot corakligi: hediye=0, stil=0 (hip hop/luxury yok), kullanim=0 (everyday yok), alici dili zayif (''Gold Chain Men'' gramersiz). Genel ''Gold Chain''/''10K Chain''/''Miami Chain'' tag''leri ust-huni browser''i ceker — leak''i tam bunlar besliyor. Cozum: (a) redundant kok varyantlarini kes (chain 11->5, gold 7->5, cuban 6->4), (b) genel tag''leri satin-alma-niyetli long-tail''e kaydir (''solid/real gold'', ''gold chain for men''), (c) eksik slotlari ac — 3 hediye (him/boyfriend/gift idea), 2 stil (hip hop/luxury), 1 kullanim (everyday), alici (mens). Tip-celiskisi yok (hepsi cuban/gold/necklace ile uyumlu); ''necklace'' baslikta oldugu icin mesru. ''Statement Necklace'' bilerek eklenmedi — kadin-moda terimi olarak erkek-agirlikli cuban chain''de yeni bir leak kaynagi olabilirdi. Tum tag''ler <=20 karakter, cok-kelimeli, birebir tekrar yok, TAM 13.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1336346678,'14K Yellow Gold Franco Bracelet – Minimalist Fine Jewelry Gift','bracelet','leak',ARRAY['Franco Bracelet','Gold Franco','Gold Franco Bracelet','Gold Mens Bracelet','Bracelet for men','Real Gold man chain','14K Gold Bracelet','solid gold bracelet','dainty gold bracelet','yellow gold bracelet','minimalist bracelet','gold bracelet women','14k jewelry gift']::text[],ARRAY['franco bracelet','14k gold bracelet','solid gold bracelet','yellow gold bracelet','dainty gold bracelet','minimalist bracelet','gold bracelet women','layering bracelet','everyday bracelet','gold gift for her','fine jewelry gift','mothers day gift','gift for girlfriend']::text[],'[{"tag": "Gold Franco", "reason": "Franco koku redundancy — ''franco bracelet'' slotu zaten Etsy''nin ''gold''+''franco'' kelimelerini kombinlemesini sagliyor; ayri slot israfi."}, {"tag": "Gold Franco Bracelet", "reason": "Ucuncu Franco varyanti; ''franco bracelet'' ile birebir ortusuyor, slot israfi."}, {"tag": "Gold Mens Bracelet", "reason": "Kitle celiskisi: baslik/urun ''minimalist fine jewelry gift'' + dainty/women cizgisinde; erkek trafigi gelip donusmuyor (leak kaynagi)."}, {"tag": "Bracelet for men", "reason": "Ayni erkek-kitle celiskisi; feminen/minimalist listing kimligiyle uyumsuz, yanlis trafik."}, {"tag": "Real Gold man chain", "reason": "TIP celiskisi — ''chain'' kelimesi kolye arayanini cekiyor (urun bilezik) + ''man'' kitle celiskisi; iki yonlu leak. ''real gold'' niyeti ''solid gold bracelet''te korunuyor."}, {"tag": "14k jewelry gift", "reason": "Belirsiz hediye ifadesi; daha net satin-alma-niyetli hediye slotlariyla (fine jewelry gift / mothers day / gift for her) yukseltildi."}]'::jsonb,'[{"tag": "layering bracelet", "reason": "Kullanim/stil slotu — franco''nun stackleme/layering kullanimi; yeni ve alici-niyetli anahtar ''layering''."}, {"tag": "everyday bracelet", "reason": "Kullanim slotu — gunluk takilabilir minimalist konumlandirmayi guclendirir, bracelet-disi niyet cesitlendirir."}, {"tag": "gold gift for her", "reason": "Hediye + kadin kitlesi netligi; listing kimligiyle uyumlu donusum-odakli ifade."}, {"tag": "fine jewelry gift", "reason": "Basliktaki ''Fine Jewelry Gift'' ifadesiyle birebir hizalanir; premium hediye niyeti."}, {"tag": "mothers day gift", "reason": "Occasion/hediye slotu — mevsimsel yuksek-niyetli arama, ''bracelet'' kokunu tekrar etmeden slot genisletir."}, {"tag": "gift for girlfriend", "reason": "Kadin hediye kitlesini netlestirir; bracelet kokunu tekrar etmeyen long-tail alici ifadesi, tutarli hediye acisini tamamlar."}]'::jsonb,'Etiketler celiskili kitle sinyali veriyor (mens + ''man chain'' vs dainty/minimalist/women) ve ''Franco'' koku 3 slot yiyor; minimalist bir kadin-hediye listing''ine yanlis/donusmeyen trafik cekiyor.','Leak arketipi (64K goruntuleme / %0.12 donusum) trafik degil DONUSUM problemi: etiketler iki celiskili kitleyi (mens/''man chain'' vs dainty/minimalist/women) ayni anda cekiyor ve gelen alicilarin bir kismi listing kimligiyle eslesmedigi icin satin almiyor. Uc buyuk sorun: (1) TIP celiskisi — ''Real Gold man chain'' bilezik listing''ine kolye arayanini getiriyor; (2) KITLE celiskisi — baslik ''Minimalist Fine Jewelry Gift'', urun dainty/women cizgisinde, ama 3 etiket erkek; (3) REDUNDANCY — ''Franco'' koku 3 slotta (Franco Bracelet / Gold Franco / Gold Franco Bracelet), Etsy zaten kelimeleri kombinlerken bu 2 slot israf. Cozum: relevance''i listing''in gercek kimligine (minimalist, dainty, yellow gold, kadin, hediye) sikilastirdim; tip/kitle celiskilerini attim; Franco''yu tek slota indirdim; acilan 6 slotu kullanim (layering, everyday) ve hediye/kitle netligi (gift for her, fine jewelry gift, mothers day, gift for girlfriend) ile doldurdum. ''real gold'' alici dili ''solid gold bracelet''te korunuyor. Cogunluk cok-kelimeli long-tail, birebir tekrar yok, hepsi <=20 karakter.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1355681376,'14K Solid Gold Diamond Cut Valentino Bracelet | Tri Color Link Chain','bracelet','leak',ARRAY['Valentino Chain','Valentino Bracelet','14K Gold Bracelet','Gold Link Bracelet','14K Link Bracelet','Tri Color bracelet','Solid Gold Bracelet','Diamond Cut Bracelet','14K Bracelet','Real Gold Bracelet','Link Chain Bracelet','14K Gold Chain','Rose Gold Bracelet']::text[],ARRAY['Valentino Bracelet','Valentino Chain','Diamond Cut Bracelet','14K Gold Bracelet','Solid Gold Bracelet','Real Gold Bracelet','Tri Color Gold','14k Italian Gold','Womens Gold Bracelet','Gift for Her','Mothers Day Gift','Gold Chain Bracelet','Stackable Bracelet']::text[],'[{"tag": "Rose Gold Bracelet", "reason": "Tip-çelişkisi: ürün tri-color (sarı/beyaz/rose karışık), som rose gold değil; sadece rose gold arayan alıcıyı çekip eşleşmeyince çıkıyor — leak''in ana kaynağı."}, {"tag": "14K Gold Chain", "reason": "Necklace/zincir niyetli terim; ürün bir BILEKLIK. Kolye arayan yanlış kitleyi getiriyor, tıklıyor ama almıyor (leak)."}, {"tag": "14K Bracelet", "reason": "Neredeyse tek-kelime + ''14K Gold Bracelet'' ile birebir kök tekrarı; slot israfı."}, {"tag": "Link Chain Bracelet", "reason": "Generic ''link/chain'' kökü zaten Valentino Chain + Gold Chain Bracelet ile karşılanıyor; düşük satın-alma niyeti."}, {"tag": "Gold Link Bracelet", "reason": "''link bracelet'' kökü fazlalık; Gold Chain Bracelet daha yüksek aranan varyantla değiştirildi."}, {"tag": "14K Link Bracelet", "reason": "14K + link kökünün üçüncü tekrarı; hiçbir yeni arama yüzeyi açmıyor."}, {"tag": "Tri Color bracelet", "reason": "''bracelet'' kökü zaten doygun; kavram ''Tri Color Gold'' olarak korunup malzeme sinyaline genişletildi."}]'::jsonb,'[{"tag": "Tri Color Gold", "reason": "Ayırt edici renk özelliğini korur ama ''bracelet'' tekrarından kaçıp ''gold'' malzeme sinyaline genişler."}, {"tag": "14k Italian Gold", "reason": "Valentino gerçek bir İtalyan zincir stili — yüksek relevance + ''italian gold'' premium/satın-alma-niyetli alıcı dili."}, {"tag": "Womens Gold Bracelet", "reason": "Eksik alıcı slotu; ince diamond-cut Valentino kadın hedef kitlesini doğru daraltır, dönüşümü kurtarır."}, {"tag": "Gift for Her", "reason": "Eksik hediye slotu; yüksek satın-alma niyetli sorgu, doğru alıcıyı çeker."}, {"tag": "Mothers Day Gift", "reason": "Sezonluk hediye slotu; takıda güçlü dönüşüm getiren niyet ifadesi."}, {"tag": "Gold Chain Bracelet", "reason": "Ürün gerçekte zincir-örgü bir bileklik; ''link/chain'' kökünün meşru tek varyantı, bileklik niyetini korur (kolye değil)."}, {"tag": "Stackable Bracelet", "reason": "Eksik kullanım slotu; ince Valentino için doğal ''stacking'' arama davranışını yakalar."}]'::jsonb,'Aşırı redundancy (bracelet/link/14k kökleri 10+ slotu yiyor) ve tip-çelişkili tag''ler (Rose Gold, 14K Gold Chain) yanlış kitle çekip dönüşümü boğuyor.','Arketip ''leak'' (61943 view, %0.155 conv): trafik var, kitle yanlış. Kök sorun iki katmanlı — (1) tip-çelişkisi: ''Rose Gold Bracelet'' (ürün tri-color) ve ''14K Gold Chain'' (ürün bileklik, kolye değil) alakasız/yanlış-niyetli tıklamayı besliyor; (2) aşırı redundancy: 13 tag''in 10''u ''bracelet'' ve 5''i ''14k/link'' kökünü tekrarlıyor, Etsy zaten kelimeleri kombinlediği için bu net slot israfı. Çözüm: çelişkili 2 tag atıldı, redundant link/14k varyantları tek meşru ''Gold Chain Bracelet''e indirildi ve boşalan slotlar satın-alma-niyetli eksenlere kaydırıldı — alıcı (womens), hediye (gift for her, mothers day), stil (italian gold), kullanım (stackable). Çekirdek yüksek-relevance terimler (Valentino Bracelet/Chain, Diamond Cut, Solid/Real/14K Gold Bracelet) korundu. Tüm 13 tag <=20 karakter ve çok-kelimeli.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1713308864,'10K Gold Nugget Heart Pendant Necklace | Diamond Cut Rope Chain','pendant','leak',ARRAY['Nugget Necklace','10K Gold Necklace','Gold Heart Necklace','10K Nugget Chain','Rope Chain','Rope Necklace','10K Gold Rope Chain','10K Rope Necklace','10K Necklace','Small Necklace','Gold Charm Necklace','Gold Large Necklace','Gold Medium Necklace']::text[],ARRAY['Gold Nugget Necklace','Gold Heart Pendant','Diamond Cut Chain','Rope Chain Necklace','10K Real Gold Chain','Solid Gold Pendant','Gold Chain for Men','Womens Gold Jewelry','Gold Gift for Her','Mothers Day Gift','Layering Necklace','Italian Gold Chain','Yellow Gold Pendant']::text[],'[{"tag": "Rope Chain", "reason": "Tek-kelime yoğun + ''rope chain'' kökü orijinalde 5 tag''de tekrar; Etsy kombinlediği için slot israfı. Konsept ''Rope Chain Necklace''te korundu."}, {"tag": "Rope Necklace", "reason": "Rope kökünün birebir tekrarı; yeni arama ifadesi getirmiyor."}, {"tag": "10K Gold Rope Chain", "reason": "Rope + 10K tekrarı; ''10K Real Gold Chain'' alıcı diliyle daha güçlü karşılıyor."}, {"tag": "10K Rope Necklace", "reason": "Rope+10K+necklace üçlü tekrar, saf redundancy."}, {"tag": "10K Nugget Chain", "reason": "Nugget kökü ''Gold Nugget Necklace''te var; bu varyant ek arama değeri katmıyor."}, {"tag": "10K Necklace", "reason": "Fazla generic + necklace tekrarı; dönüşüm getiren niyet taşımıyor."}, {"tag": "Small Necklace", "reason": "Beden tag''i (aynı anda Large+Medium var) çelişki yaratıyor; vague, düşük satın-alma niyeti."}, {"tag": "Gold Large Necklace", "reason": "Small ile doğrudan çelişen beden tag''i; hangi bedeni arayanı çekiyor belirsiz."}, {"tag": "Gold Medium Necklace", "reason": "Üçüncü çelişkili beden tag''i; slotları boşa harcayıp yanlış kitle çekiyor."}, {"tag": "Gold Charm Necklace", "reason": "''Charm'' ürün tipiyle (heart pendant) tam örtüşmüyor; ''Gold Heart Pendant'' başlık gerçeğine daha sadık."}, {"tag": "10K Gold Necklace", "reason": "Generic + necklace tekrarı; ''10K Real Gold Chain'' (alıcı dili ''real gold'') daha yüksek niyetli."}, {"tag": "Gold Heart Necklace", "reason": "Ürün tipi ''pendant'' olduğu için ''Gold Heart Pendant''e çevrildi (başlık/tip gerçeğiyle hizalı)."}, {"tag": "Nugget Necklace", "reason": "''Gold Nugget Necklace'' olarak genişletildi (materyal + tam 20 karakter değerlendirmesi)."}]'::jsonb,'[{"tag": "Gold Chain for Men", "reason": "Alıcı slotu (erkek) + ''gold chain for men'' yüksek hacimli alıcı dili; nugget/rope kombosu erkek kitlesine güçlü hitap eder."}, {"tag": "Womens Gold Jewelry", "reason": "Alıcı slotu (kadın) + ''jewelry'' yeni kök; heart pendant kadın alıcıyı hedefler, dönüşüm niyeti yüksek."}, {"tag": "Gold Gift for Her", "reason": "Hediye slotu; heart pendant klasik ''gift for her'' — satın-alma niyeti yüksek, leak''i kapatan kitle."}, {"tag": "Mothers Day Gift", "reason": "Sezonsal hediye slotu; kalp kolye + anneler günü çok güçlü dönüşüm kümesi."}, {"tag": "Layering Necklace", "reason": "Kullanım slotu; ince nugget/heart parça katmanlama aramalarında satın alınır."}, {"tag": "Italian Gold Chain", "reason": "Stil slotu; rope chain gerçeğiyle uyumlu (italian rope yaygın), tip çelişkisi yok."}, {"tag": "Solid Gold Pendant", "reason": "Alıcı dili (''solid gold'') + pendant tip hizası; imitasyon değil gerçek altın arayan yüksek-niyetli alıcıyı filtreler."}, {"tag": "10K Real Gold Chain", "reason": "''real gold'' alıcı dili; materyal (10k real gold) doğrudan destekliyor, kalite arayan alıcıyı çeker."}, {"tag": "Diamond Cut Chain", "reason": "Başlıktaki ''Diamond Cut'' niteliğini bağımsız arama ifadesi olarak açar."}, {"tag": "Yellow Gold Pendant", "reason": "Materyal varyantı (yellow gold) + pendant tip hizası; renk-spesifik aramayı yakalar."}]'::jsonb,'Aşırı redundancy (necklace 10x, rope 5x) + çelişkili beden tag''leri (small/large/medium birlikte) + hiç alıcı/hediye/stil/kullanım slotu yok — trafik geliyor ama yanlış/dağınık kitle dönüşümü öldürüyor.','Leak stratejisi = trafik var, dönüşümü kurtar. Yaklaşım: (1) redundancy''yi kes — ''necklace'' 10→3 kontrollü varyant, ''rope'' 5→1 (''Rope Chain Necklace''); her tag benzersiz arama ifadesi taşıyor. (2) Çelişkili 3 beden tag''ini (small/large/medium) tamamen at — kitle dağıtıcı, düşük niyet. (3) Boş slotları doldur: alıcı (men/womens), hediye (for her/mothers day), kullanım (layering), stil (italian), alıcı-dili materyal (real/solid gold). (4) Tip-çelişkisi kontrolü: ''necklace'' başlık ''Pendant Necklace'' olduğu için MEŞRU tutuldu (körlemesine silinmedi); ''italian/diamond cut'' rope gerçeğiyle uyumlu tutuldu ama ''miami cuban'' KOYULMADI (rope ile çelişir). Hepsi çok-kelimeli long-tail ve ≤20 karakter. Necklace=3, chain=5 (her biri farklı modifier: diamond cut/rope/10K real/for men/italian → distinct fraz), pendant=3 dengeli dağıldı.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1442796773,'14K Solid Gold Valentino Link Chain Necklace | Diamond Cut Tri-Color','necklace','leak',ARRAY['Valentino Chain','14K Gold Chain','14K Valentino','Gold Link Chain','Tri Color Chain','Rose Gold Chain','White Gold Chain','14K Gold Chain Men','Valentino Necklace','Solid Gold Chain','14K Gold Necklace','Mirror Chain','Rose Gold Necklace']::text[],ARRAY['Valentino Chain','14K Gold Chain','Tri Color Chain','Valentino Necklace','Solid Gold Chain','14K Gold Necklace','Diamond Cut Chain','Real Gold Necklace','Gold Chain for Her','Layering Necklace','Italian Gold Chain','Womens Gold Chain','Gift for Her']::text[],'[{"tag": "14K Valentino", "reason": "Redundant kok: ''Valentino'' + ''14K'' zaten iki ayri tag''de var; slot israfi."}, {"tag": "Gold Link Chain", "reason": "Cok genel, dusuk satin-alma niyeti; ''link chain'' nitelenmemis genis trafik ceker."}, {"tag": "Rose Gold Chain", "reason": "SOLID rose gold ima eder; urun tri-color -> kitle celiskisi/leak, Tri Color ile mukerrer."}, {"tag": "White Gold Chain", "reason": "SOLID white gold ima eder; urun tri-color -> ayni mismatch, mukerrer renk slotu."}, {"tag": "14K Gold Chain Men", "reason": "Kitle celiskisi: zarif tri-color Valentino womens/unisex; erkek-zincir alicisini cekip sekten dusuruyor -> ana leak kaynagi."}, {"tag": "Mirror Chain", "reason": "Belirsiz/mustesnalik dusuk terim; zayif alici alaka, yanlis kitle riski."}, {"tag": "Rose Gold Necklace", "reason": "Mukerrer renk + solid-rose mismatch; ucuncu rose gold slotu tamamen israf."}]'::jsonb,'[{"tag": "Diamond Cut Chain", "reason": "Basliktaki ana stil niteligi; satin-alma niyetli, dogru alicida donusumu artirir."}, {"tag": "Real Gold Necklace", "reason": "Alici dili (''real gold'') solid urunu net anlatir; kaplama-arayanlari eler, niyetliyi ceker."}, {"tag": "Gold Chain for Her", "reason": "Eksik hediye+kitle slotu; kadin/hediye satin-alma niyetli long-tail."}, {"tag": "Layering Necklace", "reason": "Eksik kullanim slotu; ince zincir katmanlama arayan donusum-yuksek kitle."}, {"tag": "Italian Gold Chain", "reason": "Eksik stil slotu; Valentino Italyan-link tarzi, kaliteli-alici dili."}, {"tag": "Womens Gold Chain", "reason": "Dogru kitle sinyali; erkek tag''i yerine urun-tipine uygun donusumlu kitle."}, {"tag": "Gift for Her", "reason": "Eksik hediye slotu; evergreen hediye niyeti donusum icin guclu."}]'::jsonb,'Renk/kitle celisen tag''ler (solid rose/white gold ve ''Men'') tri-color womens Valentino urunune yanlis alici cekiyor: yuksek trafik, dusuk donusum.','Leak stratejisi: trafik zaten yuksek, sorun donusum. Uc buyuk hata giderildi: (1) Kitle celiskisi — ''Rose Gold Chain'', ''White Gold Chain'', ''Rose Gold Necklace'' solid tek-ton ima ederken urun tri-color; bunlar yanlis beklentiyle tiklayip cikan alici cekiyordu, ayrica ''14K Gold Chain Men'' zarif Valentino''ya erkek-zincir alicisi cekiyordu. (2) Redundancy — Valentino 3 kez, 14K bircok kez; ''14K Valentino'' ve ''Gold Link Chain'' kok israfiydi. (3) Eksik niyet slotlari — hic hediye/kullanim/stil/kadin-niyet tag''i yoktu. Yeni set relevance''i sikilastirir (Tri Color differentiator korundu), satin-alma-niyetli alici dili (real/solid gold), dogru kitle (womens, gift for her) ve stil/kullanim (diamond cut, italian, layering) slotlari ekler. 13/13 dolu, hepsi <=20 karakter, tamami cok-kelimeli, birebir tekrar yok."','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1469384188,'10K Gold Diamond Cut Bamboo Hoop Earrings | Large Yellow Gold Jewelry','earring','leak',ARRAY['Hoop Earrings','Gold Hoop Earrings','Diamond Cut Earrings','Graduated Hoop','Gold Graduated','Bamboo Hoop Earrings','Gold Bamboo Earrings','Large Hoop Earrings','Real Gold Earrings','10K Gold Hoop','Bamboo Earrings','Graduated Earrings','10K Gold Earrings']::text[],ARRAY['Gold Hoop Earrings','Bamboo Hoop Earrings','Diamond Cut Earrings','Large Hoop Earrings','Real Gold Earrings','10K Gold Earrings','Graduated Hoop','Gift for Her','Womens Gold Hoops','Statement Earrings','Mothers Day Gift','Yellow Gold Hoops','Everyday Earrings']::text[],'[{"tag": "Hoop Earrings", "reason": "Çok genel/zayıf; kökü ''Gold Hoop Earrings'' + ''Large Hoop Earrings'' zaten kapsıyor — geniş kitle + slot israfı."}, {"tag": "Gold Graduated", "reason": "''graduated'' için 3 slot kullanılmış; tek ''Graduated Hoop'' yeterli, gerisi tekrar."}, {"tag": "Gold Bamboo Earrings", "reason": "''Bamboo Hoop Earrings'' ile aynı kök (bamboo+gold+earrings) tekrarı; Etsy kombinler."}, {"tag": "10K Gold Hoop", "reason": "10k+gold+hoop üçlüsü ''10K Gold Earrings'' ve gold-hoop tag''lerinde zaten var; redundant."}, {"tag": "Bamboo Earrings", "reason": "''Bamboo Hoop Earrings'' varken alt-küme tekrarı; slot israfı."}, {"tag": "Graduated Earrings", "reason": "Üçüncü ''graduated'' slotu; tek graduated tag yeterli."}]'::jsonb,'[{"tag": "Gift for Her", "reason": "Hediye slotu tamamen eksikti; satın-alma niyetli, dönüşüm kurtarıcı."}, {"tag": "Womens Gold Hoops", "reason": "Alıcı (womens) slotu yok; başka nitelikle yeni arama yakalar."}, {"tag": "Statement Earrings", "reason": "Stil/kullanım slotu; büyük graduated bambu hoop statement parça olarak aranıyor."}, {"tag": "Mothers Day Gift", "reason": "Occasion/hediye slotu; altın takıda yüksek dönüşümlü niyet."}, {"tag": "Yellow Gold Hoops", "reason": "Başlıktaki ''yellow gold'' + malzeme sarı altın aramasını yakalar; hiç yoktu."}, {"tag": "Everyday Earrings", "reason": "Kullanım slotu; günlük takı niyetiyle eşleşir, kitleyi genişletir."}]'::jsonb,'Aşırı redundancy: 13 slotun tamamı "hoop/earrings/gold/bamboo/graduated" köklerini tekrar ediyor (Etsy zaten kombinler), hediye/stil/kullanım/alıcı slotları hiç yok — yüksek trafik ama düşük dönüşümün (leak) kaynağı bu.','Ürün tipi çelişkisi YOK — tüm mevcut tag''ler earring-ilgili ve doğru (10K, diamond cut, bamboo, graduated, large, yellow gold hepsi gerçek). Sorun tip-çelişkisi değil, aşırı redundancy + eksik intent slotları. ''Earrings'' 10 tag''de, ''hoop'' 5''te, ''gold'' 7''de, ''bamboo'' 4''te, ''graduated'' 3''te geçiyordu; Etsy kelimeleri kendisi kombinlediği için bu kökleri tekrarlamak net slot israfı. Redundant varyantları budayıp en güçlü long-tail''leri tuttum (Gold/Bamboo/Large Hoop Earrings, Diamond Cut, Real Gold, 10K Gold, tek Graduated Hoop) ve boşalan 6 slotu leak arketipinin ihtiyacı olan dönüşüm-niyetli ifadelere kaydırdım: hediye (Gift for Her, Mothers Day Gift), alıcı (Womens Gold Hoops), stil (Statement Earrings), malzeme-aramasi (Yellow Gold Hoops — başlıkta var, tag''de yoktu), kullanım (Everyday Earrings). ''Graduated Hoop'' başlıkta geçmese de düşük-rekabetli gerçek bir özellik olduğu için körlemesine silmedim, tek slota indirdim. 13/13 çok-kelimeli, hepsi ≤20 karakter, birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1294201622,'10K Solid Gold Herringbone Necklace, High Polish Snake Chain','necklace','leak',ARRAY['herringbone necklace','gold chain','snake chain','flat gold chain','thick gold necklace','gold plated','necklace for women','layering necklace','anniversary gift','birthday gift for her','gift for mom','minimalist necklace','y2k jewelry','statement necklace']::text[],ARRAY['herringbone necklace','solid gold necklace','10k gold necklace','snake chain necklace','flat gold chain','real gold jewelry','necklace for women','layering necklace','gift for her','anniversary gift','gift for mom','italian gold chain','statement necklace']::text[],'[{"tag": "gold plated", "reason": "Urun 10K SOLID GOLD — ''plated'' birebir celiski; bargain/kostum kitlesi cekiyor, leak''in ana kaynagi."}, {"tag": "birthday gift for her", "reason": "21 karakter, Etsy 20 sinirini asiyor (gecersiz); ''gift for her'' ile karsilandi."}, {"tag": "gold chain", "reason": "Tek-kokli generic + baslikta baskin ''gold/chain'' zaten var; flat/snake varyantlariyla redundant, slot israfi."}, {"tag": "thick gold necklace", "reason": "gold+necklace tekrari; ''thick'' cuban/rope alicilari yaniltir, herringbone flat bir zincir."}, {"tag": "snake chain", "reason": "Ayni kok; ''snake chain necklace'' long-tail varyantiyla degistirildi (urun-tipi kelimesi eklendi)."}, {"tag": "y2k jewelry", "reason": "Trend/ucuz-moda kitlesi; som 10K altin icin dusuk-niyet trafik ceker, leak besler."}, {"tag": "minimalist necklace", "reason": "High-polish herringbone bir statement parca; ''minimalist'' dainty arayan yanlis kitleyi cagirir, statement ile celisir."}]'::jsonb,'[{"tag": "solid gold necklace", "reason": "Satin-alma-niyetli ''real gold'' dili; plated celiskisini duzeltip dogru (som altin) alicyi hedefler."}, {"tag": "10k gold necklace", "reason": "Malzemeye tam uyan yuksek-niyet arama; ayar-spesifik alici filtreler."}, {"tag": "real gold jewelry", "reason": "Alici dili; ''plated'' arayanin tam karsiti gercek-altin kitlesini yakalar, donusum kurtarici."}, {"tag": "snake chain necklace", "reason": "Baslik terimi ''snake chain'' + urun-tipi ''necklace'' long-tail; dar ''snake chain''i genisletir."}, {"tag": "gift for her", "reason": "Gecersiz uzun tag''in yerine; genis hediye niyeti, <=20 karakter."}, {"tag": "italian gold chain", "reason": "Stil/kalite slotu; herringbone genelde ''italian'' olarak aranir, premium alici niyeti ekler."}]'::jsonb,'"gold plated" tag on a 10K SOLID GOLD listing pulls the wrong (bargain) audience — the core leak — while a 21-char tag and 4 redundant gold/chain descriptors waste slots that should carry real-gold purchase-intent terms.','Leak arketipi: trafik yuksek (47K views) ama donusum dusuk (0.112%) — tag''ler yanlis kitle cekiyor. En buyuk suclu ''gold plated'' tag''inin 10K SOLID GOLD urunde durmasi: bargain/kostum shopper''i getirip gercek-altin fiyatinda kaciriyor. Cozum: (1) celiskiyi at, som-altin purchase-intent dili ekle (solid gold, 10k gold, real gold) — donusumu kurtaran alici sinyali; (2) 4 redundant gold/chain descriptor''unu (gold chain, thick, snake chain, flat) tek guclu long-tail setine indir, bosalan slotlari niyetli terimlerle doldur; (3) yanlis-kitle stil tag''lerini (y2k, minimalist) at, urun gercegine uyan statement + italian stil ekle; (4) 21-karakterlik gecersiz tag''i kurala uygun ''gift for her'' ile degistir. Hediye slotlari (anniversary, mom, her) korunur cunku takida guclu satin-alma tetikleyicisi. Necklace-tipi tutarli: tum tag''ler kolye/zincir gercegiyle uyumlu, celiski yok. 13/13 dolu, hepsi <=20 karakter, cogunlugu multi-word long-tail.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1296858064,'10K Solid Gold Bead Ball Chain Necklace - Diamond Cut','necklace','leak',ARRAY['Bead Ball Chain','Bead Ball Necklace','Gold Beads Chain','10K Gold Necklace','10K Gold Chain','Gold Moon Necklace','Beaded Chain','Half Moon Chain','Diamond Cut Necklace','Diamond Cut Chain','Solid Gold Necklace','Solid Gold Chain','10K Chain']::text[],ARRAY['Bead Ball Chain','Beaded Chain','10K Gold Necklace','10K Gold Chain','Solid Gold Chain','Diamond Cut Chain','Moon Cut Chain','Gold Chain for Men','Mens Gold Necklace','Gift for Him','Real Gold Chain','Layering Necklace','Italian Gold Chain']::text[],'[{"tag": "Gold Moon Necklace", "reason": "Tip celiskisi/leak: ay-sekilli kolye arayanlari cekiyor; urun ay-KESIM bead ball zinciri. ''Moon Cut Chain'' ile dogru sekilde geri kazanildi."}, {"tag": "Half Moon Chain", "reason": "Tip celiskisi/leak: yarim-ay sekli cagristiriyor, urunle alakasiz kitle — yuksek trafik dusuk donusumun kaynagi."}, {"tag": "Bead Ball Necklace", "reason": "Redundancy: ''bead ball'' koku 4 varyantta tekrarliyor; slot israfi. Chain+necklace formu zaten korundu."}, {"tag": "Gold Beads Chain", "reason": "Redundancy: yine ''bead ball/beaded'' koku; Etsy kombinleri kendisi kurar."}, {"tag": "Diamond Cut Necklace", "reason": "Redundancy: ''Diamond Cut Chain'' ile ayni kok; necklace tipi baska tag''lerde mevcut."}, {"tag": "Solid Gold Necklace", "reason": "Redundancy: ''Solid Gold Chain'' ile ayni kok; iki formdan biri yeter."}, {"tag": "10K Chain", "reason": "Cok dar/generik ve neredeyse tek-kelime; ''10K Gold Chain'' tarafindan zaten kapsaniyor."}]'::jsonb,'[{"tag": "Moon Cut Chain", "reason": "Urunun GERCEK sektor terimi (diamond/moon cut faceted ball chain) — hem relevance''i sikilastirir hem satici-niyetli aramayi yakalar; yanlis ''moon'' tag''lerini dogrusuyla degistirir."}, {"tag": "Gold Chain for Men", "reason": "Alici slotu: bead ball/moon cut zincirler hip-hop/erkek segmentinde guclu; satin-alma-niyetli ifade."}, {"tag": "Mens Gold Necklace", "reason": "Alici slotu: erkek kitlesini nitelendirir, genel trafigi donusume yakin aramayla degistirir."}, {"tag": "Gift for Him", "reason": "Hediye slotu: som altin zincir tipik erkek hediyesi; yuksek niyetli arama."}, {"tag": "Real Gold Chain", "reason": "Alici dili: ''real gold'' som altin arayanin gercek arama terimi; kaplama arayani eler, donusumu artirir."}, {"tag": "Layering Necklace", "reason": "Kullanim slotu: katmanlama trendi kadin/unisex kitleyi dengeler, stil-niyetli arama."}, {"tag": "Italian Gold Chain", "reason": "Stil/kalite slotu: som altin zincir alicisinin kalite sinyali aramasi; premium niyet."}]'::jsonb,'"Gold Moon Necklace" ve "Half Moon Chain" tag''leri ay-sekilli/crescent kolye arayan yanlis kitleyi cekiyor — urun aslinda ay-KESIM (moon cut / diamond cut) bead ball zinciri; bu terim karisikligi leak''in ana kaynagi.','Arketip ''leak'' (40K view / %0.106 conv): trafik var ama tag''ler yanlis kitle cekiyor. Iki kok sorun: (1) TIP CELISKISI — ''Gold Moon Necklace'' + ''Half Moon Chain'' ay-sekilli takı arayanı getiriyor; urun ise ay-KESIM (moon/diamond cut) bead ball zinciri. Bu terim karisikligi dogrudan donusumu oldürüyor. Cozum: bunlari at, sektorel dogru terim ''Moon Cut Chain'' ile relevant sekilde geri kazan. (2) ASIRI REDUNDANCY — 13 slotun 7''si ayni koklerin varyanti (bead ball x4, diamond cut x2, solid gold x2, 10K x3). Etsy kelimeleri kendisi kombinledigi icin bu slot israfi. Bosalan slotlari satin-alma-niyetli ve eksik kitle/hediye/stil/kullanim terimleriyle doldurdum: alici (Gold Chain for Men, Mens Gold Necklace), hediye (Gift for Him), alici-dili (Real Gold Chain), stil (Italian Gold Chain), kullanim (Layering Necklace). Necklace tipi mesru sekilde korundu (10K Gold Necklace, Mens Gold Necklace, Layering Necklace). Sonuc: 6 core korundu, 7 zayif/celiskili at, 7 niyetli ekle; tum tag <=20 char, hicbiri tek-kelime.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1615728651,'Solid 14K Yellow Gold Miami Cuban Link Chain Necklace, Heavy Curb Unisex Jewelry','necklace','leak',ARRAY['14K Gold Chain','Miami Cuban Chain','14K Gold Necklace','Gold Link Chain','Miami Cuban Necklace','Gold Cuban Chain','Gold Curb Chain','Solid Gold Chain','cuban link chain','mens gold chain','gold chain for men','gift for him','hip hop jewelry']::text[],ARRAY['Miami Cuban Chain','Cuban Link Necklace','14K Gold Necklace','Solid Gold Necklace','Real Gold Chain','Gold Curb Chain','Heavy Gold Chain','Gold Chain for Men','Unisex Jewelry','Gift for Him','Statement Necklace','Chunky Cuban Chain','Mens Gold Jewelry']::text[],'[{"tag": "14K Gold Chain", "reason": "''14K Gold Necklace'' ile ayni 14k+gold kokunu tekrar ediyor; slot bosa gidiyor."}, {"tag": "Miami Cuban Necklace", "reason": "''Miami Cuban Chain'' + ''Cuban Link Necklace'' ile ortusen 4. cuban tag''i; asiri redundancy."}, {"tag": "Gold Cuban Chain", "reason": "Cuban koku zaten 3 tag''te; ayni sorguyu ucuncu kez yakaliyor, yeni kitle getirmiyor."}, {"tag": "cuban link chain", "reason": "Urun-tipi eslesmesi icin ''Cuban Link Necklace'' daha yuksek niyetli; chain varyanti fazlalik."}, {"tag": "Gold Link Chain", "reason": "Cok genel/dusuk-niyet; gorunumu buyutup donusumu dusuren gevsek trafik (leak) besliyor."}, {"tag": "Solid Gold Chain", "reason": "''Solid Gold Necklace'' ile degistirildi — urun-tipi (necklace) eslesmesi + chain koku yiginini azaltir."}, {"tag": "mens gold chain", "reason": "''gold chain for men'' ile neredeyse birebir dup; uzun-kuyruklu olani tutuldu, slot acildi."}, {"tag": "hip hop jewelry", "reason": "LEAK SURUCUSU: ucuz/plated arayan yuksek-hacim dusuk-niyet browser cekiyor; som 14K lukse mismatch, view uretir satis uretmez."}]'::jsonb,'[{"tag": "Cuban Link Necklace", "reason": "Alicinin birebir yazdigi yuksek-niyetli urun-tipi ifadesi (cuban link + necklace)."}, {"tag": "Solid Gold Necklace", "reason": "Authenticity + urun-tipi; ''som altin'' arayan ciddi aliciyi filtreler, donusum getirir."}, {"tag": "Real Gold Chain", "reason": "Alici dili ''real gold''; plated arayani eleyip gercek-altin niyetlisini hedefler."}, {"tag": "Heavy Gold Chain", "reason": "Basliktaki ''Heavy'' sinyali; agir som parca degerini/niyetini vurgular."}, {"tag": "Unisex Jewelry", "reason": "Basligin unisex iddiasini onurlandirir; mens-only darligini kaliteli aliciya genisletir."}, {"tag": "Statement Necklace", "reason": "Kullanim/stil slotu; agir cuban''a uyar (ince ''layering'' celiskisinden kacinildi)."}, {"tag": "Chunky Cuban Chain", "reason": "Kalin-zincir arayanini yakalar; agir cuban icin yuksek niyet, yeni descriptor kokunu ekler."}, {"tag": "Mens Gold Jewelry", "reason": "Kategori/hediye browser''ini niyetle yakalar; chain-koku yiginina girmeden mens kategorisini genisletir."}]'::jsonb,'Leak: 4 cuban + 5+ "gold chain" tekrarı slotları boşa harcarken "hip hop jewelry" yüksek-hacimli düşük-niyetli browser çekiyor; som 14K lüks parça için authenticity/hediye/kullanım niyet slotları eksik.','Leak stratejisi: trafik bol, donusum olu — relevance''i sikilastir ve satin-alma niyetine kaydir. (1) Redundancy kesildi: cuban 4->3, 14K 2->1, near-dup mens 2->1; birbirini kanibalize eden kokler yeni SLOT''lara acildi. (2) Leak sürücüsü ''hip hop jewelry'' ve genel ''Gold Link Chain'' atildi — bunlar som-14K luks parcayla niyet-mismatch yapan yuksek-hacim gevsek trafigi getiriyordu. (3) Donusum slotlari eklendi: authenticity (Solid/Real Gold), urun-tipi eslesmesi (Cuban Link Necklace), title-dayanakli deger sinyali (Heavy), unisex kitle (Unisex Jewelry, basligi onurlandirir), kullanim/stil (Statement, Chunky). Agir cuban statement parca oldugu icin ''layering'' BILEREK konmadi (ince-katman aliciyi ceker, leak''i buyutur = urun celiskisi). Tum 13 tag cok-kelimeli, <=20 karakter, birebir tekrar yok, mens cekirdek donusum kitlesi korunurken unisex+hediye ile genisletildi.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1520386344,'10K Gold Last Supper Pendant Necklace, Miami Cuban Chain','pendant','leak',ARRAY['10K Gold Pendant','Egypt Jewelry','Egypt Pendant','Miami Cuban Chain','Last Supper Pendant','Jesus Pendant','Diamond Cut Pendant','White Gold Pendant','Cuban Link Chain','10K Gold Pendant men','Religious Pendant','Egyptian Pendant','10K Gold Necklace']::text[],ARRAY['10K Gold Pendant','Last Supper Pendant','Jesus Piece Necklace','Miami Cuban Chain','Diamond Cut Pendant','Real Gold Necklace','Solid Gold Pendant','Mens Gold Necklace','Christian Necklace','Religious Jewelry','Gold Chain For Him','Hip Hop Jewelry','Gift For Him']::text[],'[{"tag": "Egypt Jewelry", "reason": "Tip/tema celiskisi: urun Hristiyan Last Supper piece; Misir teması alakasiz kitle cekiyor (kacagin ana kaynagi)."}, {"tag": "Egypt Pendant", "reason": "Ayni Misir celiskisi; urunle ilgisiz."}, {"tag": "Egyptian Pendant", "reason": "Ucuncu Misir varyanti — hem alakasiz hem redundant slot israfi."}, {"tag": "White Gold Pendant", "reason": "Malzeme Yellow Gold/10K; beyaz altin iddiasi malzemeyle celisiyor, yanlis beklenti/kitle."}, {"tag": "Jesus Pendant", "reason": "Jesus Piece Necklace''e yukseltildi — hip-hop satin-alma niyetli terim + necklace slotu."}, {"tag": "Cuban Link Chain", "reason": "Miami Cuban Chain ile ayni kok (cuban) — redundant; slot hediye/stile aktarildi."}, {"tag": "10K Gold Pendant men", "reason": "Ucuncu 10K Gold tekrari + garip dizim; Mens Gold Necklace daha temiz alici hedefi."}, {"tag": "Religious Pendant", "reason": "Christian Necklace + Religious Jewelry olarak somutlastirildi (dogru din + genis relevance)."}, {"tag": "10K Gold Necklace", "reason": "10K Gold Pendant ile redundant; necklace kavrami satin-alma-niyetli Real/Mens/Christian varyantlarina tasindi."}]'::jsonb,'[{"tag": "Jesus Piece Necklace", "reason": "Guclu hip-hop alici terimi; dogru kitleyi (altin zincir alan erkekler) hedefler + necklace slotu."}, {"tag": "Real Gold Necklace", "reason": "Alici dili / satin-alma niyeti — sahte-kaplama arayanlari eleyip som altin alicisini ceker, donusumu kurtarir."}, {"tag": "Solid Gold Pendant", "reason": "Som altin niyet ifadesi; degeri onaylayarak fiyat-uyumlu alicilari yakalar."}, {"tag": "Mens Gold Necklace", "reason": "Alici/cinsiyet slotu — dogru kitleyi netlestirir."}, {"tag": "Christian Necklace", "reason": "Dogru din-relevance; Egypt yerine gercek temaya oturtur, niyetli aramayi yakalar."}, {"tag": "Religious Jewelry", "reason": "Genis dogru-tema relevance; dini takı arayan kitleyi ceker."}, {"tag": "Gold Chain For Him", "reason": "Hediye + alici slotu; erkege altin zincir arayan yuksek-niyet aramasi."}, {"tag": "Hip Hop Jewelry", "reason": "Stil/kullanim slotu — Jesus piece + Miami cuban tam bu tarzin arama dili."}, {"tag": "Gift For Him", "reason": "Hediye slotu; mevcut trafigi hediye-niyetli alicilarla donusume tasir."}]'::jsonb,'Uc adet Egypt/Egyptian etiketi, Hristiyan bir Last Supper/Jesus-piece kolyesine yanlis (Misir) kitle cekiyor — donusumu oldiren ana kacak.','Leak stratejisi: trafik zaten var, sorun relevance ve niyet. En buyuk zarar 3 Egypt etiketi + celiskili White Gold — bunlar Hristiyan/hip-hop bir urune yanlis kitle cekiyordu; hepsi atildi. Redundancy temizlendi (3x 10K Gold → 1, 2x cuban → 1). Bosalan slotlar satin-alma-niyetli ve dogru-kitle ifadeleriyle dolduruldu: alici dili (real/solid gold), cinsiyet (mens), hediye (for him), stil (hip hop), dogru din (christian/religious). Necklace etiketleri korlemesine silinmedi — baslik ''Pendant Necklace'' + ''Miami Cuban Chain'' oldugundan necklace MESRU; sadece niyetli varyantlara kaydirildi. Tum 13 etiket cok-kelimeli long-tail ve <=20 karakter; pendant/necklace/chain kokleri farkli niteleyicilerle dengeli dagitildi.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1481715945,'10K Yellow Gold Graduated Hoop Earrings | Diamond Cut','earring','leak',ARRAY['Graduated Earrings','Hoop Earrings','Gold Hoop Earrings','Gold Graduate','Diamond Cut Earrings','Diamond Cut Hoop','10K Gold Earrings','Real Gold Earrings','10K Gold Hoop','Satin Earrings','Round Hoop Earrings','10K Hoop Earrings','10K Round Earrings']::text[],ARRAY['Gold Hoop Earrings','Diamond Cut Hoops','10K Gold Earrings','Real Gold Hoops','Graduated Hoops','Womens Hoop Earrings','Gold Hoops for Her','Everyday Gold Hoops','Solid Gold Earrings','Yellow Gold Hoops','Round Hoop Earrings','Statement Gold Hoop','Gift for Women']::text[],'[{"tag": "Gold Graduate", "reason": "En buyuk leak: ''graduate'' mezuniyet-hediyesi aramasini cekiyor, altin halka alicisiyla alakasiz -> yuksek trafik dusuk donusumun ana kaynagi."}, {"tag": "Graduated Earrings", "reason": "Ayni mezuniyet belirsizligi; urun-dogru ''Graduated Hoops'' ile degistirildi (hoop''a capalandi)."}, {"tag": "Hoop Earrings", "reason": "Cok genis/generik, dusuk satin-alma niyeti; long-tail varyantlar zaten kapsiyor."}, {"tag": "Diamond Cut Earrings", "reason": "Hoop''a ozgu ''Diamond Cut Hoops'' daha yuksek relevance; genel ''earrings'' formu gereksiz."}, {"tag": "10K Gold Hoop", "reason": "10K+hoop tekrari; 10K Gold Earrings + Gold Hoops varyantlariyla cakisiyor, slot israfi."}, {"tag": "10K Hoop Earrings", "reason": "Ayni 10K+hoop kokunun bir baska tekrari, yeni sinyal katmiyor."}, {"tag": "10K Round Earrings", "reason": "10K tekrari; ''round'' zaten Round Hoop Earrings ile karsilaniyor."}, {"tag": "Satin Earrings", "reason": "Dusuk-niyetli finish terimi; urunun satis finish''i ''diamond cut'', satin kafa karistirici."}, {"tag": "Real Gold Earrings", "reason": "Hoop''a ozgu ''Real Gold Hoops'' ile daraltildi (buyer dili + urun tipi)."}, {"tag": "Diamond Cut Hoop", "reason": "Cogul, arama-dostu ''Diamond Cut Hoops'' formuna guncellendi."}]'::jsonb,'[{"tag": "Diamond Cut Hoops", "reason": "Basligin ayirt edici ozelligi, hoop''a capali cogul arama formu."}, {"tag": "Real Gold Hoops", "reason": "Buyer dili (''real gold'') + hoop tipi; som altin alim niyetini yakalar."}, {"tag": "Graduated Hoops", "reason": "Urun-dogru (kademeli boy) terim; leak yaratan ''Gold Graduate'' yerine gecti."}, {"tag": "Womens Hoop Earrings", "reason": "Eksik alici slotu; hoop''un ana hedef kitlesi."}, {"tag": "Gold Hoops for Her", "reason": "Eksik hediye slotu; yuksek niyetli ''for her'' aramasi."}, {"tag": "Everyday Gold Hoops", "reason": "Eksik kullanim slotu; gunluk takilabilir konumlama donusumu artirir."}, {"tag": "Solid Gold Earrings", "reason": "Buyer dili (''solid gold''); kaplama degil som altin arayan alicilari filtreler."}, {"tag": "Yellow Gold Hoops", "reason": "Basliktaki renk niteligini arama slotuna tasir."}, {"tag": "Statement Gold Hoop", "reason": "Stil slotu; diamond-cut + graduated''in gosterisli karakterini hedefler."}, {"tag": "Gift for Women", "reason": "Hediye-niyetli slot, yil boyu (sezon riski yok), kadin alici sinyalini pekistirir."}]'::jsonb,'"Gold Graduate" + "Graduated Earrings" mezuniyet-hediyesi trafigi cekiyor (yanlis kitle -> leak); buyer/hediye/kullanim slotu hic yok, 10K+hoop tekrari slot israfi.','Arketip ''leak'': trafik bol (31805 goruntu) ama donusum %0.236 - tag''ler yanlis kitle cekiyor. Kok neden ''Gold Graduate'' ve ''Graduated Earrings'': ''graduate'' mezuniyet-hediyesi arayanlari getiriyor, altin halka alicisi degil. Bunlari attim, sadece urun-dogru ''Graduated Hoops'' birakildi. Ikinci sorun: 4x ''10K'' ve cok sayida ciplak ''hoop/round earrings'' tekrari relevance eklemeden slot yiyordu; bunlari tek guclu 10K + tek Round''a indirdim. Bosalan slotlari donusum-odakli genislettim: alici (Womens), hediye (for Her, Gift for Women), kullanim (Everyday), stil (Statement), buyer-dili (Real Gold Hoops, Solid Gold Earrings), renk (Yellow Gold Hoops). Tum tag''ler cok-kelimeli long-tail, hepsi <=20 karakter, birebir tekrar yok; ''hoop'' koku tekrar etse de her biri farkli modifier (womens/everyday/for her/yellow/round/diamond cut/graduated) ekledigi icin mesru slot genislemesi. ''Earrings'' urun tipiyle celismiyor. Trafik korunur, niyet sikilasir.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1199260535,'14K Real Gold Rope Chain Bracelet | Unisex Twisted Jewelry','bracelet','bestseller',ARRAY['Rope Chain','Gold Rope Chain','14k Gold Chain','Gold Chain','14k Rope Chain','Rope Chain Necklace','14k Gold Rope Chain','Real Gold Chain','Real Gold Rope Chain','14K Chain','Rope Necklace','14k gold necklace','chain necklace']::text[],ARRAY['Gold Rope Bracelet','14k Gold Bracelet','Real Gold Bracelet','Mens Gold Bracelet','Womens Gold Chain','Unisex Jewelry','14k Rope Chain','Twisted Rope Chain','Gift for Him','Gift for Her','Layering Bracelet','Everyday Jewelry','Solid Gold Chain']::text[],'[{"tag": "Rope Chain Necklace", "reason": "Tip celiskisi: urun bracelet, necklace slot israfi"}, {"tag": "Rope Necklace", "reason": "Tip celiskisi: bracelet listing''de necklace"}, {"tag": "14k gold necklace", "reason": "Tip celiskisi: bracelet listing''de necklace"}, {"tag": "chain necklace", "reason": "Tip celiskisi + cok genis; bracelet''e uymuyor"}, {"tag": "Gold Rope Chain", "reason": "Rope-chain redundansi; Gold Rope Bracelet''e katlandi"}, {"tag": "14k Gold Rope Chain", "reason": "Ayni kokun ust uste yiginlanmasi (14k+gold+rope+chain zaten dagitildi)"}, {"tag": "Real Gold Rope Chain", "reason": "Redundant rope varyanti; Real Gold Bracelet + 14k Rope Chain kapsiyor"}, {"tag": "Real Gold Chain", "reason": "Real Gold Bracelet''e katlandi, kok tekrari"}, {"tag": "14k Gold Chain", "reason": "14k Gold Bracelet + 14k Rope Chain ile kapsanan tekrar"}, {"tag": "Gold Chain", "reason": "Cok genis / tek-kok, uzun-kuyruk degil; slot israfi"}, {"tag": "Rope Chain", "reason": "7 rope varyanti icinde en generik olani; long-tail degil"}, {"tag": "14K Chain", "reason": "Cok genis, dusuk alici niyeti; long-tail''e feda edildi"}]'::jsonb,'[{"tag": "Gold Rope Bracelet", "reason": "Dogru tip + core arama; ''rope chain'' kokunu bracelet''e tasir"}, {"tag": "Real Gold Bracelet", "reason": "Alici dili ''real gold'' + dogru urun tipi"}, {"tag": "Mens Gold Bracelet", "reason": "Alici slotu (erkek), unisex urunde guclu talep"}, {"tag": "Womens Gold Chain", "reason": "Alici slotu (kadin), kitleyi genisletir"}, {"tag": "Unisex Jewelry", "reason": "Baslikta ''Unisex'' var; alici slotu"}, {"tag": "Twisted Rope Chain", "reason": "Baslikta ''Twisted''; stil varyanti, generik rope yerine"}, {"tag": "Gift for Him", "reason": "Hediye slotu (eksikti)"}, {"tag": "Gift for Her", "reason": "Hediye slotu (eksikti)"}, {"tag": "Layering Bracelet", "reason": "Kullanim slotu (stackable/layering trendi)"}, {"tag": "Everyday Jewelry", "reason": "Kullanim slotu (gunluk)"}, {"tag": "Solid Gold Chain", "reason": "Alici dili ''solid gold''; som altin vurgusu"}]'::jsonb,'Urun bracelet ama 13 tag''in 4''u ''necklace'' (tip celiskisi) ve kalanlar ''rope chain'' kokunu 7 varyantla tekrarlayip slot israf ediyor; alici/hediye/kullanim slotu hic yok.','Bestseller/volume stratejisi: core rope+gold+14k sinyalini KORUDUM (Gold Rope Bracelet, 14k Rope Chain, Twisted Rope Chain) ama dogru urun tipine (bracelet) yeniden capaladim ve ''rope'' tekrarini 7''den 3''e indirdim. En buyuk kazanc 4 necklace tip-celiskisini bracelet/chain/jewelry ile degistirip komsu talebe genislemek: alici (mens/womens/unisex), hediye (him/her), kullanim (layering/everyday), alici dili (real gold/solid gold). Necklace tag''lerini korlemesine degil, urun tipinin gercekten bracelet olmasi nedeniyle sildim. 13 tag''in hepsi cok-kelimeli long-tail, birebir tekrar yok, hepsi <=20 karakter.','yuksek'),
