('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1209955532,'10K Gold Cornicello Pendant | Italian Horn Protection Charm','pendant','converter',ARRAY['Cornicello Horn','Gold Cornicello Horn','Gold Italian Horn','Horn Pendant Charm','Good Luck Necklace','Gold Horn Pendant','Horn Pendant','Good Luck Pendant','Cornicello Pendant','Italian Horn Pendant','Protection Pendant','10K Gold Pendant','Protection Charm']::text[],ARRAY['Horn Pendant','Good Luck Necklace','Cornicello Pendant','Italian Horn Pendant','Protection Pendant','Evil Eye Charm','Amulet Necklace','Gift For Him','Gift For Her','Mens Gold Necklace','Solid Gold Charm','10k Gold Necklace','Lucky Charm Gift']::text[],'[{"tag": "Cornicello Horn", "reason": "Cornicello Pendant + Gold Cornicello Horn ile aynı kök; Etsy kelimeleri kendi kombinler, slot israfı."}, {"tag": "Gold Cornicello Horn", "reason": "Cornicello + Horn + Gold kökleri başlıkta ve diğer taglarda zaten var; birebir redundant."}, {"tag": "Gold Italian Horn", "reason": "Başlık ''Italian Horn'' + ''10K Gold'' içeriyor; Etsy bunları kombinler, tekrar boşa slot."}, {"tag": "Horn Pendant Charm", "reason": "''Horn Pendant'' + ''Protection Charm'' kökleriyle örtüşüyor; ayrı slota değmez."}, {"tag": "Gold Horn Pendant", "reason": "Horn Pendant + 10K Gold zaten kapsanıyor; Gold+Horn+Pendant kombinini Etsy kurar."}, {"tag": "Good Luck Pendant", "reason": "''Good Luck Necklace'' ile aynı kök çifti; iki iyi-şans tagı gereksiz."}, {"tag": "10K Gold Pendant", "reason": "Başlıkta ''10K Gold Pendant'' birebir geçiyor — nitelik/başlık tekrarı, yeni trafik getirmiyor."}, {"tag": "Protection Charm", "reason": "Başlıkta ''Protection Charm'' birebir var; tam tekrar, slot kaybı."}]'::jsonb,'[{"tag": "Evil Eye Charm", "reason": "Cornicello malocchio/nazara karşı takılır — semantik olarak meşru, yüksek-talepli komşu arama; converter için yeni trafik."}, {"tag": "Amulet Necklace", "reason": "Yeni kök (amulet) + necklace trafiği; koruma/tılsım arayan kitleyi yakalar."}, {"tag": "Gift For Him", "reason": "Boş hediye+alıcı slotu; cornicello erkek takısında güçlü, doğrudan hediye araması."}, {"tag": "Gift For Her", "reason": "Hediye slotunu genişletir; İtalyan tılsımı kadın alıcıda da güçlü."}, {"tag": "Mens Gold Necklace", "reason": "Alıcı (mens) + necklace + gerçek-altın dili; cornicello erkek pazarı büyük, yeni trafik."}, {"tag": "Solid Gold Charm", "reason": "Alıcı dili ''solid gold'' — som altın arayan yüksek-niyetli trafik, converter için ideal."}, {"tag": "10k Gold Necklace", "reason": "Ürün pendant-necklace olarak takılıyor; ''gold necklace'' yüksek-hacimli arama, gerçek-altın + necklace trafiği."}, {"tag": "Lucky Charm Gift", "reason": "İyi-şans + hediye kombini; tek kök tekrarı yerine iki niyeti birleştirir."}]'::jsonb,'Slot israfı: "horn" 9 tagda, "pendant" 9 tagda, "cornicello" 4 tagda tekrarlıyor (Etsy zaten kombinliyor) — hediye, alıcı (mens), necklace-trafiği ve ''solid gold'' alıcı-dili slotları tamamen boş.','Arketip converter (conv %0.819, düşük trafik) — ürün dönüşüyor, hedef DAHA FAZLA TRAFİK. İşe yarayan 5 çekirdek exact-match korundu (Horn Pendant, Good Luck Necklace, Cornicello Pendant, Italian Horn Pendant, Protection Pendant), redundant 8 filler atıldı ve boş slotlar yüksek-talepli komşularla dolduruldu. TİP-ÇELİŞKİSİ İPUCU DOĞRULANDI: başlık ''pendant'' dese de bu bir pendant-necklace (zincirle takılır); ''italian horn necklace / gold necklace'' aramaları yüksek hacimli, o yüzden necklace tagları KÖRLEMESİNE SİLİNMEDİ — korunup genişletildi (Amulet/Mens Gold/10k Gold Necklace). Genişletilen slotlar: alıcı (Mens, Him/Her), hediye (3 tag), alıcı-dili (Solid Gold, 10k Gold), komşu-stil (Evil Eye, Amulet). Tüm 13 tag çok-kelimeli, <=20 karakter, birebir tekrar yok; ''pendant/necklace/charm/gift'' kökleri farklı niteleyicilerle dengelendi.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,4297100272,'10K Real Gold Rope Bracelet - Unisex Twisted Diamond Cut','bracelet','converter',ARRAY['Diamond Cut Bracelet','Rope Bracelet','real gold bracelet','unisex gold bracelet','dainty gold bracelet','gold bracelet men','gold bracelet women','rope chain bracelet','everyday jewelry','luxury gold bracelet','10k rope bracelet','genuine 10k gold','gold jewelry gift']::text[],ARRAY['Diamond Cut Bracelet','real gold bracelet','unisex gold bracelet','gold bracelet men','gold bracelet women','everyday jewelry','genuine 10k gold','luxury gold bracelet','rope chain bracelet','solid gold bracelet','gift for him','gift for her','layering bracelet']::text[],'[{"tag": "Rope Bracelet", "reason": "Rope-kökü redundancy: baslikta zaten ''Rope Bracelet'' geciyor ve ''rope chain bracelet'' tutuldu; tek-kelimeye yakin zayif varyant, slot israfi."}, {"tag": "rope chain bracelet", "reason": "KORUNDU aslinda tek rope keeper olarak birakildi (dropped degil) — not: rope kokunun tek temsilcisi."}, {"tag": "dainty gold bracelet", "reason": "Tip-celiskisi: unisex + twisted + diamond-cut + erkek konumlu rope bileklik ''dainty'' degil; ayrica ''gold bracelet'' kokunu asiri yogunlastiriyor."}, {"tag": "10k rope bracelet", "reason": "Ucuncu rope-koku tekrari + ''10k'' zaten ''genuine 10k gold'' ile karsilaniyor; ayirt edici yeni sorgu getirmiyor."}, {"tag": "gold jewelry gift", "reason": "Jenerik hediye ifadesi; spesifik ''gift for him'' + ''gift for her'' slotlariyla degistirilince alici-niyetli aramalari daha iyi yakalar."}]'::jsonb,'[{"tag": "solid gold bracelet", "reason": "Alici dili: ''solid/real gold'' arayan yuksek-niyetli som-altin musterisi; ''real gold''dan farkli distinct sorgu, converter icin yeni trafik."}, {"tag": "gift for him", "reason": "Hediye + erkek alici slotu; erkek rope bileklik hediye aramasini acar, mevcut ''...men'' etiketini tamamlar."}, {"tag": "gift for her", "reason": "Hediye + kadin alici slotu; kadin hediye aramasi (dogum gunu/yildonumu) trafigi getirir."}, {"tag": "layering bracelet", "reason": "Kullanim/stil slotu: stacking/layering arayan kitleyi acar; rope-koku disinda yeni erisim, dusuk-trafigi buyutur."}]'::jsonb,'Rope kökü 3 varyantla tekrarlanıp "dainty" tip-çelişkisi eklenince slotlar israf oluyor; hediye/kullanım gibi trafik getirecek komşu ifadeler eksik.','Converter arketipinde (conv %4.1, dusuk trafik) hedef: donusen urunu bozmadan trafik genisletmek. Calisan 9 etiket korundu (Diamond Cut, real/genuine 10k, unisex/men/women, everyday, luxury) ve tek guclu rope long-tail''i ''rope chain bracelet'' birakildi. Kesilenler: rope kokunun 2 fazla varyanti (slot israfi), ''dainty'' tip-celiskisi ve jenerik ''gold jewelry gift''. Yerine alici-niyetli ''solid gold bracelet'', iki spesifik hediye slotu ve kullanim odakli ''layering bracelet'' eklendi. Tum 13 etiket cok-kelimeli ve <=20 karakter; birebir tekrar yok, ''gold bracelet'' kokundeki tekrarlar distinct modifikatorlerle (real/solid/unisex/luxury/men/women) mesru long-tail slotlaridir.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1226252485,'10K Gold Jesus Crucifix Pendant | Religious Christian Jewelry (38mm)','pendant','converter',ARRAY['Nail Cross Pendant','Nail Cross Charm','Gold Cross Charm','Gold Cross Pendant','Religious Pendant','Religious Charm','Gold Religious Charm','Religious Jewelry','Jesus Pendant','Crucifix Pendant','Crucifix Charm','Christian Jewelry','Cross Pendant']::text[],ARRAY['Crucifix Pendant','Jesus Pendant','Christian Jewelry','Religious Jewelry','Gold Cross Pendant','Mens Gold Pendant','Religious Gift','10K Gold Crucifix','Solid Gold Cross','Gift For Him','Real Gold Crucifix','Confirmation Gift','Mens Religious Gift']::text[],'[{"tag": "Nail Cross Pendant", "reason": "Tip-celiskisi: urun bir Jesus crucifix; ''nail cross'' (civilerden yapili hac) farkli bir urun tipi, yaniltici slot israfi."}, {"tag": "Nail Cross Charm", "reason": "Ayni tip-celiskisi + Pendant surumuyle charm/pendant kopyasi."}, {"tag": "Gold Cross Charm", "reason": "''Gold Cross Pendant''in charm kopyasi; Etsy kelimeleri birlestirir, ayni kok tekrari slot israfi."}, {"tag": "Crucifix Charm", "reason": "''Crucifix Pendant''in charm kopyasi; redundant kok."}, {"tag": "Religious Charm", "reason": "''Religious Jewelry/Gift'' tarafindan kapsanan dusuk-ozgullukte charm kopyasi."}, {"tag": "Gold Religious Charm", "reason": "Charm kopyasi + ''religious/gold'' asiri tekrari; ayirt edici deger yok."}, {"tag": "Religious Pendant", "reason": "Cok genel; ''Religious Jewelry'' + ''Religious Gift'' bunu daha guclu karsiliyor."}, {"tag": "Cross Pendant", "reason": "Tek-kavramli/genel; ''Gold Cross Pendant'' ayni aramayi malzeme ozgulluguyle kapsiyor."}]'::jsonb,'[{"tag": "Mens Gold Pendant", "reason": "Alici slotu: listingde hic kitle etiketi yoktu; erkek dini taki yuksek-talepli komsu aramasi."}, {"tag": "Religious Gift", "reason": "Hediye slotu tamamen eksikti; genis yuksek-hacimli giris."}, {"tag": "10K Gold Crucifix", "reason": "Basliktaki karat/malzeme ozgullugu; ''real gold'' alici niyetini yakalar."}, {"tag": "Solid Gold Cross", "reason": "Alici dili (''solid gold'') guven sinyali; malzeme temelli trafik."}, {"tag": "Gift For Him", "reason": "Hediye+kitle: crucifix pendant erkek-hediye aramalarinda ust siralarda."}, {"tag": "Real Gold Crucifix", "reason": "Alici dili (''real gold'') + cekirdek alaka; converter''a daha fazla nitelikli trafik."}, {"tag": "Confirmation Gift", "reason": "Dini occasion/hediye slotu (confirmation/communion); dusuk rekabet, hedefli talep."}, {"tag": "Mens Religious Gift", "reason": "Kitle+hediye birlesik long-tail; dusuk rekabetli ek trafik yuzeyi."}]'::jsonb,'13 slotun 8''i ayni 4 kokun (cross/religious/crucifix) charm-vs-pendant kopyasi + tip-celisen "nail cross"; alici/hediye/malzeme slotu SIFIR, bu yuzden erkek-hediye ve real-gold aramalarina hic girmiyor.','Arketip converter: donusum var, sorun trafik. Ise yarayan cekirdek alaka etiketleri (Crucifix Pendant, Jesus Pendant, Christian/Religious Jewelry, Gold Cross Pendant) KORUNDU. Israf edilen 8 slot (charm-vs-pendant kopyalari + tip-celisen nail cross + genel Cross/Religious Pendant) yeni TALEP yuzeylerine cevrildi: alici (Mens Gold Pendant, Mens Religious Gift), hediye (Religious Gift, Gift For Him, Confirmation Gift), malzeme/alici dili (10K Gold Crucifix, Solid Gold Cross, Real Gold Crucifix). Hepsi cok-kelimeli long-tail, birebir tekrar yok, her biri <=20 karakter. UYARI: baslik ''10K'' derken malzeme nitelikleri ''14K Real Gold/14k Gold'' diyor — bu celiski dogrulanmali; etiketler basligi (10K) esas aldi, karat yanlissa 10K→14K duzeltilmeli.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1739245557,'10K Gold Heart Nugget Ring | Solid Yellow Gold','ring','standart',ARRAY['Nugget Ring','Nugget mens','Gold Nugget Ring','Nugget Rings','10K Gold Rings','10K Solid Gold Ring','Solid Gold Ring','10K Ring','Gold Ring','Heart Shape Ring','Heart Nugget Ring','Heart Ring','Solid Gold Nugget']::text[],ARRAY['Gold Nugget Ring','Heart Nugget Ring','10K Solid Gold Ring','Heart Shape Ring','Mens Nugget Ring','Womens Gold Ring','Real Gold Jewelry','Gift for Him','Gift for Her','Statement Ring','Yellow Gold Ring','Chunky Gold Ring','Everyday Jewelry']::text[],'[{"tag": "Nugget Ring", "reason": "Gold Nugget Ring ve Nugget Rings ile ayni kok; tekil kisa varyant slot israfi."}, {"tag": "Nugget Rings", "reason": "Nugget Ring cogul kopyasi; Etsy tekil/cogulu zaten eslestirir."}, {"tag": "Nugget mens", "reason": "Dilbilgisi bozuk; Mens Nugget Ring olarak long-tail''e cevrildi."}, {"tag": "10K Gold Rings", "reason": "10K Solid Gold Ring ile ortusuyor, redundant."}, {"tag": "Solid Gold Ring", "reason": "10K Solid Gold Ring bu ifadeyi zaten kapsiyor."}, {"tag": "10K Ring", "reason": "Jenerik, tek-kelime agirlikli, zayif; 10K Solid Gold Ring kapsiyor."}, {"tag": "Gold Ring", "reason": "Jenerik head-term; long-tail varyantlarda zaten mevcut."}, {"tag": "Heart Ring", "reason": "Heart Shape Ring + Heart Nugget Ring kapsiyor; kisa jenerik tekrar."}, {"tag": "Solid Gold Nugget", "reason": "''ring'' icermiyor, urun tipi belirsiz zayif varyant; slot israfi."}]'::jsonb,'[{"tag": "Mens Nugget Ring", "reason": "Erkek kitle sinyali + long-tail; bozuk ''Nugget mens''in temiz hali."}, {"tag": "Womens Gold Ring", "reason": "Eksik kadin kitle slotu; tek ''mens'' varken pazar yariya daraliyordu."}, {"tag": "Real Gold Jewelry", "reason": "Alici dili ''real gold''; kategori genisligi + hediye aramalarina girer."}, {"tag": "Gift for Him", "reason": "Hediye niyet slotu tamamen eksikti; yuksek donusumlu arama."}, {"tag": "Gift for Her", "reason": "Kalp motifi kadin hediyesine uygun; ikinci hediye slotu."}, {"tag": "Statement Ring", "reason": "Kullanim/stil slotu; nugget''in iri gorunumu bu aramayla eslesir."}, {"tag": "Yellow Gold Ring", "reason": "Baslikta gecen ''Yellow Gold'' niteligini yakalar; renk varyanti."}, {"tag": "Chunky Gold Ring", "reason": "Nugget = chunky; stil tarifli alternatif alici dili."}, {"tag": "Everyday Jewelry", "reason": "Gunluk kullanim niyet slotu; genis eslesme icin kategori terimi."}]'::jsonb,'Slot israfi: "Nugget Ring/Nugget Rings/Gold Nugget Ring" ve "Heart Ring/Heart Shape Ring" ayni koku tekrarliyor, ayrica jenerik tek-kelime tag''lar (Gold Ring, 10K Ring) varken hediye/kadin kitlesi/kullanim slotlari hic yok.','Redundant nugget (3 varyant) ve heart (3 varyant) tekrarlarini birer temsilciye indirdim (Gold Nugget Ring, Heart Nugget Ring + Heart Shape Ring korundu). Jenerik/tek-kelime zayif tag''lari (Gold Ring, 10K Ring, Solid Gold Ring) kaldirip acilan slotlari eksik niyetlerle doldurdum: hediye (Gift for Him/Her), kitle (Mens/Womens), kullanim/stil (Statement, Everyday, Chunky) ve alici dili (Real Gold). Tum tag''lar ring/urun gercegine sadik, cok-kelimeli long-tail agirlikli ve <=20 karakter. ''Solid Gold Nugget'' tip-belirsiz oldugu icin dusuruldu.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1201031517,'14K Real Gold Diamond Cut Hoop Earrings - Shiny Gold Hoops','earring','standart',ARRAY['Hoop Earrings','Gold Hoop Earrings','14K Hoop Earrings','Real Gold Earrings','14K Gold Earrings','Shiny Hoop Earrings','Round Hoop Earrings','Large Hoop Earrings','Diamond Cut Earrings','14K Round Earrings','Gold Shiny Earrings','Gold Circle Earrings','Gold Dangle Earrings']::text[],ARRAY['Gold Hoop Earrings','14K Real Gold Hoops','Diamond Cut Hoops','Shiny Gold Hoops','Real Gold Earrings','14K Gold Earrings','Yellow Gold Hoops','Womens Hoop Earrings','Gift For Her','Mothers Day Gift','Everyday Earrings','Large Gold Hoops','Statement Earrings']::text[],'[{"tag": "Hoop Earrings", "reason": "Tek başına ''Hoop Earrings'' başlıkta zaten baskın; ''Gold Hoop Earrings'' bunu kapsar, slot israfı."}, {"tag": "14K Hoop Earrings", "reason": "14K + Hoop kombinasyonu ''14K Real Gold Hoops'' ile karşılanıyor; kök tekrarı."}, {"tag": "Shiny Hoop Earrings", "reason": "''shiny'' + ''hoop'' kökü ''Shiny Gold Hoops'' ile örtüşüyor; birebir yakın tekrar."}, {"tag": "Round Hoop Earrings", "reason": "Hoop zaten yuvarlaktır; ''round'' bilgi katmıyor, slot israfı."}, {"tag": "14K Round Earrings", "reason": "''round'' redundant + 14K/Earrings kökü defalarca tekrar ediyor."}, {"tag": "Gold Shiny Earrings", "reason": "''Shiny Hoop Earrings'' ile neredeyse birebir aynı köke düşüyor; çift shiny."}, {"tag": "Gold Circle Earrings", "reason": "''circle'' = round = hoop; aynı geometriyi üçüncü kez tekrarlıyor."}, {"tag": "Gold Dangle Earrings", "reason": "TİP ÇELİŞKİSİ: ürün hoop earring, dangle değil; yanlış alıcıyı çekip relevance düşürür."}, {"tag": "Large Hoop Earrings", "reason": "''Hoop Earrings'' kökü fazla; boyut sinyali ''Large Gold Hoops'' olarak korundu (yeniden yazıldı)."}, {"tag": "Diamond Cut Earrings", "reason": "''Diamond Cut Hoops'' olarak yeniden yazıldı; ''Earrings'' kökü yerine ürün tipiyle daraltıldı."}]'::jsonb,'[{"tag": "14K Real Gold Hoops", "reason": "Alıcı dili (''real gold'') + ürün tipi long-tail; en güçlü niyet ifadesi."}, {"tag": "Shiny Gold Hoops", "reason": "Başlıktaki ''shiny gold hoops'' ifadesini tek temiz slotta karşılar."}, {"tag": "Yellow Gold Hoops", "reason": "Malzeme (Yellow Gold) sinyali; renk arayan alıcıyı yakalar, yeni kök."}, {"tag": "Womens Hoop Earrings", "reason": "Kitle slotu eksikti; ''womens'' hedef alıcıyı ekler (20 karakter)."}, {"tag": "Gift For Her", "reason": "Hediye niyeti slotu tamamen eksikti; yüksek hacimli long-tail."}, {"tag": "Mothers Day Gift", "reason": "Occasion/hediye slotu; mevsimsel yüksek dönüşümlü arama."}, {"tag": "Everyday Earrings", "reason": "Kullanım slotu; günlük takı niyetini yakalar."}, {"tag": "Statement Earrings", "reason": "Stil slotu; large/diamond-cut hoop ile uyumlu, farklı arama niyeti."}, {"tag": "Large Gold Hoops", "reason": "Mevcut ''Large'' boyut sinyalini ''hoop'' kökünü tekrarlamadan koruyan yeniden yazım."}, {"tag": "Diamond Cut Hoops", "reason": "Başlıktaki ayırt edici finish; ''Earrings'' yerine ürün tipiyle daraltıldı."}]'::jsonb,'Aşırı redundancy: 13 tag''in hepsi "Earrings", "Hoop" 6 kez, round/circle tekrarı slot israfı; ayrıca "Gold Dangle Earrings" tip çelişkisi (hoop ≠ dangle) ve hediye/kitle/stil/kullanım slotları tamamen eksik.','Orijinal set tek bir kökü (hoop/round/circle + gold + earrings) 13 slota yayarak Etsy''nin otomatik kombinlemesini boşa harcıyordu ve ''Gold Dangle Earrings'' ile tip çelişkisi yaratıyordu. Yeni set relevance''ı koruyup (gold hoop earrings, real gold, 14k, diamond cut, shiny hepsi ürün gerçeğiyle uyumlu) redundant round/circle/shiny tekrarlarını temizledi, tip çelişkili dangle''ı attı ve tamamen boş olan niyet slotlarını doldurdu: kitle (womens), hediye (gift for her, mothers day), kullanım (everyday), stil (statement). 13/13 dolu, hepsi <=20 karakter, tümü çok-kelimeli, birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1195517566,'14K Real Gold Paperclip Chain Bracelet – Italian Link','bracelet','standart',ARRAY['Paperclip Bracelet','Paperclip Chain','Gold Bracelet','Gold Paperclip','14K Gold Bracelet','Real Gold Bracelet','Real Gold Chain','14K Bracelet','Gold Chain Bracelet','14K Gold Paperclip','Solid Gold Bracelet','14K Paperclip','14K Solid Bracelet']::text[],ARRAY['Paperclip Bracelet','14K Gold Bracelet','Real Gold Bracelet','Solid Gold Bracelet','Gold Chain Bracelet','Italian Gold Chain','Layering Bracelet','Stacking Bracelet','Everyday Bracelet','Dainty Bracelet','Minimalist Bracelet','Gift for Her','Womens Bracelet']::text[],'[{"tag": "Paperclip Chain", "reason": "paperclip koku zaten Paperclip Bracelet''te var; Etsy kelimeleri kombinler, slot israfi"}, {"tag": "Gold Paperclip", "reason": "paperclip+gold ikinci kez tekrar; ayni koku uculamak yeni arama getirmiyor"}, {"tag": "Real Gold Chain", "reason": "urun bracelet; ''chain'' zaten Gold Chain Bracelet''te mesru olarak var, cift chain gereksiz"}, {"tag": "14K Bracelet", "reason": "14K Gold Bracelet tarafindan tam kapsaniyor (Etsy kombinler), zayif dar varyant"}, {"tag": "14K Gold Paperclip", "reason": "14K+gold+paperclip ucuncu kez tekrar; tamamen redundant"}, {"tag": "14K Paperclip", "reason": "ayni paperclip/14K kokunun bir baska bitisik varyanti; slot israfi"}, {"tag": "14K Solid Bracelet", "reason": "Solid Gold Bracelet + 14K Gold Bracelet birlesimiyle kapsaniyor, garip ve redundant"}, {"tag": "Gold Bracelet", "reason": "cok jenerik; 5 farkli ''X Gold/Chain Bracelet'' tag''inden Etsy zaten ''gold bracelet'' kombinasyonunu turetiyor"}]'::jsonb,'[{"tag": "Italian Gold Chain", "reason": "STIL slotu — basliktaki ''Italian Link'' niteligini aramaya baglar (yuksek niyetli long-tail)"}, {"tag": "Layering Bracelet", "reason": "KULLANIM slotu — paperclip ince zincirlerin en guclu satin alma niyeti (katmanlama)"}, {"tag": "Stacking Bracelet", "reason": "KULLANIM/stil slotu — bilezikte layering''in bilek karsiligi, ayri arama havuzu"}, {"tag": "Everyday Bracelet", "reason": "KULLANIM slotu — gunluk tasima niyeti, genis alici tabani"}, {"tag": "Dainty Bracelet", "reason": "STIL slotu — paperclip''in ince/zarif estetigi; ''gold'' tekrarini artirmadan stil ekler"}, {"tag": "Minimalist Bracelet", "reason": "TARZ slotu — minimalist taki alicisi paperclip''in ana hedef kitlesi"}, {"tag": "Gift for Her", "reason": "HEDIYE slotu — tamamen eksikti; yuksek hacimli hediye niyeti aramasi"}, {"tag": "Womens Bracelet", "reason": "KITLE slotu — alici dili; urun kitlesini aramaya net baglar"}]'::jsonb,'13 slotun neredeyse tamami ''paperclip / 14K / gold / bracelet'' kokunun varyantlariyla dolu (asiri redundancy); hediye, stil, kullanim ve kitle niyet slotlari tamamen eksik.','Standart arketip: dengeli temizlik. Cekirdek exact/kalite iddialarindan 5 tag korundu (Paperclip Bracelet ana exact; 14K/Real/Solid Gold Bracelet = alici dili kalite iddialari; Gold Chain Bracelet = tip tanimi). Redundant 8 varyant (paperclip×6, 14K×5, cift chain) temizlenip yerine 4 niyet slotu acildi: hediye (Gift for Her), stil (Italian Gold Chain, Dainty, Minimalist), kullanim (Layering, Stacking, Everyday), kitle (Womens). Relevance korundu — hicbir tag bracelet tipiyle celismez; ''Gold Chain Bracelet'' ve ''Italian Gold Chain'' zincir-bilezik gerceğine uygun mesru chain kullanimi. 13 tag''in tamami cok-kelimeli long-tail, tek-kelime yok, birebir tekrar yok. Tum tag''ler <=20 karakter (en uzun ''Minimalist Bracelet'' = tam 20).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1764133503,'10K Gold Miami Cuban Link Chain, CZ Box Lock','necklace','standart',ARRAY['Miami Cuban Link','Miami Cuban','10K Miami','Monaco Chain','Cuban Chain','Link Chain','10K Gold Chain','10K Gold Necklace','10K Miami Chain','10K Cuban Chain','Monaco Cuban','Gold Chain','10K Chain']::text[],ARRAY['Miami Cuban Link','10K Gold Necklace','Real Gold Chain','Solid Gold Chain','Gold Chain for Men','Mens Cuban Link','Monaco Chain','Iced Out Necklace','Hip Hop Jewelry','Diamond Cut Chain','Cuban Link Necklace','Gift for Him','CZ Box Lock']::text[],'[{"tag": "Miami Cuban", "reason": "''Miami Cuban Link'' ile birebir kok tekrari, slot israfi"}, {"tag": "10K Miami", "reason": "miami/10K kombinasyonu zaten baska taglerden Etsy tarafindan uretiliyor"}, {"tag": "Cuban Chain", "reason": "cuban+chain koku diger uzun-kuyruk taglerde kapsanmis"}, {"tag": "Link Chain", "reason": "belirsiz ve zayif; ''Cuban Link Necklace'' daha spesifik"}, {"tag": "10K Gold Chain", "reason": "gold+chain tekrari; ''10K Gold Necklace'' ve ''Real/Solid Gold Chain'' ile karsilaniyor"}, {"tag": "10K Miami Chain", "reason": "10K+miami+chain koklarinin uc katli redundansi"}, {"tag": "10K Cuban Chain", "reason": "ayni kok grubunun bir baska varyanti, ek deger yok"}, {"tag": "Monaco Cuban", "reason": "''Monaco Chain'' korunuyor; monaco+cuban ayrica tekrar"}, {"tag": "Gold Chain", "reason": "neredeyse tek-kavram genel; daha nitelikli varyantlar var"}, {"tag": "10K Chain", "reason": "dar/genel; 10K zaten baslikta ve tag havuzunda mevcut"}]'::jsonb,'[{"tag": "Real Gold Chain", "reason": "alici dili (som/gercek altin) niyet slotu"}, {"tag": "Solid Gold Chain", "reason": "''solid gold'' yuksek-donusum alici dili"}, {"tag": "Gold Chain for Men", "reason": "kitle slotu (erkek) + long-tail"}, {"tag": "Mens Cuban Link", "reason": "kitle + stil; agir cuban erkek alicisini hedefler"}, {"tag": "Iced Out Necklace", "reason": "CZ box lock ozelligini karsilayan stil niyeti"}, {"tag": "Hip Hop Jewelry", "reason": "tarz/kultur slotu, genis kesif trafigi"}, {"tag": "Diamond Cut Chain", "reason": "stil niteligi, farkli kelime havuzu"}, {"tag": "Cuban Link Necklace", "reason": "urun tipi (necklace) + stil, mesru zincir-necklace eslemesi"}, {"tag": "Gift for Him", "reason": "hediye niyet slotu, tamamen eksikti"}, {"tag": "CZ Box Lock", "reason": "urunun ayirt edici kilit ozelligi, niche arama"}]'::jsonb,'Ayni kok (miami/cuban/monaco ~7 varyant + gold/chain tekrari) 13 slotu doldurmus; hicbir niyet slotu yok (hediye, kitle, stil, alici dili).','Orijinal set 13 slotun ~10''unu tek kok ailesine (miami/cuban/monaco) ve gold/chain tekrarina harcamis; hicbir hediye, kitle, stil veya alici-dili sinyali yok. Bu, 24K goruntuye karsi %0.012 donusumun temel nedeni: trafik geliyor ama niyet cesitliligi yok. Yeni set relevance''i korur (necklace/cuban/link/10K/monaco hala var, urunle celisen tag yok), kok tekrarini dengeler (chain 5, necklace 3, cuban 3, gold 4) ve eksik niyet slotlarini acar: alici dili (real/solid gold), kitle (for men/mens), stil (iced out, hip hop, diamond cut, miami), hediye (gift for him) ve ayirt edici ozellik (CZ box lock). Hepsi cok-kelimeli long-tail ve <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1743489483,'10K Solid Yellow Gold Men''s Ring with CZ Stone | Polished Finish','ring','standart',ARRAY['Gold Statement Rings','10K Gold Rings','10K Solid Gold Ring','Solid Gold Ring','10K Ring','Gold Ring','White Gold Ring','Cz stone Ring','Large Men''s Ring','Solid Gold Mens Ring','Round Gold Ring','10K Yellow Gold Ring','10K men''s Ring']::text[],ARRAY['10K Solid Gold Ring','10K Yellow Gold Ring','Gold Ring for Men','Real Gold Mens Ring','CZ Stone Ring','Gold Statement Ring','Gift for Him','Fathers Day Gift','Everyday Mens Ring','Large Mens Ring','Round Gold Ring','10K Gold Jewelry','Luxury Mens Jewelry']::text[],'[{"tag": "White Gold Ring", "reason": "Tip/renk celiskisi: urun sari altin (Yellow Gold); beyaz altin tag''i yanlis trafik ceker, alakasiz."}, {"tag": "10K Gold Rings", "reason": "Kok israfi: 10K Solid/Yellow Gold Ring ile ayni koku tekrar ediyor; Etsy zaten kombinler."}, {"tag": "Solid Gold Ring", "reason": "Redundant: 10K Solid Gold Ring icinde zaten var, slot bosa gidiyor."}, {"tag": "10K Ring", "reason": "Cok kisa/genel, tek-niyet; long-tail varyantlar bunu kapsiyor."}, {"tag": "Gold Ring", "reason": "Tek-kelime yakini, en genel form; dusuk niyet, slot israfi."}, {"tag": "Solid Gold Mens Ring", "reason": "Mens+solid gold zaten Real Gold Mens Ring / 10K Solid ile kapsandi; slot hediye+kullanima acildi."}, {"tag": "10K men''s Ring", "reason": "10K + mens tekrari; Mens Gold Ring varyantlariyla cakisiyor."}]'::jsonb,'[{"tag": "Gold Ring for Men", "reason": "Alici dili (buyer intent ''gold ring for men''); dar kitleyi acar, dogal arama sorgusu."}, {"tag": "Real Gold Mens Ring", "reason": "''Real gold'' alici dili + erkek kitlesi; guven/aramayi birlestiren long-tail."}, {"tag": "Gift for Him", "reason": "Eksik hediye slotu; erkek takisi guclu hediye niyeti tasir."}, {"tag": "Fathers Day Gift", "reason": "Erkek urunune uygun sezonluk/occasion hediye slotu; yeni trafik kaynagi."}, {"tag": "Everyday Mens Ring", "reason": "Eksik kullanim slotu (everyday); gunluk giyim niyetini yakalar."}, {"tag": "10K Gold Jewelry", "reason": "Kategori genisletme: ring kokunun disina cikip magaza cesitliligi aramasini yakalar."}, {"tag": "Luxury Mens Jewelry", "reason": "Stil/tarz slotu (luxury) + kitle; premium alici niyetini hedefler, ''Gold Ring'' tekrarini kirar."}]'::jsonb,'Renk celiskisi (sari altin urunde "White Gold Ring") + "10K/solid gold ring" kokunun 6-7 varyantla tekrari slotlari yiyor; hediye/kullanim/kitle niyet slotlari bos.','Standart arketip: 7 redundant/celiskili tag temizlendi, relevance korunarak niyet slotlari genisletildi. Malzeme cekirdegi 3 tag''e indirildi (10K Solid, 10K Yellow, 10K Gold Jewelry) — hepsi farkli aci (solid/renk/kategori). Kitle mens 5 varyantla ama her biri farkli niyetle esli (buyer dili, real gold, everyday, large, luxury) yani slot israfi degil. Hediye (Gift for Him, Fathers Day), kullanim (Everyday), stil (Statement, Luxury), sekil (Round), boyut (Large), ozellik (CZ Stone) slotlari dolduruldu. Tum tag''ler <=20 karakter, birebir tekrar yok, cogunluk cok-kelimeli long-tail.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1537611621,'14K Gold Cornicello Necklace, Miami Cuban Chain, Italian Horn Good Luck Charm','pendant','standart',ARRAY['Cornicello Necklace','Horn Pendant','Miami Cuban Chain','Cornicello Charm','italian charm','Gold men Necklace','Gold Horn Pendant','Good Luck Pendat','Gold Italian Pendant','Italian Horn Pendant','14K Gold Pendant','14K Gold Necklace','14K Gold Chain']::text[],ARRAY['Cornicello Necklace','Miami Cuban Chain','Italian Horn Pendant','Good Luck Charm','Gold Chain for Men','Gift for Him','14K Gold Pendant','Real Gold Necklace','Italian Charm','Layering Necklace','Mens Gold Necklace','Hip Hop Necklace','Italian Gift']::text[],'[{"tag": "Horn Pendant", "reason": "Italian Horn Pendant zaten ayni koku tasiyor; tek kelimeye yakin zayif varyant, slot israfi."}, {"tag": "Cornicello Charm", "reason": "Cornicello Necklace ile ayni kok; cornicello baslikta da baskin, ikinci varyant gereksiz."}, {"tag": "Gold Horn Pendant", "reason": "Uc horn-pendant varyantindan biri; asiri redundancy, temiz men/kullanim slotuyla degistirildi."}, {"tag": "Good Luck Pendat", "reason": "YAZIM HATASI (Pendant->Pendat) + pendant kelimesi zaten doygun; Good Luck Charm ile duzeltildi (baslik ''Good Luck Charm'' diyor)."}, {"tag": "Gold Italian Pendant", "reason": "italian ve pendant koku diger tag''lerde tekrar ediyor; Italian Charm/Italian Gift ile daha genis kaplandi."}, {"tag": "Gold men Necklace", "reason": "Bozuk soz dizimi; alici dili ''Gold Chain for Men'' ve ''Mens Gold Necklace'' ile temizce yeniden kuruldu."}, {"tag": "14K Gold Necklace", "reason": "14K ve necklace koku 14K Gold Pendant + Real Gold Necklace ile karsilaniyor; birebir slot israfi."}, {"tag": "14K Gold Chain", "reason": "Chain zaten Miami Cuban Chain ile, 14K zaten 14K Gold Pendant ile var; redundant."}]'::jsonb,'[{"tag": "Good Luck Charm", "reason": "Baslikteki ''Good Luck Charm'' niyetini dogru yazimla yakalar; hatali ''Good Luck Pendat'' yerine gecer."}, {"tag": "Gold Chain for Men", "reason": "Alici dili + kitle slotu; yuksek hacimli ''gold chain for men'' aramasi."}, {"tag": "Gift for Him", "reason": "Eksik hediye niyet slotu; maskulen kulturel taki icin guclu alici sinyali."}, {"tag": "Real Gold Necklace", "reason": "Malzeme buyer-language (''14k real gold''); som altin arayan aliciyi hedefler."}, {"tag": "Layering Necklace", "reason": "Eksik kullanim slotu; katmanlama arayan modaya yonelik trafik."}, {"tag": "Mens Gold Necklace", "reason": "Kitle slotu; Gold men Necklace''in bozuk halinin yerine temiz varyant."}, {"tag": "Hip Hop Necklace", "reason": "Stil/kullanim slotu; Miami Cuban + horn urunune uygun, yeni izleyici acar."}, {"tag": "Italian Gift", "reason": "Hediye + kulturel niyet; horn/pendant kokunu tekrarlamadan italyan hediye aramasini kaplar."}]'::jsonb,'Asiri redundancy: "pendant" 7 tag''de, "horn pendant" 3 varyant, "cornicello" 2x tekrar ve "Good Luck Pendat" yazim hatasi slot israf ediyor; hediye/kullanim/stil niyet slotlari tamamen eksik.','Orijinal set arketip disi tek bir kelime kumesi etrafinda donuyordu: 13 tag''in cogu ''pendant''/''horn''/''cornicello''/''italian''/''14K'' koklerini tekrarliyor, Etsy''nin kendisi kombinledigi icin bu net slot israfi. ''Good Luck Pendat'' ayrica yazim hatasiyla oluydu. 5 gercek deger tasiyan long-tail''i (Cornicello Necklace, Miami Cuban Chain, Italian Horn Pendant, italian charm, 14K Gold Pendant) korudum; kalan 8 slotu bosa harcanan tekrarlardan bosaltip eksik niyet eksenlerine dagittim: hediye (Gift for Him, Italian Gift), kitle/alici dili (Gold Chain for Men, Mens Gold Necklace, Real Gold Necklace), kullanim (Layering Necklace), stil (Hip Hop Necklace) ve duzeltilmis tema (Good Luck Charm). Relevance korundu — pendant urunu olsa da baslik ''Necklace'' ve ''Chain'' dediginden necklace/chain tag''leri mesru. 13 tag''in tamami cok-kelimeli ve hepsi <=20 karakter; birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1320317404,'10K Gold Puffed Mariner Anchor Chain Necklace – Real Textured Link','necklace','standart',ARRAY['Mariner Chain','Puffed Chain','Mariner Necklace','Gold Chain','Anchor Chain','Gold Mariner','Puffed Necklace','Gold Link Chain','Real Gold Chain','Gold Mariner Chain','10K Gold Chain','10K Gold Necklace','10K Mariner Chain']::text[],ARRAY['Mariner Chain','Anchor Chain','Mariner Necklace','10K Gold Chain','Real Gold Chain','Puffed Mariner','Gold Chain For Men','Mens Gold Necklace','Gift For Him','Hip Hop Jewelry','Layering Necklace','Solid Gold Chain','Anchor Link Chain']::text[],'[{"tag": "Puffed Chain", "reason": "''Puffed Mariner'' ayni kavrami stil koku ile birlikte tasiyor; tek basina ''puffed chain'' zayif/tekrar."}, {"tag": "Gold Chain", "reason": "Cok genis, dusuk deger; 10K/Real/Solid/For Men varyantlari bu aramayi zaten kapsiyor."}, {"tag": "Gold Mariner", "reason": "''Mariner Chain/Necklace'' ile birebir ortusen redundan kok; slot israfi."}, {"tag": "Puffed Necklace", "reason": "Puffed koku ''Puffed Mariner''de korunuyor; ikinci puffed slotu gereksiz."}, {"tag": "Gold Link Chain", "reason": "Jenerik; ''Anchor Link Chain'' daha spesifik ve urun tipine sadik."}, {"tag": "Gold Mariner Chain", "reason": "Uc kelimenin ucu de baska taglarda var; en agir mariner tekrari."}, {"tag": "10K Gold Necklace", "reason": "''10K Gold Chain'' ile neredeyse ozdes; karat+tip niyeti tek slotta yeter."}, {"tag": "10K Mariner Chain", "reason": "10K ve Mariner ayri taglarda mevcut; bu kombinasyon fazladan tekrar."}]'::jsonb,'[{"tag": "Puffed Mariner", "reason": "Baslikdaki ''Puffed'' dokusunu stil koku olarak korur; tekil ''puffed chain/necklace'' yerine tek guclu varyant."}, {"tag": "Gold Chain For Men", "reason": "Kitle slotu: mariner/anchor zincir erkek pazarinda baskin; alici dili ''gold chain for men''."}, {"tag": "Mens Gold Necklace", "reason": "Kitle + urun tipi; erkek alici niyetini genisletir, ''chain for men''den farkli arama kaligi."}, {"tag": "Gift For Him", "reason": "Hediye niyeti slotu tamamen eksikti; erkek takisi icin yuksek donusum aramasi."}, {"tag": "Hip Hop Jewelry", "reason": "Stil/tarz slotu: kalin puffed mariner zincirler hip hop estetigiyle aranir, urunle celismez."}, {"tag": "Layering Necklace", "reason": "Kullanim slotu: katmanlama; kadin/unisex alici niyetini de acar, tek-kitleye sıkışmayı onler."}, {"tag": "Solid Gold Chain", "reason": "Alici dili ''solid gold'' (kaplama degil); 10K som altin gercegiyle uyumlu, ''real''dan farkli kelime."}, {"tag": "Anchor Link Chain", "reason": "Mariner = anchor link; sinonim arayan alicilari yakalar, jenerik ''gold link chain'' yerine spesifik."}]'::jsonb,'Asiri redundancy: 13 tag''in 7''si ''mariner'', 10''u ''gold'' kokunu tekrarliyor — slot israfi; hediye/stil/kullanim/kitle niyet slotlari tamamen bos.','Ana sorun celiski degil asiri redundancy: eski sette ''mariner'' 7, ''gold'' 10 kez tekrarlanıyordu ve Etsy''nin kendi kelime-kombinlemesi sayesinde bu slotlarin cogu bosa gidiyordu. Mariner tekrarini 3''e, anchor''i 2''ye indirdim; core arama gucunu koruyan 5 tag''i (Mariner Chain, Anchor Chain, Mariner Necklace, 10K Gold Chain, Real Gold Chain) tuttum. Bosalan 8 slotu tamamen eksik olan niyet katmanlariyla doldurdum: kitle (Gold Chain For Men, Mens Gold Necklace), hediye (Gift For Him), stil/tarz (Hip Hop Jewelry, Puffed Mariner), kullanim (Layering Necklace) ve alici dili (Solid Gold Chain, Anchor Link Chain). Relevance korundu — hicbir tag urun tipiyle (necklace/mariner chain) celismez; ''necklace'' zincir urununde mesru. Tum taglar cok-kelimeli (tek-kelime yok) ve <=20 karakter (en uzun ''Gold Chain For Men''/''Mens Gold Necklace'' = 18). Dusuk conv (0.072%) buyuk olcude niyet slotu eksikliginden kaynaklaniyordu; hediye+kitle sinyalleri bunu hedefliyor.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1329785553,'14K Solid Gold Rosary Necklace – Diamond Cut Cross Crucifix, Rosario','necklace','standart',ARRAY['Gold Rosary Necklace','Gold Rosary','14k Gold Rosary','14K Gold Necklace','Solid Gold Necklace','Gold Cross Necklace','Beaded Rosary','Gold Crucifix','Religious Necklace','Diamond Cut Necklace','Rosario Necklace','Rosary Necklace','Tri Color necklace']::text[],ARRAY['Gold Rosary Necklace','14k Gold Necklace','Solid Gold Necklace','Gold Cross Necklace','Gold Crucifix','Religious Necklace','Diamond Cut Necklace','Rosario Necklace','First Communion Gift','Confirmation Gift','Mens Gold Rosary','Baptism Gift','Womens Gold Necklace']::text[],'[{"tag": "Gold Rosary", "reason": "''Gold Rosary Necklace'' tag''inin alt kumesi — Etsy kombinledigi icin birebir redundancy, slot israfi."}, {"tag": "14k Gold Rosary", "reason": "14k+rosary zaten ''14k Gold Necklace''+''Gold Rosary Necklace'' kombinasyonuyla karsilaniyor; ayni koku 3. kez tekrar."}, {"tag": "Beaded Rosary", "reason": "4. rosary varyanti; ''beaded'' zaten rosary tanimi geregi ima ediliyor — slot hediye niyetine aktarildi."}, {"tag": "Rosary Necklace", "reason": "''Gold Rosary Necklace'' ile neredeyse ayni (yalniz ''gold'' eksik) — Etsy''de otomatik kapsaniyor, redundancy."}, {"tag": "Tri Color necklace", "reason": "Baslik ''14K Solid Gold'' (tek ton) diyor; tri-color dogrulanmamis ve celisebilir — relevance riski."}]'::jsonb,'[{"tag": "First Communion Gift", "reason": "Rosary takisinda en guclu hediye/okazyon araması; tamamen bos olan niyet slotunu aciyor (20 kr)."}, {"tag": "Confirmation Gift", "reason": "Dini takida yuksek donuslu ikinci okazyon slotu (konfirmasyon hediyesi)."}, {"tag": "Baptism Gift", "reason": "Vaftiz/christening hediye niyeti — rosary icin klasik yuksek-alim okazyonu."}, {"tag": "Mens Gold Rosary", "reason": "Erkek altin rosary zincirleri (hip-hop/streetwear) guclu pazar; kitle-nitelikli, saf tekrar degil buyer slotu."}, {"tag": "Womens Gold Necklace", "reason": "Kadin alici slotu — ''mens'' ile birlikte iki cinsiyeti de kapsayarak kitleyi genisletir."}]'::jsonb,'13 tag''in 6''si "rosary" kokunu tekrarlarken hediye/okazyon (ilk komunyon, vaftiz) ve kitle (erkek/kadin) niyet slotlari tamamen bos — Etsy kelimeleri zaten kombinledigi icin bu buyuk slot israfi.','Standart strateji: dengeli temizlik. Rosary tekrarini 6''dan 3''e indirdim ve kalan uc rosary tag''ini farkli niyetlere ayirdim — birincil (''Gold Rosary Necklace''), Ispanyolca/Latino pazari (''Rosario Necklace''), erkek alici (''Mens Gold Rosary''). Bosalan 5 slotu tamamen eksik olan hediye/okazyon (First Communion, Confirmation, Baptism) ve kitle (mens/womens) niyetlerine yatirdim. Relevance korundu: crucifix, cross, diamond cut, religious, solid/14k gold hepsi baslik ve urun gercegiyle uyumlu. 13 tag''in tamami cok-kelimeli, hicbiri <=20 kr sinirini asmiyor, birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1768580839,'10K Gold Saint Barbara Diamond Cut Ruby Pendant','pendant','standart',ARRAY['10K Gold Pendant','Egypt Jewelry','Egypt Pendant','Diamond Cut Pendant','White Gold Pendant','Religious Pendant','Egyptian Pendant','Supper charm pendant','solid gold pendant','ruby pendant','barbara pendant','saint pendant','10K Pendant']::text[],ARRAY['10K Gold Pendant','Saint Barbara Charm','Santa Barbara Saint','Ruby Gold Necklace','Diamond Cut Pendant','Religious Necklace','Solid Gold Pendant','Catholic Gift Idea','Real Gold Pendant','Gift for Her','Womens Gold Necklace','Patron Saint Pendant','Ruby Birthstone Gift']::text[],'[{"tag": "Egypt Jewelry", "reason": "Relevance celiskisi: Saint Barbara Hristiyan/Katolik azizi, Misir/Egypt ile alakasi yok; yanlis trafik ceker, conversion dusurur."}, {"tag": "Egypt Pendant", "reason": "Ayni relevance celiskisi (Egypt ile urun ortusmuyor)."}, {"tag": "Egyptian Pendant", "reason": "Hem irrelevant hem Egypt/Egyptian tekrari (3 kez ayni yanlis kok)."}, {"tag": "White Gold Pendant", "reason": "Malzeme/baslik celiskisi: urun Yellow Gold 10K; white gold degil, yaniltici."}, {"tag": "Supper charm pendant", "reason": "Yazim hatasi (''Supper'') + dusuk kaliteli, anlamsiz arama; slot israfi."}, {"tag": "10K Pendant", "reason": "''10K Gold Pendant'' ile fiili tekrar; ekstra sinyal katmiyor."}, {"tag": "barbara pendant", "reason": "Zayif; ''Saint Barbara Charm'' tam-ad long-tail''ine konsolide edildi."}, {"tag": "saint pendant", "reason": "Genel/zayif; ''Patron Saint Pendant'' ve ''Saint Barbara Charm''a konsolide edildi."}, {"tag": "Religious Pendant", "reason": "Kavram korundu ama ''pendant'' asiri tekrarini kirmak icin ''Religious Necklace'' varyantina cevrildi."}, {"tag": "ruby pendant", "reason": "Ruby korundu (''Ruby Gold Necklace'' + ''Ruby Birthstone Gift''); tek-kelime-agirlikli pendant tekrari yerine niyet genisletildi."}]'::jsonb,'[{"tag": "Saint Barbara Charm", "reason": "Tam ad long-tail; en spesifik ve yuksek niyetli arama, baslikla birebir ortusur."}, {"tag": "Santa Barbara Saint", "reason": "Santeria/Ispanyolca konusan alici segmenti ''Santa Barbara'' tam bu terimle arar; genis meshru kitle."}, {"tag": "Ruby Gold Necklace", "reason": "Pendant''lar kolye olarak satilir (meshru necklace) + ruby + gold birlesimi."}, {"tag": "Religious Necklace", "reason": "Religious niyetini korur, ''pendant'' kok tekrarini necklace ile cesitlendirir."}, {"tag": "Catholic Gift Idea", "reason": "Eksik hediye slotu + Catholic relevance (Saint Barbara patron azizi); hediye niyetli alici."}, {"tag": "Real Gold Pendant", "reason": "Alici dili ''real gold''; som altin arayan alicinin guven arama terimi."}, {"tag": "Gift for Her", "reason": "Hediye + kitle slotu; tamamen eksikti."}, {"tag": "Womens Gold Necklace", "reason": "Kadin kitle + necklace; dar kitleyi acar."}, {"tag": "Patron Saint Pendant", "reason": "''Patron saint'' yuksek niyetli dini arama kalibi."}, {"tag": "Ruby Birthstone Gift", "reason": "Ruby Temmuz dogum tasi acisi + hediye niyeti; yeni bir arama boyutu."}]'::jsonb,'Uc "Egypt/Egyptian" tag urunle celisiyor (Saint Barbara Hristiyan/Katolik azizi, Misirla ilgisiz) ve 13 tagin 11''i "pendant" ile bitip kok israf ediyor; hediye/kitle/stil niyet slotlari tamamen eksik.','Standart arketip: relevance korunarak slot israfi temizlendi ve eksik niyet slotlari eklendi. Uc kritik gercek sorun: (1) Egypt/Egyptian 3 tagi urunle tam celiskili (Saint Barbara Hristiyan azizi) — kaldirildi. (2) White Gold, Yellow Gold/10K malzemesiyle celisiyor — kaldirildi. (3) 13 tagin 11''i ''pendant'' ile bitiyordu (kok israfi) + Supper yazim hatasi + 10K/10K Gold tekrari. Yeni sette ''pendant'' 5, ''necklace'' 3, ''charm'' 1 olarak dengelendi; tumu cok-kelimeli long-tail, tek-kelime cogunlugu yok, birebir tekrar yok. Guclu olanlar korundu (10K Gold Pendant, Diamond Cut Pendant, Solid Gold Pendant, ruby ve religious kavramlari). Eklenen niyet slotlari: hediye (Catholic Gift Idea, Gift for Her, Ruby Birthstone Gift), kitle (Womens Gold Necklace, Gift for Her), alici dili (Real Gold Pendant), segment (Santa Barbara Saint = Santeria), niyet kalibi (Patron Saint Pendant). Ruby birthstone acisi conversion''i dusuk (0.084%) listing icin yeni hediye trafigi getirebilir.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1740336135,'10K Solid Gold Last Supper Ring | Diamond Cut Religious Jewelry','ring','standart',ARRAY['Nugget Ring','Nugget mens','Gold Nugget Ring','Gold Statement Rings','10K Gold Rings','10K Solid Gold Ring','Solid Gold Ring','10K Ring','Gold Ring','White Gold Ring','Last Supper Ring','Large men ring','Diamond cut ring men']::text[],ARRAY['Last Supper Ring','Religious Ring Men','Christian Mens Ring','Jesus Ring for Men','10K Solid Gold Ring','Real Gold Ring Men','Gold Statement Ring','Diamond Cut Ring Men','Faith Gift for Him','Chunky Mens Ring','Yellow Gold Ring Men','Catholic Ring Men','Mens Gold Jewelry']::text[],'[{"tag": "Nugget Ring", "reason": "Tip celiskisi: urun Last Supper yuzugu, nugget degil - alakasiz trafik ve relevance dususu"}, {"tag": "Nugget mens", "reason": "Tip celiskisi + belirsiz/zayif ifade"}, {"tag": "Gold Nugget Ring", "reason": "Tip celiskisi: ucuncu nugget tekrari, tamamen yanlis urun sinyali"}, {"tag": "White Gold Ring", "reason": "Malzeme celiskisi: urun 10K yellow gold; white gold arayanla eslesme yaniltici"}, {"tag": "10K Gold Rings", "reason": "10K/solid/gold kokunun 5 varyantindan biri - slot israfi"}, {"tag": "Solid Gold Ring", "reason": "Ayni gold-spec kumesinin tekrari, 10K Solid Gold Ring ile kapsaniyor"}, {"tag": "10K Ring", "reason": "Redundant ve dar; 10K Solid Gold Ring icinde zaten var"}, {"tag": "Gold Ring", "reason": "Jenerik, tek-koklu; long-tail rekabetinde deger uretmiyor"}, {"tag": "Large men ring", "reason": "Zayif ifade; Chunky Mens Ring daha aranan boyut sinyaliyle degistirildi"}, {"tag": "Gold Statement Rings", "reason": "Cogul; tekil Gold Statement Ring olarak normalize edildi"}]'::jsonb,'[{"tag": "Religious Ring Men", "reason": "Baslikta ''Religious'' var ama tag''lerde yoktu - ana niyet slotu + kitle"}, {"tag": "Christian Mens Ring", "reason": "Dinsel stil arama dili (christian) + erkek kitle"}, {"tag": "Jesus Ring for Men", "reason": "Last Supper temasinin dogrudan arama anahtari (Jesus)"}, {"tag": "Real Gold Ring Men", "reason": "Alici dili ''real gold'' + erkek kitle kombinasyonu"}, {"tag": "Gold Statement Ring", "reason": "Kullanim/stil slotu (statement); iri parca konumlandirmasi"}, {"tag": "Faith Gift for Him", "reason": "Eksik hediye slotu: faith + gift for him tek tag''de"}, {"tag": "Chunky Mens Ring", "reason": "Boyut/tarz slotu; ''large'' yerine daha aranan chunky terimi"}, {"tag": "Yellow Gold Ring Men", "reason": "Gercek malzeme (yellow gold) - yanlis white gold''un yerine dogru sinyal"}, {"tag": "Catholic Ring Men", "reason": "Mezhep bazli arama acisi (catholic) - genisletilmis dinsel kitle"}, {"tag": "Mens Gold Jewelry", "reason": "Kategori genisletme (jewelry koku); baslikta gecen ''Jewelry'' terimini yakalar"}]'::jsonb,'Uc ''Nugget'' tag''i gercek urunle (Last Supper yuzugu) celisiyor + 5''li 10K/gold/solid redundans slotu; dinsel/hediye/kitle niyet slotlari tamamen bos.','Uc kritik problem giderildi: (1) tip-celiskisi - uc Nugget tag''i urunle alakasizdi, silindi; (2) malzeme-celiskisi - White Gold gercek yellow gold ile degistirildi; (3) asiri redundans - 5''li 10K/solid/gold kumesi tek guclu tag''e (10K Solid Gold Ring) indirildi. Bosalan slotlar urunun en guclu ama tag''lerde hic islenmemis niyetiyle dolduruldu: dinsel/christian/jesus/catholic/faith temasi (baslikta var, tag''de yoktu), hediye slotu (Faith Gift for Him), stil/boyut (statement, chunky) ve alici dili (real gold, men). Last Supper Ring, 10K Solid Gold Ring ve Diamond Cut Ring Men mesru cekirdek terimler olarak korundu. 13 tag''in tamami cok-kelimeli long-tail, birebir tekrar yok, hepsi <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1763961937,'10K Gold Miami Cuban Bracelet with CZ Box Lock','bracelet','standart',ARRAY['Miami Cuban Link','Cuban Link Bracelet','10K Gold Bracelet','Gold Link Bracelet','Miami Chain Bracelet','Link Chain Bracelet','Gold Bracelet','Gold Chain Bracelet','Miami Cuban','Men Chain Bracelet','10K Bracelet','10K Miami Bracelet','Monaco Bracelet']::text[],ARRAY['Miami Cuban Link','Cuban Link Bracelet','10K Gold Bracelet','Mens Cuban Bracelet','Real Gold Bracelet','Hip Hop Bracelet','Gift for Him','Layering Bracelet','Statement Jewelry','Everyday Bracelet','Box Lock Bracelet','Mens Jewelry Gift','Unisex Bracelet']::text[],'[{"tag": "Miami Chain Bracelet", "reason": "Miami Cuban Link + Cuban Link Bracelet ile örtüşüyor; ''Miami'' kökü aşırı doygun, slot israfı."}, {"tag": "Link Chain Bracelet", "reason": "Generik; ''link/chain'' kökü tekrar, düşük niyet, ayırt edici değil."}, {"tag": "Gold Link Bracelet", "reason": "10K Gold Bracelet ile redundant + ''link'' örtüşmesi."}, {"tag": "Gold Bracelet", "reason": "Çok geniş/rekabetçi, tek niyet; 10K ve Real Gold Bracelet zaten kapsıyor."}, {"tag": "Gold Chain Bracelet", "reason": "Gold+chain tekrarı; diğer gold/bracelet tag''lerinden farkı yok."}, {"tag": "Miami Cuban", "reason": "Miami Cuban Link''in birebir kısaltılmış kökü — duplicate, slot israfı."}, {"tag": "Men Chain Bracelet", "reason": "Zayıf; alıcı yazımı ''Mens'' + core terimle (Mens Cuban Bracelet) değiştirildi."}, {"tag": "10K Bracelet", "reason": "10K Gold Bracelet ile redundant, ''gold'' sinyali yok, daha zayıf."}, {"tag": "10K Miami Bracelet", "reason": "Miami+10K örtüşmesi, doğal olmayan arama ifadesi."}, {"tag": "Monaco Bracelet", "reason": "Monaco zinciri ≠ Miami Cuban; tip-çelişkisine yakın, hedef dışı."}]'::jsonb,'[{"tag": "Mens Cuban Bracelet", "reason": "Kitle + core alıcı ifadesi; belirsiz ''Men Chain Bracelet''in yerine ''Mens'' yazımıyla."}, {"tag": "Real Gold Bracelet", "reason": "Alıcı dili ''real gold'' — som altın arayan trafiği yakalar."}, {"tag": "Hip Hop Bracelet", "reason": "Stil/tarz slotu; Miami Cuban için yüksek niyetli."}, {"tag": "Gift for Him", "reason": "Hediye slotu tamamen eksikti — erkek alıcı hediye niyetini açar."}, {"tag": "Layering Bracelet", "reason": "Kullanım slotu (katmanlama trendi)."}, {"tag": "Statement Jewelry", "reason": "Kullanım slotu + ''bracelet'' kökünden uzaklaşıp kelime çeşitliliği."}, {"tag": "Everyday Bracelet", "reason": "Kullanım slotu — günlük giyim niyeti."}, {"tag": "Box Lock Bracelet", "reason": "Başlıktaki CZ box lock kapağı — düşük rekabetli benzersiz ayırt edici."}, {"tag": "Mens Jewelry Gift", "reason": "Hediye + kitle birleşik slot."}, {"tag": "Unisex Bracelet", "reason": "Kitleyi erkek ötesine genişletir."}]'::jsonb,'13 slotun ~10''u "Miami/Cuban/Link/Gold Bracelet" kök varyantı — ağır redundancy slot israfı; hediye/stil/kullanım niyet slotları tamamen eksik.','Standart arketip: dengeli temizlik. 3 güçlü/relevant tag korundu (Miami Cuban Link, Cuban Link Bracelet, 10K Gold Bracelet). 10 redundant/dar tag çıkarıldı — bunların çoğu aynı ''Miami/Cuban/Link/Gold Bracelet'' kökünün varyantıydı ve Etsy kelimeleri kendisi kombinlediği için slot israfıydı. Boşalan slotlar eksik niyet kategorilerine dağıtıldı: kitle (Mens Cuban, Unisex), buyer-lang (Real Gold), stil (Hip Hop), hediye (Gift for Him, Mens Jewelry Gift), kullanım (Layering, Everyday, Statement) ve başlıktan gelen benzersiz ayırt edici (Box Lock). Relevance korundu — hiçbir tip-çelişkisi eklenmedi; ''Iced Out'' bilerek eklenmedi çünkü CZ yalnız kapakta, ürünün tamamı taşlı değil (over-claim riski). Hepsi çok-kelimeli long-tail, hepsi <=20 karakter, birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1522860530,'14K Yellow Gold Round Box Chain Necklace – Unisex','necklace','standart',ARRAY['14K Gold Chain','14K Gold Necklace','14K Chain','Box Chain','14K Box Chain','Gold Chain','Box Chain Necklace','Gold Box Chain','Round Box Chain','Gold Box Necklace','Gold Necklace','14K Link Chain','Gold Link Chain']::text[],ARRAY['Round Box Chain','Box Chain Necklace','Gold Box Chain','14K Gold Necklace','Real Gold Chain','Solid Gold Chain','Mens Gold Chain','Womens Gold Chain','Unisex Gold Chain','Layering Necklace','Everyday Necklace','Minimalist Chain','Gift For Him']::text[],'[{"tag": "14K Gold Chain", "reason": "14K Gold Necklace + Gold Box Chain ile ortusuyor; 14K koku 5 tag''te asiri tekrar"}, {"tag": "14K Chain", "reason": "Cok jenerik/dar kok; 14K tekrari, tek kavram slot israfi"}, {"tag": "Box Chain", "reason": "Box Chain Necklace ve Round Box Chain tarafindan zaten kapsaniyor"}, {"tag": "14K Box Chain", "reason": "Box chain koku 7 varyantla tekrarlaniyordu; birebir slot israfi"}, {"tag": "Gold Chain", "reason": "Genis jenerik; mens/womens/real/solid varyantlariyla daha iyi karsilaniyor"}, {"tag": "Gold Box Necklace", "reason": "Gold Box Chain + Box Chain Necklace ile neredeyse ayni; redundant"}, {"tag": "Gold Necklace", "reason": "Cok jenerik; 14K Gold Necklace zaten kok kelimeyi tasiyor"}, {"tag": "14K Link Chain", "reason": "Tip celiskisi: urun box chain, ''link chain'' relevance''i zayiflatir/yaniltir"}, {"tag": "Gold Link Chain", "reason": "Ayni tip celiskisi; box chain ile link chain arama niyetini bulanik yapar"}]'::jsonb,'[{"tag": "Real Gold Chain", "reason": "Alici dili (''real gold'') — som altin arayan yuksek niyetli aliciyi yakalar"}, {"tag": "Solid Gold Chain", "reason": "Alici dili (''solid gold'') — dolgu/kaplama degil som 14K vurgusu"}, {"tag": "Mens Gold Chain", "reason": "Kitle slotu: erkek aliciya acilim (unisex urun)"}, {"tag": "Womens Gold Chain", "reason": "Kitle slotu: kadin aliciya acilim (unisex urun)"}, {"tag": "Unisex Gold Chain", "reason": "Basliktaki ''Unisex'' niteligini arama slotuna tasir"}, {"tag": "Layering Necklace", "reason": "Kullanim slotu: ince yuvarlak box chain katmanlamaya ideal"}, {"tag": "Everyday Necklace", "reason": "Kullanim slotu: gunluk takim niyeti"}, {"tag": "Minimalist Chain", "reason": "Stil slotu: sade/ince box chain estetigi"}, {"tag": "Gift For Him", "reason": "Hediye slotu: erkek hediye niyeti (unisex urun, hic hediye tag''i yoktu)"}]'::jsonb,'"Box chain" koku 7/13 tag''te, "14K"/"Gold" ayrica asiri tekrar ediyor; hediye/kitle/kullanim/stil niyet slotlari komple bos ve iki tag (link chain) urun tipiyle (box chain) celisiyor.','Standart arketip = dengeli temizlik. Box chain/14K/Gold kok tekrari (7+ tag) tek varyanta indirildi; urun kimligi icin Round Box Chain, Box Chain Necklace, Gold Box Chain, 14K Gold Necklace korundu (relevance saglam). Tip-celiskili iki ''link chain'' tag''i kaldirildi. Acilan 9 slot alici dili (real/solid gold), kitle (mens/womens/unisex), kullanim (layering/everyday), stil (minimalist) ve hic olmayan hediye niyetiyle (gift for him) dolduruldu. Tumu cok-kelimeli long-tail, hepsi <=20 karakter, birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1475151914,'10K Solid Gold Nugget Stud Earrings, Diamond Cut','earring','standart',ARRAY['Gold Stud Earrings','Stud Earrings','Nugget Earrings','Diamond Cut Earrings','Real Gold Earrings','Solid Gold Earrings','10K Gold Earrings','White Gold Earrings','10K Large Earrings','10K Stud Earrings','Gold Nugget Earrings','10K Gold Hoop','Extra Large Earrings']::text[],ARRAY['Gold Stud Earrings','Nugget Earrings','Diamond Cut Earrings','Real Gold Earrings','Solid Gold Earrings','10K Gold Earrings','Womens Gold Studs','Gift for Her','Mothers Day Gift','Everyday Earrings','Statement Earrings','Luxury Gold Jewelry','Large Stud Earrings']::text[],'[{"tag": "White Gold Earrings", "reason": "Tip-celiskisi: urun sari/10K real gold; beyaz altin niteligi urun gercegiyle celisiyor, yanlis alici cekiyor."}, {"tag": "10K Gold Hoop", "reason": "Tip-celiskisi: urun STUD kupe; hoop (halka) tamamen farkli tip, alakasiz trafik."}, {"tag": "Stud Earrings", "reason": "Redundancy: ''stud'' koku ''Gold Stud Earrings'' ile zaten var; Etsy kelimeleri kombinler, ayrica tek basina daha genel/zayif."}, {"tag": "10K Stud Earrings", "reason": "Redundancy: ucuncu stud varyanti; 10K ve stud kokleri baska tag''lerde mevcut, slot israfi."}, {"tag": "Gold Nugget Earrings", "reason": "Redundancy: ''nugget'' koku ''Nugget Earrings'' ile ayni; ikinci varyant yeni arama sozcugu getirmiyor."}, {"tag": "10K Large Earrings", "reason": "Redundancy: beden niyeti ''Extra Large'' ile cift; birini birlestirilmis ''Large Stud Earrings'' ile degistirdik."}, {"tag": "Extra Large Earrings", "reason": "Redundancy: beden ikinci kez; stud+beden birlesimi ''Large Stud Earrings'' daha isabetli long-tail."}]'::jsonb,'[{"tag": "Womens Gold Studs", "reason": "Kitle slotu: alici (womens) hedeflemesi tamamen eksikti; kupe alicilarinin cogunlugu kadin."}, {"tag": "Gift for Her", "reason": "Hediye slotu: yuksek hacimli alis niyeti; taki listinginde en guclu donusum sinyallerinden."}, {"tag": "Mothers Day Gift", "reason": "Occasion/hediye slotu: mevsimsel yuksek trafikli arama; tamamen eksikti."}, {"tag": "Everyday Earrings", "reason": "Kullanim slotu: stud kupe gunluk kullanim niyetiyle aranir, eksikti."}, {"tag": "Statement Earrings", "reason": "Stil slotu: buyuk nugget stud statement urunu; genis stil aramasi getirir."}, {"tag": "Luxury Gold Jewelry", "reason": "Stil/kategori genisletme: solid gold luxury konumlandirmasi; ''earrings'' disi kategori trafigi acar."}, {"tag": "Large Stud Earrings", "reason": "Beden+tip birlesik long-tail: iki bayat beden tag''inin yerine tek isabetli, tip-uyumlu varyant."}]'::jsonb,'Tip-celiskisi (yellow gold urunde ''White Gold Earrings'' + stud urunde ''10K Gold Hoop'') ve stud/beden kokunun asiri tekrari 13 slotu tuketmis, hediye/kitle/stil niyet slotlari tamamen bos.','Set relevance''i koruyarak temizlendi: iki tip-celiskisi tag (White Gold, Hoop) silindi cunku urun sari 10K solid gold STUD. Stud (3 varyant), nugget (2 varyant) ve beden (2 varyant) kok tekrarlari tek-birer guclu varyanta indirildi; Etsy kelimeleri kombinledigi icin bu slotlar israfti. Acilan 7 slot niyet-cesitliligiyle dolduruldu: kitle (Womens Gold Studs), hediye (Gift for Her, Mothers Day Gift), kullanim (Everyday), stil (Statement, Luxury Gold Jewelry) ve tip-uyumlu beden (Large Stud Earrings). Cekirdek arama tag''leri (Gold Stud, Nugget, Diamond Cut, Real Gold, Solid Gold, 10K Gold) korundu. Tum tag''ler <=20 karakter, hepsi cok-kelimeli, birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1877080307,'14K Gold Miami Cuban Link Chain – Shiny CZ Box Lock Curb Chain','necklace','standart',ARRAY['Miami Cuban Link','Miami Cuban','Monaco Chain','Cuban Chain','Link Chain','Monaco Cuban','Gold Chain','14K GOLD CHAIN','14K MIAMI','14K CHAIN','14K CUBAN CHAIN','14K GOLD NECKLACE','14K MIAMI CHAIN']::text[],ARRAY['Miami Cuban Link','Cuban Link Necklace','14K Gold Chain','Gold Chain for Men','Mens Gold Necklace','Real Gold Chain','Iced Out Chain','Hip Hop Necklace','Layering Necklace','Gift for Him','Curb Link Chain','Monaco Chain','Statement Necklace']::text[],'[{"tag": "Miami Cuban", "reason": "Miami Cuban Link''in alt kumesi; Etsy kelimeleri zaten kombinler, birebir tekrar slot israfi"}, {"tag": "Cuban Chain", "reason": "cuban+chain koku baska tag''lerde defalarca var; bare varyant deger katmiyor"}, {"tag": "Monaco Cuban", "reason": "Monaco Chain korundu; ikinci monaco varyanti redundant"}, {"tag": "Link Chain", "reason": "asiri genel/zayif; hicbir niyet veya kitle sinyali tasimiyor"}, {"tag": "Gold Chain", "reason": "bare kok; long-tail varyantlar (for men, real, 14k) ayni tokenlari daha guclu tasiyor"}, {"tag": "14K MIAMI", "reason": "kelime parcasi; 14k ve miami zaten ayri tam tag''lerde var"}, {"tag": "14K CHAIN", "reason": "parca/redundant; 14K Gold Chain bunu kapsar"}, {"tag": "14K CUBAN CHAIN", "reason": "14k+cuban tekrari; kok zaten doygun"}, {"tag": "14K GOLD NECKLACE", "reason": "14k tekrari; necklace niyeti Cuban Link Necklace ile daha iyi karsilaniyor"}, {"tag": "14K MIAMI CHAIN", "reason": "miami+14k+chain ucuncu kez tekrar; net yeni erisim yok"}]'::jsonb,'[{"tag": "Cuban Link Necklace", "reason": "urun tipi necklace ile hizalar + cuban kokunu necklace aramasina tasir (mesru)"}, {"tag": "Gold Chain for Men", "reason": "kitle slotu: cuban link erkek-agirlikli; alici dili"}, {"tag": "Mens Gold Necklace", "reason": "kitle + necklace kombinasyonu; farkli long-tail"}, {"tag": "Real Gold Chain", "reason": "alici dili (real/solid gold); som 14K altini vurgular"}, {"tag": "Iced Out Chain", "reason": "stil slotu; basliktaki ''Shiny CZ'' ile eslesir"}, {"tag": "Hip Hop Necklace", "reason": "stil/tarz slotu; cuban link''in ana pazar dili"}, {"tag": "Layering Necklace", "reason": "kullanim slotu; katmanlama aramasi"}, {"tag": "Gift for Him", "reason": "hediye slotu; erkek-agirlikli urun icin dogru hediye niyeti"}, {"tag": "Curb Link Chain", "reason": "basliktaki ''Curb Chain'' terimini yakalar; alternatif zincir tipi aramasi"}, {"tag": "Statement Necklace", "reason": "kullanim/tarz slotu; farkli token cesitliligi ekler"}]'::jsonb,'13 slotun neredeyse tamami tek bir kok etrafinda ("14K" 6, "miami/cuban" 6+ tekrar) israf edilmis; hicbir hediye/stil/kullanim/kitle niyet slotu yok.','Standart/dengeli strateji: once redundancy temizlendi. Orijinalde 6 tag 14K parcasi, 6+ tag miami/cuban koku tasiyordu — cogu Etsy''nin kelime kombinlemesi altinda bosa slottu. Cuban/miami ailesini 4 mesru varyanta indirdim (Miami Cuban Link, Cuban Link Necklace, Curb Link Chain, Monaco Chain). Bosalan slotlari eksik niyetlere actim: kitle (Gold Chain for Men, Mens Gold Necklace), hediye (Gift for Him), stil (Iced Out Chain, Hip Hop Necklace, Statement Necklace), kullanim (Layering Necklace), alici dili (Real Gold Chain). Necklace tag''leri urun tipiyle (necklace) uyumlu, tip-celiskisi yok. 13 tag''in tamami cok-kelimeli long-tail, hepsi <=20 karakter, birebir tekrar yok. conv=0.012% cok dusuk (16.7K goruntuleme / 2 satis) — problem trafik degil, alaka/niyet eslesmesi; hediye ve kitle slotlari donusum icin kritik.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1862428966,'10K Gold Rope Chain Necklace – Twisted Diamond Cut','necklace','standart',ARRAY['Rope Chain','Gold Rope Chain','Gold Chain','Rope Chain Necklace','Real Gold Chain','Real Gold Rope Chain','Rope Necklace','chain necklace','10K ROPE CHAIN','10K GOLD CHAIN','10K CHAIN','10K GOLD ROPE CHAIN','gold necklace']::text[],ARRAY['Gold Rope Chain','Rope Chain Necklace','10K Solid Gold Chain','Diamond Cut Necklace','Twisted Rope Chain','Mens Gold Chain','Gold Chain for Him','Real Gold Necklace','Layering Necklace','Everyday Necklace','Italian Gold Chain','Hip Hop Jewelry','Womens Gold Chain']::text[],'[{"tag": "Rope Chain", "reason": "Gold Rope Chain ile ayni kok; tek-nitelik tekrari, Etsy zaten kelimeleri kombinler."}, {"tag": "Gold Chain", "reason": "Cok generic/kisa baskin terim; nitelikli varyantlarla kapsandi."}, {"tag": "Real Gold Chain", "reason": "''real gold'' niyeti Real Gold Necklace''e tasindi; chain koku fazlaydi."}, {"tag": "Real Gold Rope Chain", "reason": "rope+real+chain ucuz tekrar, saf slot israfi."}, {"tag": "Rope Necklace", "reason": "rope kok tekrari; Rope Chain Necklace daha guclu long-tail."}, {"tag": "chain necklace", "reason": "generic, ayirt edici niyet yok; nitelikli necklace tag''leri ile degistirildi."}, {"tag": "10K ROPE CHAIN", "reason": "rope kok tekrari; karat sinyali 10K Solid Gold Chain''de korundu."}, {"tag": "10K GOLD CHAIN", "reason": "10K Solid Gold Chain''e birlestirildi (''solid gold'' alici dili eklenerek)."}, {"tag": "10K CHAIN", "reason": "generic kisa tekrar; ayirt edici deger yok."}, {"tag": "10K GOLD ROPE CHAIN", "reason": "en agir rope+gold+chain tekrari; slot israfinin zirvesi."}, {"tag": "gold necklace", "reason": "generic; niyet-nitelikli necklace tag''leriyle (mens/womens/layering/everyday) degistirildi."}]'::jsonb,'[{"tag": "10K Solid Gold Chain", "reason": "''solid gold'' alici dili + karat; iki eski 10K/gold tag''ini tek guclu long-tail''de birlestirir."}, {"tag": "Diamond Cut Necklace", "reason": "Baslikta olan ''Diamond Cut'' hic tag''lenmemisti; yuksek niyetli stil slotu."}, {"tag": "Twisted Rope Chain", "reason": "Baslik ''Twisted'' tanimini tag''e tasir; rope kokunu tekrar degil stil ile ayirir."}, {"tag": "Mens Gold Chain", "reason": "Kitle slotu; rope zincir erkek aramalarinda baskin, tamamen eksikti."}, {"tag": "Gold Chain for Him", "reason": "Hediye niyet slotu (gift for him); sifirdi."}, {"tag": "Real Gold Necklace", "reason": "''real gold'' alici dilini necklace tipiyle korur; drop edilen real-gold niyetini tasir."}, {"tag": "Layering Necklace", "reason": "Kullanim slotu; katmanli takide guclu aranan niyet."}, {"tag": "Everyday Necklace", "reason": "Kullanim slotu; gunluk kullanim alicisi."}, {"tag": "Italian Gold Chain", "reason": "Stil/mensei slotu; kalite algisi ve ek arama hacmi."}, {"tag": "Hip Hop Jewelry", "reason": "Tarz slotu; rope/diamond cut zincirlerin ana estetik nisi."}, {"tag": "Womens Gold Chain", "reason": "Kitle slotunu genisletir; erkek-agirlikli set kadin alicisini disaridan iceri alir."}]'::jsonb,'"rope chain" koku 7 tag''te tekrarlanip slotlari yiyor; hediye/kitle/stil/kullanim niyet slotlari tamamen bos.','Eski set tip-celisik degildi (necklace/chain mesru) ama asiri redundant: rope-chain koku 7, gold/10K-chain koku 5+ tag''te tekrarlaniyor, hiçbiri farkli niyet eklemiyordu. Sadece Gold Rope Chain ve Rope Chain Necklace korundu (cekirdek relevance). Bosalan 11 slot baslik/urun gercegine sadik kalarak niyetle dolduruldu: stil (Diamond Cut, Twisted, Italian, Hip Hop), kitle (Mens, Womens), hediye (for Him), kullanim (Layering, Everyday), alici-dili karat (10K Solid Gold, Real Gold). Tumu 2+ kelime long-tail, hepsi <=20 karakter, birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1390701590,'14K Real Gold Mariner Link Chain | Puffed Anchor Necklace','necklace','standart',ARRAY['Puffed Chain','Mariner Necklace','Gold Chain','14K Gold Chain','Anchor Chain','Puffed Necklace','Gold Link Chain','Real Gold Chain','14K Gold Necklace','Gold Mariner Chain','Anchor Necklace','Dainty Chain','Gold Anchor Chain']::text[],ARRAY['Mariner Link Chain','Puffed Anchor Chain','14k Gold Necklace','Real Gold Chain','Solid Gold Necklace','Gold Chain for Men','Mens Gold Jewelry','Layering Necklace','Gift for Him','Italian Gold Chain','Anchor Necklace','Everyday Chain','Unisex Gold Chain']::text[],'[{"tag": "Puffed Chain", "reason": "Puffed Anchor Chain kokunu tekrar ediyor; slot israfi."}, {"tag": "Mariner Necklace", "reason": "Mariner Link Chain ile ayni kok; birebir yakin tekrar."}, {"tag": "Gold Chain", "reason": "Tek-kelimeye yakin, cok genis/dusuk long-tail; rekabette gomulur."}, {"tag": "14K Gold Chain", "reason": "14k Gold Necklace + Real Gold Chain ile gold-chain kokunu cogaltiyor."}, {"tag": "Anchor Chain", "reason": "Puffed Anchor Chain + Anchor Necklace ile anchor kokunu 3''e cikariyordu."}, {"tag": "Puffed Necklace", "reason": "Puffed kokunun 2. tekrari; ek arama niyeti yok."}, {"tag": "Gold Link Chain", "reason": "Mariner Link Chain ''link chain'' aramasini zaten kapsiyor."}, {"tag": "Gold Mariner Chain", "reason": "Mariner Link Chain ile mariner+chain ortusmesi; birebir yakin."}, {"tag": "Dainty Chain", "reason": "Puffed/anchor kalin-hacimli bir zincir; ''dainty'' urun gercegiyle celisir + slot israfi."}, {"tag": "Gold Anchor Chain", "reason": "anchor+gold+chain uclusu diger 3 tag''de zaten var; net redundancy."}]'::jsonb,'[{"tag": "Mariner Link Chain", "reason": "5 dagilmis mariner/anchor varyanti tek net long-tail cekirdekte konsolide edildi (baslikla birebir)."}, {"tag": "Puffed Anchor Chain", "reason": "Baslik anahtar ifadesi; puffed+anchor tek ozgun long-tail''de birlestirildi."}, {"tag": "Solid Gold Necklace", "reason": "Malzeme listesindeki ''Solid Gold'' alici dili; ''necklace'' koku ile chain tekrarini kirar."}, {"tag": "Gold Chain for Men", "reason": "Eksik KITLE slotu; yuksek hacimli erkek alici dili."}, {"tag": "Mens Gold Jewelry", "reason": "Kitle + kategori kokunu (jewelry) genisletir, gold-chain tekrarindan kacar."}, {"tag": "Layering Necklace", "reason": "Eksik KULLANIM slotu; katmanlama trend aramasi."}, {"tag": "Gift for Him", "reason": "Eksik HEDIYE slotu; erkek zincirinde guclu donusum niyeti."}, {"tag": "Italian Gold Chain", "reason": "Eksik STIL slotu; som altin zincirde premium arama sinyali."}, {"tag": "Everyday Chain", "reason": "Ek kullanim niyeti; gunluk tasima aramasi."}, {"tag": "Unisex Gold Chain", "reason": "Kitleyi genisletir (erkek+notr), tek-cinse sikismayi onler."}]'::jsonb,'Asiri redundancy: 13 tag''in 10''u "gold + chain/necklace" kokunu tekrarliyor (anchor/mariner/puffed 2-3''er kez) ve hediye/kitle/stil/kullanim niyet slotlari tamamen bos.','Standart arketip: dengeli temizlik. Sorun teshisi objektif — mevcut 13 tag''in 10''u gold-chain/necklace kokunu, anchor 3x, mariner/puffed 2x tekrarliyordu; Etsy kelimeleri kendi kombinledigi icin bu net slot israfi. Cozum: cekirdek urun terimlerini (mariner link, puffed anchor, anchor necklace) korurken 3''e indirdim ve acilan slotlari eksik niyetlerle doldurdum — kitle (for men / mens / unisex), hediye (gift for him), stil (italian), kullanim (layering / everyday). Relevance korundu: necklace bu urun icin mesru (urun tipi=necklace), ''solid/real/14k gold'' malzeme listesiyle birebir uyumlu. Celisen ''dainty'' cikarildi (puffed anchor kalin bir zincir). Gold-chain koku 4 tag''de kaldi ama her biri farkli arama modifier''i (real/for men/italian/unisex) tasidigi icin salt tekrar degil. Tum tag''ler cok-kelimeli long-tail ve <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1849001180,'10K Yellow Gold Figaro Link Chain | Polished Finish','necklace','standart',ARRAY['10K Gold Chain','Gold Chain','10K Chain','Gold Link Chain','Figaro Bracelet','Figaro Chain','Real Gold Chain','Gold Chain men','Real Gold man chain','10K men chain','Link Chain','10K figaro Chain','Gold Figaro Chain']::text[],ARRAY['10K Gold Figaro','Figaro Chain Men','Real Gold Chain','Gold Chain for Him','Solid Gold Necklace','Layering Necklace','Italian Gold Chain','Mens Gold Necklace','Everyday Gold Chain','Polished Gold Chain','Gift for Him','Unisex Gold Chain','10K Real Gold']::text[],'[{"tag": "Figaro Bracelet", "reason": "Tip-çelişkisi: başlık ve ürün tipi necklace/chain; bracelet farklı bir ürün, alakasız trafik + relevance düşürür."}, {"tag": "10K Gold Chain", "reason": "Etsy kelimeleri kendisi kombinler; ''10K Gold Figaro'' + ''10K Real Gold'' bu bigramı zaten üretir, slot israfı."}, {"tag": "Gold Chain", "reason": "Tek başına aşırı genel ve baskın kök; kombinasyondan doğuyor, ayrı slot harcamaya değmez."}, {"tag": "10K Chain", "reason": "Redundant; 10K + chain diğer long-tail''lerde kapsanıyor."}, {"tag": "Gold Link Chain", "reason": "''Link'' düşük ayırt edicilik; ''Link Chain'' ile birlikte aynı kökün tekrarı."}, {"tag": "Link Chain", "reason": "Zayıf, jenerik kök tekrarı; figaro/necklace long-tail''leri daha güçlü."}, {"tag": "Figaro Chain", "reason": "''Figaro Chain Men'' long-tail''ine yükseltildi (kitle sinyali ekler)."}, {"tag": "Real Gold man chain", "reason": "Bozuk gramer (''man''); ''Real Gold Chain'' + men varyantlarıyla temiz biçimde kapsandı."}, {"tag": "10K men chain", "reason": "Figaro/mens necklace varyantlarıyla kapsandı; kök tekrarı."}, {"tag": "10K figaro Chain", "reason": "''10K Gold Figaro'' ile birleşti; birebir yakın tekrar."}, {"tag": "Gold Figaro Chain", "reason": "''10K Gold Figaro'' ile örtüşüyor; slot israfı."}, {"tag": "Gold Chain men", "reason": "''Figaro Chain Men'' ve ''Mens Gold Necklace'' daha spesifik/güçlü versiyonlar."}]'::jsonb,'[{"tag": "10K Gold Figaro", "reason": "Çekirdek ayırt edici; dağınık 10K/figaro tag''lerini tek slotta birleştirir."}, {"tag": "Figaro Chain Men", "reason": "Kitle (erkek) + ürün long-tail; alıcı arama diline uyar."}, {"tag": "Gold Chain for Him", "reason": "Hediye slotu (gift for him) — tümüyle eksikti."}, {"tag": "Solid Gold Necklace", "reason": "Alıcı dili ''solid gold'' + ürün gerçeği necklace (pendant değil düz zincir de necklace olarak aranır)."}, {"tag": "Layering Necklace", "reason": "Kullanım slotu (layering) — yüksek hacimli niyet araması."}, {"tag": "Italian Gold Chain", "reason": "Stil slotu; figaro İtalyan kökenli, celişki yok, relevant."}, {"tag": "Mens Gold Necklace", "reason": "Kitle + necklace terimi; erkek alıcı segmentini genişletir."}, {"tag": "Everyday Gold Chain", "reason": "Kullanım slotu (everyday) — günlük kullanım niyeti."}, {"tag": "Polished Gold Chain", "reason": "Başlıktaki ''Polished Finish'' niteliğini arama tarafında yakalar."}, {"tag": "Gift for Him", "reason": "İkinci hediye sinyali; anahtar ''gift'' bigramını yüzeye çıkarır."}, {"tag": "Unisex Gold Chain", "reason": "Kitle genişletme (erkek dışına da açar)."}, {"tag": "10K Real Gold", "reason": "Malzeme + alıcı dili (''real gold''); som altın güvence sinyali."}]'::jsonb,'Aşırı redundancy: 13 tag''in ~10''u "gold chain / 10K chain / link chain" aynı kökünü kombinlerken hediye/stil/kullanım/kadın-unisex niyet slotları tamamen boş ve bir tag ürünle çelişiyor (Figaro Bracelet).','Orijinal set trafiği getirmiş (14477 views) ama %0.214 dönüşüm ve daralmış terim havuzu, sorunun keşif değil relevance/niyet çeşitliliği olduğunu gösteriyor. Baskın kök (''gold chain'',''10K chain'',''link chain'') 10+ slotu yiyor; Etsy bigramları kendisi kombinlediği için bunlar israf. Temizlenen slotlar dört boş niyet eksenine dağıtıldı: hediye (for him / gift for him), kitle (men / mens / unisex), stil (italian, polished), kullanım (layering, everyday). Figaro (çekirdek ayırt edici) 2 güçlü long-tail''de korundu; ''necklace'' düz zincir için meşru olduğundan 3 varyantta kullanıldı. Tip-çelişen ''Figaro Bracelet'' silindi, bozuk gramerli ''Real Gold man chain'' düzeltilerek kapsandı. 13 tag''in tamamı çok-kelimeli, birebir tekrar yok, hepsi ≤20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1485089843,'14K Solid Gold Beaded Ball Chain Necklace, Diamond Cut','necklace','standart',ARRAY['Beaded Necklace','Bead Ball Chain','Beads Necklace','Bead Necklace','Beaded Chain','14K Gold Necklace','Solid Gold Necklace','14K Gold Chain','14K Bead Necklace','Gold Bead Chain','Gold Bead Necklace','Half Moon Chain','Diamond Cut Necklace']::text[],ARRAY['Beaded Ball Chain','14K Gold Necklace','Solid Gold Necklace','Diamond Cut Chain','Gold Bead Necklace','Real Gold Necklace','Gold Chain for Her','Layering Necklace','Dainty Gold Chain','Everyday Necklace','Gift for Her','Womens Gold Chain','Minimalist Necklace']::text[],'[{"tag": "Beaded Necklace", "reason": "bead+necklace koku fazlaligi; Etsy kelimeleri kendi kombinler, tek varyant yeter"}, {"tag": "Bead Ball Chain", "reason": "asil urun long-tail''i ''Beaded Ball Chain'' olarak duzeltilerek korundu; bu near-dup"}, {"tag": "Beads Necklace", "reason": "bead necklace tekrari, slot israfi"}, {"tag": "Bead Necklace", "reason": "bead necklace tekrari, slot israfi"}, {"tag": "Beaded Chain", "reason": "bead+chain tekrari; kok zaten diger tagde var"}, {"tag": "14K Gold Chain", "reason": "''14K Gold Necklace'' ile ayni kok; chain/necklace Etsy''de kombinlenir"}, {"tag": "14K Bead Necklace", "reason": "bead+14K tekrari; 14K ve bead ayri taglerde zaten kapsandi"}, {"tag": "Gold Bead Chain", "reason": "''Gold Bead Necklace'' korundu; bu near-dup"}, {"tag": "Half Moon Chain", "reason": "RELEVANCE celiskisi — urun boncuklu top zincir, half-moon farkli bir zincir tipi; yaniltici"}, {"tag": "Diamond Cut Necklace", "reason": "''Diamond Cut Chain'' varyantina cevrildi — Etsy''nin chain/necklace kombinlemesine daha genis eslesme alani"}]'::jsonb,'[{"tag": "Beaded Ball Chain", "reason": "urunun tam kimligi; baslikla birebir long-tail (bosaltilan bead varyantlarinin yerine tek guclu kok)"}, {"tag": "Diamond Cut Chain", "reason": "baslik/nitelik kelimesi; necklace yerine chain varyanti ile kombin alani genisletir"}, {"tag": "Real Gold Necklace", "reason": "alici dili — ''real gold'' arama niyeti (solid gold aliciyi ceker)"}, {"tag": "Gold Chain for Her", "reason": "kitle+hediye slotu; kadin alici / him-her niyeti hic yoktu"}, {"tag": "Layering Necklace", "reason": "kullanim slotu — ince zincirlerde en guclu satin alma niyetlerinden"}, {"tag": "Dainty Gold Chain", "reason": "stil slotu; ince/zarif boncuk zincirin gercek estetigi"}, {"tag": "Everyday Necklace", "reason": "kullanim slotu — gunluk takilabilir konumlandirmasi"}, {"tag": "Gift for Her", "reason": "hediye niyet slotu; genis ve yuksek donusum trafigi"}, {"tag": "Womens Gold Chain", "reason": "kitle slotu — dar kalan kadin alici hedeflemesini acar"}, {"tag": "Minimalist Necklace", "reason": "tarz slotu; minimal/sade estetik arayan segmenti yakalar"}]'::jsonb,'13 tag''in 8''i tek bir kok olan "bead/beaded necklace" varyanti (Etsy zaten kombinler) — dev slot israfi; hediye/kitle/stil/kullanim niyet slotlari sifir.','Ana sorun asiri redundancy: 13 taginin 8''i pratikte ''bead necklace'' ile ayni koktu; Etsy kelimeleri kendi kombinledigi icin bu 8 slot tek bir aramayi tekrar tekrar hedefliyor, geri kalan niyet uzayi (hediye, kitle, stil, kullanim) hic kapsanmiyordu. Tum bead varyantlarini TEK guclu long-tail''e (''Beaded Ball Chain'' + ''Gold Bead Necklace'') indirdim. ''Half Moon Chain'' urun tipiyle celisen yaniltici tag oldugu icin cikarildi. Cekirdek altin/14K/solid sinyalleri korundu; bosalan 8 slot hediye (Gift for Her, Gold Chain for Her), kitle (Womens Gold Chain), stil (Dainty, Minimalist), kullanim (Layering, Everyday) ve alici dili (Real Gold) ile dolduruldu. 13/13 dolu, hepsi <=20 karakter, tamami cok-kelimeli, birebir tekrar yok, relevance korundu.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1735786221,'10K Gold Pharaoh Pendant Necklace | CZ & Ruby, Egyptian King','pendant','standart',ARRAY['Pharaoh Pendant','Pharaoh Necklace','Egyptian Pendant','Egyptian Necklace','King Pendant','King necklace','10K Rope Chain','Gold Rope Chain','Textured Pendant','Textured Necklace','10K Gold Necklace','Solid Gold Necklace','10K Gold Pendant']::text[],ARRAY['Pharaoh Pendant','Egyptian Necklace','Egyptian King','10K Gold Necklace','Solid Gold Pendant','10K Rope Chain','Gold Chain For Men','Mens Gold Necklace','Gift For Him','Hip Hop Jewelry','Iced Out Pendant','Ruby Gold Pendant','Egyptian Jewelry']::text[],'[{"tag": "Pharaoh Necklace", "reason": "Pharaoh koku ''Pharaoh Pendant'' ile zaten kapsandi; Etsy kelimeleri kendi kombinler, ayni kok ciftlemesi slot israfi."}, {"tag": "Egyptian Pendant", "reason": "''Egyptian Necklace'' ile ayni Egyptian koku; ciftleme gereksiz."}, {"tag": "King Pendant", "reason": "King temasi ''Egyptian King'' ile daha guclu/dogal kapsandi; slot niyet tag''ine acildi."}, {"tag": "King necklace", "reason": "King koku tekrari; ayrica dusuk hacimli jenerik terim."}, {"tag": "Gold Rope Chain", "reason": "''10K Rope Chain'' ile ayni rope chain koku; birebir cift, biri yeter."}, {"tag": "Textured Pendant", "reason": "''Textured'' alici arama dili degil, dusuk niyet/dusuk hacim; iki textured tag''i de tema/hediye slotu icin feda edildi."}, {"tag": "Textured Necklace", "reason": "Textured kok tekrari + zayif arama terimi."}, {"tag": "Solid Gold Necklace", "reason": "Necklace slotu doygun (4 adet); solid gold niyeti daha az dolu pendant tarafina ''Solid Gold Pendant'' olarak tasindi."}, {"tag": "10K Gold Pendant", "reason": "''10K Gold Necklace'' ile 10K gold koku zaten var; ayni kok tekrari, slot bosaltildi."}]'::jsonb,'[{"tag": "Egyptian King", "reason": "Baslikta birebir gecen guclu tema ifadesi (''Egyptian King''); King+Egyptian nitelerini tek slotta long-tail olarak birlestirir."}, {"tag": "Solid Gold Pendant", "reason": "''solid gold'' yuksek donusumlu alici dili; pendant tarafini dengeler."}, {"tag": "Gold Chain For Men", "reason": "Kitle (mens) + alici dili; Pharaoh/Egyptian/King urun tamamen erkek/hip-hop hedefli, bu slot tamamen eksikti."}, {"tag": "Mens Gold Necklace", "reason": "Erkek kitle niyeti; dar kitleyi genisletir, en olasi alici segmentini yakalar."}, {"tag": "Gift For Him", "reason": "Hediye niyet slotu tamamen bostu; erkek altin taki icin en guclu hediye sorgusu."}, {"tag": "Hip Hop Jewelry", "reason": "Stil/tarz slotu; CZ+Pharaoh estetigi hip-hop pazariyla birebir ortusur."}, {"tag": "Iced Out Pendant", "reason": "CZ tasli urun icin ''iced out'' populer alici stil terimi; kullanim/stil niyeti."}, {"tag": "Ruby Gold Pendant", "reason": "Baslikteki Ruby niteligini kullanir; renkli tas ozgunlugu rekabeti azaltir."}, {"tag": "Egyptian Jewelry", "reason": "Tema kategorisini genisletir; pendant/necklace kok tekrari yerine daha genis kesif trafigi."}]'::jsonb,'Ayni kok pendant/necklace ciftleriyle (Pharaoh/Egyptian/King/Textured) 6+ slot israf edilmis; hediye, kitle (mens) ve stil (hip hop) niyet slotlari tamamen bos.','Baslik acikca ''Pendant Necklace'' oldugu icin necklace tag''leri tip-celiskisi DEGIL, mesru — korlemesine silinmedi. Asil sorun redundancy: Pharaoh/Egyptian/King/Textured her biri hem Pendant hem Necklace olarak ciftlenmis, Etsy zaten kelimeleri kombinledigi icin bu 6+ slotu bosa harciyor. Rope chain de iki kez (10K + Gold) tekrarlanmis. Bu israf temizlenip kok basina tek guclu varyant birakildi; acilan slotlara urunun tamamen eksik olan niyet katmanlari eklendi: kitle (mens/for men), hediye (gift for him), stil (hip hop, iced out), ve tas ozgunlugu (ruby). Alici dili one cikarildi (solid gold, gold chain for men). Sonuc: 13 slotun hepsi dolu, tamami cok-kelimeli long-tail, birebir/kok tekrari yok, relevance korundu.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1355524756,'10K Solid Gold Mariner Link Bracelet | Unisex Flat Anchor Chain','bracelet','standart',ARRAY['Mariner Bracelet','Mariner Chain','Gold Anchor Bracelet','Gold Mariner Chain','Thick Gold Chain','Gold Link Bracelet','10K Gold Bracelet','10K Link Bracelet','Link Chain Bracelet','Flat Bracelet','Anchor Chain','Link Bracelet','10K Bracelet']::text[],ARRAY['Mariner Bracelet','Gold Anchor Bracelet','Solid Gold Bracelet','10K Gold Bracelet','Real Gold Bracelet','Flat Mariner Chain','Mens Gold Bracelet','Gold Bracelet Women','Gift For Him','Gift For Her','Everyday Bracelet','Stackable Bracelet','Layering Bracelet']::text[],'[{"tag": "Mariner Chain", "reason": "Mariner Bracelet + Flat Mariner Chain zaten karsiliyor; ucuncu mariner varyanti slot israfi."}, {"tag": "Gold Mariner Chain", "reason": "Pes pese ucuncu ''mariner'' kombinasyonu; Etsy koku kendi kombinler, saf redundancy."}, {"tag": "Thick Gold Chain", "reason": "Kalinlik urun gercegiyle dogrulanmadi + ''chain'' doygunlugu; hediye/kitle slotu icin feda edildi."}, {"tag": "Gold Link Bracelet", "reason": "''link'' + ''bracelet'' cok genel; arama niyeti dusuk, dort ''link bracelet'' varyantindan biri."}, {"tag": "10K Link Bracelet", "reason": "10K ve link kombinasyonu 10K Gold Bracelet ile ust uste biniyor."}, {"tag": "Link Chain Bracelet", "reason": "Uc genel isim ust uste; ozgun arama hacmi olmayan bos slot."}, {"tag": "Flat Bracelet", "reason": "Tek nitelikli, cok genel; ''flat'' sinyali Flat Mariner Chain icinde daha guclu tasindi."}, {"tag": "Anchor Chain", "reason": "Gold Anchor Bracelet zaten anchor niyetini karsiliyor; cift kayit."}, {"tag": "Link Bracelet", "reason": "Tek konsept, cok genel, defalarca tekrarlanan ''link bracelet'' kokunun ciplak hali."}, {"tag": "10K Bracelet", "reason": "10K Gold Bracelet ile ayni; daha zayif ve dar varyant."}]'::jsonb,'[{"tag": "Solid Gold Bracelet", "reason": "Alici dili ''solid gold'' (baslikta da var) — yuksek niyet, som altin arayanlari yakalar."}, {"tag": "Real Gold Bracelet", "reason": "Alici dili ''real gold''; kapli/imitasyon degil gercek altin arayan trafigi."}, {"tag": "Flat Mariner Chain", "reason": "Baslikta ''Flat Anchor Chain'' niteligini tek slotta mariner+flat olarak yogunlastirir."}, {"tag": "Mens Gold Bracelet", "reason": "Kitle slotu (erkek) — unisex/anchor stilinin baskin alici segmenti, eksikti."}, {"tag": "Gold Bracelet Women", "reason": "Kitle slotu (kadin) — unisex urun icin ikinci alici segmentini acar."}, {"tag": "Gift For Him", "reason": "Hediye niyet slotu tamamen bostu; erkege hediye yuksek donusumlu arama."}, {"tag": "Gift For Her", "reason": "Unisex urun icin ikinci hediye niyeti; kadin hediye trafigi."}, {"tag": "Everyday Bracelet", "reason": "Kullanim slotu — gunluk takilabilir dayanikli altin niyetini yakalar."}, {"tag": "Stackable Bracelet", "reason": "Kullanim slotu — bileklik istifleme aramasi, yeni ilgili trafik."}, {"tag": "Layering Bracelet", "reason": "Kullanim/tarz slotu — katmanli takı trendi, dar urun kimliginden slot genisletir."}]'::jsonb,'13 slotun neredeyse tamami tekil urun kimligini tekrarliyor (Mariner x3, "Link Bracelet" x4, "10K" x4, "Chain/Bracelet" doygunlugu) ve hediye/kitle/kullanim niyet slotlari tamamen bos.','Standart arketip: dengeli temizlik. Urun bracelet oldugu icin cekirdek kimligi 3 tag ile korudum (Mariner Bracelet, Gold Anchor Bracelet, 10K Gold Bracelet). Baslikta ''Flat Anchor Chain'' gectiginden ''chain'' terimleri mesru — ama 3 chain tag ile sinirladim (Flat Mariner Chain dahil), 4x tekrarlanan ''link bracelet'' ve 4x ''10K'', 3x ''mariner'' redundancy''sini kestim. Bosalan slotlari en yuksek getirili niyetlerle doldurdum: alici dili (solid/real gold), kitle (mens/womens), hediye (him/her) ve kullanim (everyday/stackable/layering). Origin/kesim iddiasi (Italian, diamond cut) urun gercegiyle dogrulanamadigindan relevance korumak icin eklenmedi. Tum tag''ler cok-kelimeli long-tail ve <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1232906923,'10K Gold Heart Hoop Earrings | Diamond Cut, Puffed Design','earring','standart',ARRAY['Huge Hoop Earrings','Puffed Earrings','Hoop Earrings','Gold Hoop Earrings','Graduated Earrings','Gold Graduated','Diamond Cut Earrings','Large Hoop Earrings','Heart Earrings','Gold Heart Earrings','Love Earrings','Twisted Earrings','Gold Twist Earrings']::text[],ARRAY['Gold Hoop Earrings','Heart Hoop Earrings','Diamond Cut Earrings','Puffed Hoop Earrings','10k Gold Earrings','Real Gold Earrings','Gift for Her','Valentines Day Gift','Womens Earrings','Everyday Earrings','Yellow Gold Jewelry','Large Hoop Earrings','Love Earrings']::text[],'[{"tag": "Huge Hoop Earrings", "reason": "Large Hoop Earrings ile es anlamli; ayni boyut sinyali iki slot yiyor."}, {"tag": "Hoop Earrings", "reason": "Tek-basina jenerik; uzun varyantlar (Gold/Heart/Large Hoop) zaten kapsiyor, slot israfi."}, {"tag": "Puffed Earrings", "reason": "Puffed Hoop Earrings ile tam urun ifadesine yukseltildi."}, {"tag": "Graduated Earrings", "reason": "Baslik/urun graduated tanimlamiyor; suphelli relevance, niyet slotuna cevrildi."}, {"tag": "Gold Graduated", "reason": "Kirik fragment, gercek arama ifadesi degil + relevance dusuk."}, {"tag": "Heart Earrings", "reason": "Heart Hoop Earrings icine absorbe edildi (urun gercegine daha yakin)."}, {"tag": "Gold Heart Earrings", "reason": "Heart Hoop + Gold Hoop ile cakisiyor; heart+gold sinyali zaten var."}, {"tag": "Twisted Earrings", "reason": "Tip-celiskisi: urun diamond-cut/puffed, twisted degil."}, {"tag": "Gold Twist Earrings", "reason": "Ayni twist celiskisi + redundant."}]'::jsonb,'[{"tag": "Heart Hoop Earrings", "reason": "Urunun tam kimligi (heart + hoop) tek long-tail''de; en yuksek relevance."}, {"tag": "Puffed Hoop Earrings", "reason": "Baslik ozelligini (puffed design) tam urun ifadesine tasir."}, {"tag": "10k Gold Earrings", "reason": "Alici-dili + baslik/malzeme (10k) ile birebir; eksik materyal niyeti."}, {"tag": "Real Gold Earrings", "reason": "''real/solid gold'' alici arama dili; som altin ayrimini vurgular."}, {"tag": "Gift for Her", "reason": "Eksik hediye slotu; kupe = kadin hediyesi ana niyet."}, {"tag": "Valentines Day Gift", "reason": "Kalp motifi = Valentine''s; guclu occasion/hediye trafigi."}, {"tag": "Womens Earrings", "reason": "Eksik kitle slotu; alici hedeflemesi genisletir."}, {"tag": "Everyday Earrings", "reason": "Eksik kullanim slotu; gunluk tasima niyeti."}, {"tag": "Yellow Gold Jewelry", "reason": "Malzeme niteliginden (Yellow Gold) kategori-genisletici."}]'::jsonb,'Asiri ''hoop'' redundansi (4-5 varyant + Huge/Large es anlamli) ve tip-celiskili twisted/graduated tagler slot israf ediyor; hediye/occasion/kitle/alici-dili slotlari tamamen eksik.','Set 13 dolu, tumu <=20 karakter, cogunluk cok-kelimeli long-tail, birebir tekrar yok. ''Hoop'' koku 5''ten 4''e (Gold/Heart/Puffed/Large) dusuruldu; kalanlar farkli niyet tasidigi icin israf degil. Tip-celiskili twisted/graduated tamamen ayiklandi, relevance korundu (heart hoop urun gercegi). Eksik dort niyet ekseni dolduruldu: hediye (Gift for Her), occasion (Valentines Day Gift), kitle (Womens Earrings), kullanim (Everyday Earrings) + alici-dili malzeme (10k/Real Gold). Baslik-baskini ''gold hoop'' tek slotta tutuldu, gerisi slot-genisletmeye ayrildi.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1743975353,'10K Solid Gold CZ Stone Men''s Ring | Statement Jewelry','ring','standart',ARRAY['Gold Statement Rings','10K Gold Rings','10K Solid Gold Ring','Solid Gold Ring','10K Ring','Gold Ring','White Gold Ring','Cz stone Ring','Large Men''s Ring','Solid Gold Mens Ring','Round Gold Ring','10K Yellow Gold Ring','10K men''s Ring']::text[],ARRAY['10K Solid Gold Ring','Mens Gold Ring','CZ Statement Ring','10K Yellow Gold Ring','Gold Ring for Him','Mens Statement Ring','Cubic Zirconia Ring','Hip Hop Jewelry','Iced Out Mens Ring','Fathers Day Gift','Large Mens Ring','Real Gold Jewelry','Everyday Gold Ring']::text[],'[{"tag": "White Gold Ring", "reason": "Tip/malzeme celiskisi: urun sari 10K altin (malzeme: Yellow Gold); beyaz altin alicyi yaniltir ve alakasiz trafik ceker."}, {"tag": "Gold Ring", "reason": "Tek/generik ve asiri genis; long-tail degil, rekabette gorunmez."}, {"tag": "10K Ring", "reason": "Cok kisa ve belirsiz; urun tipi/niyet tasimiyor."}, {"tag": "10K Gold Rings", "reason": "''10K Solid Gold Ring'' ve ''10K Yellow Gold Ring'' ile ayni koku tekrarliyor; slot israfi."}, {"tag": "Solid Gold Ring", "reason": "''10K Solid Gold Ring'' icinde zaten var; birebir yakin tekrar."}, {"tag": "Round Gold Ring", "reason": "Dusuk degerli sekil betimleyicisi, zayif arama niyeti; slotu hediye/stil icin actim."}, {"tag": "10K men''s Ring", "reason": "''Mens Gold Ring'' ve ''10K Yellow Gold Ring'' ile cakisan tekrar."}, {"tag": "Solid Gold Mens Ring", "reason": "''Mens Gold Ring'' + ''Solid Gold'' kokunu tekrar birlestiriyor; redundant."}, {"tag": "Cz stone Ring", "reason": "Daha iyi ifadelerle degistirildi (''CZ Statement Ring'' + ''Cubic Zirconia Ring''); ''stone'' zayif anahtar."}]'::jsonb,'[{"tag": "Mens Gold Ring", "reason": "Ana kitle + urun kokunu tek net long-tail''de toplar (baslikta ''Men''s'' baskin niyet)."}, {"tag": "Gold Ring for Him", "reason": "Hediye niyeti slotu (''for him'') — tamamen eksikti."}, {"tag": "Mens Statement Ring", "reason": "Stil + kitle; basliktaki ''Statement'' temasini erkek aramasina baglar."}, {"tag": "CZ Statement Ring", "reason": "Tas + stil kombinasyonu; ''Cz stone Ring''in guclu versiyonu."}, {"tag": "Cubic Zirconia Ring", "reason": "Alici dili varyanti; ''CZ'' kisaltmasini aramayan aliciyi yakalar (koku cesitlendirir)."}, {"tag": "Hip Hop Jewelry", "reason": "Stil slotu; ''gold ring'' kokundan cikip ''jewelry'' (baslik: Statement Jewelry) ile genisletir."}, {"tag": "Iced Out Mens Ring", "reason": "CZ tasli statement urunun yuksek hacimli stil terimi (iced out)."}, {"tag": "Fathers Day Gift", "reason": "Hediye/tarih slotu; erkek takisi icin guclu mevsimsel niyet."}, {"tag": "Real Gold Jewelry", "reason": "Alici dili (''real gold'') + koku cesitlendirir (jewelry); som altin degerini vurgular."}, {"tag": "Everyday Gold Ring", "reason": "Kullanim niyeti slotu; gunluk tasima aramalarini yakalar."}]'::jsonb,'13 slotun 8''i "gold ring" kokunun neredeyse ayni varyantlariyla dolu (birebir yakin tekrar = slot israfi) ve "White Gold Ring" tag''i sari 10K altin urunle celisiyor; hediye/stil/kullanim niyet slotlari tamamen bos.','Standart arketip: relevance korunarak slot israfi temizlendi. 8 adet birbirinin varyanti ''gold ring'' tag''i, farkli niyet tasiyan cekirdek varyantlara (10K Solid, 10K Yellow, Mens) indirildi; celisen ''White Gold Ring'' cikarildi. Bosalan slotlara hediye (Gold Ring for Him, Fathers Day Gift), stil (Hip Hop Jewelry, Iced Out Mens Ring, Mens/CZ Statement), kullanim (Everyday Gold Ring) ve alici dili (Real Gold Jewelry, Cubic Zirconia Ring) niyetleri eklendi. Urun bir yuzuk oldugu icin ''ring'' kokunu korumak mesru; ama ''jewelry'' varyantlari (baslik ''Statement Jewelry'' ile mesru) koku cesitlendirir. Tum 13 tag cok-kelimeli long-tail ve <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1652142260,'14K Gold Heart Bamboo Hoop Earrings | Diamond Cut Jewelry','earring','standart',ARRAY['Hoop Earrings','Gold Hoop Earrings','Diamond Cut Earrings','Graduated Hoop','Gold Graduated','Bamboo Hoop Earrings','Gold Bamboo Earrings','Large Hoop Earrings','Real Gold Earrings','10K Gold Hoop','Bamboo Earrings','Graduated Earrings','10K Gold Earrings']::text[],ARRAY['Gold Hoop Earrings','Bamboo Hoop Earrings','Diamond Cut Earrings','Heart Hoop Earrings','Graduated Hoops','Large Hoop Earrings','Real Gold Earrings','14K Gold Earrings','Womens Gold Earrings','Yellow Gold Hoops','Gift for Her','Statement Earrings','Everyday Earrings']::text[],'[{"tag": "10K Gold Hoop", "reason": "Metal celiskisi: bu listing 14K REAL GOLD; 10K tag urun gercegiyle ters ve aliciyi yaniltir, relevance dusurur."}, {"tag": "10K Gold Earrings", "reason": "Ayni 14K vs 10K celiskisi; 14K Gold Earrings ile dogru saflik degeriyle degistirildi."}, {"tag": "Bamboo Earrings", "reason": "''Bamboo'' koku 3 tag''de tekrar ediyordu; Bamboo Hoop Earrings zaten kapsiyor, bu slot israfi."}, {"tag": "Gold Bamboo Earrings", "reason": "3. bambu varyanti; Etsy kelimeleri kendisi kombinler, ayni koku tekrarlamak slot yakiyor."}, {"tag": "Graduated Earrings", "reason": "''Graduated'' koku 3 tag''deydi; tek Graduated Hoops varyantina konsolide edildi."}, {"tag": "Gold Graduated", "reason": "Urun nounu olmayan belirsiz fragment; graduated konsolidasyonuyla gereksizlesti."}, {"tag": "Hoop Earrings", "reason": "Cok genel; Gold/Bamboo/Large/Heart Hoop Earrings tarafindan zaten kapsaniyor, bagimsiz slota degmez."}]'::jsonb,'[{"tag": "Heart Hoop Earrings", "reason": "Baslikta ''Heart'' var ama hicbir tag''de yoktu; ayirt edici urun ozelligi, yuksek relevance."}, {"tag": "14K Gold Earrings", "reason": "Malzemenin dogru saflik degeri (14K); yanlis 10K tag''lerinin yerine gercek metal sinyali."}, {"tag": "Womens Gold Earrings", "reason": "Kitle slotu tamamen eksikti; hoop earrings aramalarinin buyuk kismi kadin niyetli."}, {"tag": "Yellow Gold Hoops", "reason": "Malzeme ''Yellow Gold''; renk+stil niyeti ekler, ''hoops'' varyantiyla noun cesitliligi."}, {"tag": "Gift for Her", "reason": "Hediye niyet slotu bostu; taki en yuksek hediye kategorilerinden, guclu alici sinyali."}, {"tag": "Statement Earrings", "reason": "Large/graduated bamboo hoop = statement parca; tarz/kullanim niyetini yakalar."}, {"tag": "Everyday Earrings", "reason": "Kullanim slotu; hoop''lar gunluk tasima aramalarinda guclu, statement ile birlikte iki uc niyeti kapsar."}]'::jsonb,'Metal celiskisi (14K listing''de iki adet 10K tag) + bambu/graduated kokunun 3''er kez tekrari slot israfi ederken basliktaki "heart" ve hediye/kitle/kullanim niyet slotlari tamamen bos.','Standart arketip dengesi: 6 guclu head korundu (Gold/Bamboo/Diamond Cut/Large Hoop + Real Gold + Graduated). Yediye kadar cikan bambu/graduated tekrari birer varyanta indirgenerek 5 slot serbest birakildi; bu slotlar basliktaki eksik ''heart'', dogru 14K metal, ve tamamen bos olan kitle (womens), hediye (gift for her), stil (yellow gold hoops), kullanim (statement/everyday) niyetleriyle dolduruldu. Iki 10K tag metal celiskisi oldugu icin cikarildi. Tum 13 tag <=20 karakter ve cok-kelimeli long-tail; birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1467444368,'10K Gold Graduated Hoop Earrings | Diamond Cut Jewelry','earring','standart',ARRAY['Heart Earrings','Gold Heart Earrings','Graduated Earrings','Hoop Earrings','Gold Hoop Earrings','Gold Graduate','Diamond Cut Earrings','Heart Hoop Earrings','Diamond Cut Hoop','10K Gold Earrings','Real Gold Earrings','10K Gold Hoop','Satin Earrings']::text[],ARRAY['Gold Hoop Earrings','Graduated Earrings','Diamond Cut Hoops','10K Gold Earrings','Real Gold Earrings','Solid Gold Hoops','Womens Hoop Earrings','Gift For Her','Mothers Day Gift','Everyday Earrings','Statement Earrings','Yellow Gold Hoops','Luxury Gold Hoops']::text[],'[{"tag": "Heart Earrings", "reason": "Tip celiskisi: urun hoop/graduated, kalp yok — yaniltici, alakasiz."}, {"tag": "Gold Heart Earrings", "reason": "Tip celiskisi: kalp niteligi urunde yok."}, {"tag": "Heart Hoop Earrings", "reason": "Tip celiskisi: kalp+hoop karma ama urun sade graduated hoop."}, {"tag": "Gold Graduate", "reason": "Anlamsiz/kirik ifade: ''graduate'' urun degil kisi cagristirir, arama niyeti yok."}, {"tag": "Hoop Earrings", "reason": "Tek-kelimemsi jenerik kok; modifikatorlu long-tail varyantlarla degistirildi."}, {"tag": "Diamond Cut Earrings", "reason": "Diamond Cut Hoops ile ayni kok tekrari; hoop varyanti korundu, digeri slot israfi."}, {"tag": "10K Gold Hoop", "reason": "10K Gold Earrings + Gold Hoop Earrings ile ayni koklerin ustuste binmesi; niyet slotuna cevrildi."}, {"tag": "Satin Earrings", "reason": "Zayif/muglak finis terimi, dusuk arama niyeti; baslikta ''diamond cut'' ile de tutarsiz."}]'::jsonb,'[{"tag": "Solid Gold Hoops", "reason": "Alici dili (''solid gold'') — som altin arayan yuksek-niyetli alici sinyali."}, {"tag": "Womens Hoop Earrings", "reason": "Eksik kitle slotu: kadin alici hedeflemesi."}, {"tag": "Gift For Her", "reason": "Eksik hediye niyeti: en yuksek hacimli takı hediye aramasi."}, {"tag": "Mothers Day Gift", "reason": "Eksik hediye/sezon slotu: mevsimsel yuksek donusum."}, {"tag": "Everyday Earrings", "reason": "Eksik kullanim slotu: gunluk tasima niyeti."}, {"tag": "Statement Earrings", "reason": "Eksik stil/kullanim slotu: graduated tasarimin gorsel iddiasini yakalar."}, {"tag": "Yellow Gold Hoops", "reason": "Malzeme rengi (Yellow Gold materyalinden) — renk-bazli arama."}, {"tag": "Luxury Gold Hoops", "reason": "Eksik tarz slotu: premium/lux konumlama, som 10K ile tutarli."}]'::jsonb,'Uc "Heart" tag''i (Heart Earrings, Gold Heart Earrings, Heart Hoop Earrings) urunle celisiyor — bu graduated diamond-cut hoop kupede kalp yok; uc slot yaniltici trafige ve israfa gidiyor.','Asil sorun tip-celiskisiydi: 3 ''Heart'' tag''i + anlamsiz ''Gold Graduate'' toplam 4 slotu bosa harciyordu, ayrica hoop/earrings/diamond-cut kokleri asiri tekrarliyordu. Alakali cekirdek tag''leri korudum (Gold Hoop Earrings, Graduated Earrings, Diamond Cut Hoops, 10K Gold Earrings, Real Gold Earrings), som/gercek altin alici dilini guclendirdim (Solid Gold, Yellow Gold), ve eksik niyet slotlarini actim: kitle (Womens), hediye (Gift For Her, Mothers Day), kullanim (Everyday), stil (Statement, Luxury). Tum 13 tag <=20 karakter, hepsi cok-kelimeli long-tail, birebir tekrar yok, relevance korundu.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1863553142,'14K White Gold Box Chain Bracelet | Real Gold, Unisex','bracelet','standart',ARRAY['Box Chain Bracelet','14K Gold Bracelet','14K Bracelet','Round Bracelet','Box Chain Gold','Gold Round Bracelet','Gold Bracelet','14K Link Bracelet','white gold jewelry','solid gold bracelet','14k box bracelet','women gold bracelet']::text[],ARRAY['box chain bracelet','white gold bracelet','14k gold bracelet','mens gold bracelet','unisex bracelet','real gold bracelet','solid gold bracelet','gift for him','gift for her','everyday bracelet','layering bracelet','minimalist jewelry','square link chain']::text[],'[{"tag": "Round Bracelet", "reason": "TIP CELISKISI: box/kare zincir ''round'' degil; alakasiz tag relevance dusurur"}, {"tag": "Gold Round Bracelet", "reason": "Ayni tip celiskisi + ''gold bracelet'' redundansi"}, {"tag": "14K Bracelet", "reason": "Tek-kelimeye yakin + ''14k gold bracelet'' ile kok tekrari, slot israfi"}, {"tag": "14K Link Bracelet", "reason": "14K kok tekrari; ''square link chain'' bunu long-tail olarak karsiliyor"}, {"tag": "Box Chain Gold", "reason": "''box chain bracelet'' ile kok tekrari, ayni aramayi ikilemek slot israfi"}, {"tag": "Gold Bracelet", "reason": "Cok jenerik/tek-kelimeye yakin; nitelikli varyantlar (real/solid/14k/white) kapsiyor"}, {"tag": "14k box bracelet", "reason": "Hem 14k hem box kok cift tekrari; ''box chain bracelet'' + ''14k gold bracelet'' yeterli"}, {"tag": "women gold bracelet", "reason": "''gold'' redundansi; kitle kapsamasi ''gift for her'' + ''unisex bracelet'' ile korunuyor"}, {"tag": "white gold jewelry", "reason": "''white gold bracelet'' daha spesifik ve urun tipiyle uyumlu; ''minimalist jewelry'' ayri niyet olarak yerini aliyor"}]'::jsonb,'[{"tag": "white gold bracelet", "reason": "Basliktaki baskin nitelik (WHITE gold) tag setinde hic yoktu; tip-spesifik alici dili"}, {"tag": "mens gold bracelet", "reason": "Kitle slotu: unisex/erkek yuksek talepli ''gold chain for men'' niyeti eksikti"}, {"tag": "unisex bracelet", "reason": "Basliktaki unisex konumlandirmasi tag olarak yoktu; kitle genisletir"}, {"tag": "real gold bracelet", "reason": "Alici dili (''real gold'') aramasi; donusum sinyali guclu"}, {"tag": "gift for him", "reason": "Hediye niyet slotu tamamen bostu; erkek hediyesi yuksek hacim"}, {"tag": "gift for her", "reason": "Hediye slotu + kadin kitle kapsamasini korur (women tag''i yerine niyet-bazli)"}, {"tag": "everyday bracelet", "reason": "Kullanim slotu: gunluk giyim niyeti eksikti"}, {"tag": "layering bracelet", "reason": "Kullanim/stil slotu: stacking/layering trendi eksikti"}, {"tag": "minimalist jewelry", "reason": "Stil slotu: ince box chain estetigiyle uyumlu, yeni kitle acar"}, {"tag": "square link chain", "reason": "Box chain''in gorsel/tarz aciklamasi (kare halka) long-tail varyanti; kok tekrari degil betimleme"}]'::jsonb,'Box/kare zincir urunune "Round Bracelet" tip-celiskisi + agir 14k/box redundansi var; hediye/stil/kullanim/kitle niyet slotlari tamamen bos.','13 tag tam dolu, hepsi <=20 karakter ve coklu-kelime long-tail. Uc gercek sorun temizlendi: (1) tip celiskisi — box/kare zincire konmus ''Round Bracelet''/''Gold Round Bracelet'' relevance''i bozuyordu, cikarildi; (2) asiri redundansi — ''14K'' 5 tag''de, ''box chain'' 3 tag''de kok tekrariydi, Etsy zaten kombinliyor, tek guclu varyanta indirildi; (3) dar niyet — hediye/stil/kullanim/kitle slotlari sifirdi. Baslikatki WHITE gold niteligi tag setinde hic yoktu (kritik bosluk), eklendi. ''gold bracelet'' cekirdegi silinmedi ama nitelikli buyer-language varyantlarina (real/solid/14k/white/mens) dagitildi — hepsi mesru arama, birebir tekrar yok. ''necklace/round'' gibi celiskili terim eklenmedi; ''square link chain'' box chain''in tarz betimlemesi olarak mesru.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1862671943,'14K White Gold Round Box Chain Necklace - Women and Men','necklace','standart',ARRAY['14K Gold Chain','14K Chain','Box Chain','14K Box Chain','Gold Chain','Box Chain Necklace','Gold Box Chain','Round Box Chain','Gold Necklace','14K Link Chain','Gold Link Chain','14K WHITE GOLD','WHITE GOLD CHAIN']::text[],ARRAY['14K White Gold Chain','Round Box Chain','Box Chain Necklace','White Gold Necklace','Mens Gold Chain','Womens Gold Chain','Solid Gold Chain','Layering Necklace','Everyday Necklace','Gift for Him','Gift for Her','Unisex Necklace','Italian Box Chain']::text[],'[{"tag": "14K Gold Chain", "reason": "14K+white+chain tek guclu long-tail''de birlestirildi (14K White Gold Chain); sari-altin ima urunle celisiyor"}, {"tag": "14K Chain", "reason": "generik + 14K koku asiri tekrar"}, {"tag": "Box Chain", "reason": "tek-ifade generik; box chain koku 6 kez doygun, daha spesifik varyantlar kapsiyor"}, {"tag": "14K Box Chain", "reason": "box chain + 14K redundans"}, {"tag": "Gold Chain", "reason": "cok generik; beyaz altin urunle sari-altin ima celisiyor; kok doygun"}, {"tag": "Gold Box Chain", "reason": "box chain koku redundans"}, {"tag": "Gold Necklace", "reason": "generik; urun gercegine uyan White Gold Necklace ile degistirildi"}, {"tag": "14K Link Chain", "reason": "RELEVANCE: urun box chain; ''link chain'' farkli zincir-tipi arama terimi, celiski"}, {"tag": "Gold Link Chain", "reason": "ayni relevance celiskisi (link chain vs box chain)"}, {"tag": "14K WHITE GOLD", "reason": "14K White Gold Chain icine katlandi; tek basina zayif ifade"}, {"tag": "WHITE GOLD CHAIN", "reason": "14K White Gold Chain ile neredeyse birebir tekrar"}]'::jsonb,'[{"tag": "14K White Gold Chain", "reason": "4 redundant tag''i (14K/white/chain) tek guclu long-tail''e konsolide; dominant nitelik tek slotta"}, {"tag": "White Gold Necklace", "reason": "urun gercegi (beyaz altin) + tip; generik Gold Necklace yerine dogru materyal"}, {"tag": "Mens Gold Chain", "reason": "kitle slotu (erkek); baslikta ''Men'', alici dili ''gold chain for men''"}, {"tag": "Womens Gold Chain", "reason": "kitle slotu (kadin); baslikta ''Women''"}, {"tag": "Solid Gold Chain", "reason": "materyaldeki SOLID GOLD''dan alici dili; guven sinyali"}, {"tag": "Layering Necklace", "reason": "kullanim slotu (katmanlama)"}, {"tag": "Everyday Necklace", "reason": "kullanim slotu (gunluk)"}, {"tag": "Gift for Him", "reason": "hediye slotu (erkek); baslikla uyumlu"}, {"tag": "Gift for Her", "reason": "hediye slotu (kadin)"}, {"tag": "Unisex Necklace", "reason": "kitle/tarz; baslik ''Women and Men'' unisex konumu"}, {"tag": "Italian Box Chain", "reason": "stil slotu; box chain''ler icin yaygin Italyan-altin kalite deskriptoru, box chain koku korunur"}]'::jsonb,'Asiri kok-tekrari: "box chain" 6, "14K" 6, "gold chain" ~5 tag''e yayilmis; slotlar israf, hediye/stil/kullanim/kitle niyeti sifir ve iki tag (link chain) box chain urunuyle celisiyor.','Standart arketip: dengeli temizlik. Toplam slotlarin ~%85''i tek zincir tipini tekrar ediyordu (box chain x6, 14K x6). Redundansi tek konsolide tag''e indirdim, iki gercek relevance hatasini (link chain, urun box chain) cikardim, materyal-gercegi olan beyaz altini one aldim. Bosalan slotlari niyet ekseninde doldurdum: kitle (mens/womens/unisex), hediye (him/her), kullanim (layering/everyday), materyal-guven (solid gold), stil (italian). Necklace tag''leri urun zincir-necklace olarak satildigi icin mesru tutuldu; her biri farkli nitelikci tasiyor. Hepsi cok-kelimeli long-tail, birebir tekrar yok, 13 dolu, hepsi <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1228150776,'14K Gold Puffed Evil Eye Pendant | Ocean Blue Good Luck Charm','pendant','standart',ARRAY['Gold Evil Eye','Good Luck Charm','Blue Evil Eye','Evil Eye Pendant','Evil Eye Charm','Protection Pendant','14K Gold Evil Eye','Good Luck Pendant','Evil Eye Jewelry','14K Gold Charm','Real Gold Evil Eye','Gold Blue Evil Eye','14K Gold Pendant']::text[],ARRAY['Evil Eye Pendant','Blue Evil Eye','Protection Pendant','14K Gold Pendant','Real Gold Evil Eye','Good Luck Charm','Evil Eye Necklace','Evil Eye Gift','Gift for Her','Layering Necklace','Nazar Amulet','Ocean Blue Pendant','Womens Gold Jewelry']::text[],'[{"tag": "Gold Evil Eye", "reason": "Real Gold Evil Eye ve 14K Gold Pendant ile ayni kok+malzeme; en zayif varyant."}, {"tag": "Evil Eye Charm", "reason": "Evil Eye Pendant/Nazar Amulet ile ayni tip anlami; redundant."}, {"tag": "14K Gold Evil Eye", "reason": "14K baslikta baskin; evil eye kokunun bir baska tekrari, slot israfi."}, {"tag": "Good Luck Pendant", "reason": "Good Luck Charm ile ayni niyet; ikisi birden gerekmiyor."}, {"tag": "Evil Eye Jewelry", "reason": "Cok genis, dusuk-donusum terim; hedefli long-tail''lerle degistirildi."}, {"tag": "14K Gold Charm", "reason": "14K Gold Pendant ile ortusuyor, charm zaten Good Luck Charm''da var."}, {"tag": "Gold Blue Evil Eye", "reason": "Blue Evil Eye + Ocean Blue Pendant ile birebir ortusen renk tekrari."}]'::jsonb,'[{"tag": "Evil Eye Necklace", "reason": "Pendant kolye olarak takilir; alicilar ''necklace'' arar (mesru cross-tip)."}, {"tag": "Evil Eye Gift", "reason": "Hediye niyet slotu tamamen eksikti; yuksek arama hacmi."}, {"tag": "Gift for Her", "reason": "Hediye+kitle slotu; ocean blue kadin egilimli alici sinyali."}, {"tag": "Layering Necklace", "reason": "Kullanim slotu; katmanlama trendi kucuk pendant''lar icin guclu."}, {"tag": "Nazar Amulet", "reason": "Kulturel es-anlam terimi; evil eye tekrari olmadan yeni kitle yakalar."}, {"tag": "Ocean Blue Pendant", "reason": "Baslikta ''Ocean Blue'' var; renk+stil odakli long-tail."}, {"tag": "Womens Gold Jewelry", "reason": "Kitle+malzeme slotu; genis ust-huni kesif aramasi."}]'::jsonb,'13 tag''in 8''i "evil eye" kokunu tekrarliyor (slot israfi) ve hediye/kitle/kullanim niyet slotlari tamamen eksik.','Ana sorun asiri redundancy: 8 tag evil-eye kokunu (Gold/Blue/Charm/Pendant/14K/Jewelry/Real/Gold-Blue varyantlari) tekrarliyordu; Etsy zaten kombinledigi icin bu net slot israfi. 7 gereksiz varyati birbirinden ayirt edilebilir tek versiyona indirdim (Evil Eye Pendant tip, Blue Evil Eye renk, Real Gold Evil Eye alici-dili). Bosalan 7 sloti eksik niyet katmanlariyla doldurdum: hediye (Evil Eye Gift, Gift for Her), kullanim (Layering Necklace), kitle (Womens Gold Jewelry), kulturel es-anlam (Nazar Amulet), renk/stil (Ocean Blue Pendant) ve mesru cross-tip (Evil Eye Necklace — pendant kolye olarak takilir). Tip-celiskisi yok; tum tag''ler pendant gerçegiyle uyumlu. Hepsi cok-kelimeli long-tail, birebir tekrar yok, her tag <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1724930320,'10K Solid Gold Jesus Head Ring | CZ Religious Nugget Ring','ring','standart',ARRAY['Nugget Ring','Nugget mens','Gold Nugget Ring','Nugget Rings','Gold Statement Rings','10K Gold Rings','10K Solid Gold Ring','Solid Gold Ring','10K Ring','Gold Ring','Jesus Head Ring','Jesus Nugget Ring','White Gold Ring']::text[],ARRAY['Gold Nugget Ring','Mens Nugget Ring','Jesus Head Ring','10K Solid Gold Ring','Real Gold Mens Ring','Gold Statement Ring','CZ Nugget Ring','Mens Religious Ring','Christian Jewelry','Gift for Him','Iced Out Ring','Hip Hop Ring','Chunky Gold Ring']::text[],'[{"tag": "Nugget Ring", "reason": "Tek-kokli genel tekrar; cok-kelimeli varyantlar (Gold/Mens/CZ Nugget Ring) icinde zaten kapsaniyor, slot israfi."}, {"tag": "Nugget Rings", "reason": "''Nugget Ring''in tekil/cogul birebir kopyasi; Etsy tekil-cogulu ayirmaz, olu slot."}, {"tag": "Nugget mens", "reason": "Bozuk kelime sirasi; duzgun long-tail ''Mens Nugget Ring'' olarak yeniden yazildi."}, {"tag": "Gold Statement Rings", "reason": "Cogul kopya; tekil ''Gold Statement Ring'' korundu."}, {"tag": "10K Gold Rings", "reason": "Ucuncu ''10K ... Ring'' varyanti; ''10K Solid Gold Ring'' ile konsolide edildi."}, {"tag": "10K Ring", "reason": "Cok kisa/genel 10K tekrari; baslikta zaten baskin, slot genisletmiyor."}, {"tag": "Solid Gold Ring", "reason": "''10K Solid Gold Ring'' icinde tamamen kapsaniyor, redundant."}, {"tag": "Gold Ring", "reason": "En genel tek-kok; rekabeti yuksek, niyet tasimayan slot israfi."}, {"tag": "Jesus Nugget Ring", "reason": "Jesus+Nugget kombosu ''Jesus Head Ring'' + nugget varyantlariyla cakisiyor, redundant."}, {"tag": "White Gold Ring", "reason": "TIP CELISKISI: malzeme sari 10k altin (Yellow Gold); beyaz altin iddiasi yaniltici, yanlis trafik/iade riski."}]'::jsonb,'[{"tag": "Mens Nugget Ring", "reason": "Kitle slotu (erkek) + urun cekirdegi; bozuk ''Nugget mens'' yerine duzgun long-tail."}, {"tag": "Real Gold Mens Ring", "reason": "Alici dili (''real gold'') + kitle; som altin arayan erkek alicilari yakalar."}, {"tag": "CZ Nugget Ring", "reason": "Baslikta gecen CZ tasi detayini yakalar, spesifik long-tail."}, {"tag": "Mens Religious Ring", "reason": "Dini niyet slotu + kitle; baslikta ''Religious'' var ama tag''de yoktu."}, {"tag": "Christian Jewelry", "reason": "Dini kategoriyi genisletir (Jesus temasinin ust-arama terimi)."}, {"tag": "Gift for Him", "reason": "Hediye niyeti slotu; erkek hediyesi aramalarina girer."}, {"tag": "Iced Out Ring", "reason": "Stil slotu; CZ-tasli nugget/hip-hop estetigi arayanlar."}, {"tag": "Hip Hop Ring", "reason": "Stil/tarz slotu; kalin altin nugget urunlerin ana pazari."}, {"tag": "Chunky Gold Ring", "reason": "Stil/form slotu; nugget yuzuklerin kalin gorunumunu tanimlar, farkli kok."}]'::jsonb,'Slotlarin cogu ayni koke ("nugget" x5, "10K/solid gold" x4) ve genel tek-kokli tekrarlara harcanmis, bir tag ("White Gold Ring") sari 10k altin malzemesiyle celisiyor; hediye/stil/kitle/dini niyet slotlari tamamen bos.','Orijinal set 13 slotun ~9''unu iki koke (''nugget'' 5, ''10K/solid gold'' 4) ve genel tekrarlara (''Gold Ring'',''10K Ring'') harciyordu; ''White Gold Ring'' ise sari 10k malzemeyle celisip yanlis trafik cekiyordu. Yeni sette 3 guclu tag korundu (Gold Nugget Ring, 10K Solid Gold Ring, Jesus Head Ring), tekrarlar tekil/temsili birer varyanta indirildi ve acilan slotlar niyet ekseninde dolduruldu: kitle (mens), alici dili (real gold), hediye (gift for him), stil (iced out, hip hop, chunky), tas (CZ) ve dini (religious, christian jewelry). Nugget koku 5''ten 3''e, gold-ring genel tekrari azaltildi; tum tag''ler cok-kelimeli ve <=20 karakter, relevance korundu (yuzuk tipiyle celisen tag yok).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1230866961,'10K Yellow Gold Graduated Heart Hoop Earrings | Diamond Cut','earring','standart',ARRAY['Heart Earrings','Gold Heart Earrings','Graduated Earrings','Hoop Earrings','Gold Hoop Earrings','Gold Graduate','Diamond Cut Earrings','Heart Hoop Earrings','Diamond Cut Hoop','10K Gold Earrings','10K Gold Hoop','Satin Earrings','10K Bamboo Earrings']::text[],ARRAY['Heart Hoop Earrings','Gold Hoop Earrings','Graduated Earrings','Diamond Cut Hoop','10K Gold Earrings','Yellow Gold Hoops','Real Gold Earrings','Gift for Her','Mothers Day Gift','Womens Gold Hoops','Everyday Earrings','Statement Earrings','Heart Jewelry Gift']::text[],'[{"tag": "10K Bamboo Earrings", "reason": "Tip celiskisi: urun kalp hoop; bamboo tamamen farkli bir stil — yanlis trafik, relevance kaybi."}, {"tag": "Satin Earrings", "reason": "Finish celiskisi: baslik ''Diamond Cut'' (parlak/fasetli), satin mat finiş — urunle uyusmaz."}, {"tag": "Gold Graduate", "reason": "Bozuk/yaniltici: ''graduate'' != graduated; mezuniyet-hediyesi karisikligi yaratir, zayif tag."}, {"tag": "Gold Heart Earrings", "reason": "Redundant: heart+gold+earrings zaten Heart Hoop Earrings + 10K Gold Earrings ile kapsandi."}, {"tag": "Diamond Cut Earrings", "reason": "Redundant: Diamond Cut Hoop daha spesifik varyantla ayni koku tekrarliyor."}, {"tag": "10K Gold Hoop", "reason": "Slot israfi: 10K Gold Earrings + Gold Hoop Earrings ile ust uste biniyor."}, {"tag": "Hoop Earrings", "reason": "Tek-kelime generik: daha spesifik hoop long-tail''ler icinde eriyor."}, {"tag": "Heart Earrings", "reason": "Duz/generik: Heart Hoop Earrings + Heart Jewelry Gift zaten kalp niyetini tasiyor."}]'::jsonb,'[{"tag": "Yellow Gold Hoops", "reason": "Baslik rengini (yellow gold) yakalar; renk niyetli aramayi acar."}, {"tag": "Real Gold Earrings", "reason": "Alici dili ''real gold'' — som altin arayan yuksek-niyetli aliciyi hedefler."}, {"tag": "Gift for Her", "reason": "Eksik hediye/alici slotu; kalp takisi guclu hediye adayi."}, {"tag": "Mothers Day Gift", "reason": "Sezonluk hediye occasion slotu — yuksek hacimli arama."}, {"tag": "Womens Gold Hoops", "reason": "Kitle+urun kombinasyonu; kadin alici niyetini acikca hedefler."}, {"tag": "Everyday Earrings", "reason": "Kullanim slotu — gunluk takilabilirlik konumlandirmasi."}, {"tag": "Statement Earrings", "reason": "Stil slotu; graduated kalp hoop dikkat cekici tasarim olarak konumlanir."}, {"tag": "Heart Jewelry Gift", "reason": "Kalp+hediye acisini earrings kokunden bagimsiz bir long-tail ile genisletir."}]'::jsonb,'Iki tag urun tipiyle celisiyor (bamboo/satin) ve 13 slotun tamami "earrings/hoop" kok varyantlariyla dolu — hediye, kitle, stil ve kullanim niyet slotlari tamamen eksik.','Iki gercek relevance sorunu vardi: 10K Bamboo Earrings (kalp hoop urunle tip celiskisi) ve Satin Earrings (diamond-cut parlak finish ile celisen mat finish) — ikisi de yanlis trafik cekip slot israf ediyordu. Ustelik 13 slotun tamami earrings/hoop kok varyantlariydi; hicbir hediye, kitle, stil veya kullanim niyeti yoktu. Cozum: cekirdek relevance''i koruyan 5 tag''i tuttum (Heart Hoop, Gold Hoop, Graduated, Diamond Cut Hoop, 10K Gold), renk (Yellow Gold Hoops) + alici dili (Real Gold) ekledim, sonra 3 hediye (Gift for Her, Mothers Day, Heart Jewelry Gift), kitle (Womens Gold Hoops), kullanim (Everyday) ve stil (Statement) slotlarini actim. Tum tag''ler cok-kelimeli, <=20 karakter, birebir tekrar yok; kok tekrari kabul edilebilir seviyede (her hoop/earrings varyanti ayri niteleyici tasiyor).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1363498864,'10K Real Gold Ice Out Bracelet | Two Tone Diamond Cut Link','bracelet','standart',ARRAY['Gold Chain Bracelet','10K Bracelet','Chain link bracelet','Minimalist Bracelet','10K Solid Bracelet','Two Tone Bracelet','ice out bracelet','Diamond Cut Bracelet','10K Gold Bracelet','ice out chain','Gold Bracelet','Real Gold Bracelet','Solid Gold Bracelet']::text[],ARRAY['Gold Chain Bracelet','10K Gold Bracelet','Iced Out Bracelet','Two Tone Bracelet','Diamond Cut Bracelet','Real Gold Bracelet','Solid Gold Bracelet','Mens Gold Bracelet','Gift for Him','Hip Hop Jewelry','Statement Bracelet','10K Real Gold','Iced Out Jewelry']::text[],'[{"tag": "Minimalist Bracelet", "reason": "Tip-celiskisi: ice out/two tone/diamond cut statement parca, minimalist DEGIL — yanlis alici cekiyor."}, {"tag": "10K Bracelet", "reason": "''10K Gold Bracelet'' ile ayni koku tekrarliyor, zayif tek-nitelik varyant."}, {"tag": "10K Solid Bracelet", "reason": "''10K Gold Bracelet'' + ''Solid Gold Bracelet'' ikilisinde eriyor; ucuncu 10K slot israfi."}, {"tag": "Chain link bracelet", "reason": "''Gold Chain Bracelet'' ile chain/link koku cakisiyor, ek deger yok."}, {"tag": "ice out chain", "reason": "Urun bilezik, zincir degil — yaniltici; iced out temasi bracelet/jewelry varyantlarina tasindi."}, {"tag": "Gold Bracelet", "reason": "Cok genis tek-nitelik; daha uzun long-tail''ler (gold chain/real gold/mens) bu aramayi zaten kapsiyor."}]'::jsonb,'[{"tag": "Mens Gold Bracelet", "reason": "Kitle slotu: iced out hip hop parca erkek-agirlikli; en guclu eksik niyet."}, {"tag": "Gift for Him", "reason": "Hediye slotu: erkege altin taki yuksek donusumlu hediye aramasi."}, {"tag": "Hip Hop Jewelry", "reason": "Stil slotu: ice out = hip hop; bracelet disinda jewelry kategori aramasini da yakalar."}, {"tag": "Statement Bracelet", "reason": "Kullanim/tarz slotu: parcanin gercek konumu (blingy statement), silinen ''minimalist''in dogru karsiligi."}, {"tag": "10K Real Gold", "reason": "Alici dili (real gold) + malzeme; ''Bracelet'' kokunu tekrarlamadan slot genisletir."}, {"tag": "Iced Out Jewelry", "reason": "Ice-out temasini jewelry seviyesine tasiyip bracelet-disi aramalari yakalar."}]'::jsonb,'Asiri redundancy — 13 tag''in 11''inde ''Bracelet'', uc adet 10K varyanti ayni koku tekrarliyor; ''Minimalist'' tip-celisiyor ve kitle/hediye/stil niyet slotlari tamamen bos.','Standart arketip icin dengeli temizlik: 7 gercek nitelik/alici-dili tag''i korundu (gold chain, 10K gold, iced out, two tone, diamond cut, real gold, solid gold), 6 redundant/celiskilı tag cikarildi. ''ice out bracelet'' alici yazimina uygun ''Iced Out Bracelet'' olarak duzeltildi. Bosalan 6 slot kitle (mens), hediye (gift for him), stil (hip hop), kullanim (statement) ve malzeme (10K real gold) niyetlerine dagitildi. Tum tag''ler cok-kelimeli long-tail, birebir tekrar yok, hepsi <=20 karakter (Diamond Cut Bracelet=20 sinir). Relevance korundu: pendant/necklace tipi genisletme yapilmadi cunku urun net bir bilezik.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1770702803,'10K Gold Last Supper Medallion Pendant, Miami Curb Border','pendant','standart',ARRAY['solid gold pendant','white gold pendant','Large mens pendant','Jesus head necklace','10K gold necklace','Miami Cuban Chain','Solid Gold Necklace','10k Gold chain','Gold Necklace','Gold Pendant','last supper pendant','10k gold pendant','last supper charm']::text[],ARRAY['last supper pendant','10k gold pendant','solid gold pendant','religious jewelry','last supper charm','gold medallion','real gold pendant','gift for him','mens gold necklace','jesus pendant','yellow gold jewelry','cuban link pendant','catholic gift']::text[],'[{"tag": "white gold pendant", "reason": "Tip-celiskisi: malzeme sari 10k altin (Yellow Gold), beyaz altin yok — yanlis alici cekiyor."}, {"tag": "Jesus head necklace", "reason": "''Jesus head'' ayri bir tasarim (Isa yuz portresi); urun Last Supper madalyonu — hem yaniltici hem necklace fazlaligi."}, {"tag": "10K gold necklace", "reason": "Necklace fazlaligi (4 necklace slotu); pendant urunde tek necklace yeter."}, {"tag": "Miami Cuban Chain", "reason": "''Chain'' tip-celiskisi (urun pendant); baslik ''Miami Curb Border'' — cuban chain degil."}, {"tag": "Solid Gold Necklace", "reason": "Necklace redundansi; ''solid gold'' fikri pendant varyantinda korundu."}, {"tag": "10k Gold chain", "reason": "''Chain'' tip-celiskisi — urun zincir degil pendant."}, {"tag": "Gold Necklace", "reason": "Jenerik + necklace redundansi; slot israfi."}, {"tag": "Gold Pendant", "reason": "Baskin kelimenin ciplak tekrari; 10k/solid/real varyantlari zaten kapsiyor."}, {"tag": "Large mens pendant", "reason": "''mens'' niyeti ''mens gold necklace'' ile korundu; slot hediye/dini icin acildi."}]'::jsonb,'[{"tag": "religious jewelry", "reason": "Eksik kategori/stil slotu — Last Supper dini takidir, buyuk arama hacmi."}, {"tag": "gold medallion", "reason": "Basliktaki ''Medallion'' urun tipini yakalar; charm/pendant disinda varyant."}, {"tag": "real gold pendant", "reason": "Alici dili (''real gold'') — malzeme 10k real gold ile birebir uyumlu."}, {"tag": "gift for him", "reason": "Eksik hediye slotu; mens dini madalyon icin dogal hediye niyeti."}, {"tag": "mens gold necklace", "reason": "Kitle (mens) + mesru tek necklace slotu (pendant zincirle takilir)."}, {"tag": "jesus pendant", "reason": "Dini alaka — Last Supper Isa''yi resmeder; ''jesus head''e gore dogru terim."}, {"tag": "yellow gold jewelry", "reason": "Malzeme dogrulugu (Yellow Gold) + pendant tekrarini kirar."}, {"tag": "cuban link pendant", "reason": "Stil slotu — curb/cuban kenar suslemesi; yuksek trafikli stil terimi, pendant olarak mesru."}, {"tag": "catholic gift", "reason": "Dini + hediye niyeti; hedef kitleye ozel ikinci hediye slotu."}]'::jsonb,'Set 4x ''necklace'' + 2x ''chain'' tip-celiskisi ve asiri gold/pendant redundansiyla dolmus; hediye/dini/stil niyet slotlari tamamen eksik.','Standart arketip icin dengeli temizlik: tip-celiskili 2 ''chain'' ve 1 beyaz-altin tag''i ile 3 fazlalik ''necklace'' tag''i cikarildi; 4 guclu core tag (last supper pendant/charm, 10k+solid gold pendant) korundu. Acilan 9 slot hediye (gift for him, catholic gift), dini kategori (religious jewelry, jesus pendant), stil (cuban link, medallion), malzeme dogrulugu (yellow gold, real gold) ve kitle+mesru necklace (mens gold necklace) niyetleriyle dolduruldu. Hepsi cok-kelimeli long-tail, birebir tekrar yok, her biri <=20 karakter (en uzun ''last supper pendant''/''real gold pendant'' turleri 17-19).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1225508465,'10K Yellow Gold Hoop Earrings, Diamond Cut, All Sizes','earring','standart',ARRAY['Hoop Earrings','Gold Hoop Earrings','Diamond Cut Earrings','Large Hoop Earrings','Real Gold Earrings','Gold Earrings','Diamond Cut Hoop','Round Earrings','10K Gold Hoop','Gold Circle Earrings','10K Gold Earrings','Gold Round Earrings','Gold Shiny Earrings']::text[],ARRAY['Gold Hoop Earrings','Diamond Cut Hoop','10K Gold Earrings','Real Gold Earrings','Solid Gold Hoops','Womens Gold Hoops','Gift for Her','Mothers Day Gift','Everyday Earrings','Large Hoop Earrings','Small Gold Hoops','Yellow Gold Hoops','Statement Earrings']::text[],'[{"tag": "Hoop Earrings", "reason": "Jenerik tek-kavram; baslik ve ''Gold Hoop Earrings'' zaten kapsiyor, slot israfi."}, {"tag": "Diamond Cut Earrings", "reason": "''Diamond Cut Hoop'' ile dublikat; 20 karakterlik hoop varyanti daha spesifik."}, {"tag": "Gold Earrings", "reason": "Cok jenerik tek-kavram; tum kombinasyonlarda zaten mevcut."}, {"tag": "Round Earrings", "reason": "round/circle uclusunun bir bacagi; redundant."}, {"tag": "10K Gold Hoop", "reason": "''10K Gold Earrings'' ile karat dublikati."}, {"tag": "Gold Circle Earrings", "reason": "round/circle redundansi; ayni kavram uc slotta."}, {"tag": "Gold Round Earrings", "reason": "round/circle redundansi; ucuncu kez ayni kavram."}, {"tag": "Gold Shiny Earrings", "reason": "Belirsiz/zayif ifade; diamond-cut parlakligi zaten ''Diamond Cut Hoop'' ile karsilaniyor."}]'::jsonb,'[{"tag": "Solid Gold Hoops", "reason": "Alici dili ''solid gold'' — som altin niyeti, yuksek donusum sinyali."}, {"tag": "Womens Gold Hoops", "reason": "Eksik kitle slotu; hoop earring aramalarinda baskin kadin niyeti."}, {"tag": "Gift for Her", "reason": "Eksik hediye slotu; genis alici niyeti yakalar."}, {"tag": "Mothers Day Gift", "reason": "Eksik occasion/hediye slotu; mevsimsel yuksek hacim."}, {"tag": "Everyday Earrings", "reason": "Eksik kullanim slotu; kucuk/orta hoop gunluk kullanim niyeti."}, {"tag": "Small Gold Hoops", "reason": "Baslikta ''All Sizes'' var ama sadece ''Large'' islenmisti; kucuk beden niyetini de acar."}, {"tag": "Yellow Gold Hoops", "reason": "Baslikteki ''Yellow Gold'' rengi tag''de hic yoktu; renk niyetini yakalar."}, {"tag": "Statement Earrings", "reason": "Eksik stil slotu; buyuk diamond-cut hoop statement parca niyetiyle ortusur."}]'::jsonb,'Asiri redundancy: ~10 tag ayni ''gold+earrings'' kokunu, 3 tag round/circle kavramini tekrarlarken hediye/kitle/stil/beden/renk niyet slotlari tamamen bos.','Standart arketip icin dengeli temizlik: 8 redundant/jenerik tag (round-circle uclusu, diamond-cut/karat ikizleri, jenerik tekiller) cikarildi; yerine bos olan hediye (2), kitle (1), kullanim/stil (2), beden (1), renk (1) ve alici-dili (1) slotlari eklendi. 5 guclu tag korundu (Gold Hoop Earrings, Diamond Cut Hoop, 10K Gold Earrings, Real Gold Earrings, Large Hoop Earrings). Tum tag''ler cok-kelimeli long-tail, hepsi <=20 karakter, urun tipiyle (earring/hoop) tam relevance, hicbir tip-celiskisi yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1595078873,'14K Gold Teddy Bear CZ Pendant Necklace, Miami Cuban Chain','pendant','standart',ARRAY['Miami Cuban Chain','14K Gold Pendant','14K Gold Necklace','14K Gold Chain','Teddy Bear Necklace','Teddy Bear Pendant','Good Luck Pendant','Gold Cz Necklace','Gold Cz Pendant','14K Teddy Bear','Gold Pendant','Gold Necklace','Gold Chain']::text[],ARRAY['Teddy Bear Necklace','Teddy Bear Pendant','Miami Cuban Chain','Gold CZ Pendant','Good Luck Pendant','14K Gold Pendant','Real Gold Necklace','Solid Gold Chain','Gift For Her','Layering Necklace','Womens Gold Chain','Dainty Gold Necklace','Everyday Necklace']::text[],'[{"tag": "14K Gold Necklace", "reason": "Redundant ''gold necklace'' koku; ayni niyeti tasiyan Real Gold/Dainty/Layering necklace long-tail''leriyle daha genis kapsandi."}, {"tag": "14K Gold Chain", "reason": "Miami Cuban Chain + diger chain etiketleriyle zincir kokunu tekrarliyor; generik, ayirt edici degil."}, {"tag": "Gold Cz Necklace", "reason": "CZ koku ''Gold CZ Pendant'' ile cift; slot israfi, tek varyant yeterli."}, {"tag": "14K Teddy Bear", "reason": "Eksik/kesik ifade; ''teddy bear'' zaten necklace+pendant etiketlerinde tam long-tail olarak var."}, {"tag": "Gold Pendant", "reason": "Neredeyse tek-kelime, generik; ''14K Gold Pendant'' ile ayni kokun zayif kopyasi."}, {"tag": "Gold Necklace", "reason": "Ciplak generik kok tekrari; dusuk long-tail degeri."}, {"tag": "Gold Chain", "reason": "Ciplak generik kok tekrari; ''Womens/Solid Gold Chain'' ile niyet-hedefli varyantlara donusturuldu."}]'::jsonb,'[{"tag": "Real Gold Necklace", "reason": "Alici dili (''real gold'') — som/gercek altin arayan yuksek-niyetli aramayi yakalar."}, {"tag": "Solid Gold Chain", "reason": "Alici dili (''solid gold''); malzeme=som 10K/14K gercegiyle uyumlu, 14K kokunden farkli kok."}, {"tag": "Gift For Her", "reason": "Eksik hediye niyet slotu; teddy bear + CZ pendant guclu kadin hediyesi sinyali."}, {"tag": "Layering Necklace", "reason": "Eksik kullanim slotu; ince pendant kolyeler katmanlama aramasinda yer alir."}, {"tag": "Womens Gold Chain", "reason": "Eksik kitle slotu; dar hedef kitleyi acar, chain kokunu niyetle yeniden kullanir."}, {"tag": "Dainty Gold Necklace", "reason": "Stil/kitle slotu; teddy bear CZ pendant''in zarif/feminen karakterini hedefler."}, {"tag": "Everyday Necklace", "reason": "Eksik kullanim slotu; gunluk-tak kullanim niyetini yakalar, farkli long-tail."}]'::jsonb,'13 slottan 6''si ciplak/tekrar altin-kok etiketlerine (gold pendant/necklace/chain + cift CZ) ziyan edilmis, hediye/kitle/kullanim niyet slotlari ise tamamen bos.','6 kok-tekrari ve cift CZ slotu (ziyan) temizlendi; ceki''ye takilan generik ''gold X'' etiketleri niyet-hedefli varyantlara donusturuldu. Urun ''pendant necklace'' oldugu icin ''necklace'' relevance korundu ama tekil kok yerine 5 farkli long-tail''e (teddy bear/real gold/dainty/layering/everyday) dagitildi. Bos olan hediye (gift for her), kitle (womens, dainty), kullanim (layering, everyday) ve alici-dili (real/solid gold) slotlari dolduruldu. Cekirdek urun (teddy bear pendant/necklace), baskin stil (miami cuban chain), CZ ve good-luck anlam etiketleri korundu. Tum 13 etiket cok-kelimeli, <=20 karakter, birebir tekrarsiz.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1816649280,'14K Gold Ice Out Bracelet | Two Tone Diamond Cut Chain','bracelet','standart',ARRAY['Gold Chain Bracelet','Chain link bracelet','Minimalist Bracelet','Two Tone Bracelet','ice out bracelet','Diamond Cut Bracelet','ice out chain','Gold Bracelet','Real Gold Bracelet','Solid Gold Bracelet','14K Bracelet','14K solid bracelet','14K Gold Bracelet']::text[],ARRAY['ice out bracelet','Two Tone Bracelet','Diamond Cut Bracelet','Gold Chain Bracelet','Solid Gold Bracelet','Mens Gold Bracelet','Hip Hop Bracelet','Statement Bracelet','Luxury Bracelet','gift for him','14K Gold Jewelry','Real Gold Jewelry','Iced Out Jewelry']::text[],'[{"tag": "Chain link bracelet", "reason": "Gold Chain Bracelet ile ayni ''chain'' koku; redundant slot israfi."}, {"tag": "Minimalist Bracelet", "reason": "Tip-celiskisi: ice-out/diamond-cut bling/hip-hop tarzi ''minimalist'' ile celisir, yanlis trafik ceker."}, {"tag": "ice out chain", "reason": "ice out bracelet ile ayni kok; ustelik urun bilezik, kolye zinciri degil — dar/yaniltici."}, {"tag": "Gold Bracelet", "reason": "Cok generik, daha spesifik gold varyantlariyla zaten kapsaniyor; slot israfi."}, {"tag": "Real Gold Bracelet", "reason": "Bracelet koku doygun; ''Real Gold Jewelry'' formuna cevrilerek kok genisletildi, alici dili korundu."}, {"tag": "14K Bracelet", "reason": "Generik ve baslikta zaten 14K var; 14K Gold Jewelry ile daha degerli forma tasindi."}, {"tag": "14K solid bracelet", "reason": "Solid Gold + 14K varyantlariyla neredeyse birebir cakisma; redundant."}, {"tag": "14K Gold Bracelet", "reason": "Baslik zaten ''14K Gold ... Bracelet'' iceriyor; bosuna tekrar, 14K Gold Jewelry olarak kok genisletildi."}]'::jsonb,'[{"tag": "Mens Gold Bracelet", "reason": "Kitle slotu: iced-out bilezik erkek/hip-hop pazari agirlikli, hedef arama."}, {"tag": "Hip Hop Bracelet", "reason": "Stil slotu: ice-out''un dogal stil eslesmesi, yeni alici niyeti."}, {"tag": "Statement Bracelet", "reason": "Kullanim slotu: bling/statement takisi arayan alici sorgusu."}, {"tag": "Luxury Bracelet", "reason": "Tarz/ton slotu: som altin premium konumlandirma."}, {"tag": "gift for him", "reason": "Hediye slotu: erkek-agirlikli urun icin yuksek donusumlu hediye niyeti."}, {"tag": "14K Gold Jewelry", "reason": "Kok genisletme: ''bracelet'' disina cikip material + jewelry kategorisini yakalar."}, {"tag": "Real Gold Jewelry", "reason": "Alici dili (''real gold'') + bracelet disi kok; genis mucevher aramasi."}, {"tag": "Iced Out Jewelry", "reason": "Stil + jewelry koku: ice-out arayanlari bilezik disinda da yakalar."}]'::jsonb,'13 tag''in 10''u "gold/14K ... bracelet" varyanti (asiri kok tekrari, slot israfi); hediye/kitle/stil/kullanim niyet slotlari tamamen eksik ve "Minimalist" ice-out urunle celisiyor.','Ana sorun asiri redundancy: orijinalde 13 tag''in 10''u ''gold/14K ... bracelet'' varyanti ve baslik zaten ''14K Gold ... Bracelet'' iceriyordu — bu koku tekrarlamak slot israfiydi. 8 tag''i cikardim, 5 gercek-deger tasiyan tag''i (ice out, two tone, diamond cut, gold chain, solid gold bracelet) korudum. Kok tekrarini kirmak icin 3 tag''i ''Jewelry'' formuna tasidim (bracelet-ending 10''dan 9''a, non-bracelet 4). Eksik niyet slotlarini doldurdum: kitle (mens), stil (hip hop, luxury), kullanim (statement), hediye (gift for him). ''Minimalist'' relevance-celiskisi oldugu icin dusuruldu. Hepsi cok-kelimeli, birebir tekrar yok, tumu <=20 karakter (en uzun ''Diamond Cut Bracelet'' = 20).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1821803697,'10K Gold Heart Nugget Earrings | Solid Yellow Gold','earring','standart',ARRAY['Solid Gold Nugget','nugget earrings','nugget women','gold nugget earrings','heart earrings','nugget','heart shape earrings','heart nugget earring','solid gold earrings','10k gold earrings','10k solid earrings','gold earrings','10k earrings']::text[],ARRAY['gold nugget earrings','heart nugget earring','heart shape earrings','10k gold earrings','solid gold earrings','real gold earrings','womens gold earrings','yellow gold earrings','gift for her','mothers day gift','everyday earrings','dainty gold earrings','gold heart jewelry']::text[],'[{"tag": "Solid Gold Nugget", "reason": "Eksik/urun-tipsiz ifade; ''gold nugget earrings'' ve ''solid gold earrings'' ile ortu, slot israfi."}, {"tag": "nugget earrings", "reason": "''gold nugget earrings'' zaten kapsiyor; ayni kok tekrari, Etsy kelimeleri kombinler."}, {"tag": "nugget women", "reason": "Bozuk dilbilgisi; yerine dogru long-tail ''womens gold earrings'' kondu."}, {"tag": "nugget", "reason": "Tek kelime = slot israfi; tek basina rekabet edemez, long-tail icinde zaten geciyor."}, {"tag": "heart earrings", "reason": "''heart shape earrings'' ve ''heart nugget earring'' ile fazlaliga dusen dar tekrar."}, {"tag": "10k solid earrings", "reason": "''10k gold earrings'' + ''solid gold earrings'' bilesenleri Etsy''de birlesir; ayrica tutmak gereksiz."}, {"tag": "gold earrings", "reason": "Baslikta baskin; cok genis, tek basina siralanamayacak kadar rekabetci, slot bosa gider."}, {"tag": "10k earrings", "reason": "''10k gold earrings'' daha guclu varyantla ortu; kisaltilmis hali ekstra deger vermez."}]'::jsonb,'[{"tag": "real gold earrings", "reason": "Alici dili (''real gold'') — som altini arayan yuksek-niyet aramasi."}, {"tag": "womens gold earrings", "reason": "Kitle slotu; bozuk ''nugget women'' yerine dogru long-tail."}, {"tag": "yellow gold earrings", "reason": "Renk/stil slotu; basliktaki ''Yellow Gold'' niteligini aramaya baglar."}, {"tag": "gift for her", "reason": "Hediye niyeti slotu — tamamen eksikti."}, {"tag": "mothers day gift", "reason": "Occasion/hediye slotu; sezonsal trafik."}, {"tag": "everyday earrings", "reason": "Kullanim slotu; nugget kalp gunluk takilabilir hafif urun konumu."}, {"tag": "dainty gold earrings", "reason": "Stil slotu; kucuk nugget kalp icin yuksek-trafik estetik terimi (orta guven — boyut varsayimi)."}, {"tag": "gold heart jewelry", "reason": "Kalp temasini taki kategorisine genisletir; ''earrings'' koku disinda slot cesitliligi."}]'::jsonb,'Slotlarin cogu tek koke ("nugget"/"gold earrings") harcanmis; hediye, kitle, stil ve kullanim niyet slotlari tamamen bos, tek-kelime "nugget" slot israfi.','Mevcut sette 13 slottan ~9''u ''nugget'' + ''gold earrings'' koklerinde toplaniyor (nugget 5 kez, earrings 9 kez); Etsy kelimeleri kendisi kombinledigi icin bu buyuk slot israfi. Tek-kelime ''nugget'' ve bozuk ''nugget women'' etkisiz. Optimize sette 5 en guclu long-tail korundu (gold nugget earrings, heart nugget earring, heart shape earrings, 10k gold earrings, solid gold earrings) ve 8 eksik niyet slotu eklendi: alici dili (real gold), kitle (womens), renk/stil (yellow, dainty), hediye/occasion (gift for her, mothers day gift), kullanim (everyday), kategori genisletme (gold heart jewelry). Tum tag''ler cok-kelimeli ve <=20 karakter; hicbiri urun tipiyle (earring, 10K yellow gold, heart nugget) celismiyor. 10K urunde ''14k'' gibi celisen karat bilerek eklenmedi.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1863505492,'14K Yellow Gold Figaro Link Chain | Women''s, Men''s Jewelry','necklace','standart',ARRAY['Gold Chain','Gold Link Chain','Figaro Bracelet','Figaro Chain','Real Gold Chain','Gold Chain men','Real Gold man chain','Link Chain','Gold Figaro Chain','14k gold chain','14k chain','14k figaro chain','14k men chain']::text[],ARRAY['14k Figaro Chain','Real Gold Chain','Gold Chain for Men','Womens Gold Chain','Figaro Chain Men','Solid Gold Necklace','Gold Necklace Women','Italian Gold Chain','Layered Necklace','Gift for Him','Mens Gold Jewelry','Everyday Necklace','Statement Necklace']::text[],'[{"tag": "Figaro Bracelet", "reason": "Tip celiskisi: urun necklace/figaro chain, bilezik degil; alakasiz aramaya dusuruyor."}, {"tag": "Gold Chain", "reason": "Neredeyse tek-kelime jenerik; ''real gold chain'' vb. varyantlar kokunu zaten tasiyor, slot israfi."}, {"tag": "Gold Link Chain", "reason": "''link'' jenerik ve figaro zaten link chain; redundant."}, {"tag": "Figaro Chain", "reason": "''14k Figaro Chain'' ve ''Figaro Chain Men'' kokunu tasiyor; birebir tekrar niteliginde."}, {"tag": "Real Gold man chain", "reason": "Bozuk dilbilgisi (''man chain''); ''Gold Chain for Men'' daha temiz long-tail ile ikame edildi."}, {"tag": "Link Chain", "reason": "Tek+jenerik dusuk deger; figaro kokuyle cakisiyor."}, {"tag": "Gold Figaro Chain", "reason": "''14k Figaro Chain'' ile ikinci figaro varyanti; redundant."}, {"tag": "14k chain", "reason": "Cok kisa/jenerik; component kelimeler diger 14k tag''inde mevcut."}, {"tag": "14k men chain", "reason": "Zayif dilbilgisi; ''Gold Chain for Men'' + ''Mens Gold Jewelry'' kapsiyor."}, {"tag": "Gold Chain men", "reason": "''Gold Chain for Men'' daha dogru long-tail; redundant."}]'::jsonb,'[{"tag": "Womens Gold Chain", "reason": "Baslik ''Women''s'' diyor ama kadin kitle tag''i yoktu; kritik eksik kitle slotu."}, {"tag": "Gold Chain for Men", "reason": "Duzgun dilbilgili erkek kitle long-tail''i (bozuk ''man chain'' yerine)."}, {"tag": "Figaro Chain Men", "reason": "Stil+kitle birlesimi; erkek figaro aramasini yakalar."}, {"tag": "Solid Gold Necklace", "reason": "''solid gold'' alici dili; necklace urun gercegine mesru."}, {"tag": "Gold Necklace Women", "reason": "Kadin necklace niyeti; kitle+urun tipi."}, {"tag": "Italian Gold Chain", "reason": "Stil slotu; figaro Italyan stili zincirdir."}, {"tag": "Layered Necklace", "reason": "Kullanim slotu (layering) — ince figaro icin guclu."}, {"tag": "Gift for Him", "reason": "Hediye slotu; erkek alici icin donusum niyeti yuksek."}, {"tag": "Mens Gold Jewelry", "reason": "Genis erkek taki kitlesi; ''chain'' kokunden cesitlendirir."}, {"tag": "Everyday Necklace", "reason": "Kullanim slotu; gunluk tasima niyeti."}, {"tag": "Statement Necklace", "reason": "Stil/kullanim slotu; kalin figaro icin uygun."}]'::jsonb,'Tip celiskili "Figaro Bracelet" tagi + "chain/figaro/14k" kokunun 8+ varyanttla tekrarindan dogan slot israfi; basligin vaat ettigi kadin kitlesi ve hediye/stil/kullanim niyet slotlari tamamen eksik.','Standart arketip: relevance korunarak slot israfi temizlendi. Tip celiskili ''Figaro Bracelet'' cikarildi. ''chain'' ve ''figaro'' kokunun tek-kelime/jenerik varyantlari (Gold Chain, Link Chain, 14k chain, Gold Figaro Chain, Figaro Chain) budandi; her biri farkli modifier tasiyan long-tail''ler birakildi. 13''un tamami cok-kelimeli, birebir tekrar yok. Eksik niyet slotlari eklendi: kitle (womens/mens/for men), hediye (gift for him), stil (italian, figaro chain men, statement), kullanim (layered, everyday). ''necklace'' figaro chain necklace icin mesru oldugundan chain/necklace dengesi kuruldu; figaro''nun celismedigi cuban/rope gibi stiller bilerek eklenmedi.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1525338848,'14K Gold Evil Eye Bracelet, Good Luck Charm Jewelry','bracelet','standart',ARRAY['Evil Eye Bracelet','14K Gold Bracelet','14K Evil Eye','Evil Eye Charm','Gold Charm Bracelet','Evil Eye Jewelry','14K Bracelet','Gold Evil Eye','Good Luck Bracelet','Projection Bracelet','Gold Luck Bracelet','Gold Bracelet','Evil Eye Chain']::text[],ARRAY['Evil Eye Bracelet','14K Gold Bracelet','Gold Charm Bracelet','Good Luck Bracelet','Evil Eye Jewelry','Real Gold Bracelet','Protection Bracelet','Nazar Bracelet','Gift for Her','Womens Bracelet','Everyday Bracelet','Stackable Bracelet','Mothers Day Gift']::text[],'[{"tag": "14K Evil Eye", "reason": "Redundant: 14K (slot 2) + evil eye (slot 1/5/8) zaten var; tek basina zayif kok tekrari."}, {"tag": "Evil Eye Charm", "reason": "Pendant-celiski riski (''charm'' tek basina kolye ucu ima eder) + evil eye asiri tekrar; yerine ayirt edici ''Nazar Bracelet'' kondu."}, {"tag": "Gold Evil Eye", "reason": "Birebir kok tekrari (gold + evil eye); yeni arama sinyali getirmiyor, slot israfi."}, {"tag": "14K Bracelet", "reason": "''14K Gold Bracelet'' ile ayni niyet; slot israfi."}, {"tag": "Projection Bracelet", "reason": "Tip/relevance celiskisi — projection (foto ici) taki bu evil eye bilezikle ilgisiz; alakasiz aramaya sokar."}, {"tag": "Gold Luck Bracelet", "reason": "''Good Luck Bracelet'' ile ayni niyet (luck + bracelet); redundant."}, {"tag": "Gold Bracelet", "reason": "Cok genis/generik, yuksek rekabet dusuk donusum; ''14K Gold Bracelet'' ile ortusuyor."}, {"tag": "Evil Eye Chain", "reason": "''Chain'' kolye/zincir ima eder = bilezik urunuyle tip celiskisi; yanlis aramaya sokar."}]'::jsonb,'[{"tag": "Real Gold Bracelet", "reason": "Alici dili (''real gold'') — malzeme listesi 14k Real Gold; som altin arayan yuksek-niyet alicilari yakalar."}, {"tag": "Protection Bracelet", "reason": "Anlam/stil slotu — evil eye''in koruma amacini arayan farkli arama grubu."}, {"tag": "Nazar Bracelet", "reason": "Ayirt edici alici keyword''u — evil eye''in yaygin arama karsiligi ''nazar''; kok tekrari degil yeni sinyal."}, {"tag": "Gift for Her", "reason": "Eksik hediye slotu — hediyelik niyetli alici trafigini acar."}, {"tag": "Womens Bracelet", "reason": "Eksik kitle slotu — kadin takisi aramasini hedefler, dar kitleyi genisletir."}, {"tag": "Everyday Bracelet", "reason": "Kullanim slotu — gunluk takilabilir dainty altin bilezik niyetini yakalar."}, {"tag": "Stackable Bracelet", "reason": "Kullanim/layering slotu — birlikte takma trendini hedefler."}, {"tag": "Mothers Day Gift", "reason": "Hediye/vesile slotu — mevsimsel yuksek hacimli hediye aramasi."}]'::jsonb,'"Evil eye" 13 tag''in 6''sinda tekrarlanip slot israf ediyor ve Gold Bracelet/Projection/Evil Eye Chain gibi generik veya tip-celiskili tag''ler hediye/kitle/kullanim niyet slotlarini tuketmis.','Baslik gercegi 14K altin evil eye BILEZIK (charm bracelet); charm ve jewelry tag''leri mesru, ama Chain/Projection tip-celiskisi ve Gold Bracelet generikligi elendi. 6 kez tekrarlanan evil eye kokunu 3 anlamli varyantla (Evil Eye Bracelet/Jewelry + Nazar) sabitleyip, bosalan slotlari niyet eksenlerine dagittim: malzeme (Real Gold), anlam (Protection), hediye (Gift for Her, Mothers Day Gift), kitle (Womens), kullanim (Everyday, Stackable). Tum tag''ler cok-kelimeli long-tail, <=20 karakter, birebir tekrar yok; ''bracelet'' tekrari her longtail''de farkli niyet tasidigi icin mesru.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1199715763,'14K Real Gold Paperclip Chain Necklace, Rectangle Link Jewelry','necklace','standart',ARRAY['Paperclip Chain','Paperclip Necklace','Gold Paperclip Chain','14K Chain','Gold Chain','Gold Paperclip','Gold Necklace','Gold Chain Necklace','14K Gold Necklace','Paperclip','Real Gold Paperclip','Solid Gold Chain','PaperClips Jewelry']::text[],ARRAY['Paperclip Chain','Paperclip Necklace','14K Gold Necklace','Rectangle Link Chain','Real Gold Chain','Solid Gold Chain','Layering Necklace','Womens Gold Chain','Dainty Necklace','Gift for Her','Minimalist Necklace','Everyday Necklace','Mothers Day Gift']::text[],'[{"tag": "Gold Paperclip Chain", "reason": "Etsy kelimeleri kombinler; ''Paperclip Chain'' + ''Gold'' zaten kapsiyor, birebir kok tekrari"}, {"tag": "14K Chain", "reason": "Tek kavram, ''14K Gold Necklace'' tarafindan kapsaniyor"}, {"tag": "Gold Chain", "reason": "Cok genel head-term; modifikatorlu varyantlar (Real/Solid/Womens Gold Chain) yerini aliyor"}, {"tag": "Gold Paperclip", "reason": "Paperclip kok tekrari, iki-kelime bile olsa slot israfi"}, {"tag": "Gold Necklace", "reason": "Genel; ''14K Gold Necklace'' ve digerleri kapsiyor"}, {"tag": "Gold Chain Necklace", "reason": "Redundant kombinasyon; Etsy zaten ''gold + chain + necklace'' eslestirir"}, {"tag": "Paperclip", "reason": "Tek-kelime, en degersiz slot; long-tail yok"}, {"tag": "Real Gold Paperclip", "reason": "Paperclip kok tekrari; ''Real Gold Chain'' alici dilini paperclip israfi olmadan tasiyor"}, {"tag": "PaperClips Jewelry", "reason": "7. paperclip varyanti; asiri redundancy"}]'::jsonb,'[{"tag": "Rectangle Link Chain", "reason": "Baslikta gecen dikdortgen link tanimini yakalar; distinct arama niyeti"}, {"tag": "Real Gold Chain", "reason": "Alici dili (''real gold'') — ''plated'' filtreleyen alicilar bu terimi yazar"}, {"tag": "Layering Necklace", "reason": "Kullanim slotu; paperclip zincirler layering icin populer"}, {"tag": "Womens Gold Chain", "reason": "Kitle slotu — daralan hedef yerine kadin alici acikca isaretlenir"}, {"tag": "Dainty Necklace", "reason": "Stil slotu; ince/zarif algi arayan alici segmenti"}, {"tag": "Gift for Her", "reason": "Hediye niyeti tamamen bostu; yuksek hacimli alici arama kaligi"}, {"tag": "Minimalist Necklace", "reason": "Tarz slotu; paperclip estetigiyle birebir ortusur"}, {"tag": "Everyday Necklace", "reason": "Kullanim slotu; gunluk tasima niyeti"}, {"tag": "Mothers Day Gift", "reason": "Mevsimsel hediye slotu; yuksek donusum donemlerinde trafik ceker"}]'::jsonb,'Slot israfi: 13 tag''in 7''si "paperclip" kokunu tekrarliyor ve hicbir hediye/kitle/stil/kullanim niyeti islenmemis.','Ana hastalik asiri redundancy idi: 13 slotun 7''si ''paperclip'', ustune ~5''i ''gold chain/necklace'' tekrariydi — Etsy kelimeleri zaten kombinledigi icin bu 12 slotu efektif ~4 farkli aramaya indiriyordu. Cekirdek iki head-term (Paperclip Chain, Paperclip Necklace) ile 14K + Solid Gold Chain korundu; relevance icin ''necklace'' mesru cunku urun tipi necklace. Bosalan 9 slot niyet cesitliligine dagitildi: kitle (Womens), hediye (Gift for Her, Mothers Day Gift), stil (Dainty, Minimalist), kullanim (Layering, Everyday), alici dili (Real Gold Chain) ve baslik-turevi tanim (Rectangle Link Chain). 13 tag''in tamami cok-kelimeli, hepsi <=20 karakter, birebir tekrar yok. conv=%0.24 dusuk oldugu icin kesif slotlari (hediye/kullanim) donusum potansiyeli tasiyor.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1756910876,'14K White Gold Franco Box Chain | Solid Gold Necklace','necklace','standart',ARRAY['Franco Chain','14K Gold Chain','Box Chain','Gold Franco Chain','14K Gold Necklace','Ladies Chain','Men Chain','14K Franco Chain','14K Box Chain','14K Ladies Chain','14K Men Chain','14K Link Chain','solid gold chain']::text[],ARRAY['Franco Chain','Box Chain Necklace','White Gold Chain','14K White Gold','Solid Gold Necklace','Real Gold Chain','Mens Gold Chain','Womens Gold Chain','Gift for Him','Layering Necklace','14K Gold Necklace','Italian Gold Chain','Everyday Chain']::text[],'[{"tag": "14K Gold Chain", "reason": "14K+Gold+Chain kombinasyonu diger tag''lerde zaten var; Etsy kelimeleri kendi kombinler, slot israfi"}, {"tag": "Box Chain", "reason": "''Box Chain Necklace'' ile yukseltildi (long-tail + necklace niyeti)"}, {"tag": "Gold Franco Chain", "reason": "Franco koku ''Franco Chain''de var; ayni kok tekrari"}, {"tag": "Ladies Chain", "reason": "Belirsiz; ''Womens Gold Chain'' ile alici dili+gold eklenerek netlestirildi"}, {"tag": "Men Chain", "reason": "Gramer bozuk tek-kok; ''Mens Gold Chain'' ile duzeltildi"}, {"tag": "14K Franco Chain", "reason": "Franco koku ucuncu kez; redundant"}, {"tag": "14K Box Chain", "reason": "Box koku ikinci kez + 14K stuffing"}, {"tag": "14K Ladies Chain", "reason": "Ladies koku tekrar + 14K stuffing"}, {"tag": "14K Men Chain", "reason": "Men koku tekrar + 14K stuffing"}, {"tag": "14K Link Chain", "reason": "Genel/jenerik; Franco-box urunune ozgu deger katmiyor"}, {"tag": "solid gold chain", "reason": "''Solid Gold Necklace'' ile korunup necklace niyetine baglandi"}]'::jsonb,'[{"tag": "White Gold Chain", "reason": "Baslikaki ana farklilastirici renk/malzeme; onceki sette tamamen eksikti"}, {"tag": "14K White Gold", "reason": "White gold + ayar aramasini yakalar; kritik bosluk"}, {"tag": "Box Chain Necklace", "reason": "Box koku + urun tipi necklace, long-tail"}, {"tag": "Solid Gold Necklace", "reason": "Alici dili ''solid gold'' + necklace niyeti"}, {"tag": "Real Gold Chain", "reason": "Yuksek niyetli alici dili ''real gold''"}, {"tag": "Mens Gold Chain", "reason": "Erkek kitlesi net + gold alici dili"}, {"tag": "Womens Gold Chain", "reason": "Kadin kitlesi net; ''Ladies Chain''in netlestirilmis hali"}, {"tag": "Gift for Him", "reason": "Eksik hediye niyeti slotu"}, {"tag": "Layering Necklace", "reason": "Eksik kullanim slotu (katmanli tarz)"}, {"tag": "Italian Gold Chain", "reason": "Stil slotu; Franco Italyan zincir stilidir, relevant"}, {"tag": "Everyday Chain", "reason": "Eksik kullanim slotu (gunluk kullanim)"}]'::jsonb,'Baslikta ana farklilastirici olan ''white gold'' tag''lerde HIC yok; ''14K'' 13 tag''in 8''ine tikilmis ve Franco/Box/Ladies/Men kokleri 2-3''er kez tekrarlanarak slotlar israf edilmis.','Standart arketip: dengeli temizlik. 11 redundant/dar tag''i cikardim (14K x8 stuffing + Franco/Box/Ladies/Men kok tekrarlari), ''Franco Chain'' ve ''14K Gold Necklace'' korundu. En buyuk kazanc: baslikta baskin ama tag''lerde hic olmayan ''white gold'' iki slotla (White Gold Chain, 14K White Gold) yakalandi. Eksik niyet slotlari acildi: alici dili (Real/Solid Gold), kitle (Mens/Womens), hediye (Gift for Him), kullanim (Layering/Everyday), stil (Italian). Tumu cok-kelimeli long-tail, hepsi <=20 karakter, birebir tekrar yok, hicbiri urun tipiyle celismez (necklace/chain zincir urununde mesru).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1771229327,'Solid 14K White Gold Franco Chain Bracelet | Unisex Real Gold Jewelry','bracelet','standart',ARRAY['Franco Bracelet','Franco Chain','Gold Franco Chain','Gold Franco Bracelet','Real Gold Bracelet','Bracelet for men','Real Gold man chain','14K Gold Bracelet','Gold Bracelet','14K Bracelet','white gold franco','white gold bracelet','solid gold bracelet']::text[],ARRAY['Franco Bracelet','Franco Chain','white gold bracelet','14k gold bracelet','solid gold bracelet','mens gold bracelet','unisex bracelet','gift for him','gift for her','italian gold','chain link bracelet','everyday bracelet','real gold jewelry']::text[],'[{"tag": "Gold Franco Chain", "reason": "Franco+chain kokunu 3. kez tekrar ediyor; baslik zaten ''Franco Chain Bracelet'' iceriyor, iki Franco tag''i yeterli — slot israfi."}, {"tag": "Gold Franco Bracelet", "reason": "Franco+bracelet kokunun 4. varyanti; ''Franco Bracelet'' ile birebir ortusuyor, Etsy kendisi kombinler."}, {"tag": "white gold franco", "reason": "5. Franco varyanti; ''white gold bracelet'' + ''Franco Bracelet'' ikilisi bu aramayi zaten kapsiyor."}, {"tag": "Real Gold man chain", "reason": "Tip-celiskisi: urun bir BILEKLIK; ''man chain'' kolye cagrisimi yapip yanlis aramaya sokar (relevance zarari)."}, {"tag": "Gold Bracelet", "reason": "Neredeyse tek-kelime, asiri genis; baslik/nitelik zaten ''gold bracelet'' ile baskin — dusuk getiri."}, {"tag": "14K Bracelet", "reason": "''14k gold bracelet'' ile ortusen zayif kismi varyant; kok tekrari."}, {"tag": "Real Gold Bracelet", "reason": "''gold bracelet'' koku zaten 4 varyantla doymus; ''real gold'' niyetini ''real gold jewelry'' ile daha genis kokte tasidik."}, {"tag": "Bracelet for men", "reason": "Zayif ifade; ''mens gold bracelet'' hem kitleyi hem malzemeyi tasidigi icin bunun yerine gecti."}]'::jsonb,'[{"tag": "mens gold bracelet", "reason": "Kitle+malzeme birlesik; zayif ''Bracelet for men''in guclu versiyonu."}, {"tag": "unisex bracelet", "reason": "Baslik ''Unisex'' vaat ediyor ama tag yoktu — kitle slotu (basligi tag ile eslestir)."}, {"tag": "gift for him", "reason": "Hediye slotu tamamen bostu; erkek altin bilekligin en guclu satin alma niyeti."}, {"tag": "gift for her", "reason": "Hediye slotu + kadin/unisex niyetini dengeler."}, {"tag": "italian gold", "reason": "Stil slotu; premium som altin alicisinin kalite arama dili."}, {"tag": "chain link bracelet", "reason": "Urun/stil slotu; Franco''nun link yapisini genis aramaya baglar, celiski yok."}, {"tag": "everyday bracelet", "reason": "Kullanim slotu; gunluk takilabilir dayanikli som altin konumlandirmasi."}, {"tag": "real gold jewelry", "reason": "Alici dili (''real gold'') + kok genisletme; doymus ''gold bracelet'' kokunun disina cikar."}]'::jsonb,'Slotlar redundancy ile tükenmiş: 5 "Franco" varyanti + 6 "gold bracelet" varyanti ayni kokleri tekrarlarken hediye/stil/kullanim slotlari ve basligin vaat ettigi "unisex" kitlesi tamamen bos.','Standart strateji: dengeli temizlik. En buyuk kayip redundancy''ydi — 5 Franco ve 6 ''gold bracelet'' varyanti birbirini yiyordu. Franco''yu 2 varyanta indirdim (baslik zaten tam ifadeyi tasiyor), ''gold bracelet'' kokunu 4 anlamli nitelikle sinirladim (white/14k/solid/mens — her biri gercek ayri arama: renk/ayar/saflik/kitle). Bosalan slotlari 4 eksik niyet ekseniyle doldurdum: hediye (gift for him/her), kitle (unisex/mens), stil (italian gold, chain link), kullanim (everyday) ve alici dili genisletme (real gold jewelry). Tip-celiskisi olan ''Real Gold man chain'' (bileklik urununde kolye cagrisimi) cikarildi. Tum tag''ler cok-kelimeli, tekil kelime yok; hepsi <=20 karakter (en uzun 19).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1330438455,'10K Solid Gold Cuban Curb Ring | Statement Chain Link','ring','standart',ARRAY['Curb Ring','Cuban Ring','10K Gold Ring','10K Ring','Gold Curb Ring','Solid Gold Ring','Cuban Curb Ring','Real Gold Ring','Cuban Link Ring','Gold Chain Ring','Chain Link Ring','Solid Chain Ring','Gold Simple Ring']::text[],ARRAY['Cuban Curb Ring','10K Solid Gold Ring','Real Gold Ring','Chain Link Ring','Miami Cuban Ring','Mens Gold Ring','Womens Gold Ring','Statement Ring','Hip Hop Ring','Luxury Gold Ring','Gift For Him','Stackable Ring','Everyday Gold Ring']::text[],'[{"tag": "Curb Ring", "reason": "Cuban Curb Ring icinde kapsandi; tek modifikatorlu zayif varyant."}, {"tag": "Cuban Ring", "reason": "Cuban Curb + Miami Cuban ile karsilaniyor, birebir kok tekrari."}, {"tag": "10K Gold Ring", "reason": "10K Solid Gold Ring icinde kapsandi."}, {"tag": "10K Ring", "reason": "Ince/anlamsiz; 10K zaten bilesik tag''lerde var."}, {"tag": "Gold Curb Ring", "reason": "Curb varyanti fazlaligi, slot israfi."}, {"tag": "Solid Gold Ring", "reason": "10K Solid Gold Ring icinde kapsandi."}, {"tag": "Cuban Link Ring", "reason": "3. Cuban varyanti; Etsy kelimeleri zaten kombinliyor."}, {"tag": "Gold Chain Ring", "reason": "Chain Link Ring korundu, bu chain fazlaligi."}, {"tag": "Solid Chain Ring", "reason": "Redundant + dogal olmayan arama ifadesi."}, {"tag": "Gold Simple Ring", "reason": "Baslikteki ''Statement'' konumlandirmasiyla celisiyor (basit vs statement)."}]'::jsonb,'[{"tag": "10K Solid Gold Ring", "reason": "Malzeme+solid+ayar tek bilesik long-tail; alici dili ''solid gold''."}, {"tag": "Miami Cuban Ring", "reason": "Stil slotu; yuksek hacimli ''miami cuban'' aramasi."}, {"tag": "Mens Gold Ring", "reason": "Kitle slotu; Cuban/curb erkek-agirlikli stil."}, {"tag": "Womens Gold Ring", "reason": "Kitle genisletme; kadin alicilari da kapsa."}, {"tag": "Statement Ring", "reason": "Baslikteki ''Statement'' kullanim/tarz niyetini yakalar."}, {"tag": "Hip Hop Ring", "reason": "Tarz slotu; Cuban/curb hip hop estetigiyle guclu eslesir."}, {"tag": "Luxury Gold Ring", "reason": "Tarz/konumlandirma slotu; som altin luks algisi."}, {"tag": "Gift For Him", "reason": "Hediye niyeti slotu; erkek hediye aramalari."}, {"tag": "Stackable Ring", "reason": "Kullanim slotu; kadin/istifleme alicilarini kapsar, kitle dengesi."}, {"tag": "Everyday Gold Ring", "reason": "Kullanim slotu; gunluk tasima niyeti."}]'::jsonb,'13 tag''in tamami "gold cuban curb chain ring" kokunun near-duplicate varyanti; Cuban x4, Curb x3, Chain x4 slot israfi yaparken kitle/hediye/stil/kullanim niyet slotlari tamamen bos.','Orijinal set tam bir redundancy tuzagi: 13 tag''in tamami ayni ''gold cuban curb chain ring'' kokunun yeniden dizilimi (Cuban x4, Curb x3, Chain x4, Gold x8) ve Etsy kelimeleri kendisi kombinledigi icin bu slotlarin cogu bosa gidiyor. Konv %0.148 dusuk. Cozum: cakisan kokleri tek guclu long-tail''e katladim (Cuban Curb Ring, 10K Solid Gold Ring, Chain Link Ring, Miami Cuban Ring korundu/eklendi), acilan 7 slotu bos niyet eksenlerine dagittim — kitle (Mens/Womens Gold Ring), hediye (Gift For Him), stil (Hip Hop, Luxury, Statement), kullanim (Stackable, Everyday). Tum tag''ler cok-kelimeli ve <=20 karakter. Relevance korundu: urun bir yuzuk oldugu icin her tag ''Ring'' ile bitiyor; ''Gold Simple Ring'' baslikteki ''Statement'' konumlandirmasiyla celistigi icin cikarildi.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1806033692,'10K Real Gold Cuban Curb Link Chain | Yellow Gold, Lobster Lock','necklace','standart',ARRAY['Cuban Link Chain','Link Chain Bracelet','Real Gold Bracelet','Gold Chain Bracelet','10K Gold Chain','Gold Chain','Miami Cuban chain','10K Chain','Cuban Chain','Gold Link Chain','Gold Curb Chain','10K Curb Chain','Cuban Curb Chain']::text[],ARRAY['Cuban Link Chain','Miami Cuban Chain','10K Gold Chain','Gold Curb Chain','Real Gold Necklace','Gold Chain for Men','Mens Gold Necklace','Gift for Him','Yellow Gold Chain','Solid Gold Chain','Hip Hop Chain','Statement Necklace','Curb Link Necklace']::text[],'[{"tag": "Link Chain Bracelet", "reason": "Tip-celiskisi: urun necklace, baslikta ''Chain'' (kolye) — bracelet aramasina dusmek yanlis trafik ve dusuk conversion getirir."}, {"tag": "Real Gold Bracelet", "reason": "Tip-celiskisi: bracelet, urun necklace; alakasiz."}, {"tag": "Gold Chain Bracelet", "reason": "Tip-celiskisi: bracelet, urun necklace; alakasiz."}, {"tag": "Gold Chain", "reason": "Cok jenerik ve ''10K Gold Chain'' ile ortusen slot israfi; tek-konseptli, rekabeti asiri yuksek."}, {"tag": "10K Chain", "reason": "Eksik/jenerik; ''10K Gold Chain'' zaten 10K+gold+chain kokunu tasiyor — redundant."}, {"tag": "Cuban Chain", "reason": "''Cuban Link Chain'' ve ''Miami Cuban Chain'' ile cuban kokunu tekrarliyor — 4 cuban varyanti slot israfi."}, {"tag": "Gold Link Chain", "reason": "Jenerik; ''Cuban Link Chain'' ve ''Curb Link Necklace'' link+chain niyetini zaten kapsiyor."}, {"tag": "10K Curb Chain", "reason": "''Gold Curb Chain'' ile curb kokunu tekrarliyor — redundant."}, {"tag": "Cuban Curb Chain", "reason": "Cuban+curb koklerini ust uste bindiren cift redundancy; ayri ayri zaten kapsanmis."}]'::jsonb,'[{"tag": "Real Gold Necklace", "reason": "Alici dili (''real gold'') + dogru urun tipi (necklace); tip-celiskili bracelet tag''larinin yerine mesru type sinyali."}, {"tag": "Gold Chain for Men", "reason": "Kitle slotu: cuban curb chain erkek agirlikli — ''for men'' niyet aramasini acar."}, {"tag": "Mens Gold Necklace", "reason": "Kitle + tip: erkek alici + necklace tipini birlestirir."}, {"tag": "Gift for Him", "reason": "Hediye slotu (tamamen eksikti); erkek hediye niyeti yuksek donusum getirir."}, {"tag": "Yellow Gold Chain", "reason": "Basliktaki ''Yellow Gold'' niteligini slot olarak degerlendirir."}, {"tag": "Solid Gold Chain", "reason": "Alici dili (''solid gold'') — 10K real gold icin guclu arama terimi."}, {"tag": "Hip Hop Chain", "reason": "Stil/tarz slotu: cuban curb zincirin baskin estetigi; farkli alici havuzu."}, {"tag": "Statement Necklace", "reason": "Kullanim slotu: kalin cuban curb kolye statement parcasi olarak konumlanir."}, {"tag": "Curb Link Necklace", "reason": "Curb+link+tip''i tek long-tail''de birlestirir; tekil curb/link tag''larinin yerine daha spesifik."}]'::jsonb,'Uc tag necklace urunune ''bracelet'' derken tip-celiskisi yaratiyor ve geri kalanlar cuban/curb/chain kokunu tekrarlayip hediye/kitle/stil/kullanim slotlarini tamamen bos birakiyor.','Once tip-celiskisi giderildi: baslik ''Chain''/necklace derken uc ''bracelet'' tag''i yanlis kategoriye trafik cekiyordu — ucu de atildi. Sonra redundancy temizlendi: cuban 4->2, curb 3->2, jenerik ''Gold Chain''/''10K Chain''/''Gold Link Chain'' cikarildi. Acilan 9 slot niyet ekseninde dolduruldu — kitle (men/mens), hediye (gift for him), title-nitelik (yellow gold), alici dili (real/solid gold), stil (hip hop), kullanim (statement) ve dogru tip (necklace varyantlari). Cekirdek yuksek-alaka tag''lar (Cuban Link Chain, Miami Cuban Chain, 10K Gold Chain, Gold Curb Chain) korundu. Tum tag''lar cok-kelimeli, birebir tekrar yok, her biri <=20 karakter (en uzun 18).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1753972282,'10K Gold Religious Medallion Pendant – St. Jude, Last Supper, Jesus','pendant','standart',ARRAY['10K Gold Pendant','Egypt Jewelry','Egypt Pendant','Diamond Cut Pendant','White Gold Pendant','10K Gold Pendant men','Religious Pendant','Egyptian Pendant','two tone pendant','solid gold pendant','jude medallion','jesus head pendant','last supper pendant']::text[],ARRAY['10K Gold Pendant','religious medallion','St Jude pendant','last supper pendant','jesus piece','gold pendant for men','solid gold pendant','diamond cut pendant','two tone medallion','catholic jewelry','first communion gift','confirmation gift','mens gold medallion']::text[],'[{"tag": "Egypt Jewelry", "reason": "Tip celiskisi: urun dini medalyon (St Jude/Isa); Misir temasi alakasiz, relevance kiriyor ve slot israfi."}, {"tag": "Egypt Pendant", "reason": "Ayni tip celiskisi + ''Egyptian Pendant'' ile kok tekrari (cift Misir slotu)."}, {"tag": "Egyptian Pendant", "reason": "''Egypt Pendant'' ile birebir redundant kok + dini urunle celiski."}, {"tag": "White Gold Pendant", "reason": "Malzeme Yellow/10k gold; beyaz altin iddiasi celisik, aliciyi yaniltir."}, {"tag": "10K Gold Pendant men", "reason": "''10K Gold Pendant'' ile kok tekrari; erkek kitle sinyali ''gold pendant for men'' ve ''mens gold medallion'' ile daha temiz tasindi."}, {"tag": "Religious Pendant", "reason": "Tek-boyutlu; ''religious medallion'' ve ''catholic jewelry'' ile hem noun cesitliligi hem daha genis dini niyet kapsandi."}, {"tag": "jude medallion", "reason": "Alicilar ''St Jude'' arar; ''St Jude pendant'' net aziz araması icin daha guclu."}, {"tag": "jesus head pendant", "reason": "Dar terim; altin taki jargonunda yuksek hacimli ''jesus piece'' ile degistirildi, ayni zamanda pendant tekrarini azaltir."}, {"tag": "two tone pendant", "reason": "Stil korundu ama ''two tone medallion'' olarak noun cesitlendirildi (pendant asiri tekrarini kirmak icin)."}]'::jsonb,'[{"tag": "religious medallion", "reason": "Dini niyet + baslikta gecen ''medallion'' terimi; pendant tekrarini kiran noun cesitliligi."}, {"tag": "St Jude pendant", "reason": "Net aziz araması; alicilar tam bu ifadeyi yazar."}, {"tag": "jesus piece", "reason": "Altin taki/hip hop jargonunda yuksek hacimli arama terimi."}, {"tag": "gold pendant for men", "reason": "Eksik kitle slotu (erkek) + ''gold'' alici dili; dar kitle sorununu acar."}, {"tag": "two tone medallion", "reason": "Mevcut iki-tonlu stil sinyalini medallion nounuyla tasir (cesitlilik)."}, {"tag": "catholic jewelry", "reason": "Dini niyeti genisletir + noun cesitliligi (Katolik alicilar)."}, {"tag": "first communion gift", "reason": "Eksik hediye/occasion slotu; dini medalyonlar icin guclu hediye niyeti."}, {"tag": "confirmation gift", "reason": "Ikinci occasion hediye slotu (konfirmasyon)."}, {"tag": "mens gold medallion", "reason": "Erkek kitle + medallion nounu; alici sinyalini pekistirir."}]'::jsonb,'Uc adet Misir/Egyptian tag''i dini urunle (St Jude, Son Aksam Yemegi, Isa) dogrudan celisip 3 slot israf ediyor; ayrica kok tekrarlari var ve hediye/kitle/occasion slotlari tamamen eksik.','Standart arketip icin dengeli temizlik yaptim. (1) Relevance: dini urunle celisen 3 Misir/Egyptian tag''i ve malzemeyle celisen ''White Gold'' cikarildi. (2) Redundancy: ''Egypt/Egyptian'' cift koku ve ''10K Gold Pendant'' + ''...men'' kok tekrari kaldirildi; ''pendant'' nounu 6 tag''e dengelendi, kalanlar medallion/piece/jewelry/gift ile cesitlendirildi. (3) Slot genisletme: kitle (gold pendant for men, mens gold medallion), occasion/hediye (first communion gift, confirmation gift), stil (diamond cut, two tone), dini niyet (religious medallion, catholic jewelry) eklendi. Net aziz/Isa terimleri (St Jude pendant, jesus piece, last supper) korunarak spesifik alici araması hedeflendi. 13 tag''in hepsi <=20 karakter, hepsi cok-kelimeli long-tail, birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1820404194,'10K Gold Cuban Curb Link Bracelet - Yellow Gold Chain','bracelet','standart',ARRAY['Cuban Link Chain','10K Gold Bracelet','Link Chain Bracelet','Gold Bracelet','Cuban Link Bracelet','Gold Curb Bracelet','Miami Cuban Bracelet','Real Gold Bracelet','Gold Chain Bracelet','10K Bracelet','Gold Link Bracelet','10K Chain Bracelet','Cuban Bracelet']::text[],ARRAY['Miami Cuban Bracelet','10K Gold Bracelet','Cuban Link Chain','Solid Gold Bracelet','Mens Gold Bracelet','Curb Chain Bracelet','Real Gold Jewelry','Gift for Him','Hip Hop Jewelry','Diamond Cut Cuban','Everyday Bracelet','Stackable Bracelet','Fathers Day Gift']::text[],'[{"tag": "Link Chain Bracelet", "reason": "Genel/muglak; ''link+chain+bracelet'' koklerini tekrarliyor, hicbir spesifik niyet katmiyor."}, {"tag": "Gold Bracelet", "reason": "Cok genis ve neredeyse tek-kok; Etsy zaten baslik+niteliklerden kombinliyor, long-tail degeri yok."}, {"tag": "Cuban Link Bracelet", "reason": "''Miami Cuban Bracelet'' + ''Cuban Link Chain'' ile ayni kok; slot israfi."}, {"tag": "Gold Curb Bracelet", "reason": "''gold'' fazlaligi; curb anahtari daha temiz ''Curb Chain Bracelet'' ile korundu."}, {"tag": "Real Gold Bracelet", "reason": "Kavram korundu ama ''Real Gold Jewelry''e tasindi; bracelet noun''u zaten cok slotta var, kategori genisletildi."}, {"tag": "Gold Chain Bracelet", "reason": "''gold+chain+bracelet'' generik tekrar; ayirt edici bir modifier yok."}, {"tag": "10K Bracelet", "reason": "Zayif, iki-kelime ama tek-kok gibi; long-tail yok, ''10K Gold Bracelet'' zaten kapsiyor."}, {"tag": "Gold Link Bracelet", "reason": "''link'' ve ''gold'' koklerinin tekrari; slot israfi."}, {"tag": "10K Chain Bracelet", "reason": "''10K'' ucuncu kez; ''10K Gold Bracelet'' ile ortusuyor."}, {"tag": "Cuban Bracelet", "reason": "Kisa; ''Miami Cuban Bracelet'' ve ''Cuban Link Chain'' alt-kumesi, slot israfi."}]'::jsonb,'[{"tag": "Solid Gold Bracelet", "reason": "Yuksek niyetli alici dili (''solid gold'') eksikti; gercek altin arayan aliciyi yakalar."}, {"tag": "Mens Gold Bracelet", "reason": "Kitle slotu yoktu; Cuban/curb bilekliklerin baskin alicisi erkek."}, {"tag": "Curb Chain Bracelet", "reason": "Baslikta gecen ''curb'' anahtarini daha temiz ifadeyle korur."}, {"tag": "Real Gold Jewelry", "reason": "Alici dili + kategori noun''unu bilekligin otesine genisletir (jewelry aramalari)."}, {"tag": "Gift for Him", "reason": "Hediye niyet slotu tamamen eksikti; erkek takisinda guclu donusum sinyali."}, {"tag": "Hip Hop Jewelry", "reason": "Stil/vibe slotu; Cuban link alicisinin dogal arama tarzi."}, {"tag": "Diamond Cut Cuban", "reason": "Stil/finis slotu; parlaklik/kesim arayan aliciyi hedefler."}, {"tag": "Everyday Bracelet", "reason": "Kullanim slotu; gunluk tasima niyetini yakalar."}, {"tag": "Stackable Bracelet", "reason": "Kullanim/layering slotu; birden fazla adet satisini tetikler."}, {"tag": "Fathers Day Gift", "reason": "Mevsimsel hediye-occasion slotu; erkek takisinda yuksek niyetli."}]'::jsonb,'Asiri redundancy: 13 slotun neredeyse tamami ayni 3-4 koke (''bracelet/gold/cuban/10K'') gomulmus; hediye, kitle, stil ve kullanim niyet slotlari tamamen bos.','Mevcut set 13 slotu ~3 koke (''bracelet'' 11x, ''gold'' ~9x, ''cuban'' 4x) yiginca slot israfi yapiyor ve hicbir hediye/kitle/stil/kullanim niyeti yok. Etsy kelimeleri kendisi kombinlediginden ayni koku tekrarlamak yeni arama yuzeyi acmiyor. 3 guclu cekirdek phrase korundu (Miami Cuban, 10K Gold Bracelet, Cuban Link Chain) + curb anahtari daha temiz tutuldu; kalan zayif/dup slotlar alici dili (solid/real gold), kitle (mens), hediye (gift for him, fathers day), stil (hip hop, diamond cut) ve kullanim (everyday, stackable) niyetlerine tasindi. Tum tag''ler cok-kelimeli, <=20 karakter, birebir tekrarsiz ve bilezik gercegiyle uyumlu.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1876638143,'14K Yellow Gold Miami Cuban Link Chain – CZ Box Lock','necklace','standart',ARRAY['Miami Cuban Link','Miami Cuban','Monaco Chain','Cuban Chain','Link Chain','Monaco Cuban','Gold Chain','14K GOLD CHAIN','14K MIAMI','14K CHAIN','14K CUBAN CHAIN','14K GOLD NECKLACE','14K MIAMI CHAIN']::text[],ARRAY['Miami Cuban Link','Cuban Link Chain','Mens Gold Chain','Solid Gold Chain','Real Gold Necklace','Gold Chain for Him','Mens Jewelry Gift','Iced Out Chain','Hip Hop Jewelry','Diamond Cut Chain','Monaco Chain','CZ Box Lock Chain','Statement Necklace']::text[],'[{"tag": "Miami Cuban", "reason": "''Miami Cuban Link'' alt kumesi — Etsy kombinledigi icin tam slot israfi"}, {"tag": "Cuban Chain", "reason": "''Cuban Link Chain'' ile ayni kok, redundant"}, {"tag": "Link Chain", "reason": "Zayif/genel; ''Cuban Link Chain'' zaten kapsiyor"}, {"tag": "Monaco Cuban", "reason": "''Monaco Chain'' + cuban kokleriyle cift redundant"}, {"tag": "Gold Chain", "reason": "Genel; ''gold chain'' koku baska modifiyeli tag''lerde zaten var"}, {"tag": "14K GOLD CHAIN", "reason": "''14K'' baslikta mevcut; ayni kok cok kez tekrar — slot israfi"}, {"tag": "14K MIAMI", "reason": "14K tekrari + eksik/parcali ifade"}, {"tag": "14K CHAIN", "reason": "14K tekrari + genel ''chain''"}, {"tag": "14K CUBAN CHAIN", "reason": "14K + cuban kokunun bir kez daha tekrari"}, {"tag": "14K MIAMI CHAIN", "reason": "14K + miami kokunun bir kez daha tekrari"}, {"tag": "14K GOLD NECKLACE", "reason": "14K tekrari; alici-dilli ''Real Gold Necklace'' ile degistirildi"}]'::jsonb,'[{"tag": "Cuban Link Chain", "reason": "Ana long-tail arama terimi; ''miami'' olmadan da genis kapsar"}, {"tag": "Mens Gold Chain", "reason": "Kitle slotu — cuban link agirlikli erkek aramasi"}, {"tag": "Solid Gold Chain", "reason": "Alici dili — som altin niyeti (real/solid gold)"}, {"tag": "Real Gold Necklace", "reason": "Alici dili + necklace niyeti (urun tipi necklace, mesru)"}, {"tag": "Gold Chain for Him", "reason": "Hediye slotu — erkege hediye niyeti"}, {"tag": "Mens Jewelry Gift", "reason": "Hediye + kitle slotu"}, {"tag": "Iced Out Chain", "reason": "Stil slotu — CZ box lock ile uyumlu buzlu gorunum"}, {"tag": "Hip Hop Jewelry", "reason": "Tarz slotu — cuban link''in ana kultur baglami"}, {"tag": "Diamond Cut Chain", "reason": "Stil slotu — parlak kesim niteligi"}, {"tag": "CZ Box Lock Chain", "reason": "Urun ozelligi (baslikta gecen box lock) — nis arama"}, {"tag": "Statement Necklace", "reason": "Kullanim/tarz slotu"}]'::jsonb,'Tag setinin tamami tek koke ("cuban/miami" 7 varyant, "14K" 6 varyant) sikismis; hediye, stil, kitle ve alici-dili niyet slotlari tamamen bos.','Standart arketip: slot israfini temizleyip relevance''i koruyarak niyet cesitlemesi actik. Orijinalde 13 tag''in 11''i sadece ''cuban/miami/14K'' kokunu tekrarliyordu (Etsy kelimeleri kendi kombinledigi icin bu net kayip). Iki kok tasiyicisini korudum: ''Miami Cuban Link'' (birincil) ve ''Monaco Chain'' (mesru sinonim). Kalan 11 slotu bos niyetlere dagittim: alici dili (Solid/Real Gold), kitle (Mens), hediye (for Him, Mens Jewelry Gift), stil (Iced Out, Hip Hop, Diamond Cut), urun ozelligi (CZ Box Lock), kullanim (Statement). Necklace tag''leri urun tipi ''necklace'' oldugu icin mesru — korlemesine silinmedi. Tumu cok-kelimeli long-tail, hicbiri >20 karakter, birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1359195369,'14K Solid Gold Curb Bracelet – Miami Cuban Chain Link','bracelet','standart',ARRAY['Gold Curb Bracelet','Solid Gold Bracelet','14K Gold Bracelet','Gold Link Bracelet','Gold Cuban Bracelet','Link Chain Bracelet','14K Solid Bracelet','Curb Chain Bracelet','Heavy Mens Bracelet','Miami Link Bracelet','Gold Bracelet','14K Link Bracelet','14K Bracelet']::text[],ARRAY['Gold Curb Bracelet','Miami Cuban Bracelet','Solid Gold Bracelet','14K Gold Bracelet','Mens Gold Bracelet','Real Gold Bracelet','Cuban Link Chain','Curb Chain Bracelet','Gift For Him','Heavy Gold Bracelet','Everyday Bracelet','Statement Bracelet','Unisex Gold Bracelet']::text[],'[{"tag": "Gold Bracelet", "reason": "Cok genis, tek-kelime niyetli, dusuk-rekabet degeri yok; slot israfi."}, {"tag": "14K Bracelet", "reason": "Cok genis; 14K zaten uc long-tail tag''de var, tek basina rekabetsiz slot israfi."}, {"tag": "Gold Link Bracelet", "reason": "''Link'' daha spesifik Cuban Link Chain/Curb Chain tag''leriyle cakisiyor; generik."}, {"tag": "Link Chain Bracelet", "reason": "''Link''+''Chain'' redundant, urun tipini belirtmeyen jenerik varyant."}, {"tag": "14K Link Bracelet", "reason": "14K ve Link koklerinin ucuncu tekrari; ek arama karsiligi yok."}, {"tag": "14K Solid Bracelet", "reason": "14K ve Solid koklerinin tekrari; Solid Gold Bracelet + 14K Gold Bracelet birlikte karsiliyor."}, {"tag": "Gold Cuban Bracelet", "reason": "Daha guclu ''Miami Cuban Bracelet'' ile degistirildi (Miami stil kelimesi eklenir)."}, {"tag": "Miami Link Bracelet", "reason": "Miami ve Cuban artik Miami Cuban Bracelet + Cuban Link Chain''de; tekrar."}, {"tag": "Heavy Mens Bracelet", "reason": "''Heavy Gold Bracelet'' + ''Mens Gold Bracelet'' olarak ikiye acildi, her biri ayri niyet yakalar."}]'::jsonb,'[{"tag": "Miami Cuban Bracelet", "reason": "Stil slotu: ''Miami Cuban'' yuksek-hacimli stil terimi, baslikla birebir uyumlu."}, {"tag": "Mens Gold Bracelet", "reason": "Kitle slotu: ''mens gold'' alici dili, curb/cuban erkek talebinde guclu."}, {"tag": "Real Gold Bracelet", "reason": "Alici dili ''real gold'' (materyal 14K REAL GOLD ile birebir), som altin aricisini yakalar."}, {"tag": "Cuban Link Chain", "reason": "Zincir/stil cesitlemesi: ''chain'' kokuyle bracelet tekrarini kirar, urun gercek bir cuban link zincir bilekliktir."}, {"tag": "Gift For Him", "reason": "Eksik hediye niyet slotu; erkek hediye aramalarini acar."}, {"tag": "Heavy Gold Bracelet", "reason": "Nitelik slotu: ''heavy'' agir gramaj arayanı hedefler, mens''ten ayirilarak niyet genisletildi."}, {"tag": "Everyday Bracelet", "reason": "Kullanim slotu: gunluk tasima niyetini yakalar."}, {"tag": "Statement Bracelet", "reason": "Tarz/kullanim slotu: agir curb parcasi statement urun; farkli niyet."}, {"tag": "Unisex Gold Bracelet", "reason": "Kitle genisletme: curb/cuban unisex; mens+gift for him erkek egilimini dengeler."}]'::jsonb,'13 tag''in tamami \"Bracelet\" ile bitip Gold/14K/Link koklerini tekrarliyor; hediye-kullanim-kitle slotlari bos, iki genis tek-niyet tag (Gold Bracelet, 14K Bracelet) slot israf ediyor.','Standart arketip: dengeli temizlik. Asiri kok tekrari (Gold/14K/Link) ve iki genis tek-niyet tag budandi; cekirdek yuksek-donusum tag''leri (Gold Curb, Solid Gold, 14K Gold, Curb Chain) korundu. Bos niyet slotlari dolduruldu: stil (Miami Cuban, Cuban Link Chain, Statement), kitle (Mens, Unisex), hediye (Gift For Him), kullanim (Everyday), alici dili (Real Gold, Heavy). Tum tag''ler bracelet urunuyle relevant, tip celiskisi yok; ''Cuban Link Chain'' urun gercek bir zincir bileklik oldugu icin mesru ve bracelet monotonlugunu kirar. Hepsi <=20 karakter, tamami cok-kelimeli.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1862675181,'14K Solid Gold Ice Out Chain | Two Tone Diamond Cut Cylinder Link','necklace','standart',ARRAY['ice out chain','14K Bracelet','GOLD CHAIN','ICEOUT CHAIN','TWO TONE CHAIN','ICE CHAIN','ICED CHAIN','SOLID GOLD CHAIN','DIAMOND CUT CHAIN','14K SOLID CHAIN','14K GOLD CHAIN','REAL GOLD CHAIN','14K CHAIN']::text[],ARRAY['ice out chain','two tone gold chain','diamond cut chain','solid gold chain','14k gold chain','cylinder link chain','iced out necklace','mens gold necklace','gold chain for him','hip hop jewelry','layering necklace','statement necklace','real gold jewelry']::text[],'[{"tag": "14K Bracelet", "reason": "Tip celiskisi: listing necklace/chain (baslik: Chain, Cylinder Link); bracelet alicisini yaniltir ve slot israfi."}, {"tag": "ICEOUT CHAIN", "reason": "''ice out chain'' ile ayni arama; birebir varyant tekrari."}, {"tag": "ICE CHAIN", "reason": "Iced-out kokunun 3. kopyasi; tek varyant yeter."}, {"tag": "ICED CHAIN", "reason": "Iced-out kokunun 4. kopyasi; ''iced out necklace'' ile korundu."}, {"tag": "GOLD CHAIN", "reason": "Tek-kelimeye yakin genel terim; long-tail varyantlar zaten kapsiyor."}, {"tag": "TWO TONE CHAIN", "reason": "''two tone gold chain''e yukseltildi (gold niyeti eklendi)."}, {"tag": "14K SOLID CHAIN", "reason": "''solid gold chain'' + ''14k gold chain'' ile cakisan 14K/solid tekrari."}, {"tag": "REAL GOLD CHAIN", "reason": "''real gold jewelry''ye donusturuldu; chain koku doygunlugu azaltildi."}, {"tag": "14K CHAIN", "reason": "''14k gold chain'' varken fazlalik 14K tekrari."}]'::jsonb,'[{"tag": "cylinder link chain", "reason": "Basliktaki asil ayirt edici ozellik (Cylinder Link) hic tag''de yoktu; dusuk rekabetli long-tail."}, {"tag": "mens gold necklace", "reason": "Kitle slotu (mens) + necklace formu; chain koku doygunlugunu dengeler."}, {"tag": "gold chain for him", "reason": "Hediye/kitle niyeti (gift for him) — bos slot dolduruldu."}, {"tag": "hip hop jewelry", "reason": "Stil slotu; iced-out estetiginin dogal aramasi."}, {"tag": "layering necklace", "reason": "Kullanim slotu; katmanlama arayan alici trafigi."}, {"tag": "statement necklace", "reason": "Kullanim/tarz slotu; iri iced-out parca icin niyet eslesmesi."}, {"tag": "real gold jewelry", "reason": "Alici dili (real gold) jewelry formunda; chain doygunlugunu bozar."}, {"tag": "iced out necklace", "reason": "Iced-out niyetini necklace formuyla korur; 4 chain-varyanti yerine tek temiz slot."}]'::jsonb,'"chain" koku ve iced-out/14K varyantlari ~10 slotu ezberden tekrar ederken tip-celiskili bracelet tag''i var ve hediye/stil/kitle/kullanim slotlari tamamen bos.','Chain koku 6+ tekrardan 6 anlamli long-tail''e indirildi (ice out/two tone/diamond cut/solid gold/14k/cylinder link + for him), necklace ve jewelry formlariyla dengelendi. Iced-out 4 kopyadan 2''ye (ice out chain + iced out necklace) dusuruldu. Tip-celiskili bracelet cikarildi. Bos hediye (for him), kitle (mens), stil (hip hop), kullanim (layering/statement) slotlari acildi. Tum tag''ler cok-kelimeli long-tail ve <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1726181962,'10K Gold Teddy Bear Bracelet | Diamond Cut Charm, 7.5"','bracelet','standart',ARRAY['Teddy Bear Bracelet','10k Gold Bracelet','HUGS and KISSES','Cz Diamond Bracelet','Gold Bracelet','Real Gold Bracelet','Bear Bracelet','Gold Bear Bracelet','Gold Teddy Bear','XOXO Bracelet','Teddy bracelet','Link Bracelet','10K Bracelet']::text[],ARRAY['Teddy Bear Bracelet','10k Gold Bracelet','Cz Diamond Bracelet','Real Gold Bracelet','Gold Charm Bracelet','Womens Gold Bracelet','Gift For Her','Mothers Day Gift','Valentines Day Gift','Cute Animal Bracelet','Dainty Gold Bracelet','Bear Charm Bracelet','Everyday Bracelet']::text[],'[{"tag": "HUGS and KISSES", "reason": "Tip-çelişkisi: XOXO/hugs-kisses ayrı bir motif; teddy bear charm ürünüyle alakasız, yanıltıcı trafik çeker."}, {"tag": "XOXO Bracelet", "reason": "Tip-çelişkisi: XOXO harf/motif ürünü değil bu; teddy bear ile aynı slotu boşa harcar."}, {"tag": "Gold Bracelet", "reason": "Tek-modifierli genel; ''10k Gold Bracelet'' ve ''Real Gold Bracelet'' bunu zaten kapsar, slot israfı."}, {"tag": "Bear Bracelet", "reason": "''Teddy Bear Bracelet'' varyantı; aynı kök tekrarı, Etsy zaten kombinler."}, {"tag": "Gold Bear Bracelet", "reason": "bear+gold+bracelet kökü 5 kez dönüyor; redundant slot israfı."}, {"tag": "Gold Teddy Bear", "reason": "Ürün tipi (''bracelet'') yok, sadece motifi tekrarlar; başlıkta baskın kelime zaten var."}, {"tag": "Teddy bracelet", "reason": "''Teddy Bear Bracelet'' alt kümesi; birebir kök tekrarı."}, {"tag": "Link Bracelet", "reason": "Relevance belirsiz: ürün charm bileklik, link/zincir stili baskın değil; slot daha güçlü niyetlere gider."}, {"tag": "10K Bracelet", "reason": "''10k Gold Bracelet'' ile aynı; kısa ve redundant, slot israfı."}]'::jsonb,'[{"tag": "Gold Charm Bracelet", "reason": "Stil slotu: başlık ''Charm'' diyor; alıcının aradığı ürün-kategorisi long-tail."}, {"tag": "Womens Gold Bracelet", "reason": "Kitle slotu: 7.5\" kadın bedeni; hedef alıcıyı adresler (tamamen eksikti)."}, {"tag": "Gift For Her", "reason": "Hediye niyeti: sevimli teddy bear = klasik hediye; en yüksek dönüşümlü niyet slotu eksikti."}, {"tag": "Mothers Day Gift", "reason": "Hediye/mevsim slotu: yüksek hacimli sezonsal arama."}, {"tag": "Valentines Day Gift", "reason": "Hediye/mevsim slotu: teddy bear temasıyla birebir örtüşen güçlü hediye niyeti."}, {"tag": "Cute Animal Bracelet", "reason": "Stil/tema slotu: motifi kategori-dışı arayıcıya açar (bear demeden ''cute animal'')."}, {"tag": "Dainty Gold Bracelet", "reason": "Stil slotu: ince/minimal altın takı yüksek hacimli aramadır, ürün estetiğine uygun."}, {"tag": "Bear Charm Bracelet", "reason": "Charm+bear kombinasyonu; ''charm bracelet'' arayan alıcıyı motifle eşler, distinct."}, {"tag": "Everyday Bracelet", "reason": "Kullanım slotu: günlük takılabilir konumlaması, farklı bir niyet dilini yakalar."}]'::jsonb,'Aşırı redundancy (5 ayrı bear+bracelet, 4 ayrı gold+bracelet varyantı slot israfı) ve XOXO/HUGS motif tag''leri teddy bear ürünüyle çelişirken hediye/stil/kitle slotları tamamen boş.','Mevcut set 13 slotun 9''unu bear/gold/bracelet kök tekrarına ve alakasız XOXO/HUGS motifine harcıyordu; kitle, hediye, stil ve kullanım niyet slotları tamamen boştu. Baskın kelime (''teddy bear'', ''gold'', ''bracelet'') başlıkta zaten güçlü olduğundan tekrar yerine slotları genişlettim: 4 güçlü/ilgili tag korundu (Teddy Bear Bracelet birincil; 10k+Real Gold buyer dili; Cz Diamond başlıktaki ''Diamond Cut'' özelliğiyle eşleşiyor), 9 slot hediye (For Her, Mothers/Valentines), kitle (Womens), stil (Charm, Dainty, Cute Animal, Bear Charm) ve kullanım (Everyday) niyetlerine yeniden dağıtıldı. Tüm tag''ler çok-kelimeli long-tail ve <=20 karakter; birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1865969006,'10K Solid Yellow Gold Wedding Band – Minimalist Unisex Ring','ring','standart',ARRAY['10k wedding band','yellow gold ring','real gold band','solid gold ring','gold wedding ring','dainty gold band','mens wedding band','womens wedding ring','thin gold ring','stackable gold ring','minimalist gold ring','anniversary band','gold ring']::text[],ARRAY['10k wedding band','mens wedding band','womens wedding ring','real gold band','dainty gold band','stackable gold ring','anniversary band','comfort fit band','plain wedding band','unisex gold ring','everyday gold band','wedding gift for him','his and hers rings']::text[],'[{"tag": "yellow gold ring", "reason": "Renk zaten baslikta+malzeme niteliginde; ''gold ring'' koku asiri temsil ediliyordu, bu slot bosa gidiyordu."}, {"tag": "solid gold ring", "reason": "''Solid'' baslikta var, ''real gold band'' ile ayni niyet; kok redundansi."}, {"tag": "gold wedding ring", "reason": "''10k wedding band'' / wedding band varyantlariyla birebir cakisan kok tekrari."}, {"tag": "thin gold ring", "reason": "''dainty gold band'' ile ayni ince/kucuk aciyi tekrarliyor."}, {"tag": "minimalist gold ring", "reason": "''Minimalist'' baslikta baskin; niteligi bosuna tekrarlamak slot israfi."}, {"tag": "gold ring", "reason": "Cok genis, tek-kavramli en zayif slot; long-tail degil."}]'::jsonb,'[{"tag": "comfort fit band", "reason": "Fit/stil slotu — dugun bandi aramalarinda yuksek niyetli ''comfort fit'' terimi eksikti."}, {"tag": "plain wedding band", "reason": "Sade stil slotu; gelin/damat aramalarinda yaygin ''plain band'' niyeti."}, {"tag": "unisex gold ring", "reason": "Kitle slotu — baslikta ''Unisex'' var ama hicbir tag''de etiketlenmemis."}, {"tag": "everyday gold band", "reason": "Kullanim slotu — gunluk takilabilir niyet tamamen eksikti."}, {"tag": "wedding gift for him", "reason": "Hediye niyet slotu (gift for him) yoktu; erkek dugun bandi hediye aramasi."}, {"tag": "his and hers rings", "reason": "Ciftler/hediye + unisex acisini birlestiren long-tail; kitle+hediye slotunu genisletir."}]'::jsonb,'"gold ring/band" koku 7+ varyantla tekrarlanip slot israfi yapiyor; hediye, kullanim ve unisex kitle niyet slotlari bos.','Urun gercek bir dugun bandi/ring oldugu icin ''band'' ve ''ring'' mesru; relevance korundu. Asil sorun tip-celiskisi degil, asiri redundansiydi: 13 tag''in 7''si ''gold ring/band'' koku etrafinda donuyor ve baslikte zaten baskin olan ''solid'', ''yellow gold'', ''minimalist'' niteliklerini bosuna tekrarliyordu. Bu koku tek guclu varyanta indirip (dainty gold band, stackable gold ring) bosalan slotlari niyet aileleriyle doldurdum: fit/stil (comfort fit, plain band), kullanim (everyday), kitle (unisex — baslikta var, tag''de yoktu), hediye (gift for him, his and hers). Guclu kitle keeper''lari (mens/womens wedding band) ve karat-spesifik ''10k wedding band'' korundu. Tum tag''ler cok-kelimeli long-tail, hepsi <=20 karakter, birebir tekrar yok.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1848404088,'14K Gold Jesus Crucifix Pendant | Two-Tone Religious Jewelry','pendant','standart',ARRAY['Cross Pendant','Gold Jesus Pendant','Jesus Necklace','Cross Necklace','Crucifix Pendant','Religious Pendant','Religious Necklace','Religious Jewelry','Gold Cross Pendant','14K GOLD PENDANT','14K GOLD NECKLACE','14K PENDANT','14K CROSS PENDANT']::text[],ARRAY['Crucifix Pendant','Gold Jesus Pendant','Gold Cross Pendant','Jesus Necklace','Religious Jewelry','Two Tone Pendant','Gold Cross for Men','Mens Gold Necklace','Real Gold Crucifix','Religious Gift','Gift for Him','14K Gold Cross','Christian Jewelry']::text[],'[{"tag": "Cross Pendant", "reason": "Tek basina zayif, ''Gold Cross Pendant'' + ''14K Gold Cross'' zaten kok kapsiyor; slot israfi."}, {"tag": "Cross Necklace", "reason": "necklace kokunu 4 varyanttan birine indirdik; ''Jesus Necklace'' + ''Mens Gold Necklace'' daha yuksek niyet tasiyor."}, {"tag": "Religious Pendant", "reason": "''Crucifix Pendant'' + ''Religious Jewelry'' ile ortusuyor; religious+pendant koku fazla tekrar."}, {"tag": "Religious Necklace", "reason": "Ucuncu religious varyanti ve dorduncu necklace varyanti; net kombinasyon deger katmiyor."}, {"tag": "14K GOLD PENDANT", "reason": "14K+pendant koku tekrarli; tek 14K slotunu ''K13K Gold Cross''a topladik."}, {"tag": "14K GOLD NECKLACE", "reason": "Hem 14K hem necklace kokunun gereksiz dorduncu tekrari."}, {"tag": "14K PENDANT", "reason": "Neredeyse iki kelimelik dolgu; ayni bilgi diger 14K/pendant taglerinde var."}, {"tag": "14K CROSS PENDANT", "reason": "''Gold Cross Pendant'' + ''14K Gold Cross'' ile birebir cakisiyor; slot israfi."}]'::jsonb,'[{"tag": "Two Tone Pendant", "reason": "Baslikta ''Two-Tone'' farklilastiricisi tag''de hic yoktu; benzersiz arama niyeti."}, {"tag": "Gold Cross for Men", "reason": "Kitle slotu: crucifix/hac takisi erkek aliciya kayar, hedefli long-tail."}, {"tag": "Mens Gold Necklace", "reason": "Kitle + mesru necklace niyeti (pendant zincirle takilir); erkek altin zincir aramasini yakalar."}, {"tag": "Real Gold Crucifix", "reason": "Alici dili ''real gold'' (malzeme 14K REAL GOLD) + crucifix kombinasyonu."}, {"tag": "Religious Gift", "reason": "Eksik hediye slotu; dini takı guclu hediye niyeti tasir."}, {"tag": "Gift for Him", "reason": "Hediye + kitle slotu; babalar gunu/dogum gunu erkek hediye aramasi."}, {"tag": "14K Gold Cross", "reason": "Tek konsolide 14K material slotu; ayara duyarli aliciyi hac tipiyle birlestirir."}, {"tag": "Christian Jewelry", "reason": "Kategori/kitle genislemesi; ''religious'' disinda ayri arama havuzunu acar."}]'::jsonb,'Asiri redundancy: ''pendant'' 8, ''cross'' 4, ''14K'' 4, ''necklace'' 4 kez tekrarlanip slot israf ediyor; buna karsilik hediye/kitle(mens)/stil(two-tone) niyet slotlari tamamen eksik.','Baslik ve urun tipi ''pendant'' olsa da crucifix pendant zincirle takildigindan sinirli ''necklace'' niyeti mesru; korlemesine silmeyip 4 necklace varyantini 2 yuksek-niyetli olana (Jesus Necklace, Mens Gold Necklace) indirdim. Ana temizlik: pendant/cross/14K/necklace koklerinin asiri tekrarini kirmak. Bosalan slotlari urun gercegiyle celiskisiz sekilde hediye (Religious Gift, Gift for Him), kitle (Gold Cross for Men, Mens Gold Necklace, Christian Jewelry), stil (Two Tone Pendant) ve alici dili (Real Gold Crucifix) ile doldurdum. 5 guclu orijinal korundu, 8 zayif/redundant dusuruldu, 8 niyet-slotu eklendi. Hepsi cok-kelimeli, <=20 karakter, birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1767404547,'10K Solid Gold Jesus Pendant | Two-Tone Religious Necklace','pendant','standart',ARRAY['Jesus head necklace','jesus head pendant','10K Gold necklace','10K Gold Pendant','Solid Gold pendant','Solid Gold Necklace','10K Solid Gold','10K White Necklace','White Gold Necklace','Large Mens pendant','10K Solid Necklace','Gold Necklace','Gold Pendant']::text[],ARRAY['Jesus head pendant','Jesus piece necklace','religious necklace','two tone pendant','mens gold necklace','gold gift for him','yellow gold pendant','solid gold pendant','hip hop jewelry','large mens pendant','10K gold necklace','statement pendant','christian jewelry']::text[],'[{"tag": "Jesus head necklace", "reason": "Jesus head pendant ile birebir cakisan varyant; ''necklace'' zaten 4 tagta korunuyor, slot israfi."}, {"tag": "10K Gold Pendant", "reason": "10K+pendant kombinasyonu ''10K gold necklace'' + ''solid gold pendant'' ile zaten kapsaniyor; Etsy kelimeleri kendisi kombinler."}, {"tag": "Solid Gold Necklace", "reason": "Fazlalik necklace+solid varyanti; ''solid gold pendant'' + ''religious necklace'' kombinasyonu ayni kokleri karsiliyor."}, {"tag": "10K Solid Gold", "reason": "Baslikta zaten var (10K Solid Gold), tek-kok tekrar; niyet slotu getirmiyor."}, {"tag": "10K White Necklace", "reason": "Malzeme Yellow Gold; beyaz altin urun gercegiyle zayif ortusuyor. Two-tone niyeti ''two tone pendant'' ile daha dogru karsilaniyor."}, {"tag": "White Gold Necklace", "reason": "Ayni beyaz-altin relevance sorunu; malzeme yalnizca sari altin, iki beyaz-altin tagi tutmak riskli ve gereksiz."}, {"tag": "10K Solid Necklace", "reason": "Ayni 10K/solid/necklace koklerinin ucuncu tekrari; hicbir yeni niyet getirmiyor."}, {"tag": "Gold Necklace", "reason": "Cok genis, tek-kelimeye yakin dusuk deger; baslikta zaten var, uzun-kuyruk degil."}, {"tag": "Gold Pendant", "reason": "Cok genis ve baslikta mevcut; long-tail olmayan doygun terim, spesifik varyantlar bunu kapsar."}]'::jsonb,'[{"tag": "Jesus piece necklace", "reason": "Hip-hop takida en yuksek trafikli aranan terim (''Jesus piece''); zincirle satilan pendant''ta ''necklace'' mesru."}, {"tag": "religious necklace", "reason": "Baslikta gecen ''Religious Necklace'' ana niyeti tagta hic yoktu; eksik slot."}, {"tag": "two tone pendant", "reason": "Baslikta ''Two-Tone'' var; stil slotu, riskli beyaz-altin taglarinin yerine urun gercegine uygun ikame."}, {"tag": "mens gold necklace", "reason": "Kitle (erkek) + necklace niyeti; alici dilinde arama."}, {"tag": "gold gift for him", "reason": "Hediye slotu tamamen bostu (gift for him)."}, {"tag": "yellow gold pendant", "reason": "Gercek malzeme (Yellow Gold) spesifik olarak taginmiyordu."}, {"tag": "hip hop jewelry", "reason": "Tarz slotu; Jesus piece urunlerinin dominant tarz konteksti."}, {"tag": "statement pendant", "reason": "Kullanim slotu; ''Large Mens'' urunu icin buyuk/statement niyeti."}, {"tag": "christian jewelry", "reason": "Dini+hediye kesisimi; genis alici niyeti, tek beyaz-altin varyantinin yerine deger katiyor."}]'::jsonb,'13 tag''in 7''si "necklace" ve neredeyse hepsi "10K/Solid/Gold" kokunu tekrarliyor (agir slot israfi); hediye/stil/kullanim/hip-hop niyet slotlari ve "Jesus piece" gibi ana arama terimi tamamen bos.','Standart strateji: agir redundancy temizlendi (7 necklace -> 4 dengeli necklace, 10K/solid/gold kok tekrarlari teke indirildi) ve acilan slotlar niyet cesitliligiyle dolduruldu. Korunanlar: Jesus head pendant (cekirdek), 10K gold necklace, solid gold pendant, large mens pendant. Eklenen niyet slotlari: hediye (gold gift for him), stil (two tone pendant, hip hop jewelry), kullanim (statement pendant), kitle (mens gold necklace), hip-hop ana terimi (Jesus piece necklace), dini/hediye (religious necklace, christian jewelry) ve gercek malzeme (yellow gold pendant). Relevance korundu: pendant zincirle satildigi icin ''necklace'' silinmedi, korlemesine budama yapilmadi; ancak beyaz-altin taglari malzeme (yalniz Yellow Gold) ile zayif ortustugu icin two-tone ile ikame edildi. Tum taglar 2-3 kelime long-tail; tek-kelime cogunlugu yok; birebir tekrar yok; hepsi <=20 karakter (en uzun ''Jesus piece necklace'' = 20).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1436080231,'14K Solid Gold Diamond Panther Pendant, Emerald Eye Charm with Miami Cuban Chain','pendant','standart',ARRAY['Miami Cuban Chain','Miami Link Chain','Cuban Chain','Cuban Link Chain','Miami Cuban','Emerald Eye Pendant','Leopard Charm','Tiger Eye Pendant','Panther Charm','Panther Pendant','14K Gold Pendant','Tiger Pendant','14K Gold men Pendant']::text[],ARRAY['Miami Cuban Chain','Panther Pendant','Emerald Eye Pendant','Diamond Panther','Gold Panther Charm','14K Solid Gold','Mens Gold Pendant','Gold Chain for Men','Gift for Him','Hip Hop Jewelry','Real Gold Necklace','Statement Pendant','Luxury Gold Charm']::text[],'[{"tag": "Miami Link Chain", "reason": "Zincir kokunun 5 varyantindan biri; Miami Cuban Chain ile ayni niyet, slot israfi (Etsy kelimeleri kendi kombinler)."}, {"tag": "Cuban Chain", "reason": "Ayni zincir koku tekrari; Miami Cuban Chain daha spesifik varyantla kapsandi."}, {"tag": "Cuban Link Chain", "reason": "Ayni zincir koku tekrari; 4. Cuban/Miami slotu, redundancy."}, {"tag": "Miami Cuban", "reason": "Miami Cuban Chain''in eksik/kirpik kopyasi; birebir kok tekrari."}, {"tag": "Tiger Eye Pendant", "reason": "RELEVANCE CELISKISI: ''tiger eye'' bir tastir; urunde zumrut goz var, tiger-eye tasi aramasi alicyi yaniltir."}, {"tag": "Tiger Pendant", "reason": "Tip celiskisi: urun panther (panter); tiger arayan yanlis eslesir."}, {"tag": "Leopard Charm", "reason": "Tip celiskisi: urun panther; leopard farkli hayvan, kafa karisiklgi."}, {"tag": "14K Gold Pendant", "reason": "Baslikta baskin ''14K Gold Pendant'' zaten var; alici dili ''Solid Gold'' varyantiyla degistirildi."}, {"tag": "14K Gold men Pendant", "reason": "Bozuk dilbilgisi/kasa (''men'' kucuk); dogal ''Mens Gold Pendant'' ile degistirildi."}, {"tag": "Panther Charm", "reason": "Gold niteligiyle guclendirilerek ''Gold Panther Charm''e evrildi (slot geri kazanildi)."}]'::jsonb,'[{"tag": "Diamond Panther", "reason": "Baslikta gecen ana ozellik (''Diamond Panther''); yuksek niyetli long-tail."}, {"tag": "Gold Panther Charm", "reason": "Panther Charm''in gold nitelikli ust versiyonu; charm arayan kitleyi tutar."}, {"tag": "14K Solid Gold", "reason": "Alici dili ''solid gold'' — som altin arayan yuksek deger nitelemesi."}, {"tag": "Mens Gold Pendant", "reason": "Kitle slotu (erkek); bozuk ''14K Gold men'' yerine dogal ifade."}, {"tag": "Gold Chain for Men", "reason": "Alici dili + kitle; zincirle satilan urunde mesru, erkek aramasini yakalar."}, {"tag": "Gift for Him", "reason": "Eksik hediye niyet slotu — erkek hediyesi aramasi."}, {"tag": "Hip Hop Jewelry", "reason": "Stil slotu; Miami Cuban + panther urunun dogal hip-hop estetigi."}, {"tag": "Real Gold Necklace", "reason": "Alici dili ''real gold'' + zincirle satildigi icin ''necklace'' mesru (baslikta chain var)."}, {"tag": "Statement Pendant", "reason": "Kullanim slotu; iri panther kolye statement takisi olarak konumlanir."}, {"tag": "Luxury Gold Charm", "reason": "Luks/stil slotu; som altin + elmas urun icin premium niyet."}]'::jsonb,'5 tag zincir kokunde (Miami/Cuban varyantlari) israf edilirken 3 tag (Tiger Eye/Tiger/Leopard) urun gercegiyle celisiyor — bu panther + zumrut goz kolyesi tiger-eye tasi degil.','Orijinal set 13 slotun 5''ini tek zincir kokune (Miami/Cuban) ve 3''unu urunle celisen hayvan/tas etiketine (Tiger Eye tasi, Tiger, Leopard) harcamis — bu ikisi hem redundancy hem yanlis-eslesme. Yeni sette 1 guclu zincir etiketi (Miami Cuban Chain) tutuldu, celiskili etiketler atildi ve bosalan slotlar niyet eksenlerine dagitildi: kitle (Mens Gold Pendant, Gold Chain for Men), hediye (Gift for Him), stil (Hip Hop Jewelry, Luxury Gold Charm), kullanim (Statement Pendant), alici dili (14K Solid Gold, Real Gold Necklace). Urun gercegi korundu: panther + emerald eye + diamond + solid gold ekseninde. ''necklace'' etiketi baslikta zincir oldugu icin mesru. Tum 13 etiket <=20 karakter ve cok-kelimeli long-tail; birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1753363056,'10K Solid Gold Jesus Head Pendant | Two-Tone Men''s Necklace','pendant','standart',ARRAY['solid gold pendant','Jesus head pendant','white gold pendant','Large mens pendant','Jesus Pendant','10K gold pendant','Jesus head necklace','10K gold necklace','Miami Cuban Chain','Solid Gold Necklace','10k Gold chain','Gold Necklace','Gold Pendant']::text[],ARRAY['Jesus head pendant','two tone pendant','Miami Cuban Chain','mens gold necklace','10k solid gold','religious necklace','gold gift for him','christian jewelry','large mens pendant','Jesus piece chain','real gold pendant','hip hop jewelry','mens necklace gift']::text[],'[{"tag": "solid gold pendant", "reason": "''solid gold'' + ''pendant'' ayri ayri baska tag''lerde var; kok tekrari, slot israfi. ''10k solid gold'' karsiliyor."}, {"tag": "white gold pendant", "reason": "Baslik two-tone; malzeme listesi tamamen sari/10k altin. Salt ''white gold'' yaniltir; ''two tone pendant'' ile dogru ifade edildi."}, {"tag": "Jesus Pendant", "reason": "''Jesus head pendant'' ile ayni kokun daraltilmis birebir tekrari; slot israfi."}, {"tag": "10K gold pendant", "reason": "10k + pendant ucuncu kez; ''10k solid gold'' ve ''real gold pendant'' kombinasyon icin yeterli."}, {"tag": "Jesus head necklace", "reason": "''Jesus head pendant'' ile neredeyse birebir; Etsy iki kelimeyi zaten kombinler, slot israfi."}, {"tag": "10K gold necklace", "reason": "10k + necklace tekrari; ''mens gold necklace'' kitleli varyantla degistirildi."}, {"tag": "Solid Gold Necklace", "reason": "Gold necklace kokunun bir baska tekrari; deger katmiyor."}, {"tag": "10k Gold chain", "reason": "Chain zaten ''Miami Cuban Chain'' + ''Jesus piece chain'' ile kapsanmis; generic tekrar."}, {"tag": "Gold Necklace", "reason": "Cok genis/generic tek-eksenli terim; long-tail slotlar daha yuksek donusum getirir."}, {"tag": "Gold Pendant", "reason": "Cok genis generic; ''pendant'' zaten fazlasiyla tekrar edilmis, en zayifi elenmeli."}]'::jsonb,'[{"tag": "two tone pendant", "reason": "Baslikttaki ''Two-Tone'' stil niyetini yakalar; yaniltici ''white gold''un yerine dogru ifade."}, {"tag": "mens gold necklace", "reason": "Kitle (mens) + urun; baslik ''Men''s Necklace'' oldugu icin necklace mesru, alici dili."}, {"tag": "10k solid gold", "reason": "Malzeme+kalite tek slotta; ''real gold/solid gold'' alici arama dili."}, {"tag": "religious necklace", "reason": "Eksik dini niyet slotu; Jesus urunu icin yuksek alakali arama."}, {"tag": "gold gift for him", "reason": "Eksik hediye slotu; erkek aliciya yonelik yuksek donusumlu niyet."}, {"tag": "christian jewelry", "reason": "Dini/stil slotu genisletir; farkli arama kohortu (christian/catholic)."}, {"tag": "Jesus piece chain", "reason": "Hip-hop argosu ''Jesus piece'' bu urunun dogal arama terimi; stil+kullanim."}, {"tag": "real gold pendant", "reason": "Alici dili ''real gold''; pendant kokunu deger katarak korur."}, {"tag": "hip hop jewelry", "reason": "Miami Cuban + Jesus piece ile uyumlu stil/pazar slotu; yeni kohort."}, {"tag": "mens necklace gift", "reason": "Hediye + kitle birlesimi; erkek hediye aramasini yakalar."}]'::jsonb,'Slot israfi: 13 tag''in 7''si "pendant", 3''u "Jesus", 4''u "10k gold" varyanti; hediye/dini/hip-hop/kitle niyet slotlari tamamen bos ve conv %0.035 cok dusuk.','Ana sorun asiri redundancy''di: ''pendant'' 7, ''Jesus'' 4, ''10k gold'' 3 varyantla tekrarlanmis, hediye/dini/stil/hip-hop niyet slotlari sifirdi. Baslik ''Two-Tone Men''s Necklace'' dediginden necklace tag''leri tip-celiskisi DEGIL — ama 4 adet fazlaydi; birini (mens gold necklace) kitleli tutup gerisini eledim. Guclu cekirdegi (Jesus head pendant, Miami Cuban Chain, large mens pendant) korudum; bosalan slotlari hediye (gold gift for him, mens necklace gift), dini (religious necklace, christian jewelry), stil/hip-hop (Jesus piece chain, hip hop jewelry, two tone pendant) ve alici dili (10k solid gold, real gold pendant) ile doldurdum. Hepsi cok kelimeli long-tail, tek-kelime yok, birebir tekrar yok, her tag <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1806007852,'14K Real Rose Gold Box Chain Bracelet | Unisex','bracelet','standart',ARRAY['Box Chain Bracelet','14K Gold Bracelet','14K Bracelet','Gold Box Chain','14K Box Chain','Round Bracelet','Box Chain Gold','Box Bracelet Gold','14K Box Bracelet','Real Gold Bracelet','Gold Round Bracelet','Gold Bracelet','14k rose gold']::text[],ARRAY['Box Chain Bracelet','Rose Gold Bracelet','14K Real Gold','Solid Gold Bracelet','Mens Gold Bracelet','Womens Gold Bracelet','Gift for Him','Gift for Her','Stacking Bracelet','Everyday Bracelet','Minimalist Bracelet','Italian Box Chain','Unisex Bracelet']::text[],'[{"tag": "Round Bracelet", "reason": "Tip-celiskisi: box chain kare-baklali; ''round'' yaniltici, alakasiz trafik ceker"}, {"tag": "Gold Round Bracelet", "reason": "Ayni ''round'' celiskisi + redundant"}, {"tag": "14K Box Chain", "reason": "box chain koku 7 varyantla tekrarlaniyor, slot israfi"}, {"tag": "Gold Box Chain", "reason": "box chain koku tekrari, slot israfi"}, {"tag": "Box Chain Gold", "reason": "''Gold Box Chain''in kelime sirasi degistirilmis kopyasi; Etsy zaten kombinler"}, {"tag": "Box Bracelet Gold", "reason": "reorder kopya, ayni kokun bir baska dizilimi"}, {"tag": "14K Box Bracelet", "reason": "14k+box+bracelet redundant kombini"}, {"tag": "14K Bracelet", "reason": "Cok generic, tek-nitelikli; diger 14k tag''lariyla ortusuyor"}, {"tag": "14K Gold Bracelet", "reason": "mens/womens/solid gold bracelet varyantlariyla kok kapsandi"}, {"tag": "Gold Bracelet", "reason": "Fazla generic, long-tail degeri dusuk"}, {"tag": "Real Gold Bracelet", "reason": "''14K Real Gold'' + ''Solid Gold Bracelet'' ile alici dili korundu, kok tekrari cikarildi"}, {"tag": "14k rose gold", "reason": "Kavram korundu ama ''Rose Gold Bracelet'' olarak urun-noun ile long-tail''e cevrildi"}]'::jsonb,'[{"tag": "Rose Gold Bracelet", "reason": "Baslikta baskin olan rose gold neredeyse hic tag''lenmemis; ana farklilastirici"}, {"tag": "14K Real Gold", "reason": "Alici dili ''real gold'' — som altin arayan yuksek-niyet trafigi"}, {"tag": "Solid Gold Bracelet", "reason": "Malzeme ''solid gold''; guclu alici dili, plated''dan ayirir"}, {"tag": "Mens Gold Bracelet", "reason": "Kitle slotu (erkek); unisex urunde erkek aramasi genis"}, {"tag": "Womens Gold Bracelet", "reason": "Kitle slotu (kadin); unisex urunun ikinci yarisi"}, {"tag": "Gift for Him", "reason": "Hediye niyeti slotu tamamen eksikti"}, {"tag": "Gift for Her", "reason": "Hediye niyeti slotu; iki cinsiyete de hediye pazari"}, {"tag": "Stacking Bracelet", "reason": "Kullanim slotu; bilezikte layering/stacking arama niyeti"}, {"tag": "Everyday Bracelet", "reason": "Kullanim slotu; gunluk tasima niyeti"}, {"tag": "Minimalist Bracelet", "reason": "Stil/estetik slotu; box chain sade tarza uyar"}, {"tag": "Italian Box Chain", "reason": "Stil/isCilik slotu; box chain''de italyan zincir sinyali kalite algisi"}, {"tag": "Unisex Bracelet", "reason": "Baslikta ''Unisex'' var; hedeflenmeyen ucuncu kitle sinyali"}]'::jsonb,'13 tag''in 11''i "box chain / 14k / gold / bracelet" kokunun yeniden dizilmesi (slot israfi) ve "round bracelet" tip-celiskisi tasiyor; hediye/kitle/stil/kullanim niyet slotlari tamamen bos.','Mevcut sette 13 tag''in ~11''i box/chain/14k/gold/bracelet kokunun mikro-varyantlari; Etsy bu kelimeleri kendi kombinledigi icin bu tekrar net slot israfi. Ayrica ''Round Bracelet'' ve ''Gold Round Bracelet'' urun gercegiyle (box chain = kare baklali) celisiyor. Yeni set: (1) primary tipi tek guclu tag ile korur (Box Chain Bracelet), (2) baslikta baskin ama tag''lenmemis rose gold''u one cikarir, (3) alici dilini ekler (real gold, solid gold), (4) eksik niyet slotlarini doldurur — kitle (mens/womens/unisex), hediye (him/her), kullanim (stacking/everyday), stil (minimalist/italian). Hepsi cok-kelimeli long-tail, birebir tekrar yok, her tag <=20 karakter. Relevance korundu: ''necklace'' gibi tip-disi hicbir sey eklenmedi; tum tag''lar bilezik/zincir gercegiyle uyumlu.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1448825748,'14K Yellow Gold Baby Angel Pendant – CZ Stone Religious Charm','pendant','standart',ARRAY['14K Gold Pendant','Gold Cz Stone Charm','Gold Cz Pendant','Baby Angel Pendant','Two Tone Pendant','White Gold Pendant','Gold Angel Pendant','14K Angel Pendant','Cz Stone Pendant','Cubic zirconia Charm','Religious jewelry','Two-tone necklace','Real Gold Pendant']::text[],ARRAY['14K Gold Pendant','Baby Angel Pendant','CZ Stone Pendant','Real Gold Pendant','Yellow Gold Charm','Religious Jewelry','Guardian Angel Charm','Angel Necklace','Cubic Zirconia Charm','Baptism Gift','Christening Gift','Communion Gift','Gift for Her']::text[],'[{"tag": "Gold Cz Stone Charm", "reason": "CZ+charm kombinasyonu ''Cubic Zirconia Charm'' ve ''CZ Stone Pendant'' ile karsilaniyor; ''gold cz'' koku tekrari"}, {"tag": "Gold Cz Pendant", "reason": "''CZ Stone Pendant'' ile birebir ayni niyet; 4 kez tekrar eden cz+pendant kokunden biri"}, {"tag": "Two Tone Pendant", "reason": "Baslik ''14K Yellow Gold'' (tek ton) — two-tone urun gercegiyle celisiyor, yaniltici"}, {"tag": "White Gold Pendant", "reason": "Baslik Yellow Gold; white gold malzeme gercegiyle celisiyor"}, {"tag": "Gold Angel Pendant", "reason": "''angel pendant'' koku ''Baby Angel Pendant'' ile ortusuyor, ekstra deger yok"}, {"tag": "14K Angel Pendant", "reason": "14K ''14K Gold Pendant''te, angel+pendant zaten var; redundant"}, {"tag": "Two-tone necklace", "reason": "Two-tone yellow gold basligiyla celisiyor; necklace niyeti ''Angel Necklace'' ile daha temiz karsilaniyor"}]'::jsonb,'[{"tag": "Yellow Gold Charm", "reason": "Baslikta baskin ''yellow gold'' terimini charm slotuna tasiyip renk+urun sorgusunu yakalar"}, {"tag": "Guardian Angel Charm", "reason": "Stil/varyant slotu — ''guardian angel'' yuksek-hacimli dini melek aramasi"}, {"tag": "Angel Necklace", "reason": "Pendant zincirle satildigi icin necklace niyeti mesru; alici cogunlukla ''angel necklace'' arar"}, {"tag": "Baptism Gift", "reason": "Dini melek pendant icin en yuksek-niyet hediye/occasion sorgusu — hic yoktu"}, {"tag": "Christening Gift", "reason": "Vaftiz hediyesi — bebek melek + dini temayla dogrudan ortusen occasion slotu"}, {"tag": "Communion Gift", "reason": "Ilk komunyon hediyesi — dini takide guclu mevsimsel alici niyeti"}, {"tag": "Gift for Her", "reason": "Kitle/hediye slotu; genis alici niyetini (kadin/kiz alici) yakalar"}]'::jsonb,'"Pendant" 13 tag''in 9''unda tekrar ediyor (slot israfi) ve tek hediye/occasion slotu yok — oysa dini bebek-melek kolyesi baptism/christening/communion sorgularinda satar.','Baslik gercegi: 14K Yellow Gold, tek-ton, CZ tasli, dini bebek-melek pendant/charm. Iki temel sorun: (1) asiri redundancy — ''pendant'' 9/13, ''cz'' 4, ''angel'' 4 tagda; Etsy kelimeleri kendisi kombinledigi icin bu slot israfi. ''Pendant''i 4''e, ''cz/cubic''i 2 farkli yazima (cz vs cubic zirconia — ayri sorgular) dusurdum. (2) Tip-celiskisi: ''Two Tone Pendant'', ''White Gold Pendant'', ''Two-tone necklace'' — hepsi tek-ton yellow gold basligiyla celisiyor, temizlendi. Necklace niyetini korlemesine silmedim; pendant zincirle satildigindan ''Angel Necklace'' olarak mesru bicimde tuttum. Bosalan 7 slota en yuksek getirili niyetleri koydum: dini occasion hediyeleri (baptism/christening/communion), kitle (gift for her), stil (guardian angel), renk (yellow gold charm). Tum taglar cok-kelimeli long-tail ve <=20 karakter (en uzun ''Guardian Angel Charm'' ve ''Cubic Zirconia Charm'' = 20).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1205110402,'10K Gold Small Hoop Earrings | Shiny Polished Finish','earring','standart',ARRAY['Hoop Earrings','Gold Hoop Earrings','Real Gold Earrings','Gold Earrings','Gold Hoop','Small Hoop Earrings','10K Gold Earrings','Plain Hoop Earrings','Gold Plain Hoop','Gold Plain Earrings','Gift for Mom','Mother''s Day','Shiny Hoop Earrings']::text[],ARRAY['Gold Hoop Earrings','Small Hoop Earrings','Real Gold Earrings','10K Gold Earrings','Shiny Hoop Earrings','Solid Gold Hoops','Dainty Earrings','Minimalist Hoops','Everyday Earrings','Womens Hoop Earrings','Mother''s Day','Gift for Her','Second Hole Earrings']::text[],'[{"tag": "Hoop Earrings", "reason": "Tek modifiersiz genis kok; ''Gold Hoop Earrings'' tarafindan yutuluyor, slot israfi."}, {"tag": "Gold Earrings", "reason": "Cok genis/rekabetci; daha spesifik real/10K/small tag''leri zaten kapsiyor."}, {"tag": "Gold Hoop", "reason": "Eksik ifade ve ''Gold Hoop Earrings'' ile birebir cakisan kok tekrari."}, {"tag": "Plain Hoop Earrings", "reason": "''Plain'' ucleme redundancy; ayrica title ''Shiny Polished'' ile celisiyor, finish tag''leriyle degistirildi."}, {"tag": "Gold Plain Hoop", "reason": "Plain kok tekrari + eksik ifade; sifir ek niyet."}, {"tag": "Gold Plain Earrings", "reason": "Ayni plain kokunun ucuncu varyanti; net slot israfi."}, {"tag": "Gift for Mom", "reason": "''Mother''s Day'' ile ayni niyeti dublike ediyor; daha genis ''Gift for Her'' ile degistirildi."}]'::jsonb,'[{"tag": "Solid Gold Hoops", "reason": "Alici dili (''solid gold'') + distinct hoops varyanti; som altin arayan yuksek niyetli alici."}, {"tag": "Dainty Earrings", "reason": "Kucuk/zarif stilini hoop-kok tekrari yapmadan yakalar; non-hoop kelime cesitliligi."}, {"tag": "Minimalist Hoops", "reason": "Stil slotu (minimalist) — small polished hoop icin dogal eslesme."}, {"tag": "Everyday Earlings icin kullanim", "reason": "Kullanim slotu: gunluk takilan kucuk hoop niyeti."}, {"tag": "Womens Hoop Earrings", "reason": "Kitle slotu (kadin) tamamen eksikti; genis arama hacmi."}, {"tag": "Gift for Her", "reason": "Hediye niyetini Mom disina genisletir; kadin aliciya genel hediye."}, {"tag": "Second Hole Earrings", "reason": "Kucuk hoop icin gercek kullanim/niyet aramasi (ikinci piercing); non-hoop cesitlilik."}]'::jsonb,'Uc "plain" varyanti + dort genis gold/hoop tag ayni koku tekrar edip slotlari israf ediyor; kitle, kullanim ve genis hediye niyet slotlari tamamen bos.','Standart arketip icin dengeli temizlik: 6 iyi tag korundu (core hoop long-tail + real/10K attribute + shiny finish + Mother''s Day). Israf eden 7 tag cikarildi — 3 ''plain'' varyanti (title''a da aykiri), 3 genis/eksik gold-hoop kok tekrari, 1 dublike hediye. Yerine 7 niyet slotu eklendi: alici dili (solid gold), stil (dainty, minimalist), kullanim (everyday, second hole), kitle (womens), genis hediye (gift for her). Tum tag''ler cok-kelimeli ve <=20 karakter; hoop-kok kullanimi 6''ya dusuruldu ve her biri distinct modifier tasiyor (kor tekrar degil).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1448764844,'14K Gold CZ Diamond Elephant Pendant, Good Luck Charm','pendant','standart',ARRAY['Elephant Pendant','Elephant Charm','Gold Elephant Charm','14k Gold Elephant','Gold Elephant','Good Luck Charm','Good Luck Pendant','Real Gold Charm','Real Gold Pendant','Cubic Zirconia Charm','Gold Cz Pendant','14K Gold Pendant','Solid Gold Charm']::text[],ARRAY['Elephant Pendant','Good Luck Charm','Gold Elephant Charm','Elephant Necklace','14K Gold Pendant','Cubic Zirconia Charm','Gift For Her','Lucky Elephant Gift','Animal Jewelry','Real Gold Necklace','Solid Gold Charm','Good Luck Gift','Minimalist Necklace']::text[],'[{"tag": "Elephant Charm", "reason": "Elephant Pendant + Gold Elephant Charm ile ayni kok; slot israfi"}, {"tag": "14k Gold Elephant", "reason": "gold+elephant kombosu Gold Elephant Charm''da mevcut; yarim ifade"}, {"tag": "Gold Elephant", "reason": "generik, iki kelimesi de digerlerinde var; ayristirici deger yok"}, {"tag": "Good Luck Pendant", "reason": "Good Luck Charm ile ayni kok; slot hediyeye kaydirildi"}, {"tag": "Real Gold Charm", "reason": "Real Gold Necklace + Solid Gold Charm ile ortusuyor"}, {"tag": "Real Gold Pendant", "reason": "real gold niyeti Real Gold Necklace''da karsilaniyor; fazlalik"}, {"tag": "Gold Cz Pendant", "reason": "CZ zaten Cubic Zirconia Charm + 14K Gold Pendant''ta; ucuncu tekrar gereksiz"}]'::jsonb,'[{"tag": "Elephant Necklace", "reason": "alicilar pendant''i ''necklace'' olarak ariyor; giyim niyeti (mesru pendant necklace)"}, {"tag": "Gift For Her", "reason": "kitle+hediye slotu; mevcut sette hic hediye tag''i yoktu"}, {"tag": "Lucky Elephant Gift", "reason": "sembol+hediye long-tail; fil = ugur, guclu hediye niyeti"}, {"tag": "Animal Jewelry", "reason": "kategori/stil genislemesi; yeni kesif trafigi"}, {"tag": "Real Gold Necklace", "reason": "alici dili ''real gold'' + necklace giyim niyeti"}, {"tag": "Good Luck Gift", "reason": "tema+hediye; ugur takisinin ana satin alma motivasyonu"}, {"tag": "Minimalist Necklace", "reason": "stil slotu; ince fil kolyesi minimalist alici segmentine oturur"}]'::jsonb,'"Elephant" 5 tag''te, "charm/pendant/gold" kökleri tekrar tekrar dönüyor; bu redundancy hediye/kitle/stil niyet slotlarını komple boğmuş (0 hediye tag''i).','Standart arketip: relevance korunarak redundancy temizlendi. Orijinalde 5 ''elephant'', tekrarli ''gold/charm/pendant'' kokleri 13 slotu boguyor ve hic hediye/kitle/stil tag''i yoktu. Fil = ugur sembolu, yani urun dogal bir hediye kalemi; bu yuzden 3 hediye niyeti (Gift For Her, Lucky Elephant Gift, Good Luck Gift), 1 kitle, 2 stil/kategori (Animal Jewelry, Minimalist Necklace) ve ''necklace'' giyim varyantlari eklendi. 6 en guclu ilgili anchor korundu (Elephant Pendant, Good Luck Charm, Gold Elephant Charm, 14K Gold Pendant, Cubic Zirconia Charm, Solid Gold Charm). Hepsi cok-kelimeli, birebir tekrar yok, her tag <=20 karakter. conv %0.40 dusuk degil ama hediye/kesif trafigi tamamen eksikti.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1729232602,'10K Solid Gold Men''s Jesus Ring | Nugget CZ Religious Ring','ring','standart',ARRAY['Nugget Ring','Nugget mens','Gold Nugget Ring','Nugget Rings','Gold Statement Rings','10K Gold Rings','10K Solid Gold Ring','Solid Gold Ring','10K Ring','Gold Ring','Jesus Head Ring','Jesus Nugget Ring','White Gold Ring']::text[],ARRAY['Gold Nugget Ring','Jesus Head Ring','10K Solid Gold Ring','Mens Nugget Ring','CZ Religious Ring','Mens Gold Ring','Real Gold Ring Men','Iced Out Ring','Hip Hop Jewelry','Statement Ring','Gift for Him','Boyfriend Gift','Everyday Ring']::text[],'[{"tag": "Nugget Ring", "reason": "Tek-kelime agirlikli, ''Gold Nugget Ring'' ile ayni kok; slot israfi."}, {"tag": "Nugget mens", "reason": "Kirik dil bilgisi; ''Mens Nugget Ring'' daha temiz long-tail ile degistirildi."}, {"tag": "Nugget Rings", "reason": "Etsy tekil/cogul ayirmaz; ''Nugget Ring'' ile birebir tekrar."}, {"tag": "Gold Statement Rings", "reason": "''Statement Ring'' olarak sadelesti; cogul+gold tekrari gereksiz."}, {"tag": "10K Gold Rings", "reason": "''10K Solid Gold Ring'' ile ayni kok, cogul varyant slot israfi."}, {"tag": "Solid Gold Ring", "reason": "''10K Solid Gold Ring'' zaten kapsiyor; zayif varyant."}, {"tag": "10K Ring", "reason": "Tek anlamli, dar; ''10K Solid Gold Ring'' ile ortusuyor."}, {"tag": "Gold Ring", "reason": "Cok genel, dusuk niyet; rekabette bogulur."}, {"tag": "Jesus Nugget Ring", "reason": "''Jesus Head Ring'' + ''Gold Nugget Ring'' zaten iki kavrami kapsiyor; ucuncu Jesus varyanti fazla."}, {"tag": "White Gold Ring", "reason": "TIP CELISKISI: urun 10K sari som altin (Yellow Gold); beyaz altin yanlis alici cekip donusumu dusurur."}]'::jsonb,'[{"tag": "Mens Nugget Ring", "reason": "Kitle (mens) + urun cekirdegini birlestiren temiz long-tail; kirik ''Nugget mens'' yerine."}, {"tag": "CZ Religious Ring", "reason": "Baslikdaki CZ + Religious nitelikleri tek slotta; dini+tas arayan niyeti yakalar."}, {"tag": "Mens Gold Ring", "reason": "Erkek alici niyet slotu; genel ''Gold Ring'' yerine kitle hedefli."}, {"tag": "Real Gold Ring Men", "reason": "Alici dili (''real gold'') + erkek kitlesi; som altin arayan yuksek niyet."}, {"tag": "Iced Out Ring", "reason": "CZ tasli urun icin stil/tarz slotu (iced out); yeni arama havuzu."}, {"tag": "Hip Hop Jewelry", "reason": "Tarz slotu; nugget+CZ+Jesus estetigi hip hop alicisina hitap eder."}, {"tag": "Statement Ring", "reason": "Kullanim/stil slotu; iri nugget yuzuk ''statement'' niyetiyle bulunur."}, {"tag": "Gift for Him", "reason": "Hediye niyet slotu (erkege hediye), tamamen eksikti."}, {"tag": "Boyfriend Gift", "reason": "Ikinci hediye slotu; sevgili/erkek arkadas hediyesi aramasi."}, {"tag": "Everyday Ring", "reason": "Kullanim slotu; gunluk takim niyetini kapsar."}]'::jsonb,'Slotlarin cogu redundansta bogulmus (4 ''nugget'' + 5 ''gold/10K'' varyanti) ve ''White Gold Ring'' urun gercegiyle (10K sari som altin) celisirken hediye/stil/kullanim niyet slotlari tamamen bos.','Iki gercek sorun: (1) asiri redundancy — 13 slotun 9''u ''nugget'' (4x) ve ''gold/10K'' (5x) koklerini tekrarliyordu, Etsy kombinlemesi bunu zaten yapiyor, slot israfi; (2) ''White Gold Ring'' urun tipiyle (10K sari som altin) celisiyor, relevance hatasi. Cozum: her kokten en guclu 1-2 long-tail varyanti tut (Gold Nugget Ring, 10K Solid Gold Ring, Jesus Head Ring, Mens Nugget Ring, CZ Religious Ring), kalan slotlari eksik niyet eksenlerine ac — kitle (Mens/Real Gold Ring Men), hediye (Gift for Him, Boyfriend Gift), stil/tarz (Iced Out Ring, Hip Hop Jewelry, Statement Ring), kullanim (Everyday Ring). Tum 13 tag cok-kelimeli, ≤20 karakter, birebir tekrarsiz; ''ring/religious/nugget'' relevans korunarak celiskili tag atildi.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1816642536,'14K White Gold Iced Out Bracelet | Diamond Cut Cylinder Chain','bracelet','standart',ARRAY['Gold Chain Bracelet','Chain link bracelet','Minimalist Bracelet','Two Tone Bracelet','ice out bracelet','Diamond Cut Bracelet','ice out chain','Gold Bracelet','Real Gold Bracelet','Solid Gold Bracelet','14K Bracelet','14K solid bracelet','14K Gold Bracelet']::text[],ARRAY['Iced Out Bracelet','White Gold Bracelet','Diamond Cut Bracelet','14K Gold Bracelet','Real Gold Bracelet','Gold Chain Bracelet','Mens Gold Bracelet','Gift For Him','Hip Hop Bracelet','Statement Bracelet','Cylinder Chain','Solid Gold Bracelet','Luxury Bracelet']::text[],'[{"tag": "Gold Bracelet", "reason": "Tek-kelimeye yakin ve nitelikli varyantlarca (14K/Real/White/Mens Gold Bracelet) kapsaniyor; slot israfi."}, {"tag": "14K Bracelet", "reason": "14K Gold Bracelet ile birebir cakisiyor; Etsy zaten kelimeleri kombinler."}, {"tag": "14K solid bracelet", "reason": "14K + Solid Gold Bracelet ayri ayri kapsandi; ucuncu 14K-solid tekrari redundant."}, {"tag": "ice out chain", "reason": "Yanlis yazim (ice vs iced) + urun bilezik, gevsek zincir degil; Iced Out Bracelet ile cakisiyor."}, {"tag": "Chain link bracelet", "reason": "Gold Chain Bracelet + baslik-ozel Cylinder Chain daha isabetli; genel ''chain link'' slot israfi."}, {"tag": "Minimalist Bracelet", "reason": "Ton celiskisi: iced out / diamond cut bir bling/statement parca, minimalist arayan aliciyi yanlis yonlendirir."}, {"tag": "Two Tone Bracelet", "reason": "Baslik ''14K White Gold'' tek-ton diyor; two tone urun gercegiyle celisir (relevance riski)."}, {"tag": "ice out bracelet", "reason": "Baslikteki dogru yazimla ''Iced Out Bracelet'' olarak degistirildi."}]'::jsonb,'[{"tag": "Iced Out Bracelet", "reason": "Baslikteki dogru yazim (''Iced Out''); ''ice out'' hatasini duzeltir, en guclu urun terimi."}, {"tag": "White Gold Bracelet", "reason": "Baslik ''White Gold'' diyor ama etiketlerde hic yoktu; kritik renk/malzeme aramasi."}, {"tag": "Mens Gold Bracelet", "reason": "Kitle slotu eksikti; iced out zincirler erkek alaraya yaslanir, yuksek hacimli buyer query."}, {"tag": "Gift For Him", "reason": "Hediye niyeti slotu tamamen eksikti; erkek altin bilezigi guclu hediye segmenti."}, {"tag": "Hip Hop Bracelet", "reason": "Stil slotu; iced out estetigi dogrudan hip hop aramalariyla eslesir."}, {"tag": "Statement Bracelet", "reason": "Kullanim/tarz slotu; diamond cut + iced out bir statement parcayla ortusur."}, {"tag": "Cylinder Chain", "reason": "Baslik-ozel zincir tipi (Cylinder Chain); yuksek ozgunluklu long-tail, hic etiketlenmemisti."}, {"tag": "Luxury Bracelet", "reason": "Konumlandirma/tarz slotu; som altin + bling premium alici dilini yakalar."}]'::jsonb,'13 slotun ~6''si "gold/14K bracelet" varyantiyla israf edilmisken baslikin en guclu niyet terimleri (White Gold, Cylinder Chain) hic etiketlenmemis ve hediye/kitle/stil slotlari tamamen eksik.','Standart arketip: asiri redundancy (6 gold/14K bracelet varyanti) temizlenip 5 nitelikli varyanta indirildi (White/14K/Real/Solid/Mens/Chain Gold Bracelet farkli buyer query''leri). Baslikin gomulu terimleri (White Gold, Cylinder Chain, Iced Out dogru yazim) etikete tasindi. Bos slotlar niyet cesitliligiyle dolduruldu: kitle (Mens), hediye (Gift For Him), stil (Hip Hop), kullanim (Statement), konum (Luxury). Ton celisen (Minimalist) ve gerceklikle celisen (Two Tone) etiketler cikarildi. 13 tag''in tumu cok-kelimeli ve <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1863059407,'14K White Gold Ice Out Chain | Diamond Cut Cylinder Link','necklace','standart',ARRAY['ice out chain','14K Bracelet','GOLD CHAIN','ICEOUT CHAIN','TWO TONE CHAIN','ICE CHAIN','ICED CHAIN','SOLID GOLD CHAIN','DIAMOND CUT CHAIN','14K SOLID CHAIN','14K GOLD CHAIN','REAL GOLD CHAIN','14K CHAIN']::text[],ARRAY['ice out chain','14k white gold chain','diamond cut chain','solid gold chain','real gold chain','cylinder link chain','mens gold necklace','unisex gold necklace','hip hop jewelry','iced out necklace','layering necklace','gift for him','statement necklace']::text[],'[{"tag": "14K Bracelet", "reason": "Tip-celiskisi: listing bir zincir/kolye, bilezik degil — alakasiz trafik ceker, relevance dusurur."}, {"tag": "TWO TONE CHAIN", "reason": "Renk celiskisi: baslik WHITE gold diyor, two-tone degil — yanlis beklenti/dusuk donusum."}, {"tag": "ICEOUT CHAIN", "reason": "''ice out chain'' ile pratik birebir tekrar (bosluksuz varyant) — slot israfi."}, {"tag": "ICE CHAIN", "reason": "Ayni ''ice'' kokunun 4. varyanti — Etsy zaten kombinler, redundant."}, {"tag": "ICED CHAIN", "reason": "Yine ''ice/iced'' redundansi; yerine ''iced out necklace'' ile necklace varyanti tutuldu."}, {"tag": "GOLD CHAIN", "reason": "Cok generic ve daha uzun long-tail''lere (14k white gold chain, mens gold necklace) gomulu — tek basina slot israfi."}, {"tag": "14K SOLID CHAIN", "reason": "''solid gold chain'' + ''14k white gold chain'' ile ortusuyor; ayni 14K-solid kombinasyonu tekrar."}, {"tag": "14K GOLD CHAIN", "reason": "''14k white gold chain'' bunu kapsiyor ve rengi de ekliyor — dar versiyonu gereksiz."}, {"tag": "14K CHAIN", "reason": "''14K...chain'' kokunun 4. tekrari, cok dar/generic — daha degerli niyet slotuna cevrildi."}]'::jsonb,'[{"tag": "14k white gold chain", "reason": "Rengi ilk kez dogru yakalar (white gold); eski tek renk ipucu yanlis ''two tone''du."}, {"tag": "cylinder link chain", "reason": "Basliktaki gercek link tipi (''Cylinder Link'') — benzersiz, dusuk-rekabet long-tail."}, {"tag": "mens gold necklace", "reason": "Kitle slotu (erkek) + necklace varyanti; ice out/hip hop erkek alicisina hitap eder."}, {"tag": "unisex gold necklace", "reason": "Kitleyi genisletir, tip-celiskisi olmadan kadin/unisex aramalarina acar."}, {"tag": "hip hop jewelry", "reason": "Stil slotu: ice out estetiginin ana arama niyeti — chain kokunu tekrarlamadan yeni kelime."}, {"tag": "iced out necklace", "reason": "''iced out'' + necklace niyetini tek slotta birlestirir; ice redundansini urun tipine yontar."}, {"tag": "layering necklace", "reason": "Kullanim slotu (katmanlama) — chain kelimesini tekrarlamayan taze arama hacmi."}, {"tag": "gift for him", "reason": "Hediye slotu: onceki sette hic yoktu; guclu satin alma-niyetli arama."}, {"tag": "statement necklace", "reason": "Kullanim/tarz slotu — bold ice out parcalari icin genis erisimli arama."}]'::jsonb,'Slotlarin cogu ice/iced ve 14K-chain tekrarlariyla ve bir bracelet tip-celiskisiyle israf edilmis; renk (white gold), link tipi (cylinder), kitle, hediye ve stil niyet slotlari hic yok.','13 slotun ~9''u ice/iced (4) ve 14K-chain (4) kok tekrarina + 1 bracelet tip-celiskisine gidiyordu; Etsy kelimeleri kendisi kombinledigi icin bu tekrarlar bedava trafik getirmiyordu. Baslik gercegiyle alakali 4 tag korundu (ice out chain, diamond cut chain, solid gold chain, real gold chain). Cinlik olan iki tag (bracelet, two tone) relevance icin cikarildi. Bosalan slotlar: renk (white gold), gercek link tipi (cylinder), kitle (mens/unisex), stil (hip hop), kullanim (layering/statement) ve hediye (gift for him) niyetleriyle dolduruldu. Urun bir zincir-kolye oldugu icin ''necklace'' varyantlari mesru; chain 6, necklace 5 tag''e dengelendi. Hepsi cok-kelimeli, birebir tekrar yok, tumu <=20 karakter (en uzunlari ''14k white gold chain'' ve ''unisex gold necklace'' = 20).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,4348088289,'14K Solid Yellow Gold Rolo Bracelet - Dainty Unisex Chain','bracelet','standart',ARRAY['14k gold bracelet','solid gold bracelet','rolo link bracelet','gold chain bracelet','dainty gold bracelet','real gold jewelry','unisex gold bracelet','14k gold chain','gold bracelet gift','everyday gold chain','men gold bracelet','women gold bracelet','ROUND BOX BRACELET']::text[],ARRAY['14k gold bracelet','solid gold bracelet','rolo link bracelet','dainty gold bracelet','yellow gold bracelet','real gold jewelry','gold chain for men','womens gold jewelry','unisex gold bracelet','gold bracelet gift','mothers day gift','layering bracelet','minimalist jewelry']::text[],'[{"tag": "ROUND BOX BRACELET", "reason": "Tip celiskisi: box zincir kare halkalidir, bu urun rolo (yuvarlak halka) — yanlis alici cekiyor. Ayrica all-caps SEO''ya katki saglamaz."}, {"tag": "gold chain bracelet", "reason": "Redundant: ''gold'' + ''bracelet'' zaten cok tag''de var; ''chain bracelet'' benzersiz long-tail katmiyor, slot israfi."}, {"tag": "14k gold chain", "reason": "''14k gold bracelet'' ile ayni koku tekrar ediyor; ''chain'' urunu bilezik degil kolye gibi gosterip relevance zayiflatiyor."}, {"tag": "everyday gold chain", "reason": "Kullanim slotu iyi ama ''chain'' bilezikle uyumsuz; daha isabetli ''layering bracelet'' ile degistirildi."}, {"tag": "men gold bracelet", "reason": "Alici dili zayif; buyer-search formu ''gold chain for men'' ile degistirilerek hem kitle hem gercek arama ifadesi kazanildi."}, {"tag": "women gold bracelet", "reason": "''bracelet'' basini bir kez daha tekrarliyordu; kadin kitlesi ''womens gold jewelry'' ile korunup bas kelime cesitlendirildi."}]'::jsonb,'[{"tag": "yellow gold bracelet", "reason": "Baslikta ''Yellow Gold'' var; alicilar renk+tip birlikte arar, guclu buyer-search long-tail."}, {"tag": "gold chain for men", "reason": "Erkek kitlesini gercek alici dilinde yakalar (''gold chain for men'' yuksek hacimli arama), zayif ''men gold bracelet''in yerine."}, {"tag": "womens gold jewelry", "reason": "Kadin kitlesini korur ama bas kelimeyi ''jewelry''ye cevirerek ''bracelet'' asiri tekrarini kirar."}, {"tag": "mothers day gift", "reason": "Eksik hediye-vesilesi slotu; dainty som altin bilezik klasik anneler gunu hediyesi, mevsimsel trafik acar."}, {"tag": "layering bracelet", "reason": "Eksik kullanim slotu; ince rolo halka istifleme/katman icin idealdir, ''everyday gold chain''in yerine daha isabetli."}, {"tag": "minimalist jewelry", "reason": "Eksik stil slotu; ''dainty'' urunu minimalist arayan kitleye baglar, bas kelime cesitliligi de saglar."}]'::jsonb,'"ROUND BOX BRACELET" tipi celisiyor (box zincir = kare halka, urun rolo = yuvarlak halka) ve tag''lerin 8+''i "gold bracelet" tekrariyla doluyken hediye/stil/kullanim niyet slotlari bos.','Standart arketip: relevance korunarak slot israfi temizlendi. Baslik/urun gercegi som 14K sari altin dainty rolo (yuvarlak halka) UNISEX bilezik. En kritik hata ''ROUND BOX BRACELET'' tip celiskisiydi (box = kare halka, rolo degil) — kaldirildi. 13 tag''in 8+''i ''gold bracelet'' kokunu tekrarliyordu; Etsy kelimeleri kendi kombinlediginden bu slot israfiydi. Bas kelimeler cesitlendirildi (bracelet / jewelry / chain karisimi) ve bos niyet slotlari dolduruldu: hediye vesilesi (mothers day gift), stil (minimalist), kullanim (layering), buyer dili (gold chain for men, real/solid/yellow gold). Kitle uc yonlu korundu (men-chain, womens-jewelry, unisex-bracelet). Rolo, dainty, 14k, solid, unisex gibi baslikla ortusen guclu tag''ler korundu. Hepsi cok-kelimeli, birebir tekrarsiz, <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1877707029,'14K Gold Two-Tone Pave Curb Cuban Bracelet','bracelet','standart',ARRAY['14k gold bracelet','two tone bracelet','curb cuban bracelet','pave cuban chain','gold cuban link','mens gold bracelet','womens gold bracelet','solid gold jewelry','luxury gold bracelet','real gold bracelet','anniversary gift','birthday gift','unisex gold jewelry']::text[],ARRAY['14k gold bracelet','two tone bracelet','curb cuban bracelet','pave cuban chain','miami cuban link','mens gold bracelet','real gold bracelet','solid gold jewelry','unisex gold jewelry','gift for him','gift for her','everyday bracelet','hip hop jewelry']::text[],'[{"tag": "gold cuban link", "reason": "Ucuncu ''cuban'' varyanti; curb cuban + pave cuban ile kok tekrari, en zayif olani (miami cuban link ile degistirildi)."}, {"tag": "womens gold bracelet", "reason": "''bracelet'' kokunun 7 tekrarindan biri; kadin kitlesi ''gift for her'' ile daha genis niyette karsilaniyor."}, {"tag": "luxury gold bracelet", "reason": "Yine ''gold bracelet'' tekrari; luks sinyali solid/real gold zaten tasiyor, slot israfi."}, {"tag": "anniversary gift", "reason": "Jenerik hediye; cinsiyete ozel ''gift for him/her'' daha yuksek niyetli donusum getirir."}, {"tag": "birthday gift", "reason": "Genis/jenerik hediye terimi; stil (hip hop) ve kullanim (everyday) slotlariyla yer degistirdi."}]'::jsonb,'[{"tag": "miami cuban link", "reason": "Kategorinin en yuksek hacimli arama terimi; curb/pave zaten var ama ''miami cuban'' talebi hic karsilanmiyordu."}, {"tag": "gift for him", "reason": "Cuban bileklik erkek-agirlikli; yuksek niyetli hediye slotu."}, {"tag": "gift for her", "reason": "Cikarilan womens kitlesini daha genis hediye niyetiyle telafi eder."}, {"tag": "everyday bracelet", "reason": "Kullanim/occasion slotu; layering/gunluk arayan aliciyi yakalar."}, {"tag": "hip hop jewelry", "reason": "Stil slotu; cuban/pave estetigi bu tarz aramasinin merkezinde."}]'::jsonb,'"gold bracelet" koku 7 slotu yiyor ve stil/kullanim/kitleye-ozel-hediye niyet slotlari bos; en guclu arama terimi ''miami cuban link'' hic yok.','Standart arketip: relevance korunarak slot israfi temizlendi. Urun gercekten bir bilezik oldugu icin ''bracelet'' longtail''leri (curb cuban, two tone, real gold, everyday) mesru tutuldu; ''pave cuban chain'' baslikdaki pave niteligini tasidigi icin korundu. Uc ''cuban'' varyantindan en zayifi (gold cuban link) atilip yerine kategorinin dominant terimi ''miami cuban link'' konuldu — kok tekrari azalmadan arama kapsami genisledi. Dar/jenerik hediye ikilisi (anniversary/birthday) cinsiyete ozel gift for him/her ile degistirilip kitle sinyali guclendirildi; eksik stil (hip hop jewelry) ve kullanim (everyday bracelet) niyet slotlari eklendi. Tum tag''ler <=20 karakter ve cok-kelimeli. Views 1518 / conv 0.0% tablosu: trafik var, donusum yok — bu yuzden niyet/hediye slotlari onceliklendirildi.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,4348066009,'14K White Gold Rolo Link Bracelet - Unisex Chain Jewelry','bracelet','standart',ARRAY['14k gold bracelet','solid gold bracelet','rolo link bracelet','gold chain bracelet','dainty gold bracelet','real gold jewelry','unisex gold bracelet','14k gold chain','gold bracelet gift','everyday gold chain','men gold bracelet','women gold bracelet','ROUND BOX BRACELET']::text[],ARRAY['14k gold bracelet','white gold bracelet','rolo link bracelet','solid gold bracelet','real gold jewelry','unisex gold bracelet','dainty gold bracelet','gold chain bracelet','mens gold bracelet','womens gold bracelet','gift for her','layering bracelet','minimalist jewelry']::text[],'[{"tag": "ROUND BOX BRACELET", "reason": "TIP-CELISKISI: urun rolo link, box link farkli bir zincir tipi; ayrica all-caps mislabel. Alakasiz aramalari cekip donusum bozar."}, {"tag": "14k gold chain", "reason": "Urun bilezik; ''chain'' tek basina kolye aramalarina kayabilir ve ''14k'' zaten 14k gold bracelet ile kapsandi — redundant kok."}, {"tag": "everyday gold chain", "reason": "''gold chain'' koku gold chain bracelet ile zaten var; kullanim-niyeti daha net ''layering bracelet''e tasindi, chain-only belirsizligi elendi."}, {"tag": "gold bracelet gift", "reason": "Genel ''gift'' yerine daha yuksek niyetli occasion ''gift for her'' ile degistirildi; ''gold bracelet'' koku fazlaligi azaltildi."}, {"tag": "men gold bracelet", "reason": "Etsy alici dili grameriyle ''mens gold bracelet'' olarak duzeltildi (arama hacmi daha yuksek)."}, {"tag": "women gold bracelet", "reason": "''womens gold bracelet'' olarak duzeltildi — dogru alici sorgu formu."}]'::jsonb,'[{"tag": "white gold bracelet", "reason": "KRITIK: baslik beyaz altin diyor ama tek bir tag bile yakalamiyordu; beyaz altin ayri ve yuksek niyetli bir arama, sari altindan farkli alici."}, {"tag": "mens gold bracelet", "reason": "Erkek kitle slotu, dogru sorgu grameriyle (men gold bracelet duzeltmesi)."}, {"tag": "womens gold bracelet", "reason": "Kadin kitle slotu, dogru sorgu grameriyle (women gold bracelet duzeltmesi)."}, {"tag": "gift for her", "reason": "Hediye-niyeti slotu; genel ''gift'' yerine spesifik alici occasion sinyali."}, {"tag": "layering bracelet", "reason": "Kullanim/stil slotu — istifleme/katmanlama arayan alicilar; ''chain'' redundancy''sini anlamli niyetle degistirir."}, {"tag": "minimalist jewelry", "reason": "Tarz slotu (dainty urunle uyumlu); ''gold bracelet'' kok tekrarindan cikip yeni bir arama havuzu acar."}]'::jsonb,'Baslik "14K White Gold" derken hicbir tag "white gold" niyetini yakalamiyor; ayrica urun rolo iken "ROUND BOX BRACELET" tip-celiskisi ve 8 adet "gold bracelet" koku slot israf ediyor.','Standart arketip icin dengeli temizlik: (1) tek tip-celiskisi (ROUND BOX BRACELET, rolo urunde box link) ve chain-only belirsiz taglar (14k gold chain, everyday gold chain) elendi; (2) basligin beyaz altin gercegini yakalayan kritik ''white gold bracelet'' eklendi; (3) kitle slotlari (mens/womens/unisex) korunup dogru arama grameriyle sabitlendi; (4) eksik niyet slotlari dolduruldu — hediye (gift for her), kullanim (layering bracelet), stil (minimalist jewelry). Cekirdek relevance (14k, solid, rolo link, real gold, dainty, gold chain bracelet) korundu. 13/13 dolu, hepsi <=20 karakter, cok-kelimeli cogunluk, birebir tekrar yok, ''gold bracelet'' kok fazlaligi 8''den dengeli seviyeye indi.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1710206336,'14K Solid Gold Diamond Cut Stud Earrings | Sparkling Yellow Gold','earring','standart',ARRAY['Stud Earrings','Gold Stud Earrings','Gold Large Earrings','Real Gold Earrings','14K Solid Earrings','Diamond cut Earrings','Sparkling Earrings','Gold Round Earrings','Gold Small Earrings','14K Stud Earrings','14K Hoop Earrings','Yellow Gold Earrings','14K Round Earrings']::text[],ARRAY['Gold Stud Earrings','14K Solid Gold Studs','Diamond Cut Earrings','Real Gold Earrings','Yellow Gold Jewelry','Womens Gold Earrings','Gift for Her','Mothers Day Gift','Everyday Earrings','Small Gold Studs','14K Gold Jewelry','Minimalist Studs','Sparkling Studs']::text[],'[{"tag": "14K Hoop Earrings", "reason": "TIP CELISKISI: urun stud kupe, hoop degil — yaniltici, relevance/donusum zarari"}, {"tag": "Gold Large Earrings", "reason": "BOYUT CELISKISI: stud kupe kucuktur, ''large'' urunle celisir"}, {"tag": "Gold Round Earrings", "reason": "Dusuk niyetli shape varyanti, redundant slot israfi"}, {"tag": "14K Round Earrings", "reason": "Ayni shape kokunun ikinci tekrari — slot israfi"}, {"tag": "14K Stud Earrings", "reason": "''Gold Stud Earrings'' + ''14K Solid Gold Studs'' bunu zaten kombinliyor; Etsy kelimeleri harmanlar, birebir tekrar gereksiz"}, {"tag": "14K Solid Earrings", "reason": "Kirik/eksik ifade (''solid'' malzemesiz) — ''gold'' ile duzeltilip ''14K Solid Gold Studs'' yapildi"}, {"tag": "Stud Earrings", "reason": "Ciplak tek-odak; ''Gold Stud Earrings'' daha guclu long-tail olarak kapsar"}, {"tag": "Sparkling Earrings", "reason": "''Sparkling Studs'' ile korundu; ''Earrings'' kokunun asiri tekrari azaltildi"}, {"tag": "Gold Small Earrings", "reason": "''Small Gold Studs'' ile korundu (daha dogru urun kelimesi)"}]'::jsonb,'[{"tag": "14K Solid Gold Studs", "reason": "Solid gold + 14K + urun tek long-tail''de; alici dili ''solid gold''"}, {"tag": "Yellow Gold Jewelry", "reason": "Basliktaki yellow gold niteligini kategoriye genisletir (jewelry aramasi)"}, {"tag": "Womens Gold Earrings", "reason": "Eksik KITLE slotu — hedef alici acikca isaretlenir"}, {"tag": "Gift for Her", "reason": "Eksik HEDIYE slotu — yuksek hacimli alici niyeti"}, {"tag": "Mothers Day Gift", "reason": "Eksik HEDIYE-VESILE slotu — sezonsal aramayi yakalar"}, {"tag": "Everyday Earrings", "reason": "Eksik KULLANIM slotu — gunluk tak niyeti (stud''a ideal)"}, {"tag": "Small Gold Studs", "reason": "Stud icin dogru boyut kelimesi; ''large'' celiskisinin yerini alir"}, {"tag": "14K Gold Jewelry", "reason": "Kategori genisletici — earrings disi genel aramayi yakalar"}, {"tag": "Minimalist Studs", "reason": "Eksik STIL slotu — sade/minimalist alici segmenti"}, {"tag": "Sparkling Studs", "reason": "Baslik kelimesi ''sparkling'' korunur, ''stud'' kokuyle dogru urune baglanir"}]'::jsonb,'Her tag "Earrings" ile bitiyor ve "14K Hoop Earrings" urun tipiyle celisiyor (urun stud/civata kupe, hoop degil); shape varyantlari slot israf ederken hediye/kitle/stil/kullanim niyet slotlari tamamen eksik.','Orijinal set klasik ''tek kelime + Earrings'' capasindan muzdaripti: 13 tag''in 13''u ''Earrings'' ile bitiyor, sadece shape/boyut degisiyordu (Round/Large/Small/Hoop) — Etsy kelimeleri kendisi kombinledigi icin bu ciddi slot israfi. En kritik: ''14K Hoop Earrings'' urun tipiyle (stud) DOGRUDAN celisiyor ve ''Gold Large Earrings'' stud''un dogasiyla (kucuk) celisiyor — ikisi de relevance/donusum zarari. Optimize sette: (1) core urun kelimeleri korundu (gold stud earrings, 14k, diamond cut, yellow gold, real gold — hepsi urun gercegi); (2) ''stud'' koku 5, ''earrings'' koku 5 varyantta dengelendi (7''den dusuruldu); (3) eksik niyet slotlari eklendi — KITLE (womens), HEDIYE (gift for her, mothers day), STIL (minimalist), KULLANIM (everyday); (4) kategori genisleticiler (yellow gold jewelry, 14k gold jewelry) earrings disi aramayi acar. Tum 13 tag cok-kelimeli, <=20 karakter, birebir tekrarsiz.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1656788008,'14K Yellow Gold Puffed Heart Hoop Earrings | Chunky Jewelry','earring','standart',ARRAY['Huge Hoop Earrings','Puffed Earrings','Hoop Earrings','Gold Hoop Earrings','Graduated Earrings','Gold Graduated','Diamond Cut Earrings','Large Hoop Earrings','Heart Earrings','Gold Heart Earrings','Love Earrings','Twisted Earrings','Gold Twist Earrings']::text[],ARRAY['Gold Hoop Earrings','Puffed Heart Hoops','Chunky Gold Earrings','14k Gold Earrings','Real Gold Earrings','Gold Heart Earrings','Diamond Cut Hoops','Graduated Hoops','Statement Earrings','Everyday Earrings','Gift for Her','Mothers Day Gift','Womens Gold Jewelry']::text[],'[{"tag": "Huge Hoop Earrings", "reason": "Boyut varyantı redundancy; ''Large Hoop'' ile ikiz, ''Chunky Gold'' ve ''Gold Hoop'' kapsıyor."}, {"tag": "Large Hoop Earrings", "reason": "''Huge Hoop'' ile birebir örtüşen ikinci boyut varyantı; slot israfı."}, {"tag": "Hoop Earrings", "reason": "Bare/düşük özgüllüklü; ''Gold Hoop Earrings'' zaten bu kökü Etsy kombinasyonuyla veriyor."}, {"tag": "Puffed Earrings", "reason": "Tek nitelikli fragman; ''Puffed Heart Hoops'' long-tail''ine katlandı."}, {"tag": "Graduated Earrings", "reason": "''Graduated Hoops'' altında ürün tipiyle birleştirildi."}, {"tag": "Gold Graduated", "reason": "Eksik/asılı ifade (isim yok); ''Graduated Hoops''a katlandı."}, {"tag": "Diamond Cut Earrings", "reason": "''Diamond Cut Hoops'' olarak ürün tipine bağlandı, hoop niyetini güçlendirdi."}, {"tag": "Love Earrings", "reason": "Zayıf/genel sinyal; yerini net hediye niyet slotları aldı."}, {"tag": "Twisted Earrings", "reason": "Ürün puffed kalp hoop, büküm değil — relevance çelişkisi."}, {"tag": "Gold Twist Earrings", "reason": "Aynı twist relevance çelişkisi + ikinci varyant redundancy."}]'::jsonb,'[{"tag": "Puffed Heart Hoops", "reason": "Puffed+heart+hoop üç kökünü tek long-tail''de toplayıp iki fragman slotunu kurtarır."}, {"tag": "Chunky Gold Earrings", "reason": "Başlıktaki ''Chunky'' niyetini yakalar; boyut+stil slotu."}, {"tag": "14k Gold Earrings", "reason": "Malzeme + alıcı arama dili; başlıktaki 14K''yı aranabilir kılar."}, {"tag": "Real Gold Earrings", "reason": "Som altın alıcı dili (''real gold'') — kaplama arayanı eler."}, {"tag": "Diamond Cut Hoops", "reason": "Elmas kesim stilini hoop tipine bağlar (bare ''Earrings'' yerine)."}, {"tag": "Graduated Hoops", "reason": "Graduated kavramını iki eski fragman yerine tek net hoop tag''inde toplar."}, {"tag": "Gift for Her", "reason": "Eksik hediye niyet slotu — kadın alıcı hediye aramasını yakalar."}, {"tag": "Mothers Day Gift", "reason": "Occasion/hediye slotu; mevsimsel arama hacmi."}, {"tag": "Statement Earrings", "reason": "Chunky/puffed ürüne uygun stil+kullanım slotu."}, {"tag": "Everyday Earrings", "reason": "Kullanım niyeti; günlük takı arayan kitleyi ekler."}, {"tag": "Womens Gold Jewelry", "reason": "Kitle (womens) + kategori genişliği; hoop kökü dışı yeni yüzey."}]'::jsonb,'Slotların yarısı "hoop earrings" kökünün varyantlarına (Huge/Large/Gold/bare Hoop) ve twist/graduated fragmanlarına gidiyor; hiç hediye, kitle veya kullanım niyet slotu yok.','Eski sette 4 tag salt ''hoop earrings'' boyut/renk varyantı, 2 tag graduated fragmanı, 2 tag ürünle çelişen twist idi — Etsy kelimeleri kendisi kombinlediği için bu tekrar slot israfıydı. Bu redundansı tek güçlü long-tail''lere (Puffed Heart Hoops, Diamond Cut Hoops, Graduated Hoops) indirdim ve boşalan slotları hiç bulunmayan niyetlerle doldurdum: malzeme/alıcı dili (14k/Real Gold), hediye (Gift for Her, Mothers Day), stil+kullanım (Chunky, Statement, Everyday), kitle (Womens Gold Jewelry). Hoop/heart/gold çekirdek relevance''ı korundu; twist gibi çelişen köklerden arındırıldı. Tüm 13 tag çok-kelimeli ve <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1768689465,'10K Gold Lion & Eagle Pendant – Diamond Cut Two-Tone Necklace','pendant','standart',ARRAY['white gold pendant','Large mens pendant','Jesus Pendant','10K gold pendant','10K gold necklace','Miami Cuban Chain','10k Gold chain','Gold Necklace','Gold Pendant','Lion Pendant','eagle pendant','animal pendant','animal necklace']::text[],ARRAY['Lion Pendant','eagle pendant','animal pendant','10K gold pendant','Large mens pendant','10K gold necklace','10k gold chain','diamond cut chain','two tone necklace','mens gold chain','gift for him','hip hop jewelry','statement necklace']::text[],'[{"tag": "Jesus Pendant", "reason": "Tip celiskisi: urun Lion & Eagle temali, dini bir motif degil; alakasiz tag relevance skorunu dusuruyor ve yanlis aramada gosterip donusumsuz view getiriyor."}, {"tag": "white gold pendant", "reason": "Malzeme celiskisi: malzeme listesi tumuyle sari/10K/10K real/Yellow Gold; beyaz altin yok. ''Two-Tone'' sari tonlari; yanltici, kaldirildi."}, {"tag": "Miami Cuban Chain", "reason": "Stil celiskisi: baslik zinciri ''Diamond Cut'' olarak tanimliyor, cuban degil; yanlis stil vaadi. Yerine dogru ''diamond cut chain''."}, {"tag": "Gold Necklace", "reason": "Redundancy/generic: ''10K gold necklace'' tarafindan kapsaniyor; tek-kok slot israfi, niyet slotuna donusturuldu."}, {"tag": "Gold Pendant", "reason": "Redundancy/generic: ''10K gold pendant'' tarafindan kapsaniyor; ayni koku tekrar, slot israfi."}, {"tag": "animal necklace", "reason": "Redundancy: ''animal pendant'' ile ayni niyet; slotu hediye/kullanim niyetine actik."}]'::jsonb,'[{"tag": "diamond cut chain", "reason": "Stil slotu (basliktan dogrulanmis ''Diamond Cut''): dogru zincir finisi; silinen yanlis ''Miami Cuban''in yerine mesru arama."}, {"tag": "two tone necklace", "reason": "Stil slotu (baslik ''Two-Tone Necklace''): ayirici stil terimi, dogrudan baslik gercegiyle uyumlu."}, {"tag": "mens gold chain", "reason": "Kitle+alici dili slotu: ''gold chain for men'' niyetini yakalar; dar kitleyi genisletir, erkek altin zincir aramasi guclu."}, {"tag": "gift for him", "reason": "Hediye slotu: hic yoktu; buyuk erkek pendant icin en dogal hediye niyeti (dogum gunu/babalar gunu erkek)."}, {"tag": "hip hop jewelry", "reason": "Tarz slotu: kalin 10K altin erkek pendant hip-hop/street tarziyla guclu ortusur; yeni kesif kanali."}, {"tag": "statement necklace", "reason": "Kullanim slotu: buyuk boy pendant ''statement'' niyetini karsilar; necklace mesru (urun necklace olarak satiliyor)."}]'::jsonb,'Alakasiz/celiskili tag''ler (Jesus Pendant, white gold, Miami Cuban) relevance''i kiriyor; ayni anda gold/pendant/necklace koku asiri tekrarlanip hediye/stil/kullanim niyet slotlari tamamen bos birakilmis.','7 tag korundu (Lion/eagle/animal pendant, 10K gold pendant, Large mens pendant, 10K gold necklace, 10k gold chain) — her biri farkli modifier (konu/malzeme/boyut/tip) tasidigi icin mesru; pendant kokunu 8''den 5''e dusurdum. 6 tag cikarildi: 3 celiskili (relevance kirici) + 3 redundant generic. 6 tag eklendi ve bos niyet slotlarina dagitildi: stil (diamond cut chain, two tone necklace), kitle/alici-dili (mens gold chain), hediye (gift for him), tarz (hip hop jewelry), kullanim (statement necklace). Necklace/chain silinmedi cunku baslik urunu necklace olarak satiyor ve pendant zincirle geliyor. 13 tag''in tumu cok-kelimeli long-tail, birebir tekrar yok, hepsi <=20 karakter (en uzun ''diamond cut chain''/''two tone necklace'' = 17). views=1273 ama units=0/conv=0 tablosu: trafik var, donusum yok — celiskili tag''lerin getirdigi yanlis-niyet trafigini kesip alici-niyeti (hediye/erkek/stil) slotlariyla nitelikli trafige cevirmek hedeflendi.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1849022518,'10K Gold Rope Chain Necklace – Twisted Diamond Cut, Men or Women','necklace','standart',ARRAY['Rope Chain','Gold Rope Chain','Gold Chain','Rope Chain Necklace','Real Gold Chain','Real Gold Rope Chain','Rope Necklace','chain necklace','10K ROPE CHAIN','10K GOLD CHAIN','10K CHAIN','10K GOLD ROPE CHAIN','gold necklace']::text[],ARRAY['gold rope chain','rope chain necklace','10k gold rope chain','real gold chain','diamond cut chain','twisted rope chain','gold chain for men','womens gold chain','mens gold necklace','layering necklace','everyday gold chain','10k solid gold chain','gift for him']::text[],'[{"tag": "Rope Chain", "reason": "Tek-kelime kok; uzun-kuyruk varyantlarca zaten kapsaniyor, slot israfi"}, {"tag": "Gold Chain", "reason": "Cok genis/generic, dusuk long-tail rekabet gucu"}, {"tag": "Real Gold Rope Chain", "reason": "''gold rope chain'' + ''real gold chain'' ile ust uste binen redundant birlesim"}, {"tag": "Rope Necklace", "reason": "''rope chain necklace'' ile ayni niyeti tekrar ediyor"}, {"tag": "chain necklace", "reason": "Cok generic; alici niyeti tasimayan zayif slot"}, {"tag": "10K ROPE CHAIN", "reason": "''10k gold rope chain'' ile redundant kok tekrari"}, {"tag": "10K GOLD CHAIN", "reason": "10K kok kumesinde ucuncu kez tekrarlanan slot"}, {"tag": "10K CHAIN", "reason": "Kisaltilmis generic tekrar, ayrik deger katmiyor"}, {"tag": "gold necklace", "reason": "Generic; ''mens gold necklace'' ile kitle-hedefli versiyona yukseltildi"}]'::jsonb,'[{"tag": "diamond cut chain", "reason": "Basliktaki ''Diamond Cut'' stil niteligi; guclu stil slotu"}, {"tag": "twisted rope chain", "reason": "Basliktaki ''Twisted'' tarifi; urunu ayirt eden stil long-tail"}, {"tag": "gold chain for men", "reason": "Eksik erkek alici/kitle slotu; yuksek hacimli alici dili"}, {"tag": "womens gold chain", "reason": "Basliktaki ''or Women'' icin kadin kitle slotu"}, {"tag": "mens gold necklace", "reason": "Erkek kitle + necklace tipini birlestiren long-tail"}, {"tag": "layering necklace", "reason": "Eksik kullanim/stil slotu (katmanlama trendi)"}, {"tag": "everyday gold chain", "reason": "Eksik kullanim slotu; gunluk giyim niyeti"}, {"tag": "10k solid gold chain", "reason": "''solid gold'' alici dili + karat; som altin arayan alicilari yakalar"}, {"tag": "gift for him", "reason": "Eksik hediye niyet slotu; erkek rope chain guclu hediye pazari"}]'::jsonb,'13 slotun 10''u "rope chain" ve "10K chain" kok tekrarlarina gitmis; hediye, kullanim ve alici-cinsiyet niyet slotlari tamamen bos.','Mevcut set tek bir cekirdek anahtar (''rope chain'') ve karat kumesini (''10K'') 10 slotta tekrarlayarak Etsy''nin otomatik kombinlemesini israf ediyordu. Cekirdegi 4 ayrik nitelikli varyantla koruyup (gold rope chain, rope chain necklace, 10k gold rope chain, real gold chain) kalan 9 slotu niyet genisletmesine actim: basliktan gelen stil (twisted, diamond cut), her iki cinsiyet icin alici sloti (men/women/mens), kullanim (layering, everyday), som-altin alici dili (solid gold) ve hediye (gift for him). Tumu urun tipiyle (necklace) tutarli; tip-celiskisi yok. Tum 13 tag <=20 karakter ve cok-kelimeli.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1222574043,'14K Gold CZ Hoop Earrings, Small Huggie Style (15mm)','earring','standart',ARRAY['Gold Huggie Earrings','Diamonique Earrings','Huggie Hoop Earrings','Gold Hoop Earrings','Channel Set Earrings','Diamond Cz Huggie','Cz Huggie Earrings','Small Hoop Earrings','Gold Small Earrings','Gold Cz Earrings','Channel Earrings','14K Gold Earrings','14K Gold Huggie']::text[],ARRAY['Gold Huggie Earrings','Small Hoop Earrings','14K Gold Earrings','Cz Huggie Hoops','Channel Set Earrings','Cubic Zirconia Hoops','Womens Gold Hoops','Everyday Gold Hoops','Huggie Earrings Gift','Dainty Gold Earrings','Bridal Hoop Earrings','Solid Gold Earrings','Gold Hoops for Her']::text[],'[{"tag": "Diamonique Earrings", "reason": "QVC markasi ''Diamonique'' — urun gercegi (14K real gold CZ) ile ilgisiz, yaniltici marka tag''i; alici dili degil."}, {"tag": "Huggie Hoop Earrings", "reason": "Gold Huggie Earrings + Cz Huggie Hoops ile ayni koku tekrarliyor; slot israfi."}, {"tag": "Gold Hoop Earrings", "reason": "Cok genel, mevcut kombolarca kapsaniyor; slot niyet genisletmeye ayrildi."}, {"tag": "Diamond Cz Huggie", "reason": "''Diamond'' + ''cz'' celiskili/yaniltici (urun elmas degil CZ); ayrica fazlalik huggie tekrari."}, {"tag": "Gold Small Earrings", "reason": "Small Hoop Earrings''in near-duplicate''i; ''small'' niyeti zaten kapsandi."}, {"tag": "Gold Cz Earrings", "reason": "Cubic Zirconia Hoops ve diger cz kombolariyla ortusuyor; redundancy."}, {"tag": "Channel Earrings", "reason": "Channel Set Earrings''in tam kopyasi; ikinci channel slotu israf."}, {"tag": "14K Gold Huggie", "reason": "Karat bilgisi 14K Gold Earrings''te, huggie bes kez var; birlesik tekrar slotu bosa harciyor."}]'::jsonb,'[{"tag": "Cubic Zirconia Hoops", "reason": "Bazi aliciar ''cz'' degil ''cubic zirconia'' tam yazimini arar; ayni niyet farkli kelime kokuyle yakalanir."}, {"tag": "Womens Gold Hoops", "reason": "Eksik kitle slotu — 15mm dainty CZ huggie kadin alici odakli; alici dilini ekler."}, {"tag": "Everyday Gold Hoops", "reason": "Eksik kullanim slotu — kucuk huggie''nin ana satis argumani gunluk/surekli takilabilirlik."}, {"tag": "Huggie Earrings Gift", "reason": "Eksik hediye slotu — Etsy''de hediye niyeti yuksek hacimli aramadir."}, {"tag": "Dainty Gold Earrings", "reason": "Eksik stil slotu — ''dainty/minimalist'' 15mm kucuk urunun estetigini hedefler."}, {"tag": "Bridal Hoop Earrings", "reason": "Eksik ozel gun/stil slotu — CZ tasli altin huggie gelin/nedime alt-pazarina uyar."}, {"tag": "Solid Gold Earrings", "reason": "Alici dili — malzeme ''14k real gold''; ''solid gold'' gercek altin arayan yuksek niyetli aliciyi ceker."}, {"tag": "Gold Hoops for Her", "reason": "Hediye-icin-o niyet slotu; ''for her'' Etsy hediye aramalarinda guclu long-tail."}]'::jsonb,'Slotlarin cogu tek bir cekirdek etrafinda israf ediliyor (huggie 5 varyant, channel 2, cz 3) ve hediye/kitle/kullanim/stil niyet slotlari tamamen eksik.','Standart arketip: dengeli temizlik. Cekirdek performans tag''leri korundu (Gold Huggie Earrings, Small Hoop Earrings, 14K Gold Earrings, Channel Set Earrings) ve cz-huggie kombosu ''Cz Huggie Hoops'' olarak sadelestirildi. Huggie tekrari 5''ten 3''e, channel 2''den 1''e indirildi; yaniltici Diamonique ve celiskili ''Diamond Cz'' cikarildi. Bosalan 8 slot niyet eksenlerine dagitildi: kitle (womens, for her), hediye (gift, for her), kullanim (everyday), stil (dainty, bridal), alici dili (solid gold, cubic zirconia). Tum tag''ler cok-kelimeli long-tail, hepsi <=20 karakter, birebir tekrar yok, urun tipiyle (earring/hoop/huggie) celismiyor."','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1731430357,'10K Gold Hamsa Necklace | CZ Stone Evil Eye Pendant, Rope Chain','pendant','standart',ARRAY['Egyptian Necklace','Hamsa Necklace','Egyptian Pendant','Egypt Necklace','Egypt Pendant','10K Gold Necklace','10K Gold Pendant','Evil Eye Necklace','Good Luck Necklace','Gold Necklace','Gold Pendant','Gold Hamsa','Rope Chain']::text[],ARRAY['Hamsa Necklace','Evil Eye Pendant','10K Gold Necklace','10K Gold Pendant','Gold Rope Chain','Good Luck Charm','Hamsa Hand Pendant','Protection Jewelry','Gift For Her','Womens Gold Jewelry','Evil Eye Jewelry','CZ Evil Eye','Real Gold Necklace']::text[],'[{"tag": "Egyptian Necklace", "reason": "Hamsa Ortadogu sembolu, Misir''la marjinal alaka; 4 Egypt-koklu tekrardan biri, slot israfi."}, {"tag": "Egyptian Pendant", "reason": "Egypt kokunun ikinci tekrari; Etsy kelimeleri kendi kombinler, redundant."}, {"tag": "Egypt Necklace", "reason": "Egypt kokunun ucuncu tekrari, ayni niyet, slot bosa."}, {"tag": "Egypt Pendant", "reason": "Egypt kokunun dorduncu tekrari; dort slot tek dusuk-alaka temaya harcanmis."}, {"tag": "Evil Eye Necklace", "reason": "Baslikta ''Evil Eye Pendant'' geciyor; pendant-basli varyant + Evil Eye Jewelry/CZ Evil Eye ile bas cesitlendirildi."}, {"tag": "Good Luck Necklace", "reason": "''necklace'' bası asiri; anlam korunarak ''charm'' basina cevrildi (Good Luck Charm)."}, {"tag": "Gold Necklace", "reason": "Genis tek-nitelikli; 10K Gold Necklace ve Real Gold Necklace tarafindan kapsaniyor."}, {"tag": "Gold Pendant", "reason": "Genis, 10K Gold Pendant tarafindan kapsaniyor; alici dili degil."}, {"tag": "Gold Hamsa", "reason": "Zayif long-tail; Hamsa Necklace ve Hamsa Hand Pendant tarafindan kapsaniyor."}, {"tag": "Rope Chain", "reason": "''Gold Rope Chain'' olarak zenginlestirildi; daha guclu long-tail + gold sinyali."}]'::jsonb,'[{"tag": "Evil Eye Pendant", "reason": "Baslikla birebir (''Evil Eye Pendant''); pendant urun tipiyle tam ortusen bas."}, {"tag": "Gold Rope Chain", "reason": "Rope Chain''in stil+malzeme zengin long-tail hali; baslik gercegi."}, {"tag": "Good Luck Charm", "reason": "Anlam/niyet slotu; ''necklace'' tekrarindan kacinmak icin ''charm'' basi."}, {"tag": "Hamsa Hand Pendant", "reason": "Yuksek hacimli ''hamsa hand'' arama terimini yakalar; pendant bası."}, {"tag": "Protection Jewelry", "reason": "Evil eye/hamsa koruma anlami; jewelry basiyla kategori genisletir."}, {"tag": "Gift For Her", "reason": "Eksik hediye niyet slotu; taki icin yuksek donusum arama."}, {"tag": "Womens Gold Jewelry", "reason": "Eksik kitle slotu (womens); jewelry basiyla erisimi genisletir."}, {"tag": "Evil Eye Jewelry", "reason": "Evil eye niyetini necklace disi kategoriye tasir, bas cesitliligi."}, {"tag": "CZ Evil Eye", "reason": "Baslikta ''CZ Stone'' vardi ama hic tag yoktu; tas ozelligi arama slotu."}, {"tag": "Real Gold Necklace", "reason": "Alici dili (''real gold''); som altin niyetli aramalari yakalar."}]'::jsonb,'Dort Egypt-koklu tag + genis tek-nitelikli gold tag''ler slot israf ederken hediye/kitle/CZ tas/koruma niyet slotlari tamamen bostu.','Baslik urunu ''Hamsa Necklace ... Rope Chain'' diye tanimladigi icin necklace tag''leri mesru; korlemesine silinmedi, sadece bas cesitlendirildi (necklace/pendant/jewelry/chain/charm dengesi). En buyuk kazanc dort Egypt-koklu dusuk-alaka tekrarini ve genis tek-nitelikli gold tag''lerini kaldirip; hediye (Gift For Her), kitle (Womens Gold Jewelry), stil/tas (CZ Evil Eye, Gold Rope Chain), anlam (Protection Jewelry) ve alici dili (Real Gold Necklace) slotlarini acmak. CZ tas basliktaydi ama hic taglenmemisti — geri kazanildi. Tum 13 tag cok-kelimeli long-tail ve <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1448783390,'14K Solid Gold Butterfly Pendant | CZ Diamond Charm, 30mm','pendant','standart',ARRAY['Butterfly Charm','Butterfly Pendant','Gold Butterfly Charm','Gold Butterfly','14K Gold Butterfly','Cz Diamond Pendant','Cz Diamond Charm','14K Gold Pendant','Solid Gold Pendant','14K Solid Gold Charm','14K Gold Charm','Gold Cz Charm','Gold Cz Pendant']::text[],ARRAY['Gold Butterfly Charm','14K Solid Gold Charm','CZ Diamond Pendant','Butterfly Necklace','Real Gold Pendant','Yellow Gold Pendant','Gift For Her','Mothers Day Gift','Womens Gold Jewelry','Dainty Gold Charm','Minimalist Jewelry','Layering Necklace','Butterfly Jewelry']::text[],'[{"tag": "Butterfly Charm", "reason": "Tek kelimeye yakin, dar; ''Gold Butterfly Charm'' zaten kapsiyor."}, {"tag": "Butterfly Pendant", "reason": "Baslikta var; ''Butterfly Necklace'' daha genis crossover ile degistirildi."}, {"tag": "Gold Butterfly", "reason": "Iki kelime ama subsumed; butterfly koku fazla tekrar ediyordu."}, {"tag": "14K Gold Butterfly", "reason": "14K+butterfly baslikta baskin; slot israfi."}, {"tag": "Cz Diamond Charm", "reason": "''CZ Diamond Pendant'' ile ayni kok; cz tekrarini kirdik."}, {"tag": "14K Gold Pendant", "reason": "Malzeme tag''leriyle (Real/Yellow/Solid) cakisan tekrar."}, {"tag": "Solid Gold Pendant", "reason": "''Real Gold Pendant'' + ''Yellow Gold Pendant'' varyantlariyla telafi edildi."}, {"tag": "14K Gold Charm", "reason": "''14K Solid Gold Charm'' alt kumesi; gereksiz."}, {"tag": "Gold Cz Charm", "reason": "Cz koku 4 kez geciyordu; slot israfi."}, {"tag": "Gold Cz Pendant", "reason": "Cz redundancy; tek ''CZ Diamond Pendant'' yeterli."}]'::jsonb,'[{"tag": "Butterfly Necklace", "reason": "Pendant kolyeyle takilir; yuksek hacimli necklace crossover terimi."}, {"tag": "Real Gold Pendant", "reason": "Alici dili ''real gold'' — som altin arayan niyeti yakalar."}, {"tag": "Yellow Gold Pendant", "reason": "Malzeme listesindeki Yellow Gold varyanti; renk niyeti."}, {"tag": "Gift For Her", "reason": "Eksik hediye niyet slotu."}, {"tag": "Mothers Day Gift", "reason": "Eksik hediye/vesile slotu (sezonsal trafik)."}, {"tag": "Womens Gold Jewelry", "reason": "Eksik kitle slotu (kadin alici)."}, {"tag": "Dainty Gold Charm", "reason": "Eksik stil slotu (dainty/ince tarz)."}, {"tag": "Minimalist Jewelry", "reason": "Eksik stil slotu; farkli kok ile slot genisletir."}, {"tag": "Layering Necklace", "reason": "Eksik kullanim slotu (katmanli takim)."}, {"tag": "Butterfly Jewelry", "reason": "Butterfly niyetini jewelry koku ile genisletir (5''ten 3''e indirilmis butterfly)."}]'::jsonb,'13 slotun tamami ayni koklerin (butterfly/charm/pendant/cz/14k gold) yeniden kombinasyonu; hediye/kitle/stil/kullanim niyet slotlari tamamen bos.','Mevcut set relevance acisindan dogruydu ama asiri redundanttı: butterfly 5, charm 6, pendant 5, cz 4 slotta tekrarliyor ve Etsy kelimeleri kendi kombinledigi icin bu slot israfiydi. 10 tekrar tag''i cikardim, urun cekirdegini (butterfly charm, 14K solid gold, cz diamond, yellow/real gold) 6 dengeli slotta koruyup gerisini eksik niyet eksenlerine actim: 2 hediye (Gift For Her, Mothers Day Gift), 1 kitle (Womens Gold Jewelry), 2 stil (Dainty Gold Charm, Minimalist Jewelry), 2 kullanim/crossover (Layering Necklace, Butterfly Necklace). Pendant kolyeyle satildigi icin ''necklace'' relevance-uyumlu. Tum tag''ler <=20 karakter ve cok-kelimeli long-tail. conv=0.093% ve units=1 dusuk donusum, trafigi (1079 view) niyet cesitliligiyle kaliteli aliciya cevirmeyi hedefler.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1864218405,'14K Gold Tri-Color Jesus Cross Pendant with Rope Chain','pendant','standart',ARRAY['Cross Pendant','Gold Jesus Pendant','Jesus Necklace','Crucifix Pendant','Religious Pendant','Religious Necklace','Religious Jewelry','Gold Cross Pendant','14K GOLD PENDANT','14K GOLD NECKLACE','14K PENDANT','14K CROSS PENDANT','TRICOLOR PENDANT']::text[],ARRAY['Gold Cross Pendant','Jesus Cross Necklace','Gold Rope Chain','Crucifix Necklace','Religious Jewelry','14K Gold Pendant','Gold Chain for Men','Mens Cross Necklace','Tri Color Gold','Real Gold Necklace','Gift for Him','Hip Hop Jewelry','Gold Jesus Pendant']::text[],'[{"tag": "Cross Pendant", "reason": "Tek basina zayif; ''Gold Cross Pendant'' ve baslik zaten kapsiyor, slot israfi."}, {"tag": "Jesus Necklace", "reason": "Ince; daha zengin ''Jesus Cross Necklace'' + ''Gold Jesus Pendant'' ile yukseltildi."}, {"tag": "Crucifix Pendant", "reason": "''pendant'' asiri yiginini azaltmak icin ''Crucifix Necklace'' varyantina cevrildi (urun zincirle satiliyor)."}, {"tag": "Religious Pendant", "reason": "''Religious Jewelry'' ile ayni kok; redundant slot."}, {"tag": "Religious Necklace", "reason": "''religious'' kokunun ucuncu tekrari; slot israfi."}, {"tag": "14K GOLD NECKLACE", "reason": "Cok jenerik/ince; alici dili ''Real Gold Necklace'' ile degistirildi."}, {"tag": "14K PENDANT", "reason": "Neredeyse tek-kelime, ''14K Gold Pendant'' ile redundant."}, {"tag": "14K CROSS PENDANT", "reason": "14K+cross+pendant asiri yigin; ayni aramayi baska tag''ler kapsiyor."}, {"tag": "TRICOLOR PENDANT", "reason": "Yine ''pendant'' tekrari; daha aranan ''Tri Color Gold'' (bosluklu) ile degistirildi."}]'::jsonb,'[{"tag": "Jesus Cross Necklace", "reason": "Baslik gercegi (Jesus+cross+zincir) tek long-tail''de; ''Jesus Necklace'' yerine daha guclu."}, {"tag": "Gold Rope Chain", "reason": "Rope chain baslikta ana ayirt edici ama hic tag''i yoktu; kritik bosluk dolduruldu."}, {"tag": "Crucifix Necklace", "reason": "Crucifix niyetini ''pendant'' yigmadan tutar, zincir gercegine uyar."}, {"tag": "Gold Chain for Men", "reason": "Kitle + alici dili (''gold chain for men''); rope chain + cross erkek egilimli."}, {"tag": "Mens Cross Necklace", "reason": "Eksik kitle slotu (mens) acildi."}, {"tag": "Tri Color Gold", "reason": "Tri-color ozelligini bosluklu, aranabilir bicimde tasir; ''pendant'' tekrarindan kurtarir."}, {"tag": "Real Gold Necklace", "reason": "Malzeme 14K REAL GOLD; ''real gold'' alici dili donusum sinyali."}, {"tag": "Gift for Him", "reason": "Eksik hediye slotu; dini + erkek urun icin guclu niyet."}, {"tag": "Hip Hop Jewelry", "reason": "Eksik stil/tarz slotu; rope chain + Jesus cross hip hop estetigiyle ortusur."}]'::jsonb,'"pendant" koku 13 tag''in ~9''unda tekrarlanip slotlari israf ediyor; baslikta one cikan rope chain, hediye, kitle ve stil niyet slotlari hic yok.','Baslik ''with Rope Chain'' dedigi icin ''necklace'' tag''leri tip-celiskisi DEGIL — ipucu baslik gercegiyle dogrulandi ve necklace mesru tutuldu (kor silme yapilmadi). Ana kazanim: ''pendant'' koku ~9 tag''ten 3''e indirildi (Gold Cross Pendant, 14K Gold Pendant, Gold Jesus Pendant), acilan slotlara ayirt edici (Gold Rope Chain, Tri Color Gold), kitle (Mens Cross Necklace, Gold Chain for Men), hediye (Gift for Him), stil (Hip Hop Jewelry) ve alici dili (Real Gold Necklace) yerlestirildi. 13/13 cok-kelimeli, birebir tekrar yok, hepsi <=20 karakter. 1037 goruntulenme / %0 donusum tablosu, dar-redundant tag setinin farkli niyetlere ulasamamasiyla tutarli.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1725092482,'10K Gold Jesus Praying Hand CZ Ring | Men''s Two-Tone Nugget Ring','ring','standart',ARRAY['Nugget Ring','Nugget mens','Gold Nugget Ring','Nugget Rings','10K Gold Rings','10K Solid Gold Ring','Solid Gold Ring','10K Ring','Gold Ring','10K Gold Ring Men','Jesus Head Ring','Praying hand Ring','Jesus Praying Ring']::text[],ARRAY['Jesus Ring for Men','Praying Hands Ring','Two Tone Nugget Ring','10K Gold Nugget Ring','Mens Solid Gold Ring','CZ Statement Ring','Christian Gift Ring','Gift for Him','Real Gold Mens Ring','Hip Hop Ring','Religious Jewelry','Yellow Gold Ring','Iced Out Ring']::text[],'[{"tag": "Nugget Rings", "reason": "Nugget Ring''in cogul birebir kopyasi; saf slot israfi (Etsy tekil/cogulu birlikte gorur)."}, {"tag": "Gold Nugget Ring", "reason": "10K Gold Nugget Ring ile ayni kok; niteliksiz redundancy, konsolide edildi."}, {"tag": "Nugget mens", "reason": "Bozuk long-tail (mens kelimesi askida); Mens Solid Gold Ring / Real Gold Mens Ring erkek sinyalini tasiyor."}, {"tag": "10K Gold Rings", "reason": "10K gold ring kokunun 6 varyantindan biri; asiri redundancy."}, {"tag": "10K Solid Gold Ring", "reason": "Solid + gold sinyali Mens Solid Gold Ring''e konsolide; kok tekrari."}, {"tag": "Solid Gold Ring", "reason": "Ayni kokun modifiersiz kopyasi; long-tail degeri dusuk."}, {"tag": "10K Ring", "reason": "Tek nitelikli, cok genis; long-tail degil, slot israfi."}, {"tag": "Gold Ring", "reason": "Asiri genis/rekabetli tek-kok; long-tail yok, donusum getirmez."}, {"tag": "10K Gold Ring Men", "reason": "Erkek+gold+ring kokunun bir baska tekrari; Real Gold Mens Ring ile karsilaniyor."}, {"tag": "Jesus Head Ring", "reason": "Urun gercegiyle celisiyor: bu praying hand, ''head'' degil; relevance riski."}, {"tag": "Jesus Praying Ring", "reason": "Jesus Ring for Men + Praying Hands Ring ile ust uste binen ucuncu Jesus/pray varyanti."}]'::jsonb,'[{"tag": "Christian Gift Ring", "reason": "Bos olan hediye + religious niyet slotunu acar; temanin dogal alici sorgusu."}, {"tag": "Gift for Him", "reason": "Kitle+hediye slotu (erkek alicisi); tamamen eksikti."}, {"tag": "CZ Statement Ring", "reason": "Basliktaki CZ nitelig ini kullanim/stil slotuna cevirir (statement)."}, {"tag": "Hip Hop Ring", "reason": "Nugget + iki tonlu + CZ tarzinin dogal stil sorgusu; yeni tarz slotu."}, {"tag": "Religious Jewelry", "reason": "Genis religious kesif slotu; Jesus/praying temasini kategori aramalarina baglar."}, {"tag": "Real Gold Mens Ring", "reason": "Alici dili (''real gold'') + erkek kitlesini tek slotta birlestirir."}, {"tag": "Yellow Gold Ring", "reason": "Malzeme (Yellow Gold) sinyalini ekler; renk aramasi karsilar."}, {"tag": "Iced Out Ring", "reason": "CZ taslarinin hip-hop alicilarindaki karsiligi; bling stil slotu."}, {"tag": "Jesus Ring for Men", "reason": "Jesus + kitle long-tail; tema+erkek niyetini tek uzun kuyrukta toplar."}]'::jsonb,'13 tag''in 10''u iki köke (nugget x4, 10K gold ring x6) yiginlanmis slot israfi; hediye/stil/kullanim ve Christian-religious niyet slotlari tamamen bos.','Kok yigilmasini kirdim: nugget 4->2 (Two Tone Nugget Ring, 10K Gold Nugget Ring), gold-ring 6->3 (her biri farkli modifier: solid/real+mens/yellow). Bosalan 8 slotu niyet cesitliligine ayirdim: hediye (Christian Gift Ring, Gift for Him), stil (Hip Hop Ring, Iced Out Ring), kullanim (CZ Statement Ring), kitle (Jesus Ring for Men, Real Gold Mens Ring) ve kategori kesfi (Religious Jewelry). Celisen ''head'' tag''i kaldirildi, praying hand gercege sadik kaldi. Hepsi cok-kelimeli long-tail, birebir tekrar yok, her tag <=20 karakter (en uzunlar 20: Two Tone/10K Gold Nugget Ring, Mens Solid Gold Ring). Christian/religious tema urunun en ayirt edici ve rekabeti dusuk niches oldugu icin agirlikli tutuldu.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1717808152,'10K Gold Hamsa Pendant Necklace | CZ Stone Evil Eye, Rope Chain','pendant','standart',ARRAY['Egyptian Necklace','Egyptian Pendant','Egypt Necklace','Hamsa Hand Pendant','Hamsa Necklace','Hamsa Hand Necklace','Egypt Pendant','10K Gold Necklace','10K Gold Pendant','Evil Eye Necklace','Rope Chain','10K Rope Necklace','Rope Necklace']::text[],ARRAY['10K Gold Hamsa','Hamsa Hand Necklace','Evil Eye Necklace','Rope Chain Necklace','CZ Stone Pendant','Protection Necklace','Real Gold Necklace','Womens Gold Necklace','Gift for Her','Mothers Day Gift','Layering Necklace','Solid Gold Pendant','Evil Eye Jewelry']::text[],'[{"tag": "Egyptian Necklace", "reason": "Hamsa Egyptian degil (Ortadogu/Musevi-Islam amuleti); zayif/yaniltici relevance, slot bosa gidiyor."}, {"tag": "Egyptian Pendant", "reason": "Ayni Egypt koku; 4 Egypt varyantindan biri, redundancy."}, {"tag": "Egypt Necklace", "reason": "''Egyptian Necklace'' ile birebir ayni niyet, slot israfi."}, {"tag": "Egypt Pendant", "reason": "Egypt koku tekrari; kaldirildi."}, {"tag": "Hamsa Hand Pendant", "reason": "Hamsa 3 varyanttan tasiyor; ''Hamsa Hand Necklace'' + ''10K Gold Hamsa'' yeterli kapsam."}, {"tag": "Hamsa Necklace", "reason": "''Hamsa Hand Necklace'' bunu kapsiyor, ayni kok tekrari."}, {"tag": "10K Gold Necklace", "reason": "Cok generic; daha guclu alici-dili varyantlariyla (Real/Womens/Solid Gold) degistirildi."}, {"tag": "10K Gold Pendant", "reason": "''10K Gold Hamsa'' + ''Solid Gold Pendant'' kapsiyor; redundant."}, {"tag": "Rope Chain", "reason": "Kisa/tek-cekirdek; ''Rope Chain Necklace'' long-tail''ine katlandi."}, {"tag": "10K Rope Necklace", "reason": "Rope 3 varyantindan biri; slot israfi."}, {"tag": "Rope Necklace", "reason": "Rope koku tekrari; ''Rope Chain Necklace'' ile tek slota indirildi."}]'::jsonb,'[{"tag": "10K Gold Hamsa", "reason": "Ana sembol + materyal tek long-tail; hamsa/gold cekirdeklerini tek slota konsolide eder."}, {"tag": "Rope Chain Necklace", "reason": "3 rope varyantini tek etkili long-tail''e katlar (rope+chain+necklace)."}, {"tag": "CZ Stone Pendant", "reason": "Basliktaki CZ tas niteligini yuzeye cikarir; stil/tas niyet slotu."}, {"tag": "Protection Necklace", "reason": "Hamsa+evil eye anlam/kullanim slotu; koruma amuleti arayan aliciyi yakalar."}, {"tag": "Real Gold Necklace", "reason": "Alici dili (''real gold''); som altin arayan yuksek-niyetli aliciyi hedefler."}, {"tag": "Womens Gold Necklace", "reason": "Eksik kitle slotu (womens) + gold; hedef kitleyi genisletir."}, {"tag": "Gift for Her", "reason": "Hic olmayan hediye niyet slotu; ana alis motivasyonu."}, {"tag": "Mothers Day Gift", "reason": "Mevsimsel/hediye slotu; yuksek hacimli sezonluk arama."}, {"tag": "Layering Necklace", "reason": "Kullanim/stil slotu; katmanli takan aliciyi yakalar."}, {"tag": "Solid Gold Pendant", "reason": "Alici dili (''solid gold'') + pendant urun gercegi; jenerik 10K Gold Pendant''in yerine."}, {"tag": "Evil Eye Jewelry", "reason": "Ikinci sembolu ''necklace'' disi kategoriye (jewelry) genisletir."}]'::jsonb,'Slotlar redundancy ile dolu (4 Egypt + 3 Hamsa + 3 Rope varyanti); hediye/kitle/kullanim/alici-dili niyet slotlari tamamen bos ve Egypt tag''leri hamsa ile zayif iliskili.','Urun bir ''pendant necklace'' (rope chain ile satiliyor) oldugundan ''necklace'' TIP-CELISKISI DEGIL, mesru — ipucundaki celiski adaylari korunabilir kabul edildi; asil sorun ayni kelime degil ayni KOK-FRAZIN tekrari. 4 Egypt (zayif relevance) + 3 Hamsa + 3 Rope varyanti 10 slotu tuketmis, donusum 0. Egypt tamamen dusuruldu (hamsa Egyptian degil), Hamsa 2 slota, Rope tek ''Rope Chain Necklace'' slotuna indirildi. Bosalan 11 slot dengeli olarak niyet slotlarina yatirildi: hediye (Gift for Her, Mothers Day Gift), kitle (Womens Gold Necklace), alici-dili (Real/Solid Gold), kullanim (Layering), anlam (Protection), tas/stil (CZ Stone Pendant), kategori genisletme (Evil Eye Jewelry). Tum 13 tag <=20 karakter, hepsi cok-kelimeli long-tail, birebir/kok tekrari yok; her sembol (hamsa/evil eye) ve materyal korundu.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1834635671,'14K Gold Puffed Hoop Earrings | Diamond Cut, Shiny Yellow Gold','earring','standart',ARRAY['Heart Earrings','Gold Heart Earrings','Graduated Earrings','Hoop Earrings','Gold Hoop Earrings','Gold Graduate','Diamond Cut Earrings','Heart Hoop Earrings','Diamond Cut Hoop','Real Gold Earrings','Satin Earrings','14K Gold Hoop','14K Gold Earrings']::text[],ARRAY['Hoop Earrings','Gold Hoop Earrings','14K Gold Hoop','Diamond Cut Hoop','Diamond Cut Earrings','Real Gold Earrings','14K Gold Earrings','Puffed Hoop Earrings','Yellow Gold Hoops','Gift for Her','Mothers Day Gift','Everyday Earrings','Gold Earrings Women']::text[],'[{"tag": "Heart Earrings", "reason": "Tip celiskisi: urun puffed hoop kupe, kalp degil; alakasiz aramaya dusuruyor."}, {"tag": "Gold Heart Earrings", "reason": "Tip celiskisi: ''heart'' urun gercegiyle ortusmuyor, relevance dusuruyor."}, {"tag": "Heart Hoop Earrings", "reason": "Celiskili melez: urun hoop ama ''heart'' yanlis; hem celiski hem slot israfi."}, {"tag": "Graduated Earrings", "reason": "Belirsiz/alakasiz; puffed hoop urunle net baglanti yok, zayif niyet."}, {"tag": "Gold Graduate", "reason": "''graduate/graduation'' yanlis niyet sinyali (mezuniyet hediyesi) + neredeyse tek-kelime zayif tag."}, {"tag": "Satin Earrings", "reason": "Finish celiskisi: baslik ''Shiny'' diyor, satin (mat) ters sinyal veriyor."}]'::jsonb,'[{"tag": "Puffed Hoop Earrings", "reason": "Basliktaki tam urun adi (''Puffed Hoop'') tag olarak yoktu; en birebir long-tail."}, {"tag": "Yellow Gold Hoops", "reason": "Baslik/malzeme ''Yellow Gold'' vurgusunu yakalar; renk/finish slotu."}, {"tag": "Gift for Her", "reason": "Eksik hediye niyet slotu; alici arama dili."}, {"tag": "Mothers Day Gift", "reason": "Hediye occasion slotu; taki icin yuksek hacimli mevsimsel niyet."}, {"tag": "Everyday Earrings", "reason": "Eksik kullanim slotu; puffed hoop gunluk tasima niyetine oturur."}, {"tag": "Gold Earrings Women", "reason": "Eksik kitle (womens) slotu; gold+earrings+kitle birlesimi long-tail."}]'::jsonb,'Urun puffed HOOP kupe olmasina ragmen 3 tag ''heart'' ve 2 tag ''graduate/graduated'' ile tip-celiskisi/alakasizlik tasiyor; hediye, kitle ve kullanim niyet slotlari tamamen eksik.','Standart arketip: relevance-kirici 6 tag (3x heart tip-celiskisi, 2x graduate alakasizlik, 1x satin finish celiskisi) temizlendi. Yuksek degerli hoop/diamond cut/real+14K gold cekirdek tag''leri korundu (7 tag). Bosalan slotlar urun-gercegine sadik niyet slotlarina aktarildi: baslik dili (Puffed Hoop, Yellow Gold), hediye (Gift for Her, Mothers Day Gift), kullanim (Everyday), kitle (Gold Earrings Women). Hoop koku 6 varyantla sinirli tutuldu (cekirdek urun, 7-katli israf esiginin altinda), diamond cut 2 farkli birlesimde. Tum 13 tag cok-kelimeli, birebir tekrar yok, her biri <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,4296776011,'Chunky 14K Yellow Gold Rope Bracelet | Unisex Statement Jewelry','bracelet','standart',ARRAY['14K rope bracelet','chunky gold bracelet','solid gold bracelet','mens rope bracelet','heavy gold bracelet','14K yellow gold','unisex gold bracelet','hip hop jewelry','real gold bracelet','gold bracelet men','luxury gold bracelet','rope chain bracelet','gold gift for him']::text[],ARRAY['14K rope bracelet','chunky gold bracelet','mens rope bracelet','solid gold bracelet','real gold bracelet','14K yellow gold','hip hop jewelry','rope chain bracelet','gold gift for him','womens gold bracelet','everyday bracelet','stacking bracelet','fathers day gift']::text[],'[{"tag": "heavy gold bracelet", "reason": "''chunky/solid/real gold bracelet'' ile ayni agirlik/kalite niyetini tekrar eden fazla ''X gold bracelet'' varyanti — slot israfi."}, {"tag": "unisex gold bracelet", "reason": "''unisex'' zaten baslikta baskin; kitle mens+womens ile daha genis kapsaniyor, ayrica bir ''gold bracelet'' tekrari."}, {"tag": "gold bracelet men", "reason": "''mens rope bracelet'' ile neredeyse ikiz (erkek niyeti); birebir yakin tekrar, slot israfi."}, {"tag": "luxury gold bracelet", "reason": "Zayif ayristirici bir baska ''X gold bracelet'' varyanti; ''solid/real gold'' zaten luks/kalite sinyali veriyor."}]'::jsonb,'[{"tag": "womens gold bracelet", "reason": "Baslik ''unisex'' oldugu halde hic kadin hedeflemesi yoktu; erkek-agirlikli seti dengeleyip kitleyi genisletir."}, {"tag": "everyday bracelet", "reason": "Eksik kullanim (use) slotu — gunluk tasima aramasini yakalar, ''bracelet'' kokunu tekrar etmeden yeni niyet."}, {"tag": "stacking bracelet", "reason": "Eksik layering/istifleme kullanim slotu; zincir bilekliklerde yuksek hacimli long-tail arama."}, {"tag": "fathers day gift", "reason": "Eksik hediye-occasion slotu; erkek altin bilekligi guclu Babalar Gunu hediye niyetiyle eslesir."}]'::jsonb,'Yedi ayri "X gold bracelet" varyanti (chunky/solid/heavy/unisex/real/luxury/men) slotlari doldurup hediye-occasion, kullanim (everyday/stacking) ve kadin kitlesi niyet slotlarini disariya itiyor.','Ana sorun tip-celiskisi degil, asiri redundancy: 13 tagin 7''si ''X gold bracelet'' kalibindaydi ve ''rope'' 3 varyantta tekrarlaniyordu; Etsy kelimeleri kendi kombinledigi icin bu slot israfiydi. Cekirdek ve yuksek-donusum terimleri korundu (14K rope bracelet, chunky/solid/real gold bracelet, mens rope bracelet, rope chain bracelet, hip hop jewelry, 14K yellow gold, gold gift for him). 4 zayif tekrar cikarilip yerine eksik niyet slotlari eklendi: kadin kitlesi (womens), iki kullanim slotu (everyday, stacking) ve hediye-occasion (fathers day gift). Tumu cok-kelimeli long-tail, hepsi rope bileziginle relevance-uyumlu, birebir tekrar yok, her tag <=20 karakter. Not: 821 goruntulenme + %0 donusum tag-disi (fiyat/fotograf) sorunlara da isaret edebilir; tag seti optimize ama tek basina donusumu garantilemez.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1228152002,'14K Gold Puffed Evil Eye Pendant | Diamond Cut Protection Charm','pendant','standart',ARRAY['Gold Evil Eye','Good Luck Charm','Blue Evil Eye','Evil Eye Pendant','Evil Eye Charm','Protection Pendant','14K Gold Evil Eye','Good Luck Pendant','Evil Eye Jewelry','14K Gold Charm','14K Gold Pendant','Diamond Cut Pendant','Puffed Pendant']::text[],ARRAY['Evil Eye Pendant','14K Gold Evil Eye','Blue Evil Eye','Turkish Evil Eye','Evil Eye Gift','Nazar Pendant','Protection Pendant','Good Luck Charm','Diamond Cut Pendant','14K Gold Pendant','Real Gold Pendant','Womens Gold Pendant','Gift For Her']::text[],'[{"tag": "Gold Evil Eye", "reason": "14K Gold Evil Eye ile ortusuyor; 14K''li versiyon daha spesifik ve alici dili"}, {"tag": "Evil Eye Charm", "reason": "Evil Eye Pendant + Good Luck Charm zaten charm/pendant kumesini kapsiyor; salt tekrar"}, {"tag": "Evil Eye Jewelry", "reason": "Cok genis/generic tek terim; spesifik long-tail''e gore donusumu dusuk, slot degerli degil"}, {"tag": "Good Luck Pendant", "reason": "Good Luck Charm ile ayni niyet; charm varyanti daha yuksek arama hacmi, birini tut"}, {"tag": "14K Gold Charm", "reason": "14K Gold Pendant + 14K Gold Evil Eye ile 14K-gold kokunu ucuncu kez tekrarliyor"}, {"tag": "Puffed Pendant", "reason": "Baslikta gecen niche kelime; dusuk arama hacmi, slotu yuksek-niyet hediye/kitle terimine devret"}]'::jsonb,'[{"tag": "Turkish Evil Eye", "reason": "Stil/gelenek slotu — nazar urununde guclu ve rekabetci alici sorgusu"}, {"tag": "Evil Eye Gift", "reason": "Hediye niyeti slotu — koruma/nazar takisi sik hediye olarak aranir"}, {"tag": "Nazar Pendant", "reason": "Evil eye''in alici sinonimi; ''evil eye'' kelimesini tekrarlamadan yeni long-tail acar"}, {"tag": "Real Gold Pendant", "reason": "Alici dili (''real gold'') — imitasyondan ayrisma sinyali, materyal true gold"}, {"tag": "Womens Gold Pendant", "reason": "Kitle slotu (womens) — evil eye tekrarlamadan hedef alici genisletir"}, {"tag": "Gift For Her", "reason": "Hediye + kitle slotu — evil eye pendant alici tabanina birebir oturur"}]'::jsonb,'13 tag''in 7''si "evil eye" kokunu tekrarlarken hediye/stil/kitle niyet slotlari tamamen bos — slot israfi var, uzun-kuyruk cesitligi yok.','Orijinal sette 7 tag "evil eye" kokunu (Gold/Blue/14K/Charm/Pendant/Jewelry) tekrarlayarak slot israf ediyor, hediye/stil/kitle niyeti hic yok. 7 saglam tag korundu (Evil Eye Pendant, 14K Gold Evil Eye, Blue Evil Eye, Protection Pendant, Good Luck Charm, Diamond Cut Pendant, 14K Gold Pendant). 6 redundant tag temizlendi. Yerine farkli niyet slotlari eklendi: stil (Turkish), sinonim (Nazar), hediye (Evil Eye Gift, Gift For Her), kitle (Womens Gold Pendant), alici dili (Real Gold Pendant). Evil-eye phrase tag sayisi 7''den 5''e indi ama her biri FARKLI modifier tasidigi icin distinct long-tail; relevance korundu (hepsi pendant/nazar gercegiyle uyumlu). Tum tag''lar <=20 karakter ve cok-kelimeli.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1743457413,'10K Gold Jesus Head Nugget Ring | Religious CZ Stone','ring','standart',ARRAY['Nugget Ring','Nugget mens','Gold Nugget Ring','Nugget Rings','Gold Statement Rings','10K Gold Rings','10K Solid Gold Ring','Solid Gold Ring','10K Ring','Gold Ring','Jesus Head Ring','Jesus Nugget Ring','White Gold Ring']::text[],ARRAY['Gold Nugget Ring','Jesus Head Ring','10K Solid Gold Ring','Mens Nugget Ring','Gold Statement Ring','Mens Religious Ring','Gift For Him','Hip Hop Ring','Christian Ring','Real Gold Ring','Iced Out Ring','Jesus Piece Ring','Fathers Day Gift']::text[],'[{"tag": "White Gold Ring", "reason": "Tip celiskisi: malzeme sari 10K altin; white gold yanlis alici cekip donusumu dusurur."}, {"tag": "Nugget Ring", "reason": "Kok israfi: ''Gold Nugget Ring'' + ''Mens Nugget Ring'' zaten nugget ring kokunu kapsiyor."}, {"tag": "Nugget Rings", "reason": "''Nugget Ring'' cogul birebir kopyasi; Etsy tekil/cogulu kendi eslestirir."}, {"tag": "Nugget mens", "reason": "Bozuk dizim; ''Mens Nugget Ring'' ile duzgun long-tail''e cevrildi."}, {"tag": "Gold Statement Rings", "reason": "Cogul; tekil ''Gold Statement Ring'' olarak korundu, slot bosaltildi."}, {"tag": "10K Gold Rings", "reason": "Kok israfi: ''10K Solid Gold Ring'' bu niyeti daha guclu kapsiyor."}, {"tag": "Solid Gold Ring", "reason": "''10K Solid Gold Ring'' icinde eriyor; ayri slot israf."}, {"tag": "10K Ring", "reason": "Zayif/kisa jenerik; ''10K Solid Gold Ring'' + ''Real Gold Ring'' ile karsilandi."}, {"tag": "Gold Ring", "reason": "Cok jenerik dusuk-degerli kok; nitelik/baslikta zaten baskin."}, {"tag": "Jesus Nugget Ring", "reason": "''Jesus Head Ring'' + ''Gold Nugget Ring'' ile ortusen ucuncu Jesus/nugget varyanti."}]'::jsonb,'[{"tag": "Mens Nugget Ring", "reason": "Kitle slotu: erkek alici + urun tipi net long-tail."}, {"tag": "Gold Statement Ring", "reason": "Stil/kullanim slotu (tekil), cogul israfini giderir."}, {"tag": "Mens Religious Ring", "reason": "Kitle + tema; Jesus/dini niyeti erkek aramasina baglar."}, {"tag": "Gift For Him", "reason": "Hediye niyet slotu; erkek takisi icin yuksek donusumlu arama."}, {"tag": "Hip Hop Ring", "reason": "Tarz slotu; nugget + iced CZ estetigi hip hop alicisina hitap eder."}, {"tag": "Christian Ring", "reason": "Dini tema varyanti; Jesus disinda genis inanc aramasi yakalar."}, {"tag": "Real Gold Ring", "reason": "Alici dili (''real gold''); kaplama degil som vurgusu."}, {"tag": "Iced Out Ring", "reason": "CZ tasi -> iced out stil slotu; urun gercegiyle uyumlu."}, {"tag": "Jesus Piece Ring", "reason": "Hip hop + dini kesisimi; niche yuksek-niyet terim."}, {"tag": "Fathers Day Gift", "reason": "Hediye occasion slotu; erkek yuzugu -> baba hediyesi arama hacmi."}]'::jsonb,'"White Gold Ring" malzemeyle (10K sari altin) celisiyor ve nugget/gold-ring koku 8+ slotta tekrar edip hediye/stil/kitle niyet slotlarini bogmus.','Iki gercek sorun: (1) ''White Gold Ring'' malzeme celiskisi, (2) nugget (4 varyant) ve gold-ring (5 varyant) koklerinin slot israfi. Etsy tekil/cogul ve kelime kombinasyonlarini kendi yaptigi icin ''Nugget Ring/Rings'', ''10K Ring'', ''Gold Ring'', ''Solid Gold Ring'' gibi ortusen jenerikleri budadim; 3 guclu kok (Gold Nugget Ring, Jesus Head Ring, 10K Solid Gold Ring) korundu. Acilan slotlara eksik niyetleri koydum: kitle (mens), hediye (gift for him, fathers day), stil (hip hop, iced out, statement), tema derinligi (religious, christian, jesus piece). Tumu <=20 karakter, coklu-kelime, birebir tekrar yok ve ring/religious/gold urun gercegiyle celismez.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,4375720322,'10K Solid White Gold Rope Bracelet – Unisex Real Gold Chain','bracelet','standart',ARRAY['10K white bracelet','solid gold rope','white gold bracelet','men gold bracelet','unisex gold jewelry','luxury bracelet','real gold chain','rope link bracelet','10k gold bracelet','gift for him or her','10K solid gold','white gold jewelry','gold jewelry women']::text[],ARRAY['white gold bracelet','rope chain bracelet','10k gold bracelet','solid gold bracelet','mens gold bracelet','womens gold jewelry','unisex gold jewelry','real gold chain','gift for him or her','mothers day gift','diamond cut bracelet','everyday bracelet','hip hop jewelry']::text[],'[{"tag": "10K white bracelet", "reason": "Arama ifadesi degil; ''white gold bracelet'' + ''10k gold bracelet'' ile artik. Etsy zaten kombinliyor."}, {"tag": "solid gold rope", "reason": "solid+rope tekrari; ''solid gold bracelet'' ve ''rope chain bracelet'' icinde eritildi."}, {"tag": "men gold bracelet", "reason": "Yanlis alici dili; dogru arama terimi ''mens gold bracelet'' ile degistirildi."}, {"tag": "10K solid gold", "reason": "10K/solid ucuncu kez; kok tekrari, tek ''solid gold bracelet'' yeter."}, {"tag": "white gold jewelry", "reason": "''white gold bracelet'' + ''gold jewelry'' tag''leriyle cakisan artik kombinasyon."}, {"tag": "gold jewelry women", "reason": "Alici phrasing zayif; ''womens gold jewelry'' ile ayni niyet, dogru dille."}, {"tag": "rope link bracelet", "reason": "Basliktaki ''chain'' ile hizalanmasi icin ''rope chain bracelet'' daha genis kapsar."}, {"tag": "luxury bracelet", "reason": "Genel tek-nitelikli; daha yuksek niyetli stil/kullanim slotlariyla degistirildi (relevance kaybi yok)."}]'::jsonb,'[{"tag": "rope chain bracelet", "reason": "rope+chain iki koku birlestirir, baslik ''Real Gold Chain'' ile eslesir; rope bilezik zincir-stili urun oldugu icin relevance dogru."}, {"tag": "solid gold bracelet", "reason": "Alici dili ''solid gold'' saflik sinyalini tek slotta bracelet ile birlestirir."}, {"tag": "mens gold bracelet", "reason": "Erkek kitlesi icin dogru arama yazimi (men -> mens)."}, {"tag": "womens gold jewelry", "reason": "Kadin kitlesini geri kazanir; unisex urunde iki cinsiyeti de acik hedefler."}, {"tag": "mothers day gift", "reason": "Bos olan hediye-donemi niyet slotu; unisex hediye urunde yuksek donusum."}, {"tag": "diamond cut bracelet", "reason": "Bos olan stil slotu; altin rope bilezikte yaygin aranan nitelik."}, {"tag": "everyday bracelet", "reason": "Bos olan kullanim slotu; gunluk tas niyetini yakalar."}, {"tag": "hip hop jewelry", "reason": "Bos olan tarz slotu; altin rope zincir bu estetikte yogun aranir, erkek kitlesini genisletir."}]'::jsonb,'Slot israfi: 13 tag''in cogu "10K / white / solid gold bracelet" ayni kokunu tekrarlarken hediye-stil-kullanim-kitle niyet slotlari tamamen bos.','Standart arketip dengeli temizlik: 8 redundant/zayif tag cikarildi, 5 gucyu long-tail korundu (white gold bracelet, 10k gold bracelet, unisex gold jewelry, real gold chain, gift for him or her). ''gold bracelet'' koku bilinçli 4 farkli niteleyiciyle sinirlandi (white/10k/solid/mens), ''jewelry'' koku 3 farkli niyetle (unisex/womens/hip hop). Acilan slotlar niyet eksiklerini doldurdu: kitle (mens+womens), hediye (mothers day + him or her), stil (diamond cut, hip hop), kullanim (everyday). Tum tag''ler cok-kelimeli, hicbiri urun tipiyle (10K white gold rope bracelet, unisex) celismez; ''chain'' tag''leri baslikta gecen ''Real Gold Chain'' gerceginden mesru. 13/13 dolu, hepsi <=20 karakter.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1206377232,'14K Gold Diamonique CZ Hamsa Hand Evil Eye Dangle Earrings','earring','standart',ARRAY['Evil Eye Earrings','Good Luck Earrings','Protection Earrings','Gold Evil Eye','Diamonique Earrings','14K Gold Earrings','14k Gold Evil Eye','Hamsa Hand Earrings','Channel Earrings','Gold Cz Earrings','Channel Set Earrings','14K Gold Hamsa Hand','14K Charm Earrings']::text[],ARRAY['Evil Eye Earrings','Hamsa Hand Earrings','Diamonique Earrings','14K Gold Earrings','Good Luck Earrings','Protection Earrings','Channel Set Earrings','Gold Dangle Earrings','Womens Gold Earrings','Gift for Her','Evil Eye Jewelry','Real Gold Earrings','Mothers Day Gift']::text[],'[{"tag": "Gold Evil Eye", "reason": "Redundant: ''evil eye'' zaten Evil Eye Earrings''te var; 2-kelime zayif slot."}, {"tag": "14k Gold Evil Eye", "reason": "Cift redundancy: hem ''14k gold'' hem ''evil eye'' baska taglarda kapsanmis, slot israfi."}, {"tag": "Channel Earrings", "reason": "Channel Set Earrings ile ayni kok; daha spesifik setting terimini tuttum, bunu attim."}, {"tag": "Gold Cz Earrings", "reason": "CZ, Diamonique Earrings ile ortu­suyor; ''gold earrings'' zaten kapsanmis."}, {"tag": "14K Gold Hamsa Hand", "reason": "Hamsa+14K gold redundancy; Hamsa Hand Earrings bu niyeti karsiliyor."}, {"tag": "14K Charm Earrings", "reason": "Zayif ve pendant/charm kategori sinyali; slotu hediye/kitle niyetine actim."}]'::jsonb,'[{"tag": "Gold Dangle Earrings", "reason": "Stil+malzeme slotu; baslikta ''Dangle'' var, alici bu uzun-kuyruk terimle ariyor."}, {"tag": "Womens Gold Earrings", "reason": "Kitle slotu (womens) tamamen eksikti; 20 karakter, guclu alici niyeti."}, {"tag": "Gift for Her", "reason": "Hediye slotu yoktu; yuksek hacimli genel hediye aramasi."}, {"tag": "Evil Eye Jewelry", "reason": "''earrings'' disina cikip ''jewelry'' ile arama yuzeyini genisletir, meaning slotu."}, {"tag": "Real Gold Earrings", "reason": "Alici dili (''real gold'') — som altin arayanlari yakalar, malzeme guveni."}, {"tag": "Mothers Day Gift", "reason": "Occasion/hediye slotu; mevsimsel yuksek trafik, kitle ile eslesir."}]'::jsonb,'Ayni kok asiri tekrarlaniyor (Evil Eye 4x, 14K Gold 4x, Channel 2x, Hamsa 2x) ve hediye/kitle/stil niyet slotlari tamamen bos.','Set 13/13 dolu, hepsi <=20 karakter ve tamami cok-kelimeli long-tail. Ana relevance korundu (Evil Eye, Hamsa, Diamonique, 14K Gold, Good Luck, Protection). Asiri redundancy temizlendi: Evil Eye 4->2 (Earrings + Jewelry, farkli noun ile yuzey genisletme), 14K Gold varyanti kirpildi, Channel 2->1 (daha spesifik ''Channel Set'' tutuldu), Hamsa 2->1. Bos niyet slotlari dolduruldu: kitle (Womens), hediye (Gift for Her, Mothers Day Gift), stil (Gold Dangle), alici dili (Real Gold). Tip-celiskisi ipucu (14K Charm->pendant) dogrulandi: ''charm earrings'' teknik olarak mesru ama zayif ve pendant kategori sinyali tasidigi icin daha yuksek getirili hediye/kitle slotuna cevrildi.','orta'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1480904845,'14K Gold CZ Hoop Huggie Earrings, Evil Eye Charms','earring','standart',ARRAY['Gold Huggie Earrings','Diamonique Earrings','Huggie Hoop Earrings','Gold Hoop Earrings','Channel Set Earrings','Diamond Cz Huggie','Cz Huggie Earrings','Small Hoop Earrings','Gold Small Earrings','Gold Cz Earrings','14K Gold Earrings','14K Gold Huggie','Evil Eye Earrings']::text[],ARRAY['Gold Huggie Earrings','Cz Huggie Earrings','Huggie Hoop Earrings','Small Hoop Earrings','14K Gold Earrings','Diamonique Earrings','Channel Set Earrings','Evil Eye Earrings','Evil Eye Jewelry','Womens Gold Earrings','Gift For Her','Everyday Earrings','Real Gold Earrings']::text[],'[{"tag": "Gold Hoop Earrings", "reason": "Hoop koku Huggie Hoop + Small Hoop varyantlarinda zaten var; Etsy kelimeleri kendi kombinler, cift kayit slot israfi."}, {"tag": "Diamond Cz Huggie", "reason": "cz+huggie ikilisi Cz Huggie Earrings ile birebir ortusuyor; ayrica tekil isim (earrings yok) daha zayif."}, {"tag": "Gold Small Earrings", "reason": "''Small'' Small Hoop Earrings''te, ''Gold'' bircok tag''de var; ''gold small'' dogal bir arama ifadesi degil."}, {"tag": "Gold Cz Earrings", "reason": "gold+cz+earrings kokleri Gold Huggie + Cz Huggie + 14K Gold tag''lerinde dagitilmis; redundant."}, {"tag": "14K Gold Huggie", "reason": "14k Gold Earrings ve Gold Huggie Earrings ikisi birden bu ifadeyi kapsiyor; huggie 3. kez tekrar, slot bosa gidiyor."}]'::jsonb,'[{"tag": "Evil Eye Jewelry", "reason": "Evil eye niyetini ''earrings'' disina (jewelry kategorisi aramasi) tasir, farkli alici havuzu yakalar."}, {"tag": "Womens Gold Earrings", "reason": "Kitle slotu eksikti; kadin altin taki arayan alici dilini ekler, relevance korunur."}, {"tag": "Gift For Her", "reason": "Hediye niyet slotu tamamen eksikti; yuksek hacimli mevsimsel/hediye aramasini acar."}, {"tag": "Everyday Earrings", "reason": "Kullanim slotu; huggie''nin gunluk-takilir konumlandirmasini yakalar, dar urun dilini genisletir."}, {"tag": "Real Gold Earrings", "reason": "Alici dili (''real gold'') + som 10K/14K gercegini vurgular; Diamonique/CZ tag''leriyle guveni dengeler."}]'::jsonb,'Ayni kokler (Gold/Huggie/Cz + Earrings) yakin-kopya varyantlarla tekrarlanip slot israf ediyor; hediye/kitle/kullanim niyet slotlari tamamen eksik.','Set 13/13 dolu, hepsi <=20 karakter ve tumu cok-kelimeli long-tail (tek-kelime yok). Tip-celiskisi yok: urun earring, tum tag''ler kupe/mucevher gercegiyle uyumlu. Cekirdek yuksek-hacim ifadeleri (Gold/Cz/Huggie Hoop, Small Hoop, 14K Gold, Diamonique, Channel Set, Evil Eye) korundu; 5 redundant varyant ayiklandi ve yerine eksik niyet slotlari kondu: kitle (Womens), hediye (Gift For Her), kullanim (Everyday), kategori genisletme (Evil Eye Jewelry), alici dili (Real Gold). Huggie koku 5''ten 3 anlamli varyanta, cift Hoop tekli oldu; ''Earrings'' tekrari azaltilarak yeni arama yuzeyleri acildi.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1868666012,'14K Yellow Gold Figaro Link Chain | Elegant Everyday Necklace','necklace','standart',ARRAY['Gold Chain','Figaro Bracelet','Figaro Chain','Real Gold Chain','Gold Chain men','Real Gold man chain','Link Chain','Gold Figaro Chain','14k gold chain','14k chain','14k figaro chain','14k men chain','Solid Figaro Chain']::text[],ARRAY['Figaro Necklace','14k Figaro Chain','Solid Gold Necklace','Gold Chain for Men','Mens Gold Necklace','Real Gold Chain','Italian Figaro Chain','Diamond Cut Chain','Layering Necklace','Everyday Necklace','Womens Gold Chain','Gift for Him','14k Gold Necklace']::text[],'[{"tag": "Figaro Bracelet", "reason": "Tip celiskisi: urun necklace, baslikta ''chain/necklace'' — bracelet alakasiz trafik ceker, relevance dusurur."}, {"tag": "Gold Chain men", "reason": "''Real Gold man chain'' ve yeni ''Gold Chain for Men'' ile ayni niyet; gramer bozuk kisa varyant, slot israfi."}, {"tag": "Real Gold man chain", "reason": "''Gold Chain men'' ile birebir yakin kopya; ayni kok ikinci kez, ekstra kesif yok."}, {"tag": "Figaro Chain", "reason": "figaro koku 6 kez tekrar ediyor; ''Figaro Necklace'' + ''Italian Figaro Chain'' ile kapsandi, cıplak varyant fazlalık."}, {"tag": "Gold Figaro Chain", "reason": "''14k Figaro Chain'' ile ayni kombinasyon; Etsy kelimeleri kendi birlestirir, ayrı slot gereksiz."}, {"tag": "14k gold chain", "reason": "14k + gold + chain koklerinin hepsi baska taglarda mevcut; Etsy kombinler, birebir slot israfi."}, {"tag": "14k chain", "reason": "Cok zayif/genel iki kelime; ''14k Figaro Chain'' ve ''14k Gold Necklace'' bunu zaten kapsiyor."}, {"tag": "14k men chain", "reason": "14k + men koku ''Gold Chain for Men''/''Mens Gold Necklace'' ile karsilaniyor; grameri zayif dar varyant."}, {"tag": "Solid Figaro Chain", "reason": "figaro + solid tekrari; ''Solid Gold Necklace'' daha genis niyet acar, bu daralticidir."}, {"tag": "Link Chain", "reason": "Cok genel, marka/nis sinyali zayif; figaro zaten link tipi, bilgi katmiyor."}, {"tag": "Gold Chain", "reason": "Cok genel, yuksek rekabetli tek-konsept; niyet slotu icin daha spesifik taglara donusturuldu."}]'::jsonb,'[{"tag": "Solid Gold Necklace", "reason": "Alici dili ''solid gold'' + necklace tipi; ''som altin'' aramasini yakalar, malzeme gercegiyle uyumlu."}, {"tag": "Italian Figaro Chain", "reason": "Stil slotu: figaro''nun dogal stil imzasi ''italian''; figaro trafigini daraltmadan niteler."}, {"tag": "Diamond Cut Chain", "reason": "Stil slotu: yuksek arama hacimli takı niteligi, figaro zincirle uyumlu, yeni kitle acar."}, {"tag": "Layering Necklace", "reason": "Kullanim slotu: katman/layering trendi, kolye alicisinin guclu niyet aramasi."}, {"tag": "Everyday Necklace", "reason": "Kullanim slotu: baslikta ''Everyday'' geciyor, gunluk kullanim niyetini SEO''ya tasir."}, {"tag": "Womens Gold Chain", "reason": "Kitle genisletme: orijinal sadece erkek hedefliyordu; figaro unisex, kadin trafigini acar."}, {"tag": "Gift for Him", "reason": "Hediye slotu: tamamen eksikti; erkek altin zincir guclu hediye niyeti (baba/sevgili)."}, {"tag": "Mens Gold Necklace", "reason": "Kitle+tip: ''necklace'' varyantiyla erkek aramasini chain disinda da yakalar."}]'::jsonb,'Slotlar figaro (x6) ve 14k (x4) kok tekrariyla israf edilmis, bir tag urun tipiyle celisiyor (Figaro Bracelet) ve hediye/stil/kullanim/kadin-unisex niyet slotlari tamamen eksik.','figaro koku 6→3, 14k koku 4→2 indirildi; chain/necklace dengesi korundu (6/6). Tip celiskisi (bracelet) kaldirildi, relevance icin 3 figaro + real/solid gold + men taglari korundu. Dort eksik niyet slotu dolduruldu: hediye (Gift for Him), stil (Italian Figaro, Diamond Cut), kullanim (Layering, Everyday), kitle (Womens, Mens). Tum taglar cok-kelimeli ve <=20 karakter; hicbir birebir tekrar yok.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1820418158,'14K Yellow Gold Puffed Hoop Earrings | Chunky Graduated Design','earring','standart',ARRAY['Huge Hoop Earrings','Puffed Earrings','Hoop Earrings','Gold Hoop Earrings','Graduated Earrings','Gold Graduated','Diamond Cut Earrings','Large Hoop Earrings','Love Earrings','Twisted Earrings','Gold Twist Earrings','Gold Earrings','14K earrings']::text[],ARRAY['Gold Hoop Earrings','Puffed Hoop Earrings','Chunky Hoop Earrings','Graduated Hoops','Diamond Cut Hoops','14K Gold Earrings','Real Gold Hoops','Solid Gold Earrings','Womens Hoop Earrings','Gift For Her','Statement Earrings','Everyday Earrings','Yellow Gold Hoops']::text[],'[{"tag": "Twisted Earrings", "reason": "Urun tip-celiskisi: urun puffed graduated hoop, twist tasarim degil; alakasiz trafik ceker"}, {"tag": "Gold Twist Earrings", "reason": "Ayni twist celiskisi; urunde twist yok"}, {"tag": "Love Earrings", "reason": "Relevance yok; kalp/love urunu degil, graduated puffed hoop"}, {"tag": "Huge Hoop Earrings", "reason": "Large ile ayni boyut niyeti; sinonim slot israfi"}, {"tag": "Large Hoop Earrings", "reason": "Huge ile mukerrer boyut sinonimi; tek boyut tag''i yeter"}, {"tag": "Hoop Earrings", "reason": "Tek-genel, cok genis; baslikta zaten baskin, slot israfi"}, {"tag": "Gold Earrings", "reason": "Cok genel tek-kelime agirlikli; baslik baskin kelimesini bosuna tekrar"}, {"tag": "14K earrings", "reason": "Zayif form; 14K Gold Earrings ile guclu long-tail''e yukseltildi"}, {"tag": "Gold Graduated", "reason": "Eksik/garip ifade; Graduated Hoops olarak duzeltildi"}, {"tag": "Puffed Earrings", "reason": "Puffed Hoop Earrings ile tam long-tail''e cevrildi"}, {"tag": "Graduated Earrings", "reason": "Graduated Hoops varyantiyla urune baglandi, mukerrer kok temizlendi"}]'::jsonb,'[{"tag": "Chunky Hoop Earrings", "reason": "Basliktaki ''Chunky'' stil sinyali; eksik stil slotu"}, {"tag": "Real Gold Hoops", "reason": "Alici dili (''real gold'') som altin niyeti"}, {"tag": "Solid Gold Earrings", "reason": "Alici dili (''solid gold''); som 14K vurgusu"}, {"tag": "Womens Hoop Earrings", "reason": "Kitle slotu tamamen eksikti; kadin alici hedefi"}, {"tag": "Gift For Her", "reason": "Hediye niyeti hic yoktu; yuksek donusum sorgusu"}, {"tag": "Statement Earrings", "reason": "Stil/kullanim slotu; chunky graduated tasarimla ortusur"}, {"tag": "Everyday Earrings", "reason": "Kullanim slotu; gunluk tasima aramasi"}, {"tag": "Yellow Gold Hoops", "reason": "Basliktaki renk/malzeme niyeti; sari altin varyant aramasi"}]'::jsonb,'Tip-celisen tag''ler (Twisted/Twist/Love, urun aslinda puffed-graduated hoop) + hoop-boyut sinonim israfi (Huge/Large/Hoop) slot yiyor; hediye/kitle/kullanim niyeti sifir.','13/13 dolu, hepsi <=20 karakter, tamami cok-kelimeli long-tail (tek-kelime yok). Type-celisen 3 tag (Twisted/Twist/Love) kaldirilarak relevance duzeltildi. ''Hoop'' kok''u urunun kendisi oldugu icin korundu ama her varyanta AYRI niyet modifikatoru (puffed/chunky/graduated/diamond cut/womens/real gold/yellow gold) eklenerek sinonim israfi degil genuine intent-genislemesi saglandi. Baskin ''gold hoop earrings'' baglantisi 1 anchor ile tutuldu, gerisi hediye (gift for her), kitle (womens), stil (chunky/statement), kullanim (everyday) ve alici dili (real/solid gold) slotlariyla genisletildi. Puffed/graduated/diamond-cut/14K/yellow-gold nitelikleri urun gercegiyle uyumlu.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1862635763,'14K Yellow Gold Paperclip Chain Necklace | Solid Gold','necklace','standart',ARRAY['Paperclip Chain','Paperclip Necklace','Gold Paperclip Chain','14K Chain','Gold Chain','Gold Paperclip','Gold Necklace','Gold Chain Necklace','14K Gold Necklace','Paperclip','Real Gold Paperclip','Solid Gold Chain','PaperClips Jewelry']::text[],ARRAY['Paperclip Chain','Gold Paperclip Chain','Paperclip Necklace','14K Gold Necklace','Solid Gold Chain','Real Gold Necklace','Layering Necklace','Dainty Gold Chain','Gift for Her','Womens Gold Chain','Everyday Necklace','Minimalist Necklace','Gold Link Chain']::text[],'[{"tag": "14K Chain", "reason": "Zayif/dar; 14K niteligi 14K Gold Necklace long-tail''inde daha guclu tasiniyor."}, {"tag": "Gold Chain", "reason": "Cok genis, tek kavramli; rekabeti yuksek, Gold Link/Womens Gold Chain daha spesifik kapsiyor."}, {"tag": "Gold Paperclip", "reason": "Paperclip kokunun gereksiz varyanti; Gold Paperclip Chain zaten mevcut."}, {"tag": "Gold Necklace", "reason": "Asiri genel; long-tail necklace tag''leri daha iyi donusum getirir."}, {"tag": "Gold Chain Necklace", "reason": "Gold Chain + Necklace birlesimini Etsy zaten kombinliyor; redundant."}, {"tag": "Paperclip", "reason": "Tek kelime + paperclip kokunun 5. tekrari; net slot israfi."}, {"tag": "Real Gold Paperclip", "reason": "Paperclip 6. kez; ''real gold'' sinyali Real Gold Necklace''e tasindi."}, {"tag": "PaperClips Jewelry", "reason": "Paperclip 7. varyant; hicbir yeni niyet katmiyor."}]'::jsonb,'[{"tag": "Real Gold Necklace", "reason": "Alici dili ''real gold'' korunuyor ama paperclip yerine necklace ile yeni kapsam."}, {"tag": "Layering Necklace", "reason": "Paperclip zincirlerin bir numarali kullanim niyeti (katmanlama) — eksik slot."}, {"tag": "Dainty Gold Chain", "reason": "Stil/estetik + bu urun tipinin populer aramasi (ince/narin)."}, {"tag": "Gift for Her", "reason": "Hediye niyet slotu tamamen bostu; yuksek hacimli arama."}, {"tag": "Womens Gold Chain", "reason": "Kitle hedeflemesi yoktu; paperclip agirlikli kadin alicisi."}, {"tag": "Everyday Necklace", "reason": "Kullanim niyeti (gunluk takilabilir) — gunluk giyim aramasini yakalar."}, {"tag": "Minimalist Necklace", "reason": "Tarz/estetik slotu; paperclip''in sade gorunumuyle birebir tutarli."}, {"tag": "Gold Link Chain", "reason": "Paperclip bir link zinciri; kok tekrarlamadan alternatif genis-eslesme kapsami."}]'::jsonb,'13 tag''in 7''si "paperclip" kokunu tekrarlayip slot israf ediyor; hediye/kitle/stil/kullanim niyet slotlari tamamen bos.','Mevcut set 7 paperclip varyanti + birkac cok-genel tek kavram (Gold Chain, Gold Necklace) ile a9 slotu birbirinin kopyasina harciyordu. Paperclip kokunu 3 mesru long-tail''e indirdim (Paperclip Chain, Gold Paperclip Chain, Paperclip Necklace) — Etsy kombinledigi icin bu yeterli kapsama verir. Karat/malzeme sinyalini 14K Gold Necklace + Solid Gold Chain + Real Gold Necklace ile alici diline sabitledim. Bosalan slotlari dort niyet ekseninde doldurdum: hediye (Gift for Her), kitle (Womens Gold Chain), kullanim (Layering Necklace, Everyday Necklace), stil/estetik (Dainty Gold Chain, Minimalist Necklace, Gold Link Chain). Hepsi necklace/gold urun gercegiyle tutarli — tip-celiskisi yok. 13 tag''in tamami cok-kelimeli long-tail, birebir tekrar yok, her biri <=20 karakter (en uzunu Gold Paperclip Chain = 20).','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1820425868,'14K Yellow Gold Chunky Twisted Hoop Earrings | Puffed Round Design','earring','standart',ARRAY['Huge Hoop Earrings','Puffed Earrings','Hoop Earrings','Gold Hoop Earrings','Graduated Earrings','Gold Graduated','Diamond Cut Earrings','Large Hoop Earrings','Love Earrings','Twisted Earrings','Gold Twist Earrings','Gold Earrings','14K earrings']::text[],ARRAY['Gold Hoop Earrings','Chunky Gold Hoops','Puffed Hoop Earrings','Twisted Gold Hoops','Diamond Cut Hoops','Real Gold Earrings','14K Gold Earrings','Womens Hoop Earrings','Statement Earrings','Everyday Earrings','Gift for Her','Mothers Day Gift','Solid Gold Earrings']::text[],'[{"tag": "Huge Hoop Earrings", "reason": "Large/Chunky ile es anlamli, hoop slot israfi; ''chunky'' urun basligiyla birebir ortusuyor, ''huge'' zayif arama."}, {"tag": "Large Hoop Earrings", "reason": "Huge/Chunky ile ucuncu es anlamli hoop varyanti; tek tanimlayici tutuldu."}, {"tag": "Hoop Earrings", "reason": "Etsy kelimeleri zaten kombinliyor; jenerik 2-kelime, uzun-kuyruk varyantlar bunu kapsiyor."}, {"tag": "Graduated Earrings", "reason": "Tip celiskisi: urun puffed twisted round, graduated (kademeli boy) set degil; alakasiz."}, {"tag": "Gold Graduated", "reason": "Ayni alakasizlik + eksik/parca ifade; urun gercegiyle celisiyor."}, {"tag": "Love Earrings", "reason": "Urunle ilgisiz, mesnetsiz; puffed twisted hoop icin arama niyeti yok."}, {"tag": "Twisted Earrings", "reason": "''Gold Twist Earrings'' ile ayni kok; tek long-tail ''Twisted Gold Hoops'' altinda birlestirildi."}, {"tag": "Gold Twist Earrings", "reason": "Twisted ile neredeyse birebir; kok tekrari, slot israfi."}, {"tag": "Puffed Earrings", "reason": "Daha spesifik ''Puffed Hoop Earrings'' ile yukseltildi."}, {"tag": "Gold Earrings", "reason": "Cok jenerik; material niyeti ''14K/Real/Solid Gold Earrings'' ile daha guclu karsilandi."}, {"tag": "14K earrings", "reason": "Duzeltilerek ''Chunky Gold Hoops''", "reason_detail": "jenerik; ''14K Gold Earrings'' olarak yukseltildi."}, {"tag": "Diamond Cut Earrings", "reason": "''earrings'' fazlaligi hoop koklerine cevrildi: ''Diamond Cut Hoops'' (daha spesifik urun tipi)."}]'::jsonb,'[{"tag": "Chunky Gold Hoops", "reason": "Baslikta gecen ''chunky'' stil + alici dili ''gold hoops''; huge/large yerine gercek arama terimi."}, {"tag": "Puffed Hoop Earrings", "reason": "''Puffed Round Design'' tanimini spesifik hoop long-tail''e baglar."}, {"tag": "Twisted Gold Hoops", "reason": "Iki twist tag''ini tek guclu long-tail''de birlestirir (baslik ''twisted'')."}, {"tag": "Diamond Cut Hoops", "reason": "Mevcut stil sinyalini daha dar urun tipiyle (hoops) eslestirir."}, {"tag": "Real Gold Earrings", "reason": "Alici dili ''real gold'' — som altin arayan alicilar (material 14k real gold)."}, {"tag": "14K Gold Earrings", "reason": "Material niyeti; jenerik ''14K earrings'' yerine tam long-tail."}, {"tag": "Solid Gold Earrings", "reason": "Alici dili ''solid gold''; som 14K altini vurgular, fiyat-niyetli alici."}, {"tag": "Womens Hoop Earrings", "reason": "Kitle slotu — hedef alici (womens), tamamen eksikti."}, {"tag": "Statement Earrings", "reason": "Stil/kullanim slotu — chunky puffed urun icin dogal ''statement'' konumlama."}, {"tag": "Everyday Earrings", "reason": "Kullanim slotu — gunluk tasima niyeti, eksikti."}, {"tag": "Gift for Her", "reason": "Hediye slotu — takida en yuksek donusumlu niyet, tamamen eksikti."}, {"tag": "Mothers Day Gift", "reason": "Sezonsal hediye slotu — genis hediye trafigi getirir."}]'::jsonb,'4 cakisan hoop varyanti (Huge/Large/Hoop/Gold Hoop) + urunde olmayan ''graduated'' etiketleri slotlari isgal ederken hediye/kitle/kullanim niyet slotlari tamamen bos.','Onceki set 4 es anlamli hoop varyanti (Huge/Large/Hoop/Gold Hoop) ve urunle celisen ''graduated'' (kademeli set degil, puffed twisted round) + mesnetsiz ''Love'' etiketleriyle slot israf ediyordu; hediye/kitle/kullanim niyeti sifirdi. Yeni set: hoop tanimlayicilarini gercek arama terimlerine indirger (chunky/puffed/twisted/diamond cut — her biri farkli long-tail), material''i alici diliyle guclendirir (real/solid/14K gold), ve 4 bos niyet slotunu doldurur (womens, statement, everyday, gift for her, mothers day). Hoop-koklu tag''ler urunun gercek tanimlayicilari oldugu icin mesru; her biri ayri modifier tasidigindan literal tekrar degil. 13/13 dolu, hepsi <=20 karakter, tamami cok-kelimeli.','yuksek'),
('f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid,1863543744,'14K Solid Gold Paperclip Chain Necklace – Dainty Minimalist Jewelry','necklace','standart',ARRAY['14K gold papercliP','solid gold necklace','real gold chain 14k','minimal gold chain','dainty gold necklace','layering gold chain','women gold jewelry','gold link chain 14k','gold everyday chain','gift for her jewelry','paperclip chain gold','stackable gold chain','thin gold necklace']::text[],ARRAY['paperclip chain 14k','solid gold necklace','real gold chain','dainty gold necklace','minimalist jewelry','layering necklace','gift for her','mothers day gift','everyday necklace','stackable necklace','womens gold jewelry','thin gold chain','14k gold jewelry']::text[],'[{"tag": "14K gold papercliP", "reason": "Yazim hatasi (papercliP) + eksik urun tipi; ''paperclip chain 14k'' olarak duzeltildi ve chain eklendi."}, {"tag": "paperclip chain gold", "reason": "Tag 1 ile ayni koku tekrarliyor (paperclip 2x) - slot israfi, tekillestirildi."}, {"tag": "minimal gold chain", "reason": "''minimalist jewelry'' daha guclu alici aramasi; ''gold chain'' koku zaten asiri temsil ediliyordu."}, {"tag": "gold link chain 14k", "reason": "''14k gold chain'' kombinasyonu 3-4 tag''de tekrar ediyor; yeni niyet katmiyor, slot israfi."}, {"tag": "gold everyday chain", "reason": "Kullanim niyeti korundu ama bas isim degistirildi (''everyday necklace'') - chain koku tekrarini kirmak icin."}, {"tag": "layering gold chain", "reason": "''layering necklace'' olarak sadelesti; ''gold chain'' redundancy azaltildi, kullanim niyeti korundu."}, {"tag": "stackable gold chain", "reason": "''stackable necklace'' - yine chain koku dedupe, niyet korundu."}, {"tag": "gift for her jewelry", "reason": "''gift for her'' olarak kisaltildi (temiz long-tail) ve acilan slota ''mothers day gift'' eklendi."}]'::jsonb,'[{"tag": "mothers day gift", "reason": "Eksik hediye-occasion slotu; yuksek sezonsal arama hacmi, dainty kadin takisi icin ideal alici."}, {"tag": "minimalist jewelry", "reason": "Baslikta gecen ''minimalist'' stil niyetini yakalar; ''minimal'' yerine tam arama terimi."}, {"tag": "14k gold jewelry", "reason": "Genis materyal/kategori kapsayicisi; ''necklace/chain'' disinda ''jewelry'' basligini cesitlendirir."}, {"tag": "womens gold jewelry", "reason": "''women gold jewelry'' gramer duzeltmesi (womens) - alici-kitle hedefi netlesti."}]'::jsonb,'"paperclip" tag''inde yazim hatasi (papercliP) + "gold chain 14k" kokunun 6 slotu doldurup hediye/stil/occasion niyet slotlarini bogmasi.','Iki gercek sorun vardi: (1) ''paperclip'' yazim hatasi urunun ANA anahtar kelimesini aramadan dusuruyor, (2) 13 tag''in ~6''si ''gold chain 14k'' varyantiydi - Etsy kelimeleri kendi kombinledigi icin bu kok tekrari saf slot israfi. Optimize sette bas isimleri dengeledim (necklace 4x, chain 2x, jewelry 2x) ve her modifier''i AYRI niyet slotuna atadim: urun (paperclip), alici dili (solid/real gold, womens), stil (dainty, minimalist, thin), kullanim (layering, everyday, stackable), hediye (gift for her, mothers day). Urun dainty/minimalist kadin takisi oldugu icin celisen ''mens'' KOYMADIM. Hepsi cok-kelimeli long-tail, birebir tekrar yok, tumu <=20 karakter (en uzun ''dainty gold necklace'' = 20).','yuksek')
) as v(org_id, etsy_listing_id, title, ptype, archetype, old_tags, proposed_tags, dropped, added, key_issue, rationale, confidence)
where exists (select 1 from public.organizations o where o.id = 'f155b853-dfaf-48fd-94c5-ddfcb856e07c'::uuid)
on conflict (org_id, etsy_listing_id) do nothing;
